Future<XFile?> _pickAndCropImage({
  ImageSource source = ImageSource.gallery,
  int imageQuality = 88,
  double? maxWidth,
  double? maxHeight,
  bool profileCrop = false,
}) async {
  final picked = await ImagePicker().pickImage(
    source: source,
    imageQuality: imageQuality,
    maxWidth: maxWidth,
    maxHeight: maxHeight,
  );
  if (picked == null) return null;

  // The native cropper is used on Android/iOS. On desktop platforms,
  // keep the existing picker behavior so the app remains usable there.
  if (!Platform.isAndroid && !Platform.isIOS) return picked;

  final cropped = await ImageCropper().cropImage(
    sourcePath: picked.path,
    compressFormat: ImageCompressFormat.jpg,
    compressQuality: 90,
    uiSettings: [
      AndroidUiSettings(
        toolbarTitle: profileCrop ? 'Adjust profile picture' : 'Adjust image',
        toolbarColor: AppColors.cream,
        toolbarWidgetColor: AppColors.ink,
        backgroundColor: AppColors.cream,
        activeControlsWidgetColor: AppColors.blue,
        cropStyle: profileCrop ? CropStyle.circle : CropStyle.rectangle,
        initAspectRatio: profileCrop
            ? CropAspectRatioPreset.square
            : CropAspectRatioPreset.original,
        lockAspectRatio: profileCrop,
        aspectRatioPresets: const [
          CropAspectRatioPreset.original,
          CropAspectRatioPreset.square,
          CropAspectRatioPreset.ratio4x3,
          CropAspectRatioPreset.ratio16x9,
        ],
      ),
      IOSUiSettings(
        title: profileCrop ? 'Adjust profile picture' : 'Adjust image',
        cropStyle: profileCrop ? CropStyle.circle : CropStyle.rectangle,
        aspectRatioLockEnabled: profileCrop,
        aspectRatioPresets: const [
          CropAspectRatioPreset.original,
          CropAspectRatioPreset.square,
          CropAspectRatioPreset.ratio4x3,
          CropAspectRatioPreset.ratio16x9,
        ],
      ),
    ],
  );

  if (cropped == null) return null;
  return XFile(cropped.path, name: picked.name);
}

Future<List<XFile>> _pickAndCropImages({
  int imageQuality = 88,
  double? maxWidth,
  double? maxHeight,
  int? maxImages,
}) async {
  final picked = await ImagePicker().pickMultiImage(
    imageQuality: imageQuality,
    maxWidth: maxWidth,
    maxHeight: maxHeight,
  );
  if (picked.isEmpty) return <XFile>[];

  final limited = maxImages == null ? picked : picked.take(maxImages).toList();
  if (!Platform.isAndroid && !Platform.isIOS) return limited;

  final croppedImages = <XFile>[];
  for (final image in limited) {
    final cropped = await ImageCropper().cropImage(
      sourcePath: image.path,
      compressFormat: ImageCompressFormat.jpg,
      compressQuality: 90,
      uiSettings: [
        AndroidUiSettings(
          toolbarTitle: 'Adjust image',
          toolbarColor: AppColors.cream,
          toolbarWidgetColor: AppColors.ink,
          backgroundColor: AppColors.cream,
          activeControlsWidgetColor: AppColors.blue,
          cropStyle: CropStyle.rectangle,
          initAspectRatio: CropAspectRatioPreset.original,
          lockAspectRatio: false,
          aspectRatioPresets: const [
            CropAspectRatioPreset.original,
            CropAspectRatioPreset.square,
            CropAspectRatioPreset.ratio4x3,
            CropAspectRatioPreset.ratio16x9,
          ],
        ),
        IOSUiSettings(
          title: 'Adjust image',
          cropStyle: CropStyle.rectangle,
          aspectRatioPresets: const [
            CropAspectRatioPreset.original,
            CropAspectRatioPreset.square,
            CropAspectRatioPreset.ratio4x3,
            CropAspectRatioPreset.ratio16x9,
          ],
        ),
      ],
    );
    if (cropped != null) {
      croppedImages.add(XFile(cropped.path, name: image.name));
    }
  }
  return croppedImages;
}

final GlobalKey<NavigatorState> peerGridNavigatorKey =
GlobalKey<NavigatorState>();

Future<void> _firebaseMessagingBackgroundHandler(RemoteMessage message) async {
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );
}

Future<void> _registerPushToken() async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return;
  try {
    final messaging = FirebaseMessaging.instance;
    await messaging.requestPermission(alert: true, badge: true, sound: true);
    final token = await messaging.getToken();
    if (token != null && token.isNotEmpty) {
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'fcmTokens': FieldValue.arrayUnion([token]),
      }, SetOptions(merge: true));
    }
    FirebaseMessaging.instance.onTokenRefresh.listen((newToken) async {
      final currentUser = FirebaseAuth.instance.currentUser;
      if (currentUser == null || newToken.isEmpty) return;
      await FirebaseFirestore.instance
          .collection('users')
          .doc(currentUser.uid)
          .set({
        'fcmTokens': FieldValue.arrayUnion([newToken]),
      }, SetOptions(merge: true));
    });
  } catch (_) {}
}

Future<void> _handlePushMessage(RemoteMessage message) async {
  final data = message.data;
  final type = data['type']?.toString() ?? '';
  final relatedId = data['relatedId']?.toString() ?? '';
  final senderId = data['senderId']?.toString() ?? '';

  if (type == 'private_message' && senderId.isNotEmpty) {
    final profile = await _loadUserProfile(senderId);
    final navigator = peerGridNavigatorKey.currentState;
    if (navigator == null) return;
    navigator.push(
      SlideFadeRoute(
        page: PrivateChatScreen(
          otherUid: senderId,
          otherName:
          (profile?['name'] ?? data['senderName'] ?? 'Student').toString(),
          otherCollege: (profile?['college'] ?? '').toString(),
          otherProfileImage:
          (profile?['profileImage'] ?? data['senderProfileImage'] ?? '')
              .toString(),
        ),
      ),
    );
  } else if (type == 'student_mention' && relatedId.isNotEmpty) {
    final navigator = peerGridNavigatorKey.currentState;
    if (navigator == null) return;
    navigator.push(
      SlideFadeRoute(
        page: StudentPostDetailScreen(postId: relatedId),
      ),
    );
  } else if (type == 'personal_post_mention' && relatedId.isNotEmpty) {
    final navigator = peerGridNavigatorKey.currentState;
    if (navigator == null) return;
    navigator.push(
      SlideFadeRoute(
        page: PersonalPostDetailScreen(postId: relatedId),
      ),
    );
  }
}

Future<void> _initializePushNotifications() async {
  FirebaseMessaging.onBackgroundMessage(_firebaseMessagingBackgroundHandler);
  if (FirebaseAuth.instance.currentUser != null) {
    await _registerPushToken();
  }
  FirebaseMessaging.onMessageOpenedApp.listen(_handlePushMessage);
  final initialMessage = await FirebaseMessaging.instance.getInitialMessage();
  if (initialMessage != null) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _handlePushMessage(initialMessage);
    });
  }
}


// =====================================================
// IN-APP ANDROID UPDATER
// =====================================================

class AppUpdateInfo {
  final String latestVersion;
  final String minimumVersion;
  final String apkUrl;
  final String releaseNotes;

  const AppUpdateInfo({
    required this.latestVersion,
    required this.minimumVersion,
    required this.apkUrl,
    required this.releaseNotes,
  });

  bool get isMandatory =>
      _compareVersions(minimumVersion, _currentVersion) > 0;

  static String _currentVersion = '0.0.0';
}

int _compareVersions(String a, String b) {
  List<int> parse(String value) {
    final match = RegExp(r'\d+(?:\.\d+)*').firstMatch(value.trim());
    if (match == null) return [0];
    return match.group(0)!
        .split('.')
        .map((part) => int.tryParse(part) ?? 0)
        .toList();
  }

  final left = parse(a);
  final right = parse(b);
  final length = math.max(left.length, right.length);
  for (var i = 0; i < length; i++) {
    final l = i < left.length ? left[i] : 0;
    final r = i < right.length ? right[i] : 0;
    if (l != r) return l.compareTo(r);
  }
  return 0;
}

Future<AppUpdateInfo?> _fetchAppUpdateInfo() async {
  if (!Platform.isAndroid) return null;

  try {
    final packageInfo = await PackageInfo.fromPlatform();
    AppUpdateInfo._currentVersion = packageInfo.version;

    final snap = await FirebaseFirestore.instance
        .collection('appConfig')
        .doc('android')
        .get();

    if (!snap.exists) return null;

    final data = snap.data() ?? <String, dynamic>{};
    final latestVersion = (data['latestVersion'] ?? '').toString().trim();
    final minimumVersion =
    (data['minimumVersion'] ?? latestVersion).toString().trim();
    final apkUrl = (data['apkUrl'] ?? '').toString().trim();
    final releaseNotes = (data['releaseNotes'] ?? '').toString().trim();

    if (latestVersion.isEmpty || apkUrl.isEmpty) return null;

    if (_compareVersions(packageInfo.version, latestVersion) >= 0) {
      return null;
    }

    return AppUpdateInfo(
      latestVersion: latestVersion,
      minimumVersion: minimumVersion,
      apkUrl: apkUrl,
      releaseNotes: releaseNotes,
    );
  } catch (_) {
    // Never block the app just because the updater service is unavailable.
    return null;
  }
}

Future<bool> _downloadAndInstallUpdate(
    AppUpdateInfo info,
    void Function(double progress) onProgress,
    ) async {
  try {
    final tempDir = await getTemporaryDirectory();
    final apkFile = File('${tempDir.path}/peergrid_update.apk');

    if (await apkFile.exists()) {
      await apkFile.delete();
    }

    await Dio().download(
      info.apkUrl,
      apkFile.path,
      deleteOnError: true,
      onReceiveProgress: (received, total) {
        if (total > 0) {
          onProgress(received / total);
        }
      },
    );

    if (!await apkFile.exists() || await apkFile.length() == 0) {
      return false;
    }

    final result = await InstallPlugin.install(apkFile.path);
    if (result is Map) {
      return result['isSuccess'] == true;
    }

    return true;
  } catch (_) {
    return false;
  }
}

Future<bool> _showAppUpdateDialog(
    BuildContext context,
    AppUpdateInfo info,
    ) async {
  if (!context.mounted) return false;

  return await showDialog<bool>(
    context: context,
    barrierDismissible: !info.isMandatory,
    builder: (_) => _AppUpdateDialog(info: info),
  ) ??
      false;
}

// Settings-only update check. The splash-screen updater above remains unchanged.
Future<void> _checkForUpdateFromSettings(BuildContext context) async {
  if (!Platform.isAndroid) {
    if (context.mounted) {
      showSnack(context, 'App updates are available on Android.');
    }
    return;
  }

  try {
    final packageInfo = await PackageInfo.fromPlatform();
    AppUpdateInfo._currentVersion = packageInfo.version;

    final snap = await FirebaseFirestore.instance
        .collection('appConfig')
        .doc('android')
        .get();

    if (!snap.exists) {
      if (context.mounted) {
        showSnack(context, 'Could not check for updates. Please try again.');
      }
      return;
    }

    final data = snap.data() ?? <String, dynamic>{};
    final latestVersion = (data['latestVersion'] ?? '').toString().trim();
    final minimumVersion =
    (data['minimumVersion'] ?? latestVersion).toString().trim();
    final apkUrl = (data['apkUrl'] ?? '').toString().trim();
    final releaseNotes = (data['releaseNotes'] ?? '').toString().trim();

    if (latestVersion.isEmpty || apkUrl.isEmpty) {
      if (context.mounted) {
        showSnack(context, 'Could not check for updates. Please try again.');
      }
      return;
    }

    if (_compareVersions(packageInfo.version, latestVersion) >= 0) {
      if (context.mounted) {
        showSnack(context, 'You are using the latest version.');
      }
      return;
    }

    if (!context.mounted) return;

    final updateInfo = AppUpdateInfo(
      latestVersion: latestVersion,
      minimumVersion: minimumVersion,
      apkUrl: apkUrl,
      releaseNotes: releaseNotes,
    );

    await _showAppUpdateDialog(context, updateInfo);
  } catch (_) {
    if (context.mounted) {
      showSnack(context, 'Could not check for updates. Please try again.');
    }
  }
}

class _AppUpdateDialog extends StatefulWidget {
  final AppUpdateInfo info;

  const _AppUpdateDialog({required this.info});

  @override
  State<_AppUpdateDialog> createState() => _AppUpdateDialogState();
}

class _AppUpdateDialogState extends State<_AppUpdateDialog> {
  bool downloading = false;
  double progress = 0;
  String? error;

  Future<void> _update() async {
    if (downloading) return;

    setState(() {
      downloading = true;
      progress = 0;
      error = null;
    });

    final success = await _downloadAndInstallUpdate(
      widget.info,
          (value) {
        if (!mounted) return;
        setState(() => progress = value.clamp(0.0, 1.0));
      },
    );

    if (!mounted) return;

    if (!success) {
      setState(() {
        downloading = false;
        error = 'Could not download or start the update. Please try again.';
      });
      return;
    }

    Navigator.of(context).pop(true);
  }

  @override
  Widget build(BuildContext context) {
    final force = widget.info.isMandatory;

    return PopScope(
      canPop: !force && !downloading,
      child: AlertDialog(
        backgroundColor: AppColors.cream,
        title: Row(
          children: [
            Container(
              width: 42,
              height: 42,
              decoration: neoDeco(
                color: AppColors.cyan,
                radius: 10,
                shadow: false,
              ),
              child: const Icon(Icons.system_update_rounded),
            ),
            const SizedBox(width: 12),
            const Expanded(
              child: Text(
                'Update PeerGrid',
                style: TextStyle(fontWeight: FontWeight.w900),
              ),
            ),
          ],
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              force
                  ? 'A newer version is required to continue.'
                  : 'A newer version of PeerGrid is available.',
              style: const TextStyle(
                fontSize: 15,
                fontWeight: FontWeight.w700,
                height: 1.35,
              ),
            ),
            const SizedBox(height: 12),
            Text(
              'Version ${widget.info.latestVersion}',
              style: const TextStyle(fontWeight: FontWeight.w900),
            ),
            if (widget.info.releaseNotes.isNotEmpty) ...[
              const SizedBox(height: 8),
              Text(
                widget.info.releaseNotes,
                style: const TextStyle(
                  color: AppColors.muted,
                  height: 1.4,
                ),
              ),
            ],
            if (downloading) ...[
              const SizedBox(height: 18),
              LinearProgressIndicator(value: progress),
              const SizedBox(height: 8),
              Text(
                'Downloading ${(progress * 100).round()}%',
                style: const TextStyle(fontWeight: FontWeight.w800),
              ),
            ],
            if (error != null) ...[
              const SizedBox(height: 12),
              Text(
                error!,
                style: const TextStyle(
                  color: Colors.red,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ],
        ),
        actions: [
          if (!force && !downloading)
            TextButton(
              onPressed: () => Navigator.of(context).pop(false),
              child: const Text('Later'),
            ),
          FilledButton.icon(
            onPressed: downloading ? null : _update,
            icon: Icon(
              downloading
                  ? Icons.downloading_rounded
                  : Icons.download_rounded,
            ),
            label: Text(downloading ? 'Updating...' : 'Update now'),
          ),
        ],
      ),
    );
  }
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );

  await _initializePushNotifications();

  final prefs = await SharedPreferences.getInstance();
  darkMode.value = prefs.getBool('darkMode') ?? false;

  runApp(const PeerGridApp());
}

