BoxDecoration neoDeco({
  Color color = Colors.white,
  double radius = 10,
  bool shadow = true,
  double width = 2,
  BoxShape shape = BoxShape.rectangle,
}) {
  return BoxDecoration(
    color: color,
    shape: shape,
    borderRadius: shape == BoxShape.circle ? null : BorderRadius.circular(radius),
    border: Border.all(color: AppColors.ink, width: width),
    boxShadow: shadow ? neoShadow : null,
