// APP-WIDE DARK MODE
final ValueNotifier<bool> darkMode = ValueNotifier<bool>(false);

final ColorFilter _darkFilter = const ColorFilter.matrix(<double>[
  0.574, -1.430, -0.144, 0, 255,
  -0.426, -0.430, -0.144, 0, 255,
  -0.426, -1.430, 0.856, 0, 255,
  0, 0, 0, 1, 0,
]);

/// Wrap images/videos in this so they remain visually normal in dark mode.
class DarkSafe extends StatelessWidget {
  final Widget child;
  const DarkSafe({super.key, required this.child});

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<bool>(
      valueListenable: darkMode,
      builder: (_, dark, __) =>
      dark ? ColorFiltered(colorFilter: _darkFilter, child: child) : child,
    );
  }
}

Future<void> setDarkMode(bool value) async {
  darkMode.value = value;
  final prefs = await SharedPreferences.getInstance();
  await prefs.setBool('darkMode', value);
}

