void toggleInSet(ValueNotifier<Set<String>> notifier, String id) {
  final next = Set<String>.from(notifier.value);
  if (!next.remove(id)) next.add(id);
  notifier.value = next;
}

void showSnack(
    BuildContext context,
    String message, {
      Color? color,
      double bottomMargin = 110,
    }) {
  final messenger = ScaffoldMessenger.of(context);
  messenger.hideCurrentSnackBar();
  messenger.showSnackBar(
    SnackBar(
      content: Text(
        message,
        style: const TextStyle(fontWeight: FontWeight.w700),
      ),
      behavior: SnackBarBehavior.floating,
      backgroundColor: color ?? AppColors.ink,
      margin: EdgeInsets.fromLTRB(20, 0, 20, bottomMargin),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(20),
      ),
      duration: const Duration(milliseconds: 1800),
    ),
  );
}


