const String peerGridGlobalAdminUid = 'BqPehWM7H4ZTSIgK6IsSAViZpee2';

bool isPeerGridGlobalAdmin([String? uid]) =>
    (uid ?? FirebaseAuth.instance.currentUser?.uid) == peerGridGlobalAdminUid;

Future<Map<String, dynamic>?> getActivePeerGridBan(String uid) async {
  try {
    final snap = await FirebaseFirestore.instance.collection('userBans').doc(uid).get();
    if (!snap.exists) return null;
    final data = snap.data() ?? <String, dynamic>{};
    final until = data['expiresAt'];
    if (until is Timestamp && !until.toDate().isAfter(DateTime.now())) {
      // Expired bans are treated as inactive; the record is retained for audit.
      return null;
    }
    return data;
  } catch (_) {
    // Do not falsely treat a rules/network failure as a ban.
    return null;
  }
}

// =====================================================
// COLLEGE ADMIN ACCESS
// =====================================================
//
// Admin access is controlled by Firestore documents at:
// collegeAdmins/{firebaseAuthUid}
//
// Expected document:
// {
//   role: "college_admin",
//   collegeId: "ihrd_008"
// }
//
// Do not create or edit these role documents from the student app.

Future<Map<String, String>?> getCollegeAdminAccess(String uid) async {
  try {
    final doc = await FirebaseFirestore.instance
        .collection('collegeAdmins')
        .doc(uid)
        .get();

    if (!doc.exists) {
      return null;
    }

    final data = doc.data();

    if (data == null) {
      return null;
    }

    final role = data['role']?.toString().trim() ?? '';
    final collegeId = data['collegeId']?.toString().trim() ?? '';

    if (role != 'college_admin' || collegeId.isEmpty) {
      return null;
    }

    return <String, String>{
      'role': role,
      'collegeId': collegeId,
    };
  } catch (_) {
    // If the admin mapping cannot be read, do not give admin access.
    return null;
  }
}

