String _formatDateForStudent(dynamic value) {
  if (value is Timestamp) {
    final d = value.toDate();
    const months = <String>[
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${d.day} ${months[d.month - 1]} ${d.year}';
  }
  return 'Recently';
}

