AppEvent _liveCollegeEventToAppEvent(
    String collegeId,
    String eventId,
    Map<String, dynamic> data,
    ) {
  final category = data['category']?.toString().trim().isNotEmpty == true
      ? data['category'].toString().trim()
      : 'College';
  final title = data['title']?.toString().trim() ?? 'College Event';
  final org = data['collegeName']?.toString().trim().isNotEmpty == true
      ? data['collegeName'].toString().trim()
      : 'Official College Event';
  final color = switch (category) {
    'Tech' => const Color(0xFF7048FF),
    'Cultural' => const Color(0xFFE5EF72),
    'Workshop' => const Color(0xFFFF8A5B),
    'Sports' => const Color(0xFFDDF8E8),
    _ => AppColors.blue,
  };

  return AppEvent(
    id: 'college_${collegeId}_$eventId',
    title: title,
    org: org,
    date: data['date']?.toString().trim().isNotEmpty == true
        ? data['date'].toString().trim()
        : 'Date TBA',
    time: data['time']?.toString().trim().isNotEmpty == true
        ? data['time'].toString().trim()
        : 'Time TBA',
    location: data['location']?.toString().trim().isNotEmpty == true
        ? data['location'].toString().trim()
        : 'College campus',
    category: category,
    image: data['imageUrl']?.toString().trim().isNotEmpty == true
        ? data['imageUrl'].toString().trim()
        : null,
    description: data['description']?.toString().trim() ?? '',
    color: color,
    accent: color,
    icon: switch (category) {
      'Tech' => Icons.memory_rounded,
      'Cultural' => Icons.celebration_rounded,
      'Workshop' => Icons.lightbulb_rounded,
      'Sports' => Icons.sports_soccer_rounded,
      _ => Icons.event_rounded,
    },
  );
}

