// =====================================================
// PAGE TRANSITIONS
// =====================================================

class FadePageRoute<T> extends PageRouteBuilder<T> {
  final Widget page;

  FadePageRoute({
    required this.page,
    Duration duration = const Duration(milliseconds: 800),
  }) : super(
    pageBuilder: (context, animation, secondaryAnimation) => page,
    transitionsBuilder:
        (context, animation, secondaryAnimation, child) {
      return FadeTransition(opacity: animation, child: child);
    },
    transitionDuration: duration,
    reverseTransitionDuration: const Duration(milliseconds: 500),
  );
}

// 4. PAGE TRANSITION  (colour-block wipe instead of plain fade)
// ---------------------------------------------------------------------
class SlideFadeRoute<T> extends PageRouteBuilder<T> {
  final Widget page;

  SlideFadeRoute({required this.page})
      : super(
    pageBuilder: (context, animation, secondaryAnimation) => page,
    transitionsBuilder: (context, animation, secondaryAnimation, child) {
      final reveal = CurvedAnimation(
        parent: animation,
        curve: const Interval(0.45, 1, curve: Curves.easeOutCubic),
      );
      return Stack(
        children: [
          FadeTransition(opacity: reveal, child: child),
          IgnorePointer(
            child: AnimatedBuilder(
              animation: animation,
              builder: (context, _) {
                final t = Curves.easeInOutCubic.transform(animation.value);
                if (t <= 0 || t >= 1) return const SizedBox.shrink();
                final start = t < 0.5 ? 0.0 : (t - 0.5) * 2;
                final end = t < 0.5 ? t * 2 : 1.0;
                final w = (end - start).clamp(0.001, 1.0);
                final x = w >= 1 ? 0.0 : -1 + 2 * start / (1 - w);
                return Align(
                  alignment: Alignment(x, 0),
                  child: FractionallySizedBox(
                    widthFactor: w,
                    heightFactor: 1,
                    child: Container(
                      decoration: const BoxDecoration(
                        color: AppColors.cyan,
                        border: Border.symmetric(
                          vertical:
                          BorderSide(color: AppColors.ink, width: 3),
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      );
    },
    transitionDuration: const Duration(milliseconds: 520),
    reverseTransitionDuration: const Duration(milliseconds: 420),
  );
}

