// 5. MOTION WIDGETS
// ---------------------------------------------------------------------

/// Pop-up entrance: overshoot spring + 2° rotation that settles to 0.
class Entrance extends StatefulWidget {
  final Widget child;
  final int delayMs;
  final Offset offset;

  const Entrance({
    super.key,
    required this.child,
    this.delayMs = 0,
    this.offset = const Offset(0, 0.10),
  });

  @override
  State<Entrance> createState() => _EntranceState();
}

class _EntranceState extends State<Entrance>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 520),
  );
  late final Animation<double> _spring =
  CurvedAnimation(parent: _controller, curve: Curves.easeOutBack);
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    if (widget.delayMs == 0) {
      _controller.forward();
    } else {
      _timer = Timer(Duration(milliseconds: widget.delayMs), () {
        if (mounted) _controller.forward();
      });
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      child: widget.child,
      builder: (context, child) {
        final t = _spring.value;
        final inv = 1 - t;
        return Opacity(
          opacity: Curves.easeOut.transform(_controller.value.clamp(0.0, 1.0)),
          child: FractionalTranslation(
            translation: Offset(widget.offset.dx * inv, widget.offset.dy * inv),
            child: Transform.rotate(angle: 0.035 * inv, child: child),
          ),
        );
      },
    );
  }
}

/// SIGNATURE PRESS: the element slides into its own hard shadow.
/// Pass `shadow: true` + the child's corner `radius` to get the shadow
/// that collapses to 0. Without it, the child just nudges down-right.
class Pressable extends StatefulWidget {
  final Widget child;
  final VoidCallback? onTap;
  final double scale; // kept for compatibility
  final bool shadow;
  final double radius;

  const Pressable({
    super.key,
    required this.child,
    this.onTap,
    this.scale = 0.96,
    this.shadow = false,
    this.radius = 14,
  });

  @override
  State<Pressable> createState() => _PressableState();
}

class _PressableState extends State<Pressable> {
  bool _down = false;

  void _set(bool v) {
    if (mounted) setState(() => _down = v);
  }

  @override
  Widget build(BuildContext context) {
    final dx = _down ? (widget.shadow ? 2.0 : 1.0) : 0.0;
    final dy = _down ? (widget.shadow ? 4.0 : 2.0) : 0.0;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTapDown: widget.onTap == null
          ? null
          : (_) {
        HapticFeedback.selectionClick();
        _set(true);
      },
      onTapUp: widget.onTap == null ? null : (_) => _set(false),
      onTapCancel: () => _set(false),
      onTap: widget.onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 120),
        curve: Curves.easeOut,
        transform: Matrix4.translationValues(dx, dy, 0),
        decoration: widget.shadow
            ? BoxDecoration(
          borderRadius: BorderRadius.circular(widget.radius),
          boxShadow: [
            BoxShadow(
              color: AppColors.ink,
              offset: _down ? Offset.zero : const Offset(2, 4),
              blurRadius: 0,
            ),
          ],
        )
            : null,
        child: widget.child,
      ),
    );
  }
}

/// Idle float for stickers/illustrations.
class Floating extends StatefulWidget {
  final Widget child;
  final double amplitude;

  const Floating({super.key, required this.child, this.amplitude = 6});

  @override
  State<Floating> createState() => _FloatingState();
}

class _FloatingState extends State<Floating>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 3200),
  )..repeat(reverse: true);
  late final Animation<double> _curve =
  CurvedAnimation(parent: _controller, curve: Curves.easeInOut);

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _curve,
      child: widget.child,
      builder: (context, child) => Transform.translate(
        offset: Offset(0, -widget.amplitude * _curve.value),
        child: Transform.rotate(angle: (_curve.value - 0.5) * 0.06, child: child),
      ),
    );
  }
}

/// Slow ±5° sway (flowers, smileys, stickers).
class Wiggle extends StatefulWidget {
  final Widget child;
  final double degrees;

  const Wiggle({super.key, required this.child, this.degrees = 5});

  @override
  State<Wiggle> createState() => _WiggleState();
}

class _WiggleState extends State<Wiggle> with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 3600),
  )..repeat(reverse: true);

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _c,
      child: widget.child,
      builder: (context, child) {
        final a = (Curves.easeInOut.transform(_c.value) - 0.5) *
            2 *
            widget.degrees *
            math.pi /
            180;
        return Transform.rotate(angle: a, child: child);
      },
    );
  }
}

/// Four-point twinkling sparkle (needs `import 'dart:math' as math;`).
class Sparkle extends StatefulWidget {
  final double size;
  final Color color;
  final int delayMs;

  const Sparkle({
    super.key,
    this.size = 22,
    this.color = AppColors.cyan,
    this.delayMs = 0,
  });

  @override
  State<Sparkle> createState() => _SparkleState();
}

class _SparkleState extends State<Sparkle> with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1800),
  );
  Timer? _t;

  @override
  void initState() {
    super.initState();
    _t = Timer(Duration(milliseconds: widget.delayMs), () {
      if (mounted) _c.repeat(reverse: true);
    });
  }

  @override
  void dispose() {
    _t?.cancel();
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _c,
      builder: (context, _) {
        final t = Curves.easeInOut.transform(_c.value);
        return Transform.rotate(
          angle: t * math.pi / 4,
          child: Transform.scale(
            scale: 0.6 + 0.6 * t,
            child: CustomPaint(
              size: Size.square(widget.size),
              painter: _StarPainter(widget.color),
            ),
          ),
        );
      },
    );
  }
}

class _StarPainter extends CustomPainter {
  final Color color;
  _StarPainter(this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final c = size.center(Offset.zero);
    final r = size.width / 2;
    final i = r * 0.28;
    final p = Path()
      ..moveTo(c.dx, c.dy - r)
      ..lineTo(c.dx + i, c.dy - i)
      ..lineTo(c.dx + r, c.dy)
      ..lineTo(c.dx + i, c.dy + i)
      ..lineTo(c.dx, c.dy + r)
      ..lineTo(c.dx - i, c.dy + i)
      ..lineTo(c.dx - r, c.dy)
      ..lineTo(c.dx - i, c.dy - i)
      ..close();
    canvas.drawPath(p, Paint()..color = color);
    canvas.drawPath(
      p,
      Paint()
        ..color = AppColors.ink
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.6
        ..strokeJoin = StrokeJoin.round,
    );
  }

  @override
  bool shouldRepaint(covariant _StarPainter old) => old.color != color;
}

