class ProfileAvatar extends StatelessWidget {
  final String imageUrl;
  final String name;
  final double radius;
  final Color backgroundColor;
  final IconData fallbackIcon;

  const ProfileAvatar({
    super.key,
    required this.imageUrl,
    this.name = '',
    this.radius = 24,
    this.backgroundColor = AppColors.cyan,
    this.fallbackIcon = Icons.person_rounded,
  });

  @override
  Widget build(BuildContext context) {
    final cleanUrl = imageUrl.trim();
    final initial = name.trim().isNotEmpty ? name.trim()[0].toUpperCase() : '';

    return Container(
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        border: Border.all(color: AppColors.ink, width: radius > 30 ? 2.5 : 2),
      ),
      child: CircleAvatar(
        radius: radius,
        backgroundColor: backgroundColor,
        child: ClipOval(
          child: cleanUrl.isNotEmpty
              ? DarkSafe(
            child: Image.network(
              cleanUrl,
              width: radius * 2,
              height: radius * 2,
              fit: BoxFit.cover,
              cacheWidth: radius < 40
                  ? (radius * 2 *
                  MediaQuery.of(context).devicePixelRatio)
                  .round()
                  : null,
              filterQuality: FilterQuality.low,
              gaplessPlayback: true,
              errorBuilder: (_, __, ___) => _fallback(initial),
            ),
          )
              : _fallback(initial),
        ),
      ),
    );
  }

  Widget _fallback(String initial) {
    if (initial.isNotEmpty) {
      return Center(
        child: Text(
          initial,
          style: TextStyle(
            color: AppColors.ink,
            fontWeight: FontWeight.w900,
            fontSize: radius * 0.72,
          ),
        ),
      );
    }
    return Icon(fallbackIcon, color: AppColors.ink, size: radius * 0.9);
  }
}

