class SegmentedTabs extends StatelessWidget {
  final List<String> labels;
  final int index;
  final ValueChanged<int> onChanged;

  const SegmentedTabs({
    super.key,
    required this.labels,
    required this.index,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 54,
      padding: const EdgeInsets.all(4),
      decoration: neoDeco(color: Colors.white, radius: 16),
      child: LayoutBuilder(
        builder: (context, box) {
          final w = box.maxWidth / labels.length;
          return Stack(
            children: [
              AnimatedPositioned(
                duration: const Duration(milliseconds: 360),
                curve: Curves.easeOutBack,
                left: w * index,
                top: 0,
                bottom: 0,
                width: w,
                child: Container(
                  decoration: neoDeco(
                      color: AppColors.blue, radius: 12, shadow: false),
                ),
              ),
              Positioned.fill(
                child: Row(
                  children: [
                    for (int i = 0; i < labels.length; i++)
                      Expanded(
                        child: GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTap: () {
                            HapticFeedback.selectionClick();
                            onChanged(i);
                          },
                          child: Center(
                            child: Text(
                              labels[i],
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: i == index ? Colors.white : AppColors.ink,
                                fontWeight: FontWeight.w900,
                                fontSize: 13.5,
                              ),
                            ),
                          ),
                        ),
                      ),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

class PillButton extends StatelessWidget {
  final String label;
  final IconData? icon;
  final Color color;
  final Color? textColor; // null = auto (ink on light, white on dark)
  final VoidCallback? onTap;
  final double height;
  final bool loading;

  const PillButton({
    super.key,
    required this.label,
    required this.onTap,
    this.icon,
    this.color = AppColors.blue,
    this.textColor,
    this.height = 52,
    this.loading = false,
  });

  @override
  Widget build(BuildContext context) {
    final disabled = onTap == null;
    final bg = disabled ? const Color(0xFFE6E0CC) : color;
    final fg = disabled
        ? AppColors.muted
        : (textColor ??
        (ThemeData.estimateBrightnessForColor(bg) == Brightness.dark
            ? Colors.white
            : AppColors.ink));

    return Pressable(
      onTap: loading ? null : onTap,
      shadow: !disabled,
      radius: 14,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 250),
        height: height,
        alignment: Alignment.center,
        decoration: neoDeco(color: bg, radius: 14, shadow: false),
        child: loading
            ? SizedBox(
          width: 22,
          height: 22,
          child: CircularProgressIndicator(strokeWidth: 3, color: fg),
        )
            : Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (icon != null) ...[
              Icon(icon, size: 20, color: fg),
              const SizedBox(width: 8),
            ],
            Text(
              label,
              style: TextStyle(
                color: fg,
                fontWeight: FontWeight.w900,
                fontSize: 15,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

