class FloatingNavBar extends StatelessWidget {
  final int currentIndex;
  final ValueChanged<int> onTap;

  const FloatingNavBar({
    super.key,
    required this.currentIndex,
    required this.onTap,
  });

  Widget _item(int i, IconData icon, IconData activeIcon, String label) {
    final selected = currentIndex == i;
    return Pressable(
      onTap: () => onTap(i),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 320),
        curve: Curves.easeOutBack,
        padding: EdgeInsets.symmetric(horizontal: selected ? 14 : 10, vertical: 10),
        decoration: BoxDecoration(
          color: selected ? AppColors.cyan : Colors.transparent,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: selected ? AppColors.ink : Colors.transparent,
            width: 2,
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(selected ? activeIcon : icon, color: AppColors.ink, size: 24),
            AnimatedSize(
              duration: const Duration(milliseconds: 300),
              curve: Curves.easeOutBack,
              child: selected
                  ? Padding(
                padding: const EdgeInsets.only(left: 6),
                child: Text(
                  label,
                  style: const TextStyle(
                    color: AppColors.ink,
                    fontWeight: FontWeight.w900,
                    fontSize: 12,
                  ),
                ),
              )
                  : const SizedBox.shrink(),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 68,
      padding: const EdgeInsets.symmetric(horizontal: 6),
      decoration: neoDeco(color: AppColors.cream, radius: 24, width: 2.5),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          _item(0, Icons.home_outlined, Icons.home_rounded, 'Home'),
          _item(1, Icons.calendar_month_outlined, Icons.calendar_month, 'Events'),
          _item(2, Icons.groups_outlined, Icons.groups_rounded, 'Groups'),
          _item(3, Icons.search_rounded, Icons.search_rounded, 'Explore'),
          _item(4, Icons.person_outline_rounded, Icons.person_rounded, 'Me'),
        ],
      ),
    );
  }
}

