/// Displays an image using its real aspect ratio so portrait and landscape
/// images get different layouts instead of being cropped into one fixed shape.
class AdaptiveImage extends StatefulWidget {
  final ImageProvider image;
  final double? width;
  final double? maxHeight;
  final BoxFit fit;
  final Widget? error;

  const AdaptiveImage({
    super.key,
    required this.image,
    this.width,
    this.maxHeight,
    this.fit = BoxFit.contain,
    this.error,
  });

  @override
  State<AdaptiveImage> createState() => _AdaptiveImageState();
}

class _AdaptiveImageState extends State<AdaptiveImage> {
  ImageStream? _stream;
  ImageStreamListener? _listener;
  ImageInfo? _imageInfo;
  Object? _error;

  @override
  void initState() {
    super.initState();
    _resolveImage();
  }

  @override
  void didUpdateWidget(covariant AdaptiveImage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.image != widget.image) {
      _resolveImage();
    }
  }

  void _resolveImage() {
    if (_stream != null && _listener != null) {
      _stream!.removeListener(_listener!);
    }
    _imageInfo = null;
    _error = null;

    final stream = widget.image.resolve(const ImageConfiguration());
    final listener = ImageStreamListener(
      _handleImage,
      onError: (error, stackTrace) {
        if (mounted) {
          setState(() {
            _error = error;
          });
        }
      },
    );

    _stream = stream;
    _listener = listener;
    stream.addListener(listener);
  }

  void _handleImage(ImageInfo info, bool synchronousCall) {
    if (!mounted) return;

    setState(() {
      _imageInfo = info;
    });
  }

  @override
  void dispose() {
    if (_stream != null && _listener != null) {
      _stream!.removeListener(_listener!);
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_error != null) {
      return widget.error ??
          const Center(child: Icon(Icons.broken_image_outlined));
    }

    final image = _imageInfo?.image;
    if (image == null) {
      return Container(
        width: widget.width,
        height: widget.maxHeight,
        color: AppColors.softBlue,
        alignment: Alignment.center,
        child: const SizedBox(
          width: 24,
          height: 24,
          child: CircularProgressIndicator(
            color: AppColors.ink,
            strokeWidth: 2.5,
          ),
        ),
      );
    }

    final aspectRatio = image.width / image.height;

    return LayoutBuilder(
      builder: (context, constraints) {
        final availableWidth = widget.width ??
            (constraints.hasBoundedWidth
                ? constraints.maxWidth
                : double.infinity);

        var targetWidth = availableWidth;
        var targetHeight = targetWidth / aspectRatio;

        if (widget.maxHeight != null && targetHeight > widget.maxHeight!) {
          targetHeight = widget.maxHeight!;
          targetWidth = targetHeight * aspectRatio;
        }

        if (constraints.hasBoundedHeight &&
            targetHeight > constraints.maxHeight) {
          targetHeight = constraints.maxHeight;
          targetWidth = targetHeight * aspectRatio;
        }

        if (constraints.hasBoundedWidth &&
            targetWidth > constraints.maxWidth) {
          targetWidth = constraints.maxWidth;
          targetHeight = targetWidth / aspectRatio;
        }

        if (!targetWidth.isFinite || !targetHeight.isFinite) {
          targetWidth = constraints.hasBoundedWidth
              ? constraints.maxWidth
              : 200;
          targetHeight = targetWidth / aspectRatio;
        }

        return SizedBox(
          width: targetWidth,
          height: targetHeight,
          child: DarkSafe(
            child: Image(
              image: widget.image,
              width: targetWidth,
              height: targetHeight,
              fit: widget.fit,
              errorBuilder: (_, __, ___) =>
              widget.error ??
                  const Center(child: Icon(Icons.broken_image_outlined)),
            ),
          ),
        );
      },
    );
  }
}

class CollegeImage extends StatelessWidget {
  final College college;
  final double? width;
  final double? height;

  const CollegeImage({
    super.key,
    required this.college,
    this.width,
    this.height,
  });

  @override
  Widget build(BuildContext context) {
    final isNetworkImage =
        college.image.startsWith('http://') ||
            college.image.startsWith('https://');

    if (college.isPhoto) {
      final provider = isNetworkImage
          ? NetworkImage(college.image) as ImageProvider
          : AssetImage(college.image);

      return Container(
        width: width,
        height: height,
        color: Colors.white,
        alignment: Alignment.center,
        child: AdaptiveImage(
          image: provider,
          width: width,
          maxHeight: height,
          fit: BoxFit.contain,
          error: Container(
            width: width,
            height: height,
            color: AppColors.softBlue,
            alignment: Alignment.center,
            child: const Icon(
              Icons.image_not_supported_outlined,
              color: AppColors.muted,
            ),
          ),
        ),
      );
    }

    return Container(
      width: width,
      height: height,
      color: Colors.white,
      padding: const EdgeInsets.all(10),
      child: appImage(college.image, fit: BoxFit.contain),
    );
  }
}

class EventVisual extends StatelessWidget {
  final AppEvent event;

  const EventVisual({super.key, required this.event});

  @override
