    final image = event.image?.trim() ?? '';

    if (image.isNotEmpty) {
      final provider = image.startsWith('http://') || image.startsWith('https://')
          ? NetworkImage(image) as ImageProvider
          : AssetImage(image);

      return Container(
        width: double.infinity,
