class NotificationBell extends StatelessWidget {
  final VoidCallback onTap;

  const NotificationBell({super.key, required this.onTap});

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: uid.isEmpty
          ? const Stream<QuerySnapshot<Map<String, dynamic>>>.empty()
          : FirebaseFirestore.instance
          .collection('notifications')
          .where('recipientId', isEqualTo: uid)
          .snapshots(),
      builder: (context, snapshot) {
        int unread = 0;
        for (final doc in snapshot.data?.docs ?? const <QueryDocumentSnapshot<Map<String, dynamic>>>[]) {
          if (doc.data()['isRead'] != true) unread++;
        }

        return Stack(
          clipBehavior: Clip.none,
          children: [
            Pressable(
              onTap: onTap,
              child: Container(
                width: 42,
                height: 42,
                decoration: BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  border: Border.all(color: Colors.black, width: 1.5),
                ),
                child: const Icon(
                  Icons.notifications_none_rounded,
                  color: Colors.black,
                  size: 22,
                ),
              ),
            ),
            if (unread > 0)
              Positioned(
                right: -2,
                top: -4,
                child: Container(
                  constraints: const BoxConstraints(minWidth: 18),
                  height: 18,
                  padding: const EdgeInsets.symmetric(horizontal: 4),
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: Colors.red,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: Colors.white, width: 1.5),
                  ),
                  child: Text(
                    unread > 99 ? '99+' : '$unread',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 9,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

Future<void> _markNotificationRead(
    DocumentReference<Map<String, dynamic>> ref,
    ) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;
  await ref.update({
    'isRead': true,
    'readAt': FieldValue.serverTimestamp(),
  });
}

Future<void> _markAllNotificationsRead() async {
  final uid = _currentUid();
  if (uid.isEmpty) return;

  final snap = await FirebaseFirestore.instance
      .collection('notifications')
      .where('recipientId', isEqualTo: uid)
      .get();
  if (snap.docs.isEmpty) return;

  for (var i = 0; i < snap.docs.length; i += 400) {
    final batch = FirebaseFirestore.instance.batch();
    for (final doc in snap.docs.skip(i).take(400)) {
      batch.delete(doc.reference);
    }
    await batch.commit();
  }
}

Future<void> _openNotification(
    BuildContext context,
    DocumentSnapshot<Map<String, dynamic>> doc,
    ) async {
  final data = doc.data() ?? <String, dynamic>{};
  final type = (data['type'] ?? '').toString();
  final senderId = (data['senderId'] ?? '').toString();
  final relatedId = (data['relatedId'] ?? '').toString();

  await _markNotificationRead(doc.reference);
  if (!context.mounted) return;
  Navigator.of(context).pop();

  if (type == 'private_message' && senderId.isNotEmpty) {
    final profile = await _loadUserProfile(senderId);
    if (!context.mounted) return;
    Navigator.of(context).push(
      SlideFadeRoute(
        page: PrivateChatScreen(
          otherUid: senderId,
          otherName: (profile?['name'] ?? data['senderName'] ?? 'Student').toString(),
          otherCollege: (profile?['college'] ?? '').toString(),
          otherProfileImage: (profile?['profileImage'] ?? data['senderProfileImage'] ?? '').toString(),
        ),
      ),
    );
  } else if (type == 'group_message' && relatedId.isNotEmpty) {
    if (!context.mounted) return;
    Navigator.of(context).push(
      SlideFadeRoute(
        page: GroupChatScreen(groupId: relatedId),
      ),
    );
  } else if (
  (type == 'student_post' ||
      type == 'student_post_like' ||
      type == 'student_post_comment' ||
      type == 'student_mention') &&
      relatedId.isNotEmpty) {
    if (!context.mounted) return;
    Navigator.of(context).push(
      SlideFadeRoute(
        page: StudentPostDetailScreen(postId: relatedId),
      ),
    );
  }
}

Future<void> _handleFollowRequestNotification(
    BuildContext context,
    DocumentSnapshot<Map<String, dynamic>> notification,
    String requesterUid,
    bool accept,
    ) async {
  final me = _currentUid();
  if (me.isEmpty || requesterUid.isEmpty) return;

  try {
    final requestSnap = await FirebaseFirestore.instance
        .collection('users').doc(me)
        .collection('followRequests').doc(requesterUid)
        .get();

    // Stale notification: the request was cancelled or already handled.
    if (!requestSnap.exists) {
      try {
        await notification.reference.delete();
      } catch (_) {}
      if (context.mounted) {
        showSnack(context, 'This follow request is no longer available.',
            bottomMargin: 20);
      }
      return;
    }

    if (accept) {
      await _acceptFollowRequest(requesterUid);
    } else {
      await _rejectFollowRequest(requesterUid);
    }

    try {
      await notification.reference.delete();
    } catch (_) {}

    if (context.mounted) {
      showSnack(
        context,
        accept ? 'Follow request accepted.' : 'Follow request rejected.',
        bottomMargin: 20,
      );
    }
  } catch (e) {
    if (context.mounted) {
      showSnack(
        context,
        'Could not ${accept ? 'accept' : 'reject'} the request: $e',
        color: Colors.red,
        bottomMargin: 20,
      );
    }
  }
}

void showNotifications(BuildContext context) {
  final uid = _currentUid();
  if (uid.isEmpty) {
    showSnack(context, 'Please sign in to view notifications.');
    return;
  }

  showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    backgroundColor: Colors.white,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(32)),
    ),
    builder: (sheetContext) {
      final stream = FirebaseFirestore.instance
          .collection('notifications')
          .where('recipientId', isEqualTo: uid)
          .snapshots();

      return SafeArea(
        child: SizedBox(
          height: MediaQuery.of(sheetContext).size.height * 0.78,
          child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: stream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return Padding(
                  padding: const EdgeInsets.all(24),
                  child: Center(
                    child: Text(
                      'Could not load notifications.\n${snapshot.error}',
                      textAlign: TextAlign.center,
                    ),
                  ),
                );
              }

              final docs = [...?snapshot.data?.docs];
              docs.sort((a, b) {
                final at = a.data()['createdAt'];
                final bt = b.data()['createdAt'];
                if (at is Timestamp && bt is Timestamp) {
                  return bt.compareTo(at);
                }
                return 0;
              });

              final unread = docs.where((doc) => doc.data()['isRead'] != true).length;

              return Padding(
                padding: const EdgeInsets.fromLTRB(20, 16, 20, 8),
                child: Column(
                  children: [
                    Container(
                      width: 44,
                      height: 5,
                      decoration: BoxDecoration(
                        color: Colors.black26,
                        borderRadius: BorderRadius.circular(3),
                      ),
                    ),
                    const SizedBox(height: 16),
                    Row(
                      children: [
                        const Expanded(
                          child: Text(
                            'Notifications',
                            style: TextStyle(fontSize: 24, fontWeight: FontWeight.w900),
                          ),
                        ),
                        if (docs.isNotEmpty)
                          TextButton(
                            onPressed: () async {
                              try {
                                await _markAllNotificationsRead();
                              } catch (e) {
                                if (sheetContext.mounted) {
                                  showSnack(sheetContext, 'Could not mark notifications as read: $e', color: Colors.red, bottomMargin: 20);
                                }
                              }
                            },
                            child: const Text('Mark all read'),
                          ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    Expanded(
                      child: docs.isEmpty
                          ? const EmptyState(
                        icon: Icons.notifications_none_rounded,
                        title: 'You are all caught up',
                        subtitle: 'New messages and group activity will appear here.',
                      )
                          : ListView.separated(
                        padding: const EdgeInsets.only(bottom: 16),
                        itemCount: docs.length,
                        separatorBuilder: (_, __) => const SizedBox(height: 8),
                        itemBuilder: (context, index) {
                          final doc = docs[index];
                          final data = doc.data();
                          final type = (data['type'] ?? '').toString();
                          final isRead = data['isRead'] == true;
                          final title = (data['title'] ?? 'Notification').toString();
                          final body = (data['body'] ?? '').toString();
                          final image = (data['senderProfileImage'] ?? '').toString();
                          final senderName = (data['senderName'] ?? '').toString();
                          final icon = type == 'group_message'
                              ? Icons.groups_rounded
                              : type == 'follow_request'
                              ? Icons.person_add_alt_1_rounded
                              : Icons.chat_bubble_rounded;
                          final isFollowRequest = type == 'follow_request';
                          final isStudyGroupJoinRequest = type == 'study_group_join_request';
                          final requesterUid = (data['senderId'] ?? data['relatedId'] ?? '').toString();

                          return AnimatedContainer(
                            duration: const Duration(milliseconds: 180),
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: isRead ? const Color(0xFFF7F7F7) : AppColors.softBlue,
                              borderRadius: BorderRadius.circular(22),
                              border: Border.all(
                                color: isRead ? Colors.black12 : AppColors.blue.withOpacity(0.35),
                              ),
                            ),
                            child: Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                if (image.isNotEmpty || senderName.isNotEmpty)
                                  ProfileAvatar(
                                    imageUrl: image,
                                    name: senderName,
                                    radius: 24,
                                  )
                                else
                                  CircleAvatar(
                                    radius: 24,
                                    backgroundColor: AppColors.cyan,
                                    child: Icon(icon, color: Colors.black),
                                  ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    children: [
                                      Text(title, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 14)),
                                      const SizedBox(height: 3),
                                      Text(body, style: const TextStyle(fontSize: 13, height: 1.3)),
                                      const SizedBox(height: 4),
                                      Text(
                                        _chatDisplayTime(data['createdAt']),
                                        style: const TextStyle(color: AppColors.muted, fontSize: 10, fontWeight: FontWeight.w700),
                                      ),
                                      if ((isFollowRequest || isStudyGroupJoinRequest) && requesterUid.isNotEmpty) ...[
                                        const SizedBox(height: 10),
                                        Row(
                                          children: [
                                            Expanded(
                                              child: PillButton(
                                                label: 'Accept',
                                                icon: Icons.check_rounded,
                                                color: AppColors.green,
                                                height: 42,
                                                onTap: () => isFollowRequest
                                                    ? _handleFollowRequestNotification(context, doc, requesterUid, true)
                                                    : _handleStudyGroupJoinRequestNotification(context, doc, (data['relatedId'] ?? '').toString(), requesterUid, true),
                                              ),
                                            ),
                                            const SizedBox(width: 8),
                                            Expanded(
                                              child: PillButton(
                                                label: 'Reject',
                                                icon: Icons.close_rounded,
                                                color: AppColors.softBlue,
                                                height: 42,
                                                onTap: () => isFollowRequest
                                                    ? _handleFollowRequestNotification(context, doc, requesterUid, false)
                                                    : _handleStudyGroupJoinRequestNotification(context, doc, (data['relatedId'] ?? '').toString(), requesterUid, false),
                                              ),
                                            ),
                                          ],
                                        ),
                                      ],
                                    ],
                                  ),
                                ),
                                if (!isFollowRequest && !isStudyGroupJoinRequest)
                                  GestureDetector(
                                    onTap: () => _openNotification(context, doc),
                                    child: const Padding(
                                      padding: EdgeInsets.all(4),
                                      child: Icon(Icons.chevron_right_rounded),
                                    ),
                                  ),
                                if (!isRead)
                                  Container(
                                    margin: const EdgeInsets.only(left: 4, top: 4),
                                    width: 9,
                                    height: 9,
                                    decoration: const BoxDecoration(color: AppColors.blue, shape: BoxShape.circle),
                                  ),
                              ],
                            ),
                          );
                        },
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        ),
      );
    },
  );
}

const List<String> presetHobbies = <String>[
  'Guitar', 'Writing', 'Movies', 'Singing', 'Fashion', 'Cooking',
  'Video Editing', 'Photo Editing', 'Chess', 'Vehicle Modification',
  'Photography', 'Music', 'Dance', 'Travel', 'Reading', 'Drawing',
  'Painting', 'Gaming', 'Coding', 'Artificial Intelligence', 'Robotics',
  'Football', 'Cricket', 'Badminton', 'Gym', 'Running', 'Yoga',
  'Volunteering', 'Entrepreneurship', 'Event Planning', 'DIY Projects',
];

List<String> _parseHobbies(String value) => value
    .split(RegExp(r'[,;]'))
    .map((item) => item.trim())
    .where((item) => item.isNotEmpty)
    .toSet()
    .toList();

String _serializeHobbies(Iterable<String> values) => values.join(', ');

class HobbySelector extends StatelessWidget {
  final Set<String> selected;
  final ValueChanged<String> onToggle;
  final bool compact;

  const HobbySelector({super.key, required this.selected, required this.onToggle, this.compact = false});

  @override
  Widget build(BuildContext context) {
    return Wrap(
      spacing: compact ? 7 : 9,
      runSpacing: compact ? 7 : 9,
      children: presetHobbies.map((hobby) {
        final active = selected.contains(hobby);
        return FilterChip(
          label: Text(hobby, style: TextStyle(fontWeight: FontWeight.w800, fontSize: compact ? 12 : 13)),
          selected: active,
          showCheckmark: true,
          avatar: active ? const Icon(Icons.check_circle_rounded, size: 17) : const Icon(Icons.circle_outlined, size: 17),
          onSelected: (_) => onToggle(hobby),
          backgroundColor: Colors.white,
          selectedColor: AppColors.cyan,
          side: BorderSide(color: active ? AppColors.ink : Colors.black26, width: active ? 1.6 : 1),
          shape: const StadiumBorder(),
          materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
        );
      }).toList(),
    );
  }
}

