Future<void> showPrivacySettings(BuildContext context) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;

  final ref = FirebaseFirestore.instance.collection('users').doc(uid);
  bool discoverable = true;
  bool privateChatEnabled = true;

  try {
    final snap = await ref.get();
    final data = snap.data() ?? <String, dynamic>{};
    discoverable = data['discoverable'] != false;
    privateChatEnabled = data['privateChatEnabled'] != false;
  } catch (_) {
    // Keep safe defaults if the profile cannot be read.
  }

  if (!context.mounted) return;

  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    backgroundColor: Colors.white,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(32)),
    ),
    builder: (sheetContext) {
      return StatefulBuilder(
        builder: (context, setSheetState) {
          Future<void> saveSetting(String field, bool value) async {
            try {
              await ref.set({field: value}, SetOptions(merge: true));
              showSnack(context, 'Privacy setting updated', bottomMargin: 110);
            } catch (_) {
              showSnack(
                context,
                'Could not update this setting.',
                color: Colors.red,
                bottomMargin: 110,
              );
            }
          }

          return SafeArea(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(20, 18, 20, 24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    width: 42,
                    height: 5,
                    decoration: BoxDecoration(
                      color: Colors.black12,
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'Privacy',
                    style: TextStyle(fontSize: 24, fontWeight: FontWeight.w900),
                  ),
                  const SizedBox(height: 6),
                  const Text(
                    'Choose how other PeerGrid students can discover and contact you.',
                    textAlign: TextAlign.center,
                    style: TextStyle(color: AppColors.muted, fontSize: 12.5, height: 1.35),
                  ),
                  const SizedBox(height: 18),
                  Container(
                    decoration: BoxDecoration(
                      color: AppColors.grey,
                      borderRadius: BorderRadius.circular(24),
                      border: Border.all(color: Colors.black, width: 1.2),
                    ),
                    child: Column(
                      children: [
                        SwitchListTile.adaptive(
                          value: discoverable,
                          onChanged: (value) async {
                            setSheetState(() => discoverable = value);
                            await saveSetting('discoverable', value);
                          },
                          title: const Text(
                            'Show me in Discover',
                            style: TextStyle(fontWeight: FontWeight.w800),
                          ),
                          subtitle: const Text(
                            'Allow other students to find your public profile.',
                            style: TextStyle(fontSize: 11.5),
                          ),
                        ),
                        const Divider(height: 1),
                        SwitchListTile.adaptive(
                          value: privateChatEnabled,
                          onChanged: (value) async {
                            setSheetState(() => privateChatEnabled = value);
                            await saveSetting('privateChatEnabled', value);
                          },
                          title: const Text(
                            'Allow private messages',
                            style: TextStyle(fontWeight: FontWeight.w800),
                          ),
                          subtitle: const Text(
                            'Allow students to start a private chat with you.',
                            style: TextStyle(fontSize: 11.5),
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 12),
                  const Text(
                    'Your email and other private account information are never shown on public student profiles.',
                    textAlign: TextAlign.center,
                    style: TextStyle(color: AppColors.muted, fontSize: 11, height: 1.4),
                  ),
                ],
              ),
            ),
          );
        },
      );
    },
  );
}

Future<void> showProfilePhotoActions(BuildContext context) async {
  final choice = await showModalBottomSheet<String>(
    context: context,
    backgroundColor: Colors.white,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(32)),
    ),
    builder: (sheetContext) {
      final hasPhoto = userProfileImage.value.trim().isNotEmpty;
      return SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 20, 20, 18),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Text(
                'Profile photo',
                style: TextStyle(fontSize: 22, fontWeight: FontWeight.w900),
              ),
              const SizedBox(height: 18),
              ProfileAvatar(
                imageUrl: userProfileImage.value,
                name: userName.value,
                radius: 46,
              ),
              const SizedBox(height: 18),
              ListTile(
                leading: const Icon(Icons.photo_library_rounded),
                title: const Text('Change photo', style: TextStyle(fontWeight: FontWeight.w800)),
                onTap: () => Navigator.pop(sheetContext, 'change'),
              ),
              if (hasPhoto)
                ListTile(
                  leading: const Icon(Icons.delete_outline_rounded, color: Colors.red),
                  title: const Text('Remove photo', style: TextStyle(color: Colors.red, fontWeight: FontWeight.w800)),
                  onTap: () => Navigator.pop(sheetContext, 'remove'),
                ),
            ],
          ),
        ),
      );
    },
  );

  if (!context.mounted || choice == null) return;
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return;

  if (choice == 'change') {
    try {
      final picked = await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 82,
        maxWidth: 900,
        maxHeight: 900,
        profileCrop: true,
      );
      if (picked == null || !context.mounted) return;

      showDialog(
        context: context,
        barrierDismissible: false,
        builder: (_) => const Center(child: CircularProgressIndicator()),
      );

      final file = File(picked.path);
      final ref = FirebaseStorage.instance
          .ref()
          .child('users')
          .child(user.uid)
          .child('profile.jpg');

      await ref.putFile(
        file,
        SettableMetadata(contentType: 'image/jpeg'),
      );
      final url = await ref.getDownloadURL();

      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .set({
        'profileImage': url,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      userProfileImage.value = url;

      if (context.mounted) {
        Navigator.of(context).pop();
        showSnack(context, 'Profile photo updated.', color: AppColors.green);
      }
    } catch (e) {
      if (context.mounted) {
        Navigator.of(context, rootNavigator: true).pop();
        showSnack(context, 'Could not update profile photo: $e', color: Colors.red);
      }
    }
  } else if (choice == 'remove') {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)),
        title: const Text('Remove profile photo?', style: TextStyle(fontWeight: FontWeight.w900)),
        content: const Text('Your default PeerGrid avatar will be shown instead.'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            child: const Text('Remove'),
          ),
        ],
      ),
    );
    if (confirmed != true || !context.mounted) return;

    try {
      try {
        await FirebaseStorage.instance
            .ref()
            .child('users')
            .child(user.uid)
            .child('profile.jpg')
            .delete();
      } catch (_) {}

      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .set({
        'profileImage': '',
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      userProfileImage.value = '';
      if (context.mounted) {
        showSnack(context, 'Profile photo removed.', color: AppColors.green);
      }
    } catch (e) {
      if (context.mounted) {
        showSnack(context, 'Could not remove profile photo: $e', color: Colors.red);
      }
    }
  }
}

Future<void> deleteCurrentAccount(BuildContext context) async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return;

  final confirmed = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(28)),
      title: const Text(
        'Delete account permanently?',
        style: TextStyle(fontWeight: FontWeight.w900),
      ),
      content: const Text(
        'This permanently deletes your PeerGrid login, profile and profile photo. This action cannot be undone.',
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext, false),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, true),
          style: FilledButton.styleFrom(backgroundColor: Colors.red),
          child: const Text('Continue'),
        ),
      ],
    ),
  );

  if (confirmed != true || !context.mounted) return;

  final passwordController = TextEditingController();
  final password = await showDialog<String>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(28)),
      title: const Text('Confirm your password', style: TextStyle(fontWeight: FontWeight.w900)),
      content: TextField(
        controller: passwordController,
        obscureText: true,
        decoration: InputDecoration(
          labelText: 'Password',
          filled: true,
          fillColor: AppColors.softBlue,
          border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(22),
            borderSide: BorderSide.none,
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, passwordController.text),
          style: FilledButton.styleFrom(backgroundColor: Colors.red),
          child: const Text('Delete account'),
        ),
      ],
    ),
  );
  passwordController.dispose();

  if (password == null || password.isEmpty || !context.mounted) return;

  showDialog(
    context: context,
    barrierDismissible: false,
    builder: (_) => const Center(child: CircularProgressIndicator()),
  );

  try {
    final email = user.email;
    if (email == null || email.trim().isEmpty) {
      throw FirebaseAuthException(code: 'missing-email', message: 'No email is attached to this account.');
    }

    final credential = EmailAuthProvider.credential(
      email: email,
      password: password,
    );
    await user.reauthenticateWithCredential(credential);

    final uid = user.uid;

    try {
      await FirebaseStorage.instance
          .ref()
          .child('users')
          .child(uid)
          .child('profile.jpg')
          .delete();
    } catch (_) {}

    await FirebaseFirestore.instance.collection('users').doc(uid).delete();
    await user.delete();

    userName.value = '';
    userUsername.value = '';
    userCollege.value = '';
    userHobbies.value = '';
    userYearOfStudy.value = '';
    userProfileImage.value = '';
    userTechnicalSkills.value = <String, String>{};
    savedColleges.value = <String>{};
    registeredEvents.value = <String>{};
    joinedCommunities.value = <String>{};

    if (!context.mounted) return;
    Navigator.of(context, rootNavigator: true).pop();
    Navigator.of(context).pushAndRemoveUntil(
      FadePageRoute(page: const WelcomeScreen()),
          (route) => false,
    );
  } on FirebaseAuthException catch (e) {
    if (context.mounted) {
      Navigator.of(context, rootNavigator: true).pop();
      final message = e.code == 'wrong-password' || e.code == 'invalid-credential'
          ? 'Incorrect password. Account was not deleted.'
          : e.code == 'requires-recent-login'
          ? 'Please sign in again and then delete the account.'
          : (e.message ?? 'Could not delete your account.');
      showSnack(context, message, color: Colors.red, bottomMargin: 16);
    }
  } catch (e) {
    if (context.mounted) {
      Navigator.of(context, rootNavigator: true).pop();
      showSnack(context, 'Could not delete your account: $e', color: Colors.red, bottomMargin: 16);
    }
  }
}


