// PROFILE SETUP
// =====================================================

const List<String> engineeringTechnicalSkills = [
  'Dart',
  'Flutter',
  'Python',
  'Java',
  'C',
  'C++',
  'JavaScript',
  'HTML/CSS',
  'SQL',
  'Firebase',
  'Git/GitHub',
  'AI / ML',
  'Data Science',
  'IoT',
  'Robotics',
  'UI / UX',
  'Cybersecurity',
  'Electronics',
  'AutoCAD',
];

const List<String> profileSkillLevels = [
  'Beginner',
  'Intermediate',
  'Advanced',
];

class ProfileSetupScreen extends StatefulWidget {
  final bool isFirstSetup;

  const ProfileSetupScreen({
    super.key,
    this.isFirstSetup = true,
  });

  @override
  State<ProfileSetupScreen> createState() => _ProfileSetupScreenState();
}

class _ProfileSetupScreenState extends State<ProfileSetupScreen> {
  final usernameController = TextEditingController();
  final Set<String> selectedHobbies = <String>{};
  final collegeController = TextEditingController();
  final courseController = TextEditingController();

  String selectedYear = '';
  String profileImageUrl = '';
  File? selectedImage;
  bool uploading = false;
  bool saving = false;

  final Map<String, String> selectedSkills = <String, String>{};

  @override
  void initState() {
    super.initState();
    usernameController.text = userUsername.value;
    selectedHobbies.addAll(_parseHobbies(userHobbies.value == 'Cooking, dance & more' ? '' : userHobbies.value));
    collegeController.text = userCollege.value;
    selectedYear = userYearOfStudy.value;
    profileImageUrl = userProfileImage.value;
    selectedSkills.addAll(userTechnicalSkills.value);
  }

  @override
  void dispose() {
    usernameController.dispose();
    collegeController.dispose();
    courseController.dispose();
    super.dispose();
  }

  Future<void> _pickProfileImage() async {
    try {
      final picked = await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 82,
        maxWidth: 900,
        maxHeight: 900,
        profileCrop: true,
      );
      if (picked == null) return;
      setState(() => selectedImage = File(picked.path));
    } catch (_) {
      if (!mounted) return;
      showSnack(context, 'Could not choose that image.',
          color: Colors.red, bottomMargin: 16);
    }
  }

  Future<String> _uploadProfileImage(String uid) async {
    if (selectedImage == null) return profileImageUrl;

    final ref = FirebaseStorage.instance
        .ref()
        .child('users')
        .child(uid)
        .child('profile.jpg');

    await ref.putFile(
      selectedImage!,
      SettableMetadata(contentType: 'image/jpeg'),
    );
    return ref.getDownloadURL();
  }

  Future<void> _saveProfile() async {
    FocusScope.of(context).unfocus();

    final username = usernameController.text.trim();
    final hobbies = _serializeHobbies(selectedHobbies);
    final college = collegeController.text.trim();
    final course = courseController.text.trim();
    final user = FirebaseAuth.instance.currentUser;

    if (user == null) {
      showSnack(context, 'Your session has expired. Please sign in again.',
          color: Colors.red, bottomMargin: 16);
      return;
    }
    if (widget.isFirstSetup &&
        selectedImage == null &&
        profileImageUrl.trim().isEmpty) {
      showSnack(
        context,
        'Please add a profile photo to finish setting up your profile.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }
    if (username.length < 3) {
      showSnack(context, 'Username must be at least 3 characters.',
          color: Colors.red, bottomMargin: 16);
      return;
    }
    if (college.isEmpty) {
      showSnack(context, 'Please add your college.',
          color: Colors.red, bottomMargin: 16);
      return;
    }
    if (selectedYear.isEmpty) {
      showSnack(context, 'Please select your current year of study.',
          color: Colors.red, bottomMargin: 16);
      return;
    }
    if (selectedSkills.isEmpty) {
      showSnack(context, 'Choose at least one technical skill.',
          color: Colors.red, bottomMargin: 16);
      return;
    }

    setState(() => saving = true);

    try {
      var imageUrl = profileImageUrl;

      if (selectedImage != null) {
        setState(() => uploading = true);
        imageUrl = await _uploadProfileImage(user.uid);
        if (mounted) setState(() => uploading = false);
      }

      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .set({
        'username': username,
        'name': user.displayName?.trim().isNotEmpty == true
            ? user.displayName!.trim()
            : username,
        'college': college,
        'course': course,
        'hobbies': hobbies,
        'yearOfStudy': selectedYear,
        'technicalSkills': selectedSkills,
        'profileImage': imageUrl,
        'profileSetupComplete': true,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      userName.value = user.displayName?.trim().isNotEmpty == true
          ? user.displayName!.trim()
          : username;
      userUsername.value = username;
      userCollege.value = college;
      userHobbies.value = hobbies;
      userYearOfStudy.value = selectedYear;
      userProfileImage.value = imageUrl;
      userTechnicalSkills.value = Map<String, String>.from(selectedSkills);

      if (!mounted) return;
      Navigator.of(context).pushAndRemoveUntil(
        FadePageRoute(page: const MainShell()),
            (route) => false,
      );
    } on FirebaseException catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        e.code == 'permission-denied'
            ? 'Profile permission denied. Check your Firestore and Storage rules.'
            : (e.message ?? 'Could not save your profile.'),
        color: Colors.red,
        bottomMargin: 16,
      );
    } catch (_) {
      if (!mounted) return;
      showSnack(context, 'Could not finish your profile. Please try again.',
          color: Colors.red, bottomMargin: 16);
    } finally {
      if (mounted) {
        setState(() {
          saving = false;
          uploading = false;
        });
      }
    }
  }

  Widget _sectionTitle(String title, String subtitle) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title,
              style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w900, color: AppColors.ink)),
          const SizedBox(height: 3),
          Text(subtitle,
              style: const TextStyle(
                  color: AppColors.muted, fontSize: 13, height: 1.35)),
        ],
      ),
    );
  }

  Widget _skillTile(String skill) {
    final selected = selectedSkills.containsKey(skill);
    final level = selectedSkills[skill];

    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(13),
        border: Border.all(color: AppColors.ink, width: 2),
        boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(3, 3), blurRadius: 0)],
      ),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 10, 8, 10),
        child: Row(
          children: [
            Expanded(
              child: Text(skill,
                  style: const TextStyle(
                      fontWeight: FontWeight.w800, fontSize: 14)),
            ),
            if (selected)
              DropdownButtonHideUnderline(
                child: DropdownButton<String>(
                  value: level,
                  isDense: true,
                  items: profileSkillLevels
                      .map((item) => DropdownMenuItem<String>(
                    value: item,
                    child: Text(item,
                        style: const TextStyle(
                            fontWeight: FontWeight.w700, fontSize: 12)),
                  ))
                      .toList(),
                  onChanged: (value) {
                    if (value == null) return;
                    setState(() => selectedSkills[skill] = value);
                  },
                ),
              )
            else
              TextButton(
                onPressed: () =>
                    setState(() => selectedSkills[skill] = 'Beginner'),
                child: const Text('Add',
                    style: TextStyle(fontWeight: FontWeight.w800)),
              ),
            if (selected)
              IconButton(
                tooltip: 'Remove',
                icon: const Icon(Icons.close_rounded, size: 19),
                onPressed: () =>
                    setState(() => selectedSkills.remove(skill)),
              ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        backgroundColor: AppColors.cream,
        foregroundColor: AppColors.ink,
        elevation: 0,
        centerTitle: true,
        title: Text(
          widget.isFirstSetup ? 'Set Up Your Profile' : 'Edit Your Profile',
          style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900, color: AppColors.ink),
        ),
      ),
      body: Container(
        width: double.infinity,
        height: double.infinity,
        color: AppColors.cream,
        child: SafeArea(
          child: LayoutBuilder(
            builder: (context, constraints) {
              return SingleChildScrollView(
                padding: const EdgeInsets.fromLTRB(18, 12, 18, 32),
                child: ConstrainedBox(
                  constraints: BoxConstraints(minHeight: constraints.maxHeight - 44),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (widget.isFirstSetup)
                        Container(
                          width: double.infinity,
                          margin: const EdgeInsets.only(bottom: 18),
                          padding: const EdgeInsets.all(16),
                          decoration: BoxDecoration(
                            color: const Color(0xFFECE8FF),
                            border: Border.all(color: AppColors.ink, width: 2),
                            borderRadius: BorderRadius.circular(12),
                            boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(4, 4), blurRadius: 0)],
                          ),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Container(
                                width: 30, height: 30,
                                decoration: BoxDecoration(color: const Color(0xFFD6CCFE), border: Border.all(color: AppColors.ink, width: 1.5), borderRadius: BorderRadius.circular(8), boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(2, 2), blurRadius: 0)]),
                                child: const Icon(Icons.auto_awesome_rounded, size: 18),
                              ),
                              SizedBox(width: 10),
                              Expanded(
                                child: Text(
                                  'Let’s build your PeerGrid profile. Add a few details '
                                      'so other students can discover your interests and '
                                      'technical skills.',
                                  style: TextStyle(
                                      fontWeight: FontWeight.w700, height: 1.4),
                                ),
