// =====================================================
// SPLASH SCREEN  (unchanged)
// =====================================================

class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});

  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen> {
  @override
  void initState() {
    super.initState();
    _checkExistingLogin();
  }

  Future<void> _checkExistingLogin() async {
    // Keep the existing splash-screen duration.
    await Future.delayed(const Duration(milliseconds: 2500));

    if (!mounted) return;

    final updateInfo = await _fetchAppUpdateInfo();
    if (!mounted) return;
    if (updateInfo != null) {
      final updateHandled = await _showAppUpdateDialog(context, updateInfo);
      if (!mounted) return;
      if (updateInfo.isMandatory && !updateHandled) {
        return;
      }
    }

    final user = FirebaseAuth.instance.currentUser;

    if (user != null) {
      final ban = await getActivePeerGridBan(user.uid);
      if (ban != null && !isPeerGridGlobalAdmin(user.uid)) {
        await FirebaseAuth.instance.signOut();
        if (!mounted) return;
        final reason = (ban['reason'] ?? '').toString().trim();
        final until = ban['expiresAt'];
        final expiryText = until is Timestamp
            ? 'This ban expires on ${until.toDate().toLocal()}.'
            : 'This ban is permanent.';
        Navigator.of(context).pushReplacement(FadePageRoute(page: _PeerGridBanNotice(
          reason: reason,
          expiryText: expiryText,
        )));
        return;
      }
      await _registerPushToken();
    }

    // No Firebase user is signed in: show the normal Welcome screen.
    if (user == null) {
      Navigator.of(context).pushReplacement(
        FadePageRoute(
          page: const WelcomeScreen(),
        ),
      );
      return;
    }

    // A Firebase session already exists. Check for a college-admin
    // account before restoring the normal student profile.
    final adminAccess = await getCollegeAdminAccess(user.uid);

    if (adminAccess != null) {
      if (!mounted) return;

      Navigator.of(context).pushReplacement(
        FadePageRoute(
          page: CollegeAdminDashboard(
            collegeId: adminAccess['collegeId']!,
          ),
        ),
      );

      return;
    }

    // Normal student session: restore the user's PeerGrid profile.
    try {
      final profile = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();

      final data = profile.data();

      if (data != null) {
        final name = data['name']?.toString().trim() ?? '';
        final college = data['college']?.toString().trim() ?? '';
        final hobbies = data['hobbies']?.toString().trim() ?? '';
        final setupIncomplete = data['profileSetupComplete'] == false;

        if (name.isNotEmpty) {
          userName.value = name;
        } else if ((user.displayName ?? '').trim().isNotEmpty) {
          userName.value = user.displayName!.trim();
        }

        if (college.isNotEmpty) {
          userCollege.value = college;
        }

        if (hobbies.isNotEmpty) {
          userHobbies.value = hobbies;
        }

        userUsername.value = data['username']?.toString().trim() ?? '';
        userYearOfStudy.value =
            data['yearOfStudy']?.toString().trim() ?? '';
        userProfileImage.value =
            data['profileImage']?.toString().trim() ?? '';

        final skills = data['technicalSkills'];
        if (skills is Map) {
          userTechnicalSkills.value = skills.map(
                (key, value) => MapEntry(key.toString(), value.toString()),
          );
        }

        if (setupIncomplete) {
          if (!mounted) return;
          Navigator.of(context).pushReplacement(
            FadePageRoute(
              page: const ProfileSetupScreen(isFirstSetup: true),
            ),
          );
          return;
        }
      } else if ((user.displayName ?? '').trim().isNotEmpty) {
        userName.value = user.displayName!.trim();
      }
    } catch (_) {
      // Authentication is still valid even if the profile cannot be read.
      if ((user.displayName ?? '').trim().isNotEmpty) {
        userName.value = user.displayName!.trim();
      }
    }

    if (!mounted) return;

    Navigator.of(context).pushReplacement(
      FadePageRoute(
        page: const MainShell(),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFFFC21A),
      body: SizedBox.expand(
        child: Image.asset(
          'assets/images/peergrid_splash.png',
          fit: BoxFit.cover,
          alignment: Alignment.center,
        ),
      ),
    );
  }
}

