class _WelcomeDotPatternPainter extends CustomPainter {
  const _WelcomeDotPatternPainter();

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = const Color(0xFFD3CBBE);
    for (double y = 8; y < size.height; y += 20) {
      for (double x = 8; x < size.width; x += 20) {
        canvas.drawCircle(Offset(x, y), 1.15, paint);
      }
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

