class SignInScreen extends StatefulWidget {
  const SignInScreen({super.key});

  @override
  State<SignInScreen> createState() => _SignInScreenState();
}

class _SignInScreenState extends State<SignInScreen> {
  final TextEditingController usernameController = TextEditingController();
  final TextEditingController passwordController = TextEditingController();
  bool hidePassword = true;
  bool loading = false;

  @override
  void dispose() {
    usernameController.dispose();
    passwordController.dispose();
    super.dispose();
  }

  Future<void> resetPassword() async {
    // Do not create a TextEditingController for the reset dialog.
    // The previous version disposed the controller immediately after
    // showDialog() returned while Flutter was still rebuilding the dialog,
    // which caused:
    // "A TextEditingController was used after being disposed."
    String resetEmail = usernameController.text.trim();

    final email = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(28),
          ),
          title: const Text(
            'Reset Password',
            style: TextStyle(fontWeight: FontWeight.w900),
          ),
          content: TextField(
            keyboardType: TextInputType.emailAddress,
            autofocus: true,
            onChanged: (value) {
              resetEmail = value;
            },
            decoration: authDecoration(
              hint: 'email',
              icon: Icons.email_outlined,
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text('Cancel'),
            ),
            TextButton(
              onPressed: () {
                Navigator.of(dialogContext).pop(resetEmail.trim());
              },
              child: const Text(
                'Send',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
            ),
          ],
        );
      },
    );

    if (!mounted || email == null) return;

    final cleanEmail = email.trim();

    if (cleanEmail.isEmpty || !cleanEmail.contains('@')) {
      showSnack(
        context,
        'Please enter a valid email address.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    try {
      await FirebaseAuth.instance.sendPasswordResetEmail(
        email: cleanEmail,
      );

      if (!mounted) return;

      showSnack(
        context,
        'Password reset email sent. Check your inbox.',
        bottomMargin: 16,
      );
    } on FirebaseAuthException catch (e) {
      if (!mounted) return;

      String message;

      switch (e.code) {
        case 'invalid-email':
          message = 'Please enter a valid email address.';
          break;
        case 'user-not-found':
          message = 'No account was found with this email.';
          break;
        case 'network-request-failed':
          message = 'Network error. Please check your internet connection.';
          break;
        default:
          message = e.message ??
              'Could not send the password reset email.';
      }

      showSnack(
        context,
        message,
        color: Colors.red,
        bottomMargin: 16,
      );
    } catch (_) {
      if (!mounted) return;

      showSnack(
        context,
        'Could not send the password reset email.',
        color: Colors.red,
        bottomMargin: 16,
      );
    }
  }

  Future<void> login() async {
    final email = usernameController.text.trim();
    final password = passwordController.text;
    FocusScope.of(context).unfocus();

    if (email.isEmpty) {
      showSnack(
        context,
        'Please enter your email address.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    if (password.isEmpty) {
      showSnack(
        context,
        'Please enter your password.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    setState(() => loading = true);

    try {
      final credential =
      await FirebaseAuth.instance.signInWithEmailAndPassword(
        email: email,
        password: password,
      );

      final user = credential.user;

      if (user == null) {
        throw Exception('Could not sign in.');
      }

      await _registerPushToken();

      // =================================================
      // CHECK COLLEGE ADMIN ACCESS
      // =================================================

      final adminAccess = await getCollegeAdminAccess(user.uid);

      if (adminAccess != null) {
        if (!mounted) return;

        Navigator.of(context).pushAndRemoveUntil(
          FadePageRoute(
            page: CollegeAdminDashboard(
              collegeId: adminAccess['collegeId']!,
            ),
          ),
              (route) => false,
        );

        return;
      }

      // Load the user's PeerGrid profile if it exists.
      // If the profile cannot be read, authentication is still successful,
      // so allow the user to continue into the app.
      try {
        final profile = await FirebaseFirestore.instance
            .collection('users')
            .doc(user.uid)
            .get();

        final data = profile.data();

        if (data != null) {
          final name = data['name']?.toString().trim() ?? '';
          final college = data['college']?.toString().trim() ?? '';
          final hobbies = data['hobbies']?.toString().trim() ?? '';
          final setupIncomplete = data['profileSetupComplete'] == false;

          if (name.isNotEmpty) {
            userName.value = name;
          } else if ((user.displayName ?? '').trim().isNotEmpty) {
            userName.value = user.displayName!.trim();
          }

          if (college.isNotEmpty) {
            userCollege.value = college;
          }

          if (hobbies.isNotEmpty) {
            userHobbies.value = hobbies;
          }

          userUsername.value = data['username']?.toString().trim() ?? '';
          userYearOfStudy.value =
              data['yearOfStudy']?.toString().trim() ?? '';
          userProfileImage.value =
              data['profileImage']?.toString().trim() ?? '';

          final skills = data['technicalSkills'];
          if (skills is Map) {
            userTechnicalSkills.value = skills.map(
                  (key, value) => MapEntry(key.toString(), value.toString()),
            );
          }

          if (setupIncomplete && mounted) {
            Navigator.of(context).pushAndRemoveUntil(
              FadePageRoute(
                page: const ProfileSetupScreen(isFirstSetup: true),
              ),
                  (route) => false,
            );
            return;
          }
        } else if ((user.displayName ?? '').trim().isNotEmpty) {
          userName.value = user.displayName!.trim();
        }
      } catch (_) {
        if ((user.displayName ?? '').trim().isNotEmpty) {
          userName.value = user.displayName!.trim();
        }
      }

      if (!mounted) return;

      Navigator.of(context).pushAndRemoveUntil(
        FadePageRoute(page: const MainShell()),
            (route) => false,
      );
    } on FirebaseAuthException catch (e) {
      String message;

      switch (e.code) {
        case 'invalid-credential':
        case 'wrong-password':
        case 'user-not-found':
          message = 'Incorrect email or password.';
          break;
        case 'invalid-email':
          message = 'Please enter a valid email address.';
          break;
        case 'user-disabled':
          message = 'This account has been disabled.';
          break;
        case 'too-many-requests':
          message = 'Too many attempts. Please try again later.';
          break;
        case 'network-request-failed':
          message = 'Network error. Please check your internet connection.';
          break;
        default:
          message = e.message ?? 'Could not sign in. Please try again.';
      }

      if (mounted) {
        showSnack(
          context,
          message,
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } catch (_) {
      if (mounted) {
        showSnack(
          context,
          'Something went wrong. Please try again.',
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } finally {
      if (mounted) {
        setState(() => loading = false);
      }
    }
  }

