class SignUpScreen extends StatefulWidget {
  const SignUpScreen({super.key});

  @override
  State<SignUpScreen> createState() => _SignUpScreenState();
}

class _SignUpScreenState extends State<SignUpScreen> {
  final nameController = TextEditingController();
  final emailController = TextEditingController();
  final collegeController = TextEditingController();
  final passwordController = TextEditingController();
  bool hidePassword = true;
  bool loading = false;

  @override
  void dispose() {
    nameController.dispose();
    emailController.dispose();
    collegeController.dispose();
    passwordController.dispose();
    super.dispose();
  }

  Future<void> createAccount() async {
    FocusScope.of(context).unfocus();

    final name = nameController.text.trim();
    final email = emailController.text.trim();
    final college = collegeController.text.trim();
    final password = passwordController.text;

    // -------------------------------
    // BASIC VALIDATION
    // -------------------------------

    if (name.isEmpty) {
      showSnack(
        context,
        'Please enter your full name.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    if (email.isEmpty || !email.contains('@')) {
      showSnack(
        context,
        'Please enter a valid email address.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    if (password.length < 6) {
      showSnack(
        context,
        'Password must be at least 6 characters.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    setState(() {
      loading = true;
    });

    try {
      // -------------------------------
      // CREATE FIREBASE AUTH ACCOUNT
      // -------------------------------

      final credential =
      await FirebaseAuth.instance.createUserWithEmailAndPassword(
        email: email,
        password: password,
      );

      final user = credential.user;

      if (user == null) {
        throw Exception('Could not create user account.');
      }

      await _registerPushToken();

      // -------------------------------
      // SAVE DISPLAY NAME
      // -------------------------------

      await user.updateDisplayName(name);

      // -------------------------------
      // CREATE FIRESTORE USER PROFILE
      // -------------------------------

      await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .set({
        'uid': user.uid,
        'name': name,
        'email': email,
        'college': college,
        'course': '',
        'bio': '',
        'hobbies': '',
        'profileImage': '',
        'profileSetupComplete': false,
        'privateChatEnabled': true,
        'nearbyEnabled': true,
        'discoverable': true,
        'createdAt': FieldValue.serverTimestamp(),
        'lastSeen': FieldValue.serverTimestamp(),
        'isOnline': true,
      });

      // -------------------------------
      // UPDATE CURRENT APP STATE
      // -------------------------------

      userName.value = name;

      if (college.isNotEmpty) {
        userCollege.value = college;
      }

      if (!mounted) return;

      // -------------------------------
      // GO TO PROFILE SETUP
      // -------------------------------

      Navigator.of(context).pushAndRemoveUntil(
        FadePageRoute(
          page: const ProfileSetupScreen(isFirstSetup: true),
        ),
            (route) => false,
      );
    } on FirebaseAuthException catch (e) {
      String message;

      switch (e.code) {
        case 'email-already-in-use':
          message = 'An account already exists with this email.';
          break;
        case 'invalid-email':
          message = 'Please enter a valid email address.';
          break;
        case 'weak-password':
          message = 'Please choose a stronger password.';
          break;
        case 'operation-not-allowed':
          message = 'Email/password sign-in is not enabled in Firebase.';
          break;
        case 'network-request-failed':
          message = 'Network error. Please check your internet connection.';
          break;
        default:
          message = e.message ?? 'Could not create your account.';
      }

      if (mounted) {
        showSnack(
          context,
          message,
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Something went wrong. Please try again.',
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } finally {
      if (mounted) {
        setState(() {
          loading = false;
        });
      }
    }
  }

