// =====================================================
// MAIN SHELL  (animated floating bottom navigation)
// =====================================================

class MainShell extends StatefulWidget {
  const MainShell({super.key});

  @override
  State<MainShell> createState() => _MainShellState();
}

class _MainShellState extends State<MainShell>
    with SingleTickerProviderStateMixin {
  final Set<int> _visited = <int>{0};
  late final AnimationController _fade = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 350),
    value: 1,
  );
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _banSubscription;
  bool _handlingBan = false;

  @override
  void initState() {
    super.initState();
    navIndex.value = 0;
    navIndex.addListener(_onNav);
    final user = FirebaseAuth.instance.currentUser;
    if (user != null && !isPeerGridGlobalAdmin(user.uid)) {
      _banSubscription = FirebaseFirestore.instance.collection('userBans').doc(user.uid).snapshots().listen((snapshot) async {
        if (!mounted || _handlingBan || !snapshot.exists) return;
        final ban = snapshot.data() ?? <String, dynamic>{};
        final expiry = ban['expiresAt'];
        if (expiry is Timestamp && !expiry.toDate().isAfter(DateTime.now())) return;
        _handlingBan = true;
        final reason = (ban['reason'] ?? '').toString().trim();
        final expiryText = expiry is Timestamp
            ? 'This ban expires on ${expiry.toDate().toLocal()}.'
            : 'This ban is permanent.';
        await FirebaseAuth.instance.signOut();
        if (!mounted) return;
        Navigator.of(context).pushAndRemoveUntil(
          FadePageRoute(page: _PeerGridBanNotice(reason: reason, expiryText: expiryText)),
              (route) => false,
        );
      });
    }
  }

  void _onNav() {
    if (!mounted) return;
    setState(() => _visited.add(navIndex.value));
    _fade.forward(from: 0);
  }

  @override
  void dispose() {
    navIndex.removeListener(_onNav);
    _banSubscription?.cancel();
    _fade.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final pages = <Widget>[
      const HomeScreen(),
      const EventsScreen(),
      const CommunityScreen(),
      const ExploreScreen(),
      const ProfileScreen(),
    ];

    return Scaffold(
      backgroundColor: Colors.white,
      body: Stack(
        children: [
          Positioned.fill(
            child: FadeTransition(
              opacity: _fade.drive(CurveTween(curve: Curves.easeOut)),
              child: IndexedStack(
                index: navIndex.value,
                children: [
                  for (int i = 0; i < pages.length; i++)
                    _visited.contains(i) ? pages[i] : const SizedBox.shrink(),
                ],
              ),
            ),
          ),
          Positioned(
            left: 16,
            right: 16,
            bottom: 16 + MediaQuery.of(context).padding.bottom,
            child: FloatingNavBar(
              currentIndex: navIndex.value,
              onTap: (i) => navIndex.value = i,
            ),
          ),
        ],
      ),
    );
  }
}



