class _CreateStoryScreen extends StatefulWidget {
  const _CreateStoryScreen();
  @override
  State<_CreateStoryScreen> createState() => _CreateStoryScreenState();
}

class _CreateStoryScreenState extends State<_CreateStoryScreen> {
  final _text = TextEditingController();
  final _musicTitle = TextEditingController();
  final _musicArtist = TextEditingController();
  XFile? _media;
  String _mediaType = 'text';
  bool _busy = false;
  bool _friendsLoaded = false;
  final Set<String> _selectedAudience = <String>{};
  List<Map<String, String>> _friends = <Map<String, String>>[];

  @override
  void initState() { super.initState(); _loadFriends(); }

  @override
  void dispose() { _text.dispose(); _musicTitle.dispose(); _musicArtist.dispose(); super.dispose(); }

  Future<void> _loadFriends() async {
    final uid = _currentUid();
    if (uid.isEmpty) { if (mounted) setState(() => _friendsLoaded = true); return; }
    try {
      final snap = await FirebaseFirestore.instance.collection('users').doc(uid).collection('following').get();
      final list = <Map<String, String>>[];
      for (final f in snap.docs) {
        final friendUid = f.id;
        final data = await FirebaseFirestore.instance.collection('users').doc(friendUid).get();
        final profile = data.data() ?? <String, dynamic>{};
        list.add({'uid': friendUid, 'name': (profile['name'] ?? profile['displayName'] ?? f.data()['name'] ?? 'Student').toString(), 'image': (profile['profileImage'] ?? '').toString()});
      }
      if (!mounted) return;
      setState(() { _friends = list; _selectedAudience.addAll(list.map((e) => e['uid']!)); _friendsLoaded = true; });
    } catch (_) { if (mounted) setState(() => _friendsLoaded = true); }
  }

  Future<void> _pickMedia(bool video) async {
    try {
      final picked = video
          ? await ImagePicker().pickVideo(source: ImageSource.gallery, maxDuration: const Duration(seconds: 60))
          : await _pickAndCropImage(source: ImageSource.gallery, imageQuality: 88);
      if (picked == null || !mounted) return;
      setState(() { _media = picked; _mediaType = video ? 'video' : 'image'; });
    } catch (_) { if (mounted) showSnack(context, 'Could not select media.'); }
  }

  Future<void> _publish() async {
    final uid = _currentUid();
    if (uid.isEmpty) { showSnack(context, 'Sign in to share a story.'); return; }
    if (_media == null && _text.text.trim().isEmpty && _musicTitle.text.trim().isEmpty) {
      showSnack(context, 'Add text, a photo/video, or a music status.'); return;
    }
    if (_selectedAudience.isEmpty) {
      showSnack(context, 'Choose at least one friend who can view this update.'); return;
    }
    setState(() => _busy = true);
    try {
      final db = FirebaseFirestore.instance;
      final ref = db.collection('stories').doc();
      String mediaUrl = '';
      if (_media != null) {
        final storageRef = FirebaseStorage.instance.ref().child('stories/$uid/${ref.id}/media');
        final metadata = SettableMetadata(contentType: _mediaType == 'video' ? 'video/mp4' : 'image/jpeg');
        await storageRef.putFile(File(_media!.path), metadata);
        mediaUrl = await storageRef.getDownloadURL();
      }
      final user = await db.collection('users').doc(uid).get();
      final profile = user.data() ?? <String, dynamic>{};
      await ref.set({
        'authorId': uid,
        'authorName': (profile['name'] ?? profile['displayName'] ?? userName.value).toString(),
        'authorProfileImage': (profile['profileImage'] ?? userProfileImage.value).toString(),
        'text': _text.text.trim(),
        'mediaUrl': mediaUrl,
        'mediaType': _mediaType == 'text' && _musicTitle.text.trim().isNotEmpty ? 'music' : _mediaType,
        'musicTitle': _musicTitle.text.trim(),
        'musicArtist': _musicArtist.text.trim(),
        'audienceUids': <String>{..._selectedAudience, uid}.toList(),
        'createdAt': FieldValue.serverTimestamp(),
        'expiresAt': Timestamp.fromDate(DateTime.now().add(const Duration(hours: 24))),
      });
      if (!mounted) return;
      Navigator.of(context).pop();
      showSnack(context, 'Story shared with ${_selectedAudience.length} friend(s).');
    } catch (_) {
      if (mounted) showSnack(context, 'Could not publish story. Check Firestore and Storage rules.');
    } finally { if (mounted) setState(() => _busy = false); }
  }

  @override
  Widget build(BuildContext context) {
    final selectedCount = _selectedAudience.length;
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        backgroundColor: AppColors.cream,
