  Widget _storyActionButton({
    required IconData icon,
    required String label,
    required Color color,
    required VoidCallback? onPressed,
  }) {
    return SizedBox(
      height: 56,
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: Colors.white,
          border: Border.all(color: AppColors.ink, width: 2),
          borderRadius: BorderRadius.circular(14),
          boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(3, 3), blurRadius: 0)],
        ),
        child: OutlinedButton.icon(
          onPressed: onPressed,
          style: OutlinedButton.styleFrom(
            foregroundColor: AppColors.ink,
            backgroundColor: Colors.white,
            side: BorderSide.none,
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          ),
          icon: Icon(icon, color: color, size: 22),
          label: Text(label, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 14)),
        ),
      ),
    );
  }

}


class _StoryViewerScreen extends StatefulWidget {
  final List<QueryDocumentSnapshot<Map<String, dynamic>>> stories;
  final int initialIndex;
  final String currentUid;
  const _StoryViewerScreen({required this.stories, required this.initialIndex, required this.currentUid});
  @override
  State<_StoryViewerScreen> createState() => _StoryViewerScreenState();
}

class _StoryViewerScreenState extends State<_StoryViewerScreen> {
  late int _index;
  Timer? _timer;
  double _progress = 0;
  VideoPlayerController? _video;
  final TextEditingController _reply = TextEditingController();

  QueryDocumentSnapshot<Map<String, dynamic>> get _current => widget.stories[_index];
  Map<String, dynamic> get _data => _current.data();

  @override
  void initState() {
    super.initState();
    _index = widget.initialIndex.clamp(0, widget.stories.length - 1).toInt();
    _startProgress();
  }

  void _startProgress() {
    _timer?.cancel();
    _video?.dispose();
    _video = null;
    _progress = 0;
    final d = _data;
    final type = (d['mediaType'] ?? '').toString();
    final url = (d['mediaUrl'] ?? '').toString();
    if (type == 'video' && url.isNotEmpty) {
      _video = VideoPlayerController.networkUrl(Uri.parse(url))
        ..initialize().then((_) { if (mounted) { setState(() {}); _video?.play(); } });
    }
    _timer = Timer.periodic(const Duration(milliseconds: 100), (timer) {
      if (!mounted) return;
      setState(() => _progress = (_progress + .02).clamp(0.0, 1.0));
      if (_progress >= 1) _next();
    });
  }

  void _next() {
    if (_index < widget.stories.length - 1) {
      setState(() => _index++);
      _startProgress();
    } else {
      Navigator.of(context).maybePop();
    }
  }

  void _previous() {
    if (_index > 0) {
      setState(() => _index--);
      _startProgress();
    } else {
      _startProgress();
    }
  }

  Future<void> _sendReply() async {
    final message = _reply.text.trim();
    if (message.isEmpty) return;
    try {
      await _current.reference.collection('replies').add({
        'authorId': widget.currentUid,
        'text': message,
        'createdAt': FieldValue.serverTimestamp(),
      });
      _reply.clear();
      if (mounted) showSnack(context, 'Reply sent.');
    } catch (_) {
      if (mounted) showSnack(context, 'Could not send reply. Check story reply permissions.');
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    _video?.dispose();
    _reply.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final d = _data;
    final type = (d['mediaType'] ?? 'text').toString();
    final url = (d['mediaUrl'] ?? '').toString();
    final music = (d['musicTitle'] ?? '').toString();
    final artist = (d['musicArtist'] ?? '').toString();
    final authorId = (d['authorId'] ?? '').toString();
    final own = authorId == widget.currentUid;
    return Scaffold(
      backgroundColor: Colors.black,
      body: SafeArea(
        child: Stack(children: [
          Positioned.fill(
            child: GestureDetector(
              onTapUp: (details) {
                final width = MediaQuery.of(context).size.width;
                if (details.localPosition.dx < width * .35) { _previous(); } else { _next(); }
              },
              child: Container(
                alignment: Alignment.center,
                color: type == 'text' || type == 'music' ? const Color(0xFF25221D) : Colors.black,
                child: type == 'image' && url.isNotEmpty
                    ? Image.network(url, fit: BoxFit.contain, width: double.infinity, errorBuilder: (_, __, ___) => const Icon(Icons.broken_image_rounded, color: Colors.white, size: 64))
                    : type == 'video' && _video != null
                    ? (_video!.value.isInitialized ? AspectRatio(aspectRatio: _video!.value.aspectRatio, child: VideoPlayer(_video!)) : const CircularProgressIndicator())
                    : Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                  Icon(type == 'music' ? Icons.music_note_rounded : Icons.auto_awesome_rounded, size: 72, color: _HomeDesign.yellow),
                  if (music.isNotEmpty) Padding(padding: const EdgeInsets.only(top: 18), child: Text('♫ $music${artist.isNotEmpty ? ' · $artist' : ''}', textAlign: TextAlign.center, style: const TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.w900))),
                  if ((d['text'] ?? '').toString().trim().isNotEmpty) Padding(padding: const EdgeInsets.only(top: 18), child: Text(d['text'].toString(), textAlign: TextAlign.center, style: const TextStyle(color: Colors.white, fontSize: 21, fontWeight: FontWeight.w800))),
                ])),
              ),
            ),
          ),
          Positioned(top: 12, left: 12, right: 12, child: Column(children: [
            Row(children: List.generate(widget.stories.length, (i) => Expanded(child: Container(
              margin: const EdgeInsets.symmetric(horizontal: 2),
              height: 3,
              decoration: BoxDecoration(color: Colors.white24, borderRadius: BorderRadius.circular(4)),
              child: FractionallySizedBox(alignment: Alignment.centerLeft, widthFactor: i < _index ? 1 : i == _index ? _progress : 0, child: Container(decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(4)))),
            )))),
            const SizedBox(height: 12),
            Row(children: [
              CircleAvatar(radius: 18, backgroundImage: (d['authorProfileImage'] ?? '').toString().isNotEmpty ? NetworkImage(d['authorProfileImage'].toString()) : null, child: (d['authorProfileImage'] ?? '').toString().isEmpty ? const Icon(Icons.person) : null),
              const SizedBox(width: 9),
              Expanded(child: Text((d['authorName'] ?? 'Student').toString(), style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900))),
              if (own) IconButton(onPressed: () async {
                final yes = await showDialog<bool>(context: context, builder: (ctx) => AlertDialog(
                  title: const Text('Delete story?'),
                  actions: [
                    TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                    FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Delete')),
                  ],
                ));
                if (yes == true) {
                  try {
                    final media = (d['mediaUrl'] ?? '').toString();
                    if (media.isNotEmpty) { try { await FirebaseStorage.instance.refFromURL(media).delete(); } catch (_) {} }
                    await _current.reference.delete();
                    if (mounted) Navigator.pop(context);
                  } catch (_) { if (mounted) showSnack(context, 'Could not delete story.'); }
                }
              }, icon: const Icon(Icons.delete_outline, color: Colors.white)),
              IconButton(onPressed: () => Navigator.pop(context), icon: const Icon(Icons.close_rounded, color: Colors.white)),
            ]),
          ])),
          Positioned(left: 14, right: 14, bottom: 12, child: Row(children: [
            Expanded(child: TextField(
              controller: _reply,
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                hintText: 'Reply to story…',
                hintStyle: const TextStyle(color: Colors.white70),
                filled: true,
                fillColor: Colors.white12,
                contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(28), borderSide: const BorderSide(color: Colors.white54)),
                enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(28), borderSide: const BorderSide(color: Colors.white54)),
              ),
            )),
            const SizedBox(width: 8),
            IconButton(onPressed: _sendReply, icon: const Icon(Icons.send_rounded, color: Colors.white)),
          ])),
        ]),
      ),
    );
  }
}


class _HomeStoriesPreview extends StatelessWidget {
  const _HomeStoriesPreview();

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Padding(
      // Keep the Stories row open on the homepage: no enclosing card or box.
      padding: const EdgeInsets.fromLTRB(22, 0, 22, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              const Text(
                'Pages',
                style: TextStyle(
                  color: _HomeDesign.ink,
                  fontSize: 16,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -.2,
                ),
              ),
              const SizedBox(width: 8),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
                decoration: BoxDecoration(
                  color: const Color(0xFFFFEAE4),
                  border: Border.all(color: _HomeDesign.orange, width: 1),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: const Text(
                  'STORIES',
                  style: TextStyle(
                    color: _HomeDesign.orange,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    letterSpacing: .3,
                  ),
                ),
              ),
              const Spacer(),

            ],
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 92,
            child: uid.isEmpty
                ? ListView(
              scrollDirection: Axis.horizontal,
              children: [
                _StoryCircle(
                  name: 'Add story',
                  image: userProfileImage.value,
                  isAdd: true,
                  viewed: false,
                  onTap: () => pushPage(context, const _CreateStoryScreen()),
                ),
              ],
            )
                : StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance
                  .collection('stories')
                  .where('audienceUids', arrayContains: uid)
                  .snapshots(),
              builder: (context, snapshot) {
                final docs = (snapshot.data?.docs ?? []).where((doc) {
                  final expiry = doc.data()['expiresAt'];
                  return expiry is Timestamp && expiry.toDate().isAfter(DateTime.now());
                }).toList()
                  ..sort((a, b) {
                    final av = a.data()['createdAt'];
                    final bv = b.data()['createdAt'];
                    return (bv is Timestamp ? bv.toDate() : DateTime(2000))
                        .compareTo(av is Timestamp ? av.toDate() : DateTime(2000));
                  });
                final authors = <String, QueryDocumentSnapshot<Map<String, dynamic>>>{};
                for (final doc in docs) {
                  authors.putIfAbsent((doc.data()['authorId'] ?? '').toString(), () => doc);
                }
                return ListView(
                  scrollDirection: Axis.horizontal,
                  padding: EdgeInsets.zero,
                  children: [
                    _StoryCircle(
                      name: 'Add story',
                      image: userProfileImage.value,
                      isAdd: true,
                      viewed: false,
                      onTap: () => pushPage(context, const _CreateStoryScreen()),
                    ),
                    ...authors.entries.map((entry) {
                      final doc = entry.value;
                      return _StoryCircle(
                        name: entry.key == uid
                            ? 'Your story'
                            : (doc.data()['authorName'] ?? 'Student').toString(),
                        image: (doc.data()['authorProfileImage'] ?? '').toString(),
                        viewed: false,
                        onTap: () {
                          final authorStories = docs.where((story) =>
                          (story.data()['authorId'] ?? '').toString() == entry.key
                          ).toList();
                          if (authorStories.isEmpty) return;
                          pushPage(
                            context,
                            _StoryViewerScreen(
                              stories: authorStories,
                              initialIndex: 0,
                              currentUid: uid,
                            ),
                          );
                        },
                      );
                    }),
                  ],
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// =====================================================
// WHAT'S NEXT — swipeable campus card deck + global-admin card editor
// Firestore collection: whatNextCards/{cardId}
// =====================================================
class WhatNextCardData {
  final String id, title, subtitle, badge, destination, emoji;
  final int accent;
  final int order;
  const WhatNextCardData({required this.id, required this.title, required this.subtitle, required this.badge, required this.destination, required this.emoji, required this.accent, required this.order});
  factory WhatNextCardData.fromDoc(QueryDocumentSnapshot<Map<String, dynamic>> d) {
    final x = d.data();
    return WhatNextCardData(id: d.id, title: '${x['title'] ?? 'Campus update'}', subtitle: '${x['subtitle'] ?? ''}', badge: '${x['badge'] ?? 'FEATURED'}', destination: '${x['destination'] ?? 'games'}', emoji: '${x['emoji'] ?? '✨'}', accent: (x['accent'] as num?)?.toInt() ?? 0xFF34D399, order: (x['order'] as num?)?.toInt() ?? 0);
  }
  Map<String, dynamic> toMap() => {'title': title, 'subtitle': subtitle, 'badge': badge, 'destination': destination, 'emoji': emoji, 'accent': accent, 'order': order, 'updatedAt': FieldValue.serverTimestamp()};
}

class WhatsNextScreen extends StatefulWidget {
  const WhatsNextScreen({super.key});
  @override State<WhatsNextScreen> createState() => _WhatsNextScreenState();
}
class _WhatsNextScreenState extends State<WhatsNextScreen> {
  int index = 0;
  double dragX = 0;
  bool get isGlobalAdmin => FirebaseAuth.instance.currentUser?.uid == peerGridGlobalAdminUid;
  final _cards = FirebaseFirestore.instance.collection('whatNextCards');
  List<WhatNextCardData> get defaults => const [
    WhatNextCardData(id:'default_games', title:'NEO TIC-TAC-TOE', subtitle:'Instant 1v1 turn-based duels on the campus grid. Challenge friends and play Tic-Tac-Toe.', badge:'NEW CAMPUS GAME', destination:'games', emoji:'🎮', accent:0xFF34D399, order:0),
    WhatNextCardData(id:'default_leaderboard', title:'PEER RANKINGS: INFLUENCE & IMPACT', subtitle:'Discover student rankings and explore the PeerGrid leaderboard.', badge:'STUDENT LEADERBOARD', destination:'leaderboard', emoji:'🏆', accent:0xFFFFD23F, order:1),
  ];
  @override void initState() { super.initState(); _seedDefaultCardsForAdmin(); }
  Future<void> _seedDefaultCardsForAdmin() async {
    if (!isGlobalAdmin) return;
    try {
      final existing = await _cards.limit(1).get();
      if (existing.docs.isNotEmpty) return;
      final batch = FirebaseFirestore.instance.batch();
      for (final card in defaults) { batch.set(_cards.doc(card.id), {...card.toMap(), 'createdBy': peerGridGlobalAdminUid}); }
      await batch.commit();
    } catch (_) { /* Firestore rules must explicitly authorize the global admin. */ }
  }
  void _move(int delta, int length) { if (length == 0) return; setState(() { index = (index + delta).clamp(0, length - 1); dragX = 0; }); }
  void _openDestination(String destination) {
    switch (destination) {
      case 'games': pushPage(context, const GamesHubScreen()); break;
      case 'leaderboard': pushPage(context, const LeaderboardScreen()); break;
      default: showSnack(context, 'This card has no supported destination yet.');
    }
  }
  Future<void> _editCard({WhatNextCardData? card}) async {
    final title = TextEditingController(text: card?.title ?? '');
    final subtitle = TextEditingController(text: card?.subtitle ?? '');
    final badge = TextEditingController(text: card?.badge ?? 'FEATURED');
    final emoji = TextEditingController(text: card?.emoji ?? '✨');
    String destination = card?.destination ?? 'games';
    int accent = card?.accent ?? 0xFF34D399;
    final result = await showDialog<bool>(context: context, builder: (dialogContext) => StatefulBuilder(builder: (context, setDialogState) => AlertDialog(
      title: Text(card == null ? 'Craft a What’s Next card' : 'Edit card', style: const TextStyle(fontWeight: FontWeight.w900)),
      content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: title, decoration: const InputDecoration(labelText: 'Card headline'), maxLength: 72),
        TextField(controller: subtitle, decoration: const InputDecoration(labelText: 'Description'), maxLines: 3, maxLength: 220),
        TextField(controller: badge, decoration: const InputDecoration(labelText: 'Top badge'), maxLength: 32),
        TextField(controller: emoji, decoration: const InputDecoration(labelText: 'Emoji / icon'), maxLength: 4),
        const SizedBox(height: 10), DropdownButtonFormField<String>(value: destination, decoration: const InputDecoration(labelText: 'Open page'), items: const [DropdownMenuItem(value:'games', child:Text('Games / Tic-Tac-Toe hub')), DropdownMenuItem(value:'leaderboard', child:Text('Leaderboard'))], onChanged: (v) => setDialogState(() => destination = v ?? 'games')),
        const SizedBox(height: 12), Wrap(spacing: 10, children: [0xFF34D399, 0xFFFFD23F, 0xFFFF5A36, 0xFF62D9FF, 0xFFB9A8F5].map((c) => GestureDetector(onTap: () => setDialogState(() => accent = c), child: Container(width: 30, height: 30, decoration: BoxDecoration(color: Color(c), border: Border.all(color: accent == c ? Colors.black : Colors.grey, width: accent == c ? 3 : 1), borderRadius: BorderRadius.circular(7))))).toList()),
      ])), actions: [TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Save card'))],
    )));
    if (result != true) return;
    if (title.text.trim().isEmpty || subtitle.text.trim().isEmpty) { if (mounted) showSnack(context, 'Add a headline and description first.'); return; }
    try {
      final ref = card == null ? _cards.doc() : _cards.doc(card.id);
      await ref.set({'title': title.text.trim(), 'subtitle': subtitle.text.trim(), 'badge': badge.text.trim().isEmpty ? 'FEATURED' : badge.text.trim(), 'emoji': emoji.text.trim().isEmpty ? '✨' : emoji.text.trim(), 'destination': destination, 'accent': accent, 'order': card?.order ?? DateTime.now().millisecondsSinceEpoch, 'updatedAt': FieldValue.serverTimestamp(), 'createdBy': peerGridGlobalAdminUid}, SetOptions(merge: true));
      if (mounted) showSnack(context, 'What’s Next card saved.');
    } catch (_) { if (mounted) showSnack(context, 'Could not save card. Check Firestore rules.'); }
  }
  Future<void> _deleteCard(WhatNextCardData card) async {
    final yes = await showDialog<bool>(context: context, builder: (c) => AlertDialog(title: const Text('Remove this card?'), content: Text('“${card.title}” will disappear from What’s Next.'), actions: [TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Keep')), FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Remove'))]));
    if (yes != true) return;
    try { await _cards.doc(card.id).delete(); if (mounted) showSnack(context, 'Card removed.'); } catch (_) { if (mounted) showSnack(context, 'Could not remove card. Check Firestore rules.'); }
  }
  Widget _deck(List<WhatNextCardData> cards) {
    if (cards.isEmpty) {
      return const Center(
        child: Text(
          'No cards published yet.',
          style: TextStyle(color: Colors.white70),
        ),
      );
    }

    final safeIndex = index.clamp(0, cards.length - 1);
    final card = cards[safeIndex];

    return Column(
      children: [
        Row(
          children: [
            const Icon(Icons.diamond, color: Color(0xFF34D399), size: 15),
            const SizedBox(width: 7),
            Text(
              'CARD ${safeIndex + 1} OF ${cards.length}',
              style: const TextStyle(
                color: Color(0xFF6EE7B7),
                fontWeight: FontWeight.w900,
                letterSpacing: 1,
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),
        Expanded(
          child: GestureDetector(
            onHorizontalDragUpdate: (details) {
              setState(() => dragX += details.delta.dx);
