    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const SizedBox(height: 30),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 22),
          child: Row(
            children: [
              const Expanded(
                child: Text(
                  'Upcoming Events',
                  style: TextStyle(
                    color: _HomeDesign.ink,
                    fontSize: 21,
                    fontWeight: FontWeight.w900,
                    letterSpacing: -0.4,
                  ),
                ),
              ),
              Pressable(
                onTap: () => navIndex.value = 1,
                child: const Row(
                  children: [
                    Text(
                      'View all',
                      style: TextStyle(
                        color: _HomeDesign.ink,
                        fontSize: 12,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    SizedBox(width: 4),
                    Icon(
                      Icons.north_east_rounded,
                      size: 16,
                      color: _HomeDesign.ink,
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 14),
        StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: FirebaseFirestore.instance
              .collection('colleges')
              .doc('ihrd_008')
              .collection('events')
              .snapshots(),
          builder: (context, snapshot) {
            final liveEvents = <AppEvent>[];
            for (final doc in snapshot.data?.docs ?? const []) {
              liveEvents.add(
                _liveCollegeEventToAppEvent(
                  'ihrd_008',
                  doc.id,
                  doc.data(),
                ),
              );
            }

            final combined = <AppEvent>[
              ...liveEvents,
              ...sampleEvents,
            ];

            if (combined.isEmpty) {
              return const Padding(
                padding: EdgeInsets.symmetric(horizontal: 22),
                child: Text(
                  'No upcoming events yet.',
                  style: TextStyle(
                    color: _HomeDesign.muted,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              );
            }

            return Padding(
              padding: const EdgeInsets.symmetric(horizontal: 22),
              child: _HomeEventCard(event: combined.first),
            );
          },
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _HomeDesign.cream,
      body: SafeArea(
        bottom: false,
        child: GestureDetector(
          onHorizontalDragEnd: (details) {
            final velocity = details.primaryVelocity ?? 0;
            if (velocity.abs() < 350) return;
            Navigator.of(context).push(
              SlideFadeRoute(page: const ChatHubScreen()),
            );
          },
          child: RefreshIndicator(
            color: AppColors.blue,
            onRefresh: () async {
              // Home sections are Firestore-backed streams, so they update
              // automatically; complete the pull gesture without blocking on
              // pending writes when the device is offline.
              await Future<void>.delayed(const Duration(milliseconds: 350));
            },
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.only(bottom: 130),
              children: [
                _homeHeader(context),
                _campusHeading(),
                _greeting(),
                Entrance(
                  delayMs: 80,
                  child: _predictCard(context),
                ),
                Entrance(
                  delayMs: 140,
                  child: _quickActions(context),
                ),
                Entrance(
                  delayMs: 175,
                  child: const _HomeStoriesPreview(),
                ),
                Entrance(
                  delayMs: 190,
                  child: _radarCard(context),
                ),
                Entrance(
                  delayMs: 230,
                  child: _collegeHubCard(context),
                ),
                const SizedBox(height: 28),
                const SizedBox(height: 30),
              ],
            ),
          ),
        ),
      ),
    );
  }
}


