class _AnimatedCampusIllustration extends StatefulWidget {
  const _AnimatedCampusIllustration();

  @override
  State<_AnimatedCampusIllustration> createState() =>
      _AnimatedCampusIllustrationState();
}

class _AnimatedCampusIllustrationState extends State<_AnimatedCampusIllustration>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 8),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Widget _cloud(double width, double height) => Container(
    width: width,
    height: height,
    decoration: BoxDecoration(
      color: Colors.white,
      border: Border.all(color: _HomeDesign.ink, width: 1.5),
      borderRadius: BorderRadius.circular(height),
      boxShadow: const [
        BoxShadow(color: _HomeDesign.ink, offset: Offset(1, 1), blurRadius: 0),
      ],
    ),
  );

  Widget _tree({required double sway, required Color leafColor}) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Transform.rotate(
        angle: sway,
        child: Container(
          width: 30,
          height: 30,
          decoration: BoxDecoration(
            color: leafColor,
            shape: BoxShape.circle,
            border: Border.all(color: _HomeDesign.ink, width: 1.8),
          ),
          child: const Icon(Icons.add, size: 13, color: _HomeDesign.ink),
        ),
      ),
      Container(width: 5, height: 20, color: const Color(0xFF795548)),
    ],
  );

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(builder: (context, constraints) {
      final w = constraints.maxWidth;
      return AnimatedBuilder(
        animation: _controller,
        builder: (context, _) {
          final phase = _controller.value * math.pi * 2;
          final cloudDx = math.sin(phase) * 10;
          final flagAngle = math.sin(phase * 1.4) * .10;
          final windowOpacity = .55 + ((math.sin(phase * 1.8) + 1) / 2) * .45;
          return Stack(
            clipBehavior: Clip.hardEdge,
            alignment: Alignment.bottomCenter,
            children: [
              // Warm sun and little printed rays add depth without gradients.
              Positioned(
                top: 12,
                right: w * .23,
                child: Transform.rotate(
                  angle: phase * .08,
                  child: Container(
                    width: 31,
                    height: 31,
                    decoration: BoxDecoration(
                      color: _HomeDesign.yellow,
                      shape: BoxShape.circle,
                      border: Border.all(color: _HomeDesign.ink, width: 1.8),
                    ),
                    child: const Icon(Icons.wb_sunny_rounded, size: 17, color: _HomeDesign.ink),
                  ),
                ),
              ),
              Positioned(left: 24 + cloudDx, top: 27, child: _cloud(42, 16)),
              Positioned(right: 22 - cloudDx, top: 39, child: _cloud(32, 13)),
              Positioned(left: 25, bottom: 7, child: _tree(sway: math.sin(phase) * .07, leafColor: _HomeDesign.green)),
              Positioned(right: 25, bottom: 7, child: _tree(sway: -math.sin(phase) * .07, leafColor: const Color(0xFF18B981))),
              Positioned(left: 0, right: 0, bottom: 7, child: Container(height: 2.5, color: _HomeDesign.ink)),
              Positioned(
                bottom: 8,
                child: SizedBox(
                  width: math.min(w * .70, 242),
                  height: 106,
                  child: Stack(
                    alignment: Alignment.bottomCenter,
                    children: [
                      // Side wings with small, gently pulsing windows.
                      Positioned(
                        bottom: 0, left: 0,
                        child: Container(
                          width: 53, height: 51,
                          decoration: BoxDecoration(color: _HomeDesign.orange, border: Border.all(color: _HomeDesign.ink, width: 2)),
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(7, 13, 7, 5),
                            child: Opacity(opacity: windowOpacity, child: const Row(children: [Expanded(child: _CampusWindow()), SizedBox(width: 5), Expanded(child: _CampusWindow())])),
                          ),
                        ),
                      ),
                      Positioned(
                        bottom: 0, right: 0,
                        child: Container(
                          width: 53, height: 51,
                          decoration: BoxDecoration(color: _HomeDesign.orange, border: Border.all(color: _HomeDesign.ink, width: 2)),
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(7, 13, 7, 5),
                            child: Opacity(opacity: windowOpacity, child: const Row(children: [Expanded(child: _CampusWindow()), SizedBox(width: 5), Expanded(child: _CampusWindow())])),
                          ),
                        ),
                      ),
                      Positioned(
                        bottom: 0, left: 16, right: 16,
                        child: Container(
                          height: 76,
                          decoration: BoxDecoration(color: const Color(0xFFFFFDF8), border: Border.all(color: _HomeDesign.ink, width: 2)),
                          child: Column(
                            children: [
                              Container(height: 9, color: _HomeDesign.yellow),
                              Expanded(
                                child: Row(
                                  children: [
                                    const SizedBox(width: 8),
                                    ...List.generate(3, (i) => Expanded(child: Padding(
                                      padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
                                      child: Opacity(opacity: windowOpacity, child: const _CampusWindow()),
                                    ))),
                                    const SizedBox(width: 8),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                      Positioned(
                        bottom: 76,
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.end,
                          children: [
                            Container(width: 5, height: 23, color: _HomeDesign.ink),
                            Transform.rotate(
                              angle: flagAngle,
                              alignment: Alignment.centerLeft,
                              child: Container(
                                width: 57, height: 23,
                                decoration: BoxDecoration(color: _HomeDesign.yellow, border: Border.all(color: _HomeDesign.ink, width: 1.8), boxShadow: const [BoxShadow(color: _HomeDesign.ink, offset: Offset(1, 1), blurRadius: 0)]),
                                child: const Center(child: Text('CAMPUS', style: TextStyle(fontSize: 8, fontWeight: FontWeight.w900, letterSpacing: .5, color: _HomeDesign.ink))),
                              ),
                            ),
                          ],
                        ),
                      ),
                      Positioned(
                        bottom: 0,
                        child: Container(
                          width: 16, height: 35,
                          decoration: const BoxDecoration(color: _HomeDesign.ink, borderRadius: BorderRadius.vertical(top: Radius.circular(9))),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          );
        },
      );
    });
  }
}

