class StudentOfficialCollegeUpdates extends StatelessWidget {
  const StudentOfficialCollegeUpdates({super.key});

  String _formatDate(dynamic value) {
    if (value is Timestamp) {
      final d = value.toDate();
      const months = <String>[
        'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
      ];
      return '${d.day} ${months[d.month - 1]} ${d.year}';
    }
    return 'Recently';
  }

  @override
  Widget build(BuildContext context) {
    const collegeId = 'ihrd_008';

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('colleges')
          .doc(collegeId)
          .collection('posts')
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return const SizedBox.shrink();
        }

        final docs = [
          ...(snapshot.data?.docs ??
              <QueryDocumentSnapshot<Map<String, dynamic>>>[])
        ];

        docs.sort((a, b) {
          final aValue = a.data()['createdAt'];
          final bValue = b.data()['createdAt'];
          final aDate =
          aValue is Timestamp ? aValue.toDate() : DateTime(2000);
          final bDate =
          bValue is Timestamp ? bValue.toDate() : DateTime(2000);
          return bDate.compareTo(aDate);
        });

        final latest = docs.take(1).toList();

        if (latest.isEmpty) return const SizedBox.shrink();

        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 22),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  const Expanded(
                    child: Text(
                      'Campus Bulletin',
                      style: TextStyle(
                        color: _HomeDesign.ink,
                        fontSize: 21,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.4,
                      ),
                    ),
                  ),
                  Pressable(
                    onTap: () => pushPage(
                      context,
                      const CollegePublicPage(collegeId: collegeId),
                    ),
                    child: const Row(
                      children: [
                        Text(
                          'Archive',
                          style: TextStyle(
                            color: _HomeDesign.ink,
                            fontSize: 12,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        SizedBox(width: 4),
                        Icon(
                          Icons.arrow_forward_rounded,
                          color: _HomeDesign.ink,
                          size: 16,
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 14),
              Container(
                clipBehavior: Clip.antiAlias,
                decoration: _HomeDesign.surface(
                  color: _HomeDesign.white,
                  radius: 12,
                  shadowX: 5,
                  shadowY: 5,
                ),
                child: Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 15, 16, 14),
                      child: Row(
                        children: [
                          Container(
                            width: 52,
                            height: 52,
                            decoration: _HomeDesign.surface(
                              color: _HomeDesign.yellow,
                              radius: 11,
                              shadowX: 2,
                              shadowY: 2,
                              borderWidth: 2,
                            ),
                            child: const Icon(
                              Icons.account_balance_rounded,
                              color: _HomeDesign.ink,
                              size: 27,
                            ),
                          ),
                          const SizedBox(width: 12),
                          const Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  'College of Engineering Poonjar',
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    color: _HomeDesign.ink,
                                    fontSize: 15,
                                    fontWeight: FontWeight.w900,
                                    height: 1.15,
                                  ),
                                ),
                                SizedBox(height: 4),
                                Text(
                                  'Official Channel',
                                  style: TextStyle(
                                    color: _HomeDesign.muted,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          OutlinedButton(
                            onPressed: () => pushPage(
                              context,
                              const CollegePublicPage(
                                collegeId: collegeId,
                              ),
                            ),
                            style: OutlinedButton.styleFrom(
                              foregroundColor: _HomeDesign.ink,
                              backgroundColor: _HomeDesign.white,
                              side: const BorderSide(
                                color: _HomeDesign.ink,
                                width: 2,
                              ),
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 10,
                              ),
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(9),
                              ),
                              textStyle: const TextStyle(
                                fontSize: 11,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            child: const Text('Following'),
                          ),
                        ],
                      ),
                    ),
                    for (int i = 0; i < latest.length; i++) ...[
                      const Divider(
                        height: 1,
                        thickness: 1,
                        color: Color(0xFFE1DCD4),
                      ),
                      _StudentOfficialPostPreview(
                        postId: latest[i].id,
                        collegeId: collegeId,
                        data: latest[i].data(),
                        dateText:
                        _formatDate(latest[i].data()['createdAt']),
                      ),
                    ],
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _StudentOfficialPostPreview extends StatefulWidget {
  final String postId;
  final String collegeId;
  final Map<String, dynamic> data;
  final String dateText;

  const _StudentOfficialPostPreview({
    required this.postId,
    required this.collegeId,
    required this.data,
    required this.dateText,
  });

  @override
  State<_StudentOfficialPostPreview> createState() =>
      _StudentOfficialPostPreviewState();
}

class _StudentOfficialPostPreviewState
    extends State<_StudentOfficialPostPreview> {
  bool _likeBusy = false;

  CollectionReference<Map<String, dynamic>> get _likes =>
      FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('posts')
          .doc(widget.postId)
          .collection('likes');

  CollectionReference<Map<String, dynamic>> get _comments =>
      FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('posts')
          .doc(widget.postId)
          .collection('comments');

  Future<void> _toggleLike(bool alreadyLiked) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || _likeBusy) return;

    setState(() => _likeBusy = true);
    try {
      final ref = _likes.doc(user.uid);

      if (alreadyLiked) {
        await ref.delete();
      } else {
        await ref.set({
          'userId': user.uid,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not update like.',
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } finally {
      if (mounted) setState(() => _likeBusy = false);
    }
  }

  Future<void> _openComments() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    final controller = TextEditingController();

    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();

      final userData = userDoc.data() ?? {};
      final userName =
      userData['username']?.toString().trim().isNotEmpty == true
          ? userData['username'].toString().trim()
          : (userData['name']?.toString().trim().isNotEmpty == true
          ? userData['name'].toString().trim()
          : 'Student');

      if (!mounted) return;

      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          bool sending = false;

          return StatefulBuilder(
            builder: (context, setSheetState) {
              Future<void> sendComment() async {
                final value = controller.text.trim();
                if (value.isEmpty || sending) return;

                setSheetState(() => sending = true);

                try {
                  await _comments.add({
                    'userId': user.uid,
                    'userName': userName,
                    'text': value,
                    'createdAt': FieldValue.serverTimestamp(),
                  });

                  controller.clear();
                } catch (_) {
                  if (sheetContext.mounted) {
                    showSnack(
                      sheetContext,
                      'Could not add comment.',
                      color: Colors.red,
                      bottomMargin: 16,
                    );
                  }
                } finally {
                  if (sheetContext.mounted) {
                    setSheetState(() => sending = false);
                  }
                }
              }

              return SafeArea(
                child: Container(
                  height: MediaQuery.of(context).size.height * 0.72,
                  decoration: const BoxDecoration(
                    color: AppColors.cream,
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(28),
                    ),
                    border: Border(
                      top: BorderSide(color: AppColors.ink, width: 2),
                      left: BorderSide(color: AppColors.ink, width: 2),
                      right: BorderSide(color: AppColors.ink, width: 2),
                    ),
                  ),
                  child: Column(
                    children: [
                      Padding(
                        padding: const EdgeInsets.fromLTRB(18, 14, 12, 10),
                        child: Row(
                          children: [
                            const Expanded(
                              child: Text(
                                'Comments',
                                style: TextStyle(
                                  fontSize: 20,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                            NeoIconButton(
                              icon: Icons.close_rounded,
                              onTap: () => Navigator.pop(sheetContext),
                            ),
                          ],
                        ),
                      ),
                      const Divider(height: 1),
                      Expanded(
                        child: StreamBuilder<
                            QuerySnapshot<Map<String, dynamic>>>(
                          stream: _comments
                              .orderBy('createdAt', descending: false)
                              .snapshots(),
                          builder: (context, snapshot) {
                            if (snapshot.hasError) {
                              return const Center(
                                child: Text(
                                  'Could not load comments.',
                                  style: TextStyle(
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              );
                            }

                            final docs = snapshot.data?.docs ?? [];

                            if (docs.isEmpty) {
                              return const Center(
                                child: Text(
                                  'No comments yet. Be the first!',
                                  style: TextStyle(
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              );
                            }

                            return ListView.separated(
                              padding: const EdgeInsets.all(16),
                              itemCount: docs.length,
                              separatorBuilder: (_, __) =>
                              const SizedBox(height: 10),
                              itemBuilder: (context, index) {
                                final comment = docs[index].data();
                                final name =
                                    comment['userName']?.toString().trim() ??
                                        'Student';
                                final value =
                                    comment['text']?.toString().trim() ?? '';

                                return Container(
                                  padding: const EdgeInsets.all(13),
                                  decoration: BoxDecoration(
                                    color: Colors.white,
                                    borderRadius: BorderRadius.circular(18),
                                    border: Border.all(
                                      color: AppColors.ink,
                                      width: 1.2,
                                    ),
                                  ),
                                  child: Column(
                                    crossAxisAlignment:
                                    CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        name.isEmpty ? 'Student' : name,
                                        style: const TextStyle(
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      const SizedBox(height: 4),
                                      Text(
                                        value,
                                        style: const TextStyle(
                                          height: 1.35,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                      _FirestoreReactionBar(document: _comments.doc(docs[index].id)),
                                    ],
                                  ),
                                );
                              },
                            );
                          },
                        ),
                      ),
                      Padding(
                        padding: EdgeInsets.fromLTRB(
                          14,
                          10,
                          14,
                          14 + MediaQuery.of(context).viewInsets.bottom,
                        ),
                        child: Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: controller,
                                textInputAction: TextInputAction.send,
                                onSubmitted: (_) => sendComment(),
                                decoration: InputDecoration(
                                  hintText: 'Write a comment...',
                                  filled: true,
                                  fillColor: Colors.white,
                                  border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(18),
                                    borderSide: const BorderSide(
                                      color: AppColors.ink,
                                    ),
                                  ),
                                  enabledBorder: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(18),
                                    borderSide: const BorderSide(
                                      color: AppColors.ink,
                                    ),
                                  ),
                                ),
                              ),
                            ),
                            const SizedBox(width: 8),
                            NeoIconButton(
                              icon: sending
                                  ? Icons.hourglass_top_rounded
                                  : Icons.send_rounded,
                              onTap: sending ? null : sendComment,
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );
    } finally {
      controller.dispose();
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = widget.data['text']?.toString().trim() ?? '';

    final imageUrls = widget.data['imageUrls'] is List
        ? (widget.data['imageUrls'] as List)
        .map((e) => e.toString().trim())
        .where((e) => e.isNotEmpty)
        .toList()
        : <String>[];

    final user = FirebaseAuth.instance.currentUser;

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: _likes.snapshots(),
      builder: (context, likeSnapshot) {
        final likeDocs = likeSnapshot.data?.docs ?? [];
        final liked = user != null &&
            likeDocs.any((doc) => doc.id == user.uid);

        return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: _comments.snapshots(),
          builder: (context, commentSnapshot) {
            final commentCount =
                commentSnapshot.data?.docs.length ?? 0;

            return Container(
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(20),
                border: Border.all(
                  color: AppColors.ink,
                  width: 1.5,
                ),
              ),
              clipBehavior: Clip.antiAlias,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Full image area: contain instead of crop.
                  if (imageUrls.isNotEmpty)
                    AspectRatio(
                      aspectRatio: 1.15,
                      child: Container(
                        color: AppColors.softBlue,
                        alignment: Alignment.center,
                        child: PageView.builder(
