class LiveCollegeCard extends StatelessWidget {
  final College college;
  final String heroPrefix;

  const LiveCollegeCard({
    super.key,
    required this.college,
    required this.heroPrefix,
  });

  @override
  Widget build(BuildContext context) {
    final firestoreId = firestoreCollegeIdForStudentCollege(college.id);
    if (firestoreId == null) {
      return CollegeCard(college: college, heroPrefix: heroPrefix);
    }

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('colleges')
          .doc(firestoreId)
          .snapshots(),
      builder: (context, snapshot) {
        final data = snapshot.data?.data() ?? {};
        final coverUrl = data['coverUrl']?.toString().trim() ?? '';
        final liveCollege = coverUrl.isEmpty
            ? college
            : College(
          id: college.id,
          name: data['name']?.toString().trim().isNotEmpty == true
              ? data['name'].toString().trim()
              : college.name,
          shortName: data['shortName']?.toString().trim().isNotEmpty == true
              ? data['shortName'].toString().trim()
              : college.shortName,
          location: data['location']?.toString().trim().isNotEmpty == true
              ? data['location'].toString().trim()
              : college.location,
          blurb: data['description']?.toString().trim().isNotEmpty == true
              ? data['description'].toString().trim()
              : college.blurb,
          image: coverUrl,
          isPhoto: true,
          rating: college.rating,
          reviews: college.reviews,
          courses: (data['courses'] as List?)
              ?.map((e) => e.toString())
              .where((e) => e.trim().isNotEmpty)
              .toList() ??
              college.courses,
          highlights: (data['facilities'] as List?)
              ?.map((e) => e.toString())
              .where((e) => e.trim().isNotEmpty)
              .toList() ??
              college.highlights,
        );

        if (coverUrl.isEmpty) {
          return CollegeCard(college: liveCollege, heroPrefix: heroPrefix);
        }

        final heroTag = '$heroPrefix-${college.id}';
        return Pressable(
          onTap: () => pushPage(
            context,
            CollegeDetailsScreen(college: liveCollege, heroTag: heroTag),
          ),
          child: Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: const Color(0xFFEAF2F4),
              borderRadius: BorderRadius.circular(28),
              border: Border.all(color: Colors.black54, width: 1.5),
            ),
            child: Row(
              children: [
                Hero(
                  tag: heroTag,
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(20),
                    child: Container(
                      width: 92,
                      height: 92,
                      color: Colors.white,
                      alignment: Alignment.center,
                      child: AdaptiveImage(
                        image: NetworkImage(coverUrl),
                        width: 92,
                        maxHeight: 92,
                        fit: BoxFit.contain,
                        error: CollegeImage(
                          college: college,
                          width: 92,
                          height: 92,
                        ),
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        liveCollege.name,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Colors.black,
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          height: 1.2,
                        ),
                      ),
                      const SizedBox(height: 6),
                      Row(
                        children: [
                          const Icon(
                            Icons.verified_rounded,
                            color: AppColors.blue,
                            size: 17,
                          ),
                          const SizedBox(width: 4),
                          const Text(
                            'Official',
                            style: TextStyle(
                              color: AppColors.blue,
                              fontSize: 12,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          const SizedBox(width: 8),
                          const Icon(
                            Icons.location_on_rounded,
                            color: AppColors.green,
                            size: 17,
                          ),
                          const SizedBox(width: 2),
                          Expanded(
                            child: Text(
                              liveCollege.location,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(fontSize: 12.5),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

