class ExploreScreen extends StatefulWidget {
  const ExploreScreen({super.key});

  @override
  State<ExploreScreen> createState() => _ExploreScreenState();
}

class _ExploreScreenState extends State<ExploreScreen> {
  final TextEditingController _search = TextEditingController();
  String _query = '';
  String _tab = 'Students';
  String _collegeFilter = 'All';
  String _yearFilter = 'All';
  String _skillFilter = 'All';

  static const Color _cream = Color(0xFFF5F0E8);
  static const Color _orange = Color(0xFFFF5A36);
  static const Color _yellow = Color(0xFFFFD23F);
  static const Color _cyan = Color(0xFF62D9FF);
  static const Color _mint = Color(0xFF72E06A);
  static const Color _ink = Color(0xFF111111);
  static const Color _muted = Color(0xFF555555);

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  List<Map<String, dynamic>> _studentResults(
      List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
      ) {
    final q = _query.trim().toLowerCase();
    final results = <Map<String, dynamic>>[];

    for (final doc in docs) {
      final data = Map<String, dynamic>.from(doc.data());
      final name = (data['name'] ?? '').toString();
      final username = (data['username'] ?? '').toString();
      final college = (data['college'] ?? '').toString();
      final course = (data['course'] ?? '').toString();
      final hobbies = (data['hobbies'] ?? '').toString();
      final year = (data['yearOfStudy'] ?? '').toString();
      final skillsRaw = data['technicalSkills'];
      final skills = skillsRaw is Map
          ? skillsRaw.entries.map((e) => e.key.toString()).toList()
          : <String>[];

      if (doc.id == _currentUid()) continue;
      if (data['profileSetupComplete'] == false) continue;
      if (data['discoverable'] == false) continue;

      final searchable = [
        name,
        username,
        college,
        course,
        hobbies,
        year,
        ...skills,
      ].join(' ').toLowerCase();

      final matchesQuery = q.isEmpty || searchable.contains(q);
      final matchesCollege =
          _collegeFilter == 'All' || college == _collegeFilter;
      final matchesYear = _yearFilter == 'All' || year == _yearFilter;
      final matchesSkill =
          _skillFilter == 'All' || skills.any((s) => s == _skillFilter);

      if (matchesQuery && matchesCollege && matchesYear && matchesSkill) {
        data['uid'] = doc.id;
        results.add(data);
      }
    }

    results.sort((a, b) {
      final an = (a['name'] ?? a['username'] ?? '').toString().toLowerCase();
      final bn = (b['name'] ?? b['username'] ?? '').toString().toLowerCase();
      return an.compareTo(bn);
    });

    return results;
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      bottom: false,
      child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('users')
            .limit(150)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return ListView(
              padding: const EdgeInsets.fromLTRB(20, 18, 20, 130),
              children: [
                _discoverHeader(context),
                const SizedBox(height: 18),
                const _DiscoverErrorCard(),
              ],
            );
          }

          final docs = snapshot.data?.docs ??
              const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
          final students = _studentResults(docs);

          final colleges = <String>{'All'};
          for (final doc in docs) {
            final college = (doc.data()['college'] ?? '').toString().trim();
            if (college.isNotEmpty) colleges.add(college);
          }

          final skills = <String>{'All'};
          for (final doc in docs) {
            final raw = doc.data()['technicalSkills'];
            if (raw is Map) {
              for (final key in raw.keys) {
                final skill = key.toString().trim();
                if (skill.isNotEmpty) skills.add(skill);
              }
            }
          }

          const years = <String>[
            'All',
            '1st Year',
            '2nd Year',
            '3rd Year',
            '4th Year'
          ];

          return ListView(
            padding: const EdgeInsets.fromLTRB(20, 18, 20, 130),
            children: [
              _discoverHeader(context),
              const SizedBox(height: 18),

              // Students / Colleges switch. Navigation and all existing tab
              // logic remain unchanged.
              _discoverSegmentedTabs(),

              const SizedBox(height: 18),
              _nearbyRadarCard(context),

              const SizedBox(height: 18),
              _discoverSearchField(),

              if (_tab == 'Students') ...[
                const SizedBox(height: 16),
                _discoverFilterBar(
                  colleges: colleges.toList()..sort(),
                  years: years,
                  skills: skills.toList()..sort(),
                ),
                const SizedBox(height: 18),
                Row(
                  children: [
                    Text(
                      '${students.length} student${students.length == 1 ? '' : 's'} found',
                      style: const TextStyle(
                        color: _ink,
                        fontSize: 15,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const Spacer(),
                    const Icon(Icons.swap_vert_rounded, size: 18, color: _muted),
                    const SizedBox(width: 4),
                    const Text(
                      'Sort: Relevance',
                      style: TextStyle(
                        color: _muted,
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                if (students.isEmpty)
                  const EmptyState(
                    icon: Icons.person_search_rounded,
                    title: 'No students found',
                    subtitle: 'Try another name, college, year or skill.',
                  ),
                for (int i = 0; i < students.length; i++)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 14),
                    child: Entrance(
                      delayMs: i < 6 ? i * 60 : 360,
                      child: StudentDiscoverCard(profile: students[i]),
                    ),
                  ),
              ] else ...[
                const SizedBox(height: 18),
                // Keep the existing college discovery experience intact.
                _CollegeExploreList(
                  query: _query,
                  onClearQuery: () {
                    _search.clear();
                    setState(() => _query = '');
                  },
                ),
              ],
            ],
          );
        },
      ),
    );
  }

