class StudentDiscoverCard extends StatelessWidget {
  final Map<String, dynamic> profile;

  const StudentDiscoverCard({super.key, required this.profile});

  static const Color _orange = Color(0xFFFF5A36);
  static const Color _yellow = Color(0xFFFFD23F);
  static const Color _cyan = Color(0xFF62D9FF);
  static const Color _mint = Color(0xFF72E06A);
  static const Color _ink = Color(0xFF111111);
  static const Color _muted = Color(0xFF555555);

  @override
  Widget build(BuildContext context) {
    final uid = (profile['uid'] ?? '').toString();
    final name = (profile['name'] ?? profile['username'] ?? 'Student').toString();
    final username = (profile['username'] ?? '').toString().trim();
    final college = (profile['college'] ?? '').toString();
    final course = (profile['course'] ?? '').toString();
    final year = (profile['yearOfStudy'] ?? '').toString();
    final image = (profile['profileImage'] ?? '').toString();
    final verified = profile['verified'] == true;
    final skillsRaw = profile['technicalSkills'];
    final skills = skillsRaw is Map
        ? skillsRaw.keys
        .map((e) => e.toString())
        .where((e) => e.trim().isNotEmpty)
        .take(3)
        .toList()
        : <String>[];

    return Pressable(
      shadow: true,
      radius: 14,
      onTap: uid.isEmpty
          ? null
          : () => pushPage(
        context,
        PublicStudentProfileScreen(profile: profile),
      ),
      child: Container(
        padding: const EdgeInsets.fromLTRB(14, 14, 12, 12),
        decoration: BoxDecoration(
          color: Colors.white,
          border: Border.all(color: _ink, width: 2),
          borderRadius: BorderRadius.circular(14),
        ),
        child: Column(
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                ProfileAvatar(
                  imageUrl: image,
                  name: name,
                  radius: 31,
                  backgroundColor: _yellow,
                ),
                const SizedBox(width: 13),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              name,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: _ink,
                                fontSize: 18,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          if (verified) ...[
                            const SizedBox(width: 5),
                            const Icon(
                              Icons.verified_rounded,
                              color: Color(0xFF3B82F6),
                              size: 18,
                            ),
                          ],
                        ],
                      ),
                      if (username.isNotEmpty) ...[
                        const SizedBox(height: 2),
                        Text(
                          '@$username',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: _orange,
                            fontSize: 12.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                      const SizedBox(height: 4),
                      if (course.isNotEmpty || year.isNotEmpty)
                        Text(
                          [course, year]
                              .where((x) => x.trim().isNotEmpty)
                              .join(' • '),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: _muted,
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                Container(
                  width: 42,
                  height: 42,
                  decoration: BoxDecoration(
                    color: const Color(0xFFF5F0E8),
                    border: Border.all(color: _ink, width: 2),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: const Icon(
                    Icons.chevron_right_rounded,
                    color: _ink,
                    size: 26,
                  ),
                ),
              ],
            ),
            if (college.isNotEmpty) ...[
              const SizedBox(height: 13),
              Row(
                children: [
                  const Icon(
                    Icons.location_on_outlined,
                    color: Color(0xFF8A857C),
                    size: 18,
                  ),
                  const SizedBox(width: 5),
                  Expanded(
                    child: Text(
                      college,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: _muted,
                        fontSize: 11.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ],
              ),
            ],
            if (skills.isNotEmpty) ...[
              const SizedBox(height: 11),
              Container(
                height: 1.5,
                color: const Color(0xFFE2DED7),
              ),
              const SizedBox(height: 11),
              Row(
                children: [
                  Expanded(
                    child: SingleChildScrollView(
                      scrollDirection: Axis.horizontal,
                      child: Row(
                        children: [
                          for (int i = 0; i < skills.length; i++) ...[
                            _skillChip(
                              skills[i],
                              i == 0
                                  ? AppColors.softBlue
                                  : i == 1
                                  ? _cyan
                                  : _mint,
                            ),
                            if (i != skills.length - 1)
                              const SizedBox(width: 6),
                          ],
                        ],
                      ),
                    ),
                  ),
                ],
              ),
            ],
          ],
        ),
      ),
    );
  }

  Widget _skillChip(String skill, Color color) {
    return Container(
      constraints: const BoxConstraints(maxWidth: 110),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: color,
        border: Border.all(color: _ink, width: 1.5),
        borderRadius: BorderRadius.circular(9),
        boxShadow: const [
          BoxShadow(color: _ink, offset: Offset(2, 2), blurRadius: 0),
        ],
      ),
      child: Text(
        skill,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: const TextStyle(
          color: _ink,
          fontSize: 11,
          fontWeight: FontWeight.w900,
        ),
      ),
    );
  }
}

class _CollegeExploreList extends StatelessWidget {
  final String query;
  final VoidCallback onClearQuery;

  const _CollegeExploreList({required this.query, required this.onClearQuery});

  @override
  Widget build(BuildContext context) {
    final q = query.toLowerCase();
    final results = allColleges.where((c) {
      return q.isEmpty ||
          c.name.toLowerCase().contains(q) ||
          c.shortName.toLowerCase().contains(q) ||
          c.location.toLowerCase().contains(q);
    }).toList()
      ..sort((a, b) => b.rating.compareTo(a.rating));

    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 22),
          child: Row(
            children: [
              Expanded(
                child: Text(
                  '${results.length} college${results.length == 1 ? '' : 's'} found',
                  style: const TextStyle(color: AppColors.muted, fontWeight: FontWeight.w700),
                ),
              ),
              if (query.isNotEmpty)
                TextButton(onPressed: onClearQuery, child: const Text('Clear')),
            ],
          ),
        ),
        const SizedBox(height: 8),
        if (results.isEmpty)
          const EmptyState(
            icon: Icons.search_off_rounded,
            title: 'No colleges found',
            subtitle: 'Try another college name or district.',
          ),
        for (int i = 0; i < results.length; i++)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
            child: Entrance(
              delayMs: i < 6 ? i * 60 : 360,
              child: CollegeCard(college: results[i], heroPrefix: 'discover'),
            ),
          ),
      ],
    );
  }
}

