  static const Color _yellow = Color(0xFFFFD23F);
  static const Color _mint = Color(0xFF9BC8B8);
  static const Color _lavender = Color(0xFFE6DEFF);
  static const Color _ink = Color(0xFF111111);

  BoxDecoration _card({
    Color color = Colors.white,
    double radius = 18,
    bool shadow = true,
  }) {
    return BoxDecoration(
      color: color,
      borderRadius: BorderRadius.circular(radius),
      border: Border.all(color: _ink, width: 2),
      boxShadow: shadow
          ? const [
        BoxShadow(
          color: _ink,
          offset: Offset(4, 5),
          blurRadius: 0,
        ),
      ]
          : null,
    );
  }

  Widget _statCard(
      BuildContext context,
      String value,
      String label,
      Stream<int> stream,
      FollowListType type,
      ) {
    return Expanded(
      child: InkWell(
        onTap: () => pushPage(
          context,
          FollowListScreen(uid: (profile['uid'] ?? '').toString(), type: type),
        ),
        borderRadius: BorderRadius.circular(18),
        child: StreamBuilder<int>(
          stream: stream,
          builder: (context, snapshot) {
            return Container(
              height: 90,
              decoration: _card(shadow: true),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
