class FollowStatsRow extends StatelessWidget {
  final String uid;
  const FollowStatsRow({super.key, required this.uid});

  Widget _item(BuildContext context, String label, Stream<int> stream, FollowListType type) {
    return Expanded(
      child: InkWell(
        onTap: () => pushPage(context, FollowListScreen(uid: uid, type: type)),
        borderRadius: BorderRadius.circular(18),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 10),
          decoration: neoDeco(color: Colors.white, radius: 18, shadow: false),
          child: StreamBuilder<int>(
            stream: stream,
            builder: (context, snapshot) {
              return Column(
                children: [
                  Text('${snapshot.data ?? 0}', style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w900)),
                  const SizedBox(height: 2),
                  Text(label, style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800)),
                ],
              );
            },
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        _item(context, 'Followers', _followCountStream(uid, 'followers'), FollowListType.followers),
        const SizedBox(width: 8),
        _item(context, 'Following', _followCountStream(uid, 'following'), FollowListType.following),
      ],
    );
  }
}

enum FollowListType { followers, following }

enum _FollowRequestState { none, requested, incoming, accepted }

Stream<int> _followCountStream(String uid, String collection) {
  return FirebaseFirestore.instance
      .collection('users')
      .doc(uid)
      .collection(collection)
      .snapshots()
      .map((snapshot) => snapshot.size);
}

Stream<bool> _acceptedRelationshipStream(String uid1, String uid2) {
  if (uid1.isEmpty || uid2.isEmpty || uid1 == uid2) return Stream<bool>.value(false);
  return FirebaseFirestore.instance
      .collection('users')
      .doc(uid1)
      .collection('following')
      .doc(uid2)
      .snapshots()
      .map((doc) => doc.exists);
}

Future<_FollowRequestState> _followState(String me, String other) async {
  if (me.isEmpty || other.isEmpty || me == other) return _FollowRequestState.accepted;
  final following = await FirebaseFirestore.instance
      .collection('users').doc(me).collection('following').doc(other).get();
  if (following.exists) return _FollowRequestState.accepted;
  final outgoing = await FirebaseFirestore.instance
      .collection('users').doc(other).collection('followRequests').doc(me).get();
  if (outgoing.exists && outgoing.data()?['status'] == 'pending') return _FollowRequestState.requested;
  final incoming = await FirebaseFirestore.instance
      .collection('users').doc(me).collection('followRequests').doc(other).get();
  if (incoming.exists && incoming.data()?['status'] == 'pending') return _FollowRequestState.incoming;
  return _FollowRequestState.none;
}

Future<void> _sendFollowRequest(String targetUid) async {
  final me = _currentUid();
  if (me.isEmpty || targetUid.isEmpty || me == targetUid) return;
  final db = FirebaseFirestore.instance;

  final ref = db
      .collection('users').doc(targetUid)
      .collection('followRequests').doc(me);
  final notificationRef =
  db.collection('notifications').doc('follow_${me}_$targetUid');

  // Remove any stale notification from an earlier request.
  try {
    await notificationRef.delete();
  } catch (_) {}

  await ref.set({
    'requesterId': me,
    'recipientId': targetUid,
    'status': 'pending',
    'createdAt': FieldValue.serverTimestamp(),
  });

  await notificationRef.set({
    'recipientId': targetUid,
    'senderId': me,
    'senderName': userName.value,
    'senderProfileImage': userProfileImage.value,
    'type': 'follow_request',
    'title': '${userName.value} sent you a follow request',
    'body': 'Accept or reject this request from Notifications.',
    'relatedId': me,
    'isRead': false,
    'createdAt': FieldValue.serverTimestamp(),
  });
}

Future<void> _cancelFollowRequest(String targetUid) async {
  final me = _currentUid();
  if (me.isEmpty || targetUid.isEmpty) return;
  final db = FirebaseFirestore.instance;

  await db
      .collection('users').doc(targetUid)
      .collection('followRequests').doc(me)
      .delete();

  try {
    await db.collection('notifications').doc('follow_${me}_$targetUid').delete();
  } catch (_) {}
}

Future<void> _deleteFollowRequestNotifications(String requesterUid) async {
  final me = _currentUid();
  if (me.isEmpty || requesterUid.isEmpty) return;
  final db = FirebaseFirestore.instance;

  try {
    await db.collection('notifications').doc('follow_${requesterUid}_$me').delete();
  } catch (_) {}

  try {
    final snap = await db
        .collection('notifications')
        .where('recipientId', isEqualTo: me)
        .where('senderId', isEqualTo: requesterUid)
        .get();
    for (final doc in snap.docs) {
      if (doc.data()['type'] == 'follow_request') {
        await doc.reference.delete();
      }
    }
  } catch (_) {}
}

Future<void> _rejectFollowRequest(String requesterUid) async {
  final me = _currentUid();
  if (me.isEmpty || requesterUid.isEmpty) return;
  await FirebaseFirestore.instance
      .collection('users').doc(me).collection('followRequests').doc(requesterUid).delete();
  await _deleteFollowRequestNotifications(requesterUid);
}

Future<void> _acceptFollowRequest(String requesterUid) async {
  final me = _currentUid();
  if (me.isEmpty || requesterUid.isEmpty || me == requesterUid) return;
  final db = FirebaseFirestore.instance;
  final batch = db.batch();
  final now = FieldValue.serverTimestamp();

  // requester -> me
  batch.set(
    db.collection('users').doc(me).collection('followers').doc(requesterUid),
    {'uid': requesterUid, 'createdAt': now},
  );
  batch.set(
    db.collection('users').doc(requesterUid).collection('following').doc(me),
    {'uid': me, 'createdAt': now},
  );

  batch.delete(
    db.collection('users').doc(me).collection('followRequests').doc(requesterUid),
  );
  await batch.commit();
  await _deleteFollowRequestNotifications(requesterUid);
}

Future<void> _unfollowUser(String targetUid) async {
  final me = _currentUid();
  if (me.isEmpty || targetUid.isEmpty) return;
  final batch = FirebaseFirestore.instance.batch();
  batch.delete(FirebaseFirestore.instance.collection('users').doc(me).collection('following').doc(targetUid));
  batch.delete(FirebaseFirestore.instance.collection('users').doc(targetUid).collection('followers').doc(me));
  await batch.commit();
}

class FollowRelationshipActions extends StatelessWidget {
  final String targetUid;
  final String targetName;
  final String targetCollege;
  final String targetProfileImage;

  const FollowRelationshipActions({
    super.key,
    required this.targetUid,
    required this.targetName,
    this.targetCollege = '',
    this.targetProfileImage = '',
  });

  @override
  Widget build(BuildContext context) {
    final me = _currentUid();
    return StreamBuilder<_FollowRequestState>(
      stream: _followStateStream(me, targetUid),
      builder: (context, snapshot) {
        final state = snapshot.data ?? _FollowRequestState.none;
        if (state == _FollowRequestState.accepted) {
          return PillButton(
            label: 'Following',
            icon: Icons.person_remove_alt_1_rounded,
            color: AppColors.sky,
            onTap: () async {
              final ok = await showDialog<bool>(
                context: context,
                builder: (d) => AlertDialog(
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(24),
                  ),
                  title: Text(
                    'Unfollow $targetName?',
                    style: const TextStyle(fontWeight: FontWeight.w900),
                  ),
                  content: const Text(
                    'You will stop following this student and won\'t be able to message them until you follow each other again.',
                  ),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.pop(d, false),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () => Navigator.pop(d, true),
                      style: FilledButton.styleFrom(backgroundColor: Colors.red),
                      child: const Text('Unfollow'),
                    ),
                  ],
                ),
              );
              if (ok != true) return;
              try {
                await _unfollowUser(targetUid);
              } catch (e) {
                if (context.mounted) {
                  showSnack(
                    context,
                    'Could not unfollow: $e',
                    color: Colors.red,
                    bottomMargin: 20,
                  );
                }
              }
            },
          );
        }
        if (state == _FollowRequestState.requested) {
          return PillButton(
            label: 'Requested',
            icon: Icons.schedule_rounded,
            color: AppColors.softBlue,
            onTap: () async {
              try {
                await _cancelFollowRequest(targetUid);
              } catch (e) {
                if (context.mounted) showSnack(context, 'Could not cancel request: $e', color: Colors.red, bottomMargin: 20);
              }
            },
          );
        }
        if (state == _FollowRequestState.incoming) {
          return Row(
            children: [
              Expanded(
                child: PillButton(
                  label: 'Accept',
                  icon: Icons.check_rounded,
                  color: AppColors.green,
                  onTap: () async {
                    try {
                      await _acceptFollowRequest(targetUid);
                    } catch (e) {
                      if (context.mounted) showSnack(context, 'Could not accept request: $e', color: Colors.red, bottomMargin: 20);
                    }
                  },
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: PillButton(
                  label: 'Reject',
                  icon: Icons.close_rounded,
                  color: AppColors.softBlue,
                  onTap: () async {
                    try {
                      await _rejectFollowRequest(targetUid);
                    } catch (e) {
                      if (context.mounted) showSnack(context, 'Could not reject request: $e', color: Colors.red, bottomMargin: 20);
                    }
                  },
                ),
              ),
            ],
          );
        }
        return PillButton(
          label: 'Follow',
          icon: Icons.person_add_alt_1_rounded,
          color: AppColors.blue,
          textColor: Colors.white,
          onTap: () async {
            try {
              await _sendFollowRequest(targetUid);
            } catch (e) {
              if (context.mounted) showSnack(context, 'Could not send follow request: $e', color: Colors.red, bottomMargin: 20);
            }
          },
        );
      },
    );
  }
}

Stream<_FollowRequestState> _followStateStream(String me, String other) async* {
  while (true) {
    yield await _followState(me, other);
    await Future<void>.delayed(const Duration(seconds: 2));
  }
}

class FollowListScreen extends StatelessWidget {
  final String uid;
  final FollowListType type;

  const FollowListScreen({super.key, required this.uid, required this.type});

  @override
  Widget build(BuildContext context) {
    final collection = type == FollowListType.followers ? 'followers' : 'following';
    final title = type == FollowListType.followers ? 'Followers' : 'Following';
    return Scaffold(
      backgroundColor: AppColors.cream,
      body: SafeArea(
        child: Column(
          children: [
            PageHeader(title: title),
            Expanded(
              child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: FirebaseFirestore.instance.collection('users').doc(uid).collection(collection).snapshots(),
                builder: (context, snapshot) {
                  if (snapshot.connectionState == ConnectionState.waiting) {
                    return const Center(child: CircularProgressIndicator());
                  }
                  if (snapshot.hasError) {
                    return Center(child: Text('Could not load $title.\n${snapshot.error}', textAlign: TextAlign.center));
                  }
                  final docs = snapshot.data?.docs ?? [];
                  if (docs.isEmpty) {
                    return EmptyState(
                      icon: type == FollowListType.followers ? Icons.people_outline_rounded : Icons.person_add_alt_1_rounded,
                      title: 'No $title yet',
                      subtitle: type == FollowListType.followers ? 'People who follow this student will appear here.' : 'Students this person follows will appear here.',
                    );
                  }
                  return ListView.separated(
                    padding: const EdgeInsets.fromLTRB(20, 4, 20, 30),
                    itemCount: docs.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 10),
                    itemBuilder: (context, index) {
                      final otherUid = docs[index].id;
                      return FutureBuilder<Map<String, dynamic>?>(
                        future: _loadUserProfile(otherUid),
                        builder: (context, profileSnapshot) {
                          final data = profileSnapshot.data;
                          if (data == null) return const SizedBox.shrink();
                          final merged = Map<String, dynamic>.from(data)..['uid'] = otherUid;
                          final otherName = (data['name'] ?? data['username'] ?? 'Student').toString();
                          return Pressable(
                            onTap: () => pushPage(context, PublicStudentProfileScreen(profile: merged)),
                            child: Container(
                              padding: const EdgeInsets.all(12),
                              decoration: neoDeco(color: Colors.white, radius: 20),
                              child: Row(
                                children: [
                                  ProfileAvatar(imageUrl: (data['profileImage'] ?? '').toString(), name: otherName, radius: 25),
                                  const SizedBox(width: 12),
                                  Expanded(
                                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                      Text(otherName, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 15)),
                                      if ((data['username'] ?? '').toString().trim().isNotEmpty)
                                        Text('@${data['username']}', style: const TextStyle(color: AppColors.blue, fontWeight: FontWeight.w800, fontSize: 11)),
                                      Text((data['college'] ?? '').toString(), maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(color: AppColors.muted, fontSize: 11.5)),
                                    ]),
                                  ),
                                  const Icon(Icons.chevron_right_rounded),
                                ],
                              ),
                            ),
                          );
                        },
                      );
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

