// =====================================================
// COMMUNITY TAB
// =====================================================
//
// Student Campus Feed
// - Real Firestore student posts (no generated/fake posts)
// - Current user's real profile picture in the composer
// - Photo/video attachment picker
// - Persistent likes
// - Persistent comments
// - Posts remain available after app restart
//
// NOTE:
// The Flutter code below uses:
//   studentPosts/{postId}
//   studentPosts/{postId}/likes/{uid}
//   studentPosts/{postId}/comments/{commentId}
// and Storage:
//   studentPosts/{postId}/media/{fileName}
//
// The corresponding Firestore/Storage rules must allow these paths.
// This Community section is the only part changed; Groups and all
// other PeerGrid features remain unchanged.
// =====================================================

class _StudentFeedPost {
  final String id;
  final String authorId;
  final String author;
  final String college;
  final String profileImage;
  final String text;
  final String mediaUrl;
  final String mediaType;
  final List<String> mentionedUserIds;
  final List<String> mentionedUsernames;
  final Timestamp? createdAt;
  final String collectionName;

  const _StudentFeedPost({
    required this.id,
    required this.authorId,
    required this.author,
    required this.college,
    required this.profileImage,
    required this.text,
    required this.mediaUrl,
    required this.mediaType,
    required this.mentionedUserIds,
    required this.mentionedUsernames,
    required this.createdAt,
    this.collectionName = 'studentPosts',
  });

  factory _StudentFeedPost.fromDoc(
      QueryDocumentSnapshot<Map<String, dynamic>> doc, {
        String collectionName = 'studentPosts',
      }) {
    final data = doc.data();
    return _StudentFeedPost(
      id: doc.id,
      authorId: data['authorId']?.toString() ?? '',
      author: data['authorName']?.toString().trim().isNotEmpty == true
          ? data['authorName'].toString().trim()
          : 'Student',
      college: data['college']?.toString().trim() ?? '',
      profileImage: data['authorProfileImage']?.toString().trim() ?? '',
      text: data['text']?.toString() ?? '',
      mediaUrl: data['mediaUrl']?.toString().trim() ?? '',
      mediaType: data['mediaType']?.toString().trim() ?? '',
      mentionedUserIds: (data['mentionedUserIds'] as List?)
          ?.map((e) => e.toString())
          .where((e) => e.isNotEmpty)
          .toList() ??
          <String>[],
      mentionedUsernames: (data['mentionedUsernames'] as List?)
          ?.map((e) => e.toString())
          .where((e) => e.isNotEmpty)
          .toList() ??
          <String>[],
      createdAt: data['createdAt'] is Timestamp
          ? data['createdAt'] as Timestamp
          : null,
      collectionName: collectionName,
    );
  }
}

String _studentPostTime(Timestamp? timestamp) {
  if (timestamp == null) return 'Just now';

  final difference = DateTime.now().difference(timestamp.toDate());
  if (difference.inSeconds < 60) return 'Just now';
  if (difference.inMinutes < 60) {
    return '${difference.inMinutes}m ago';
  }
  if (difference.inHours < 24) {
    return '${difference.inHours}h ago';
  }
  if (difference.inDays < 7) {
    return '${difference.inDays}d ago';
  }

  final date = timestamp.toDate();
  return '${date.day}/${date.month}/${date.year}';
}

