class PeerGridGlobalAdminScreen extends StatelessWidget {
  const PeerGridGlobalAdminScreen({super.key});

  Future<void> _setBan(BuildContext context, String uid, String name, {required Duration? duration}) async {
    if (!isPeerGridGlobalAdmin()) return;
    final reasonController = TextEditingController(text: 'Community moderation');
    final reason = await showDialog<String>(context: context, builder: (dialogContext) => AlertDialog(
      title: Text(duration == null ? 'Permanently ban $name?' : 'Temporarily ban $name?'),
      content: TextField(controller: reasonController, maxLines: 2, decoration: const InputDecoration(labelText: 'Reason')),
      actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')), TextButton(onPressed: () => Navigator.pop(dialogContext, reasonController.text.trim()), child: const Text('Confirm'))],
    ));
    reasonController.dispose();
    if (reason == null) return;
    try {
      await FirebaseFirestore.instance.collection('userBans').doc(uid).set({
        'userId': uid,
        'reason': reason,
        'createdBy': peerGridGlobalAdminUid,
        'createdAt': FieldValue.serverTimestamp(),
        'expiresAt': duration == null ? null : Timestamp.fromDate(DateTime.now().add(duration)),
      });
      if (context.mounted) showSnack(context, duration == null ? 'Permanent ban saved.' : 'Temporary ban saved.', color: AppColors.green, bottomMargin: 16);
    } catch (e) {
      if (context.mounted) showSnack(context, 'Could not save ban: $e', color: Colors.red, bottomMargin: 16);
    }
  }

  Future<void> _unban(BuildContext context, String uid) async {
    if (!isPeerGridGlobalAdmin()) return;
    try {
      await FirebaseFirestore.instance.collection('userBans').doc(uid).delete();
      if (context.mounted) showSnack(context, 'Ban removed.', color: AppColors.green, bottomMargin: 16);
    } catch (e) {
      if (context.mounted) showSnack(context, 'Could not remove ban: $e', color: Colors.red, bottomMargin: 16);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!isPeerGridGlobalAdmin()) return const Scaffold(body: Center(child: Text('Access denied.')));
    return Scaffold(
      appBar: AppBar(title: const Text('PeerGrid admin')),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance.collection('users').snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) return const Center(child: Text('Could not load users.'));
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());
          final users = snapshot.data!.docs.where((doc) => doc.id != peerGridGlobalAdminUid).toList();
          if (users.isEmpty) return const Center(child: Text('No other users found.'));
          return ListView.separated(
            padding: const EdgeInsets.all(16),
            itemCount: users.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) {
              final doc = users[index];
              final data = doc.data();
              final name = (data['name'] ?? data['username'] ?? 'Student').toString();
              final college = (data['college'] ?? '').toString();
              return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: FirebaseFirestore.instance.collection('userBans').doc(doc.id).snapshots(),
                builder: (context, banSnapshot) {
                  final ban = banSnapshot.data?.data();
                  final expiresAt = ban?['expiresAt'];
                  final active = ban != null && !(expiresAt is Timestamp && !expiresAt.toDate().isAfter(DateTime.now()));
                  return Container(
                    padding: const EdgeInsets.all(12),
                    decoration: neoDeco(color: active ? const Color(0xFFFFE4E1) : Colors.white, radius: 14, shadow: false),
                    child: Row(children: [
                      ProfileAvatar(imageUrl: (data['profileImage'] ?? '').toString(), name: name, radius: 22),
                      const SizedBox(width: 10),
                      Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text(name, style: const TextStyle(fontWeight: FontWeight.w900)),
                        Text(college.isEmpty ? doc.id : college, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 11, color: AppColors.muted)),
                        if (active) Text(expiresAt is Timestamp ? 'Banned until ${expiresAt.toDate().toLocal()}' : 'Permanently banned', style: const TextStyle(color: Colors.redAccent, fontSize: 11, fontWeight: FontWeight.w800)),
                      ])),
                      PopupMenuButton<String>(
                        tooltip: 'Moderation actions',
                        onSelected: (value) {
                          if (value == 'day') _setBan(context, doc.id, name, duration: const Duration(days: 1));
                          if (value == 'week') _setBan(context, doc.id, name, duration: const Duration(days: 7));
                          if (value == 'permanent') _setBan(context, doc.id, name, duration: null);
                          if (value == 'unban') _unban(context, doc.id);
                        },
                        itemBuilder: (_) => [
                          if (active) const PopupMenuItem(value: 'unban', child: Text('Remove ban')),
                          const PopupMenuItem(value: 'day', child: Text('Ban for 1 day')),
                          const PopupMenuItem(value: 'week', child: Text('Ban for 7 days')),
                          const PopupMenuItem(value: 'permanent', child: Text('Permanent ban')),
                        ],
                      ),
                    ]),
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}

class CommunityScreen extends StatefulWidget {
  const CommunityScreen({super.key});

  @override
  State<CommunityScreen> createState() => _CommunityScreenState();
}

class _CommunityScreenState extends State<CommunityScreen> {
  int _tab = 0;
  final TextEditingController _postController = TextEditingController();
  final TextEditingController _groupSearch = TextEditingController();
  final TextEditingController _commentController = TextEditingController();

  String _groupQuery = '';
  XFile? _attachment;
  bool _attachmentIsVideo = false;
  bool _posting = false;
  String _mentionQuery = '';
  List<Map<String, String>> _mentionSuggestions = <Map<String, String>>[];

  CollectionReference<Map<String, dynamic>> get _studentPosts =>
      FirebaseFirestore.instance.collection('studentPosts');

  @override
  void dispose() {
    _postController.dispose();
    _groupSearch.dispose();
    _commentController.dispose();
    super.dispose();
  }

  Future<void> _updateMentionSuggestions(String text) async {
    final match = RegExp(r'@([A-Za-z0-9_.-]*)$').firstMatch(text);
    if (match == null) {
      if (mounted && _mentionSuggestions.isNotEmpty) {
        setState(() => _mentionSuggestions = <Map<String, String>>[]);
      }
      _mentionQuery = '';
      return;
    }

    final query = (match.group(1) ?? '').toLowerCase();
    _mentionQuery = query;
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .limit(100)
          .get();
      final results = <Map<String, String>>[];
      for (final doc in snap.docs) {
        if (doc.id == _currentUid()) continue;
        final data = doc.data();
        final username = data['username']?.toString().trim() ?? '';
        final name = data['name']?.toString().trim() ?? '';
        if (username.isEmpty && name.isEmpty) continue;
        if (query.isNotEmpty &&
            !username.toLowerCase().contains(query) &&
            !name.toLowerCase().contains(query)) {
          continue;
        }
        results.add({
          'uid': doc.id,
          'username': username.isNotEmpty ? username : name,
          'name': name.isNotEmpty ? name : username,
        });
        if (results.length >= 6) break;
      }
      if (!mounted || _mentionQuery != query) return;
      setState(() => _mentionSuggestions = results);
    } catch (_) {
      if (mounted) setState(() => _mentionSuggestions = <Map<String, String>>[]);
    }
  }

  void _insertMention(Map<String, String> student) {
    final match =
    RegExp(r'@([A-Za-z0-9_.-]*)$').firstMatch(_postController.text);
    final username = student['username']?.trim() ?? '';
    if (match == null || username.isEmpty) return;
    final next =
    _postController.text.replaceRange(match.start, _postController.text.length, '@$username ');
    _postController.value = TextEditingValue(
      text: next,
      selection: TextSelection.collapsed(offset: next.length),
    );
    setState(() {
      _mentionQuery = '';
      _mentionSuggestions = <Map<String, String>>[];
    });
  }

  Future<Map<String, List<String>>> _resolveMentions(String text) async {
    final names = RegExp(r'@([A-Za-z0-9_.-]{2,30})')
        .allMatches(text)
        .map((m) => (m.group(1) ?? '').toLowerCase())
        .toSet();
    if (names.isEmpty) {
      return {'ids': <String>[], 'usernames': <String>[]};
    }

    final snap =
    await FirebaseFirestore.instance.collection('users').limit(200).get();
    final ids = <String>[];
    final usernames = <String>[];
    for (final doc in snap.docs) {
      final username = doc.data()['username']?.toString().trim() ?? '';
      if (username.isNotEmpty &&
          names.contains(username.toLowerCase()) &&
          doc.id != _currentUid()) {
        ids.add(doc.id);
        usernames.add(username);
      }
    }
    return {'ids': ids, 'usernames': usernames};
  }

  Future<void> _pickAttachment() async {
    if (_posting) return;

    final choice = await showModalBottomSheet<String>(
      context: context,
      builder: (sheetContext) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 20, 20, 24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Text(
                  'Add to your post',
                  style: TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Expanded(
                      child: PillButton(
                        label: 'Photo',
                        icon: Icons.image_rounded,
                        color: AppColors.cyan,
                        onTap: () => Navigator.pop(sheetContext, 'image'),
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: PillButton(
                        label: 'Video',
                        icon: Icons.videocam_rounded,
                        color: AppColors.lavender,
                        onTap: () => Navigator.pop(sheetContext, 'video'),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        );
      },
    );

    if (!mounted || choice == null) return;

    try {
      final XFile? picked = choice == 'video'
          ? await ImagePicker().pickVideo(source: ImageSource.gallery)
          : await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 88,
      );

      if (picked == null || !mounted) return;

      setState(() {
        _attachment = picked;
        _attachmentIsVideo = choice == 'video';
      });
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not select ${choice == 'video' ? 'video' : 'photo'}: $e',
          color: Colors.red,
        );
      }
    }
  }

  void _removeAttachment() {
    if (_posting) return;
    setState(() {
      _attachment = null;
      _attachmentIsVideo = false;
    });
  }

  Future<String?> _uploadStudentPostMedia({
    required String postId,
    required XFile file,
    required bool video,
  }) async {
    final extension = file.name.contains('.')
        ? file.name.split('.').last.toLowerCase()
        : (video ? 'mp4' : 'jpg');

    final contentType = video
        ? (extension == 'mov'
        ? 'video/quicktime'
        : extension == 'm4v'
        ? 'video/x-m4v'
        : 'video/mp4')
        : (extension == 'png'
        ? 'image/png'
        : extension == 'webp'
        ? 'image/webp'
        : extension == 'gif'
        ? 'image/gif'
        : 'image/jpeg');

    final path =
        'studentPostMedia/${_currentUid()}/$postId/${DateTime.now().millisecondsSinceEpoch}.$extension';

    final ref = FirebaseStorage.instance.ref().child(path);

    final upload = await ref.putFile(
      File(file.path),
      SettableMetadata(contentType: contentType),
    );

    return upload.ref.getDownloadURL();
  }

  Future<void> _publish() async {
    if (_posting) return;

    final text = _postController.text.trim();
    final hasAttachment = _attachment != null;

    if (text.isEmpty && !hasAttachment) {
      showSnack(
        context,
        'Write something or attach a photo/video.',
        color: Colors.red,
      );
      return;
    }

    final uid = _currentUid();
    if (uid.isEmpty) {
      showSnack(context, 'Please sign in again.', color: Colors.red);
      return;
    }

    FocusScope.of(context).unfocus();
    setState(() => _posting = true);

    try {
      final postRef = _studentPosts.doc();
      String mediaUrl = '';
      String mediaType = '';

      final mentionData = await _resolveMentions(text);
      final mentionedUserIds =
          mentionData['ids'] ?? <String>[];
      final mentionedUsernames =
          mentionData['usernames'] ?? <String>[];

      final attachment = _attachment;
      final attachmentIsVideo = _attachmentIsVideo;

      if (attachment != null) {
        mediaUrl = await _uploadStudentPostMedia(
          postId: postRef.id,
          file: attachment,
          video: attachmentIsVideo,
        ) ?? '';
        mediaType = attachmentIsVideo ? 'video' : 'image';
      }

      await postRef.set({
        'authorId': uid,
        'authorName': userName.value.trim().isNotEmpty
            ? userName.value.trim()
            : 'Student',
        'authorProfileImage': userProfileImage.value.trim(),
        'college': userCollege.value.trim(),
        'text': text,
        'mediaUrl': mediaUrl,
        'mediaType': mediaType,
        'mentionedUserIds': mentionedUserIds,
        'mentionedUsernames': mentionedUsernames,
        'createdAt': FieldValue.serverTimestamp(),
      });

      await _notifyStudentPostFollowers(
        authorUid: uid,
        postId: postRef.id,
        postText: text,
      );

      for (final mentionedUid in mentionedUserIds) {
        await FirebaseFirestore.instance.collection('notifications').add({
          'recipientId': mentionedUid,
          'senderId': uid,
          'senderName': userName.value.trim().isNotEmpty
              ? userName.value.trim()
              : 'Student',
          'senderProfileImage': userProfileImage.value.trim(),
          'type': 'student_mention',
          'title': '${userName.value} mentioned you in a post',
          'body': text.isEmpty ? 'You were mentioned in a post.' : text,
          'relatedId': postRef.id,
          'isRead': false,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }

      if (!mounted) return;

      setState(() {
        _postController.clear();
        _attachment = null;
        _attachmentIsVideo = false;
      });

      showSnack(
        context,
        'Posted to your campus feed',
        color: AppColors.green,
      );
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not publish post: $e',
          color: Colors.red,
        );
      }
    } finally {
      if (mounted) {
        setState(() => _posting = false);
      }
    }
  }

