class _CustomSticker {
  final String id;
  final String url;
  final String mediaType;
  final Timestamp? createdAt;

  const _CustomSticker({
    required this.id,
    required this.url,
    required this.mediaType,
    required this.createdAt,
  });

  factory _CustomSticker.fromDoc(
      QueryDocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data();
    return _CustomSticker(
      id: doc.id,
      url: data['url']?.toString().trim() ?? '',
      mediaType: data['type']?.toString().trim().toLowerCase() == 'video'
          ? 'video'
          : 'image',
      createdAt: data['createdAt'] is Timestamp
          ? data['createdAt'] as Timestamp
          : null,
    );
  }
}

CollectionReference<Map<String, dynamic>> _customStickersRef(String uid) =>
    FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('customStickers');

Future<_CustomSticker?> _createCustomCommentSticker(
    BuildContext context, {
      required bool video,
    }) async {
  final uid = _currentUid();
  if (uid.isEmpty) {
    showSnack(context, 'Please sign in again.', color: Colors.red);
    return null;
  }

  try {
    XFile? picked;
    if (video) {
      picked = await ImagePicker().pickVideo(
        source: ImageSource.gallery,
        maxDuration: const Duration(seconds: 10),
      );
    } else {
      // Keep the original image so the editor can preserve transparency and
      // composite text, emoji and drawing layers before uploading.
      picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 94,
        maxWidth: 1600,
        maxHeight: 1600,
      );
      if (picked != null && context.mounted) {
        final edited = await Navigator.of(context).push<XFile>(
          MaterialPageRoute(
            builder: (_) => _PeerGridStickerEditor(source: picked!),
          ),
        );
        picked = edited;
      }
    }

    if (picked == null) return null;

    final stickerRef = _customStickersRef(uid).doc();
    final extension = video ? 'mp4' : 'png';
    final contentType = video ? 'video/mp4' : 'image/png';
    final storageRef = FirebaseStorage.instance
        .ref()
        .child('customStickers')
        .child(uid)
        .child('${stickerRef.id}.$extension');

    final bytes = await picked.readAsBytes();
    await storageRef.putData(
      bytes,
      SettableMetadata(contentType: contentType),
    );

    final url = await storageRef.getDownloadURL();

    await stickerRef.set({
      'userId': uid,
      'url': url,
      'type': video ? 'video' : 'image',
      'createdAt': FieldValue.serverTimestamp(),
    });

    return _CustomSticker(
      id: stickerRef.id,
      url: url,
      mediaType: video ? 'video' : 'image',
      createdAt: Timestamp.now(),
    );
  } catch (e) {
    if (context.mounted) {
      showSnack(
        context,
        'Could not create sticker: $e',
        color: Colors.red,
        bottomMargin: 20,
      );
    }
    return null;
  }
}


/// Imports image stickers without re-encoding them, preserving PNG/WebP alpha.
/// Users can choose multiple image files, preview them, then add them to their
/// own custom sticker collection for use in comments.
Future<int> _importCustomCommentStickers(BuildContext context) async {
  final uid = _currentUid();
  if (uid.isEmpty) {
    showSnack(context, 'Please sign in again.', color: Colors.red);
    return 0;
  }

  try {
    final files = await ImagePicker().pickMultiImage();
    if (files.isEmpty || !context.mounted) return 0;

    final accepted = files.where((file) {
      final name = file.name.toLowerCase();
      return name.endsWith('.png') || name.endsWith('.webp') ||
          name.endsWith('.jpg') || name.endsWith('.jpeg') ||
          name.endsWith('.gif') || name.endsWith('.bmp');
    }).toList();
    if (accepted.isEmpty) {
      showSnack(context, 'Select PNG, WebP, or other supported image files.');
      return 0;
    }

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppColors.cream,
        title: Text('Import ${accepted.length} sticker${accepted.length == 1 ? '' : 's'}?'),
        content: SizedBox(
          width: 360,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Text('Preview your selected images. Transparent PNG/WebP backgrounds are preserved.'),
                const SizedBox(height: 12),
                GridView.builder(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  itemCount: accepted.length,
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 3, crossAxisSpacing: 8, mainAxisSpacing: 8,
                  ),
                  itemBuilder: (_, index) => Container(
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: AppColors.ink, width: 1),
                    ),
                    padding: const EdgeInsets.all(5),
                    child: Image.file(File(accepted[index].path), fit: BoxFit.contain,
                        errorBuilder: (_, __, ___) => const Icon(Icons.broken_image_outlined)),
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancel')),
          ElevatedButton(onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Import stickers')),
        ],
      ),
    );
    if (confirmed != true || !context.mounted) return 0;

    var imported = 0;
    for (final file in accepted) {
      try {
        final bytes = await file.readAsBytes();
        if (bytes.isEmpty) continue;
        final lowerName = file.name.toLowerCase();
        final isWebp = lowerName.endsWith('.webp');
        final isGif = lowerName.endsWith('.gif');
        final ext = isWebp ? 'webp' : (isGif ? 'gif' : (lowerName.endsWith('.jpg') || lowerName.endsWith('.jpeg') ? 'jpg' : (lowerName.endsWith('.bmp') ? 'bmp' : 'png')));
        final contentType = isWebp ? 'image/webp' : (isGif ? 'image/gif' : (ext == 'jpg' ? 'image/jpeg' : (ext == 'bmp' ? 'image/bmp' : 'image/png')));
        final stickerRef = _customStickersRef(uid).doc();
        final storageRef = FirebaseStorage.instance.ref()
            .child('customStickers').child(uid).child('${stickerRef.id}.$ext');
        await storageRef.putData(bytes, SettableMetadata(contentType: contentType));
        final url = await storageRef.getDownloadURL();
        await stickerRef.set({
          'userId': uid,
          'url': url,
          'type': 'image',
          'source': 'device_import',
          'originalName': file.name,
          'createdAt': FieldValue.serverTimestamp(),
        });
        imported++;
      } catch (_) {
        // Keep importing remaining files if one file fails.
      }
    }
    if (context.mounted) {
      showSnack(context, imported == 0
          ? 'No stickers could be imported.'
          : 'Imported $imported sticker${imported == 1 ? '' : 's'}.');
    }
    return imported;
  } catch (e) {
    if (context.mounted) showSnack(context, 'Could not import stickers: $e', color: Colors.red);
    return 0;
  }
}


// WhatsApp-style custom sticker editor. The final image is rendered as PNG so
// transparent pixels from background removal remain transparent in Storage.
class _StickerLayer {
  final String id;
  String text;
  double x;
  double y;
  double scale;
  double rotation;
  Color color;
  bool isEmoji;

  _StickerLayer({
    required this.id,
    required this.text,
    this.x = .5,
    this.y = .5,
    this.scale = 1,
    this.rotation = 0,
    this.color = Colors.white,
    this.isEmoji = false,
  });
}

class _PeerGridStickerEditor extends StatefulWidget {
  final XFile source;
  const _PeerGridStickerEditor({required this.source});

  @override
  State<_PeerGridStickerEditor> createState() => _PeerGridStickerEditorState();
}

class _PeerGridStickerEditorState extends State<_PeerGridStickerEditor> {
  final GlobalKey _canvasKey = GlobalKey();
  final List<_StickerLayer> _layers = [];
  final List<List<Offset>> _strokes = [];
  String _imagePath = '';
  bool _busy = false;
  bool _drawMode = false;
  bool _removeMode = false;
  bool _rotateMode = false;
  double _rotation = 0;
  Color _drawColor = Colors.white;
  List<Offset>? _activeStroke;
  int _nextId = 0;

  @override
  void initState() {
    super.initState();
    _imagePath = widget.source.path;
  }

  Future<void> _removeBackground() async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      final result = await NativeCutout.removeBackground(
        _imagePath,
        options: const CutoutOptions(cropToSubject: false, writeToCache: true),
      );
      if (!mounted) return;
      switch (result) {
        case CutoutFileSuccess(:final path):
          setState(() {
            _imagePath = path;
            _removeMode = false;
          });
          showSnack(context, 'Background removed. Transparent cutout ready.');
          break;
        case CutoutBytesSuccess(:final pngBytes):
          final dir = await getTemporaryDirectory();
          final file = File('${dir.path}/peergrid_cutout_${DateTime.now().millisecondsSinceEpoch}.png');
          await file.writeAsBytes(pngBytes, flush: true);
          if (!mounted) return;
          setState(() => _imagePath = file.path);
          showSnack(context, 'Background removed.');
          break;
        case CutoutFailure(:final message):
          showSnack(context, message, color: Colors.red, bottomMargin: 20);
          break;
      }
    } catch (e) {
      if (mounted) {
        showSnack(context, 'Background removal failed. Check your connection and try again.', color: Colors.red, bottomMargin: 20);
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _cropImage() async {
    if (_busy) return;
    try {
      final cropped = await ImageCropper().cropImage(
        sourcePath: _imagePath,
        compressFormat: ImageCompressFormat.png,
        compressQuality: 100,
        uiSettings: [
          AndroidUiSettings(
            toolbarTitle: 'Crop sticker',
            toolbarColor: AppColors.cream,
            toolbarWidgetColor: AppColors.ink,
            backgroundColor: AppColors.cream,
            activeControlsWidgetColor: AppColors.blue,
            cropStyle: CropStyle.rectangle,
            initAspectRatio: CropAspectRatioPreset.original,
            lockAspectRatio: false,
            aspectRatioPresets: const [
              CropAspectRatioPreset.original,
              CropAspectRatioPreset.square,
              CropAspectRatioPreset.ratio4x3,
            ],
          ),
          IOSUiSettings(
            title: 'Crop sticker',
            cropStyle: CropStyle.rectangle,
            aspectRatioPresets: const [
              CropAspectRatioPreset.original,
              CropAspectRatioPreset.square,
              CropAspectRatioPreset.ratio4x3,
            ],
          ),
        ],
      );
      if (cropped != null && mounted) setState(() => _imagePath = cropped.path);
    } catch (_) {
      if (mounted) showSnack(context, 'Could not crop this image.', color: Colors.red);
    }
  }

  Future<void> _addText() async {
    final controller = TextEditingController();
    Color chosen = Colors.white;
    final value = await showDialog<String>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('Add sticker text'),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(controller: controller, autofocus: true, maxLines: 3,
                decoration: const InputDecoration(hintText: 'Type something…')),
            const SizedBox(height: 12),
            Wrap(spacing: 8, children: [Colors.white, Colors.black, Colors.yellow, Colors.red, Colors.blue, Colors.pink].map((c) => GestureDetector(
              onTap: () => setDialogState(() => chosen = c),
              child: Container(width: 30, height: 30, decoration: BoxDecoration(color: c, shape: BoxShape.circle, border: Border.all(color: chosen == c ? AppColors.blue : Colors.grey, width: chosen == c ? 3 : 1)),),
            )).toList()),
          ]),
          actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(dialogContext, controller.text.trim()), child: const Text('Add'))],
        ),
      ),
    );
    if (!mounted || value == null || value.trim().isEmpty) return;
    setState(() => _layers.add(_StickerLayer(id: '${_nextId++}', text: value.trim(), color: chosen)));
  }

  Future<void> _addEmoji() async {
    const emojis = ['😀','😂','🥹','😍','😎','🥳','😭','😡','❤️','🔥','✨','💯','👍','👎','🙏','🎉','💀','🤝','🌈','⭐','💖','🤍','😴','🤔','🙌','🫶','👀','🐱','🐶','🍕','☕','🎓'];
    final emoji = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (context) => SafeArea(child: Padding(
        padding: const EdgeInsets.all(16),
        child: GridView.count(crossAxisCount: 6, shrinkWrap: true, children: emojis.map((e) => InkWell(onTap: () => Navigator.pop(context, e), child: Center(child: Text(e, style: const TextStyle(fontSize: 30))))).toList()),
      )),
    );
    if (!mounted || emoji == null) return;
    setState(() => _layers.add(_StickerLayer(id: '${_nextId++}', text: emoji, isEmoji: true, scale: 1.5)));
  }

  Future<void> _export() async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await WidgetsBinding.instance.endOfFrame;
      final boundary = _canvasKey.currentContext?.findRenderObject() as RenderRepaintBoundary?;
      if (boundary == null) throw StateError('Sticker canvas is not ready');
      final image = await boundary.toImage(pixelRatio: 3);
      final data = await image.toByteData(format: ui.ImageByteFormat.png);
      image.dispose();
      if (data == null) throw StateError('Could not export sticker');
      final dir = await getTemporaryDirectory();
      final file = File('${dir.path}/peergrid_sticker_${DateTime.now().millisecondsSinceEpoch}.png');
      await file.writeAsBytes(data.buffer.asUint8List(), flush: true);
      if (!mounted) return;
      Navigator.of(context).pop(XFile(file.path, name: 'peergrid_sticker.png'));
    } catch (e) {
      if (mounted) showSnack(context, 'Could not export sticker. Please try again.', color: Colors.red, bottomMargin: 20);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Widget _tool(IconData icon, String label, VoidCallback onTap, {bool selected = false}) =>
      InkWell(onTap: _busy ? null : onTap, borderRadius: BorderRadius.circular(12), child: Container(
        width: 68, padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 4),
        decoration: BoxDecoration(color: selected ? AppColors.cyan : Colors.white, border: Border.all(color: AppColors.ink, width: 1.5), borderRadius: BorderRadius.circular(12)),
        child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(icon, size: 23), const SizedBox(height: 4), Text(label, textAlign: TextAlign.center, style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w800))]),
      ));

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        title: const Text('Sticker editor', style: TextStyle(fontWeight: FontWeight.w900)),
        leading: IconButton(icon: const Icon(Icons.close), onPressed: _busy ? null : () => Navigator.pop(context)),
        actions: [TextButton.icon(onPressed: _busy ? null : _export, icon: const Icon(Icons.check), label: const Text('Done', style: TextStyle(fontWeight: FontWeight.w900)))],
      ),
      body: SafeArea(child: Column(children: [
        Expanded(child: Center(child: Padding(
          padding: const EdgeInsets.all(14),
          child: AspectRatio(aspectRatio: 1, child: RepaintBoundary(key: _canvasKey, child: LayoutBuilder(builder: (context, constraints) {
            final size = Size(constraints.maxWidth, constraints.maxHeight);
            return GestureDetector(
              onPanStart: _drawMode ? (d) { final box = context.findRenderObject() as RenderBox; final p = box.globalToLocal(d.globalPosition); setState(() { _activeStroke = [p]; _strokes.add(_activeStroke!); }); } : null,
              onPanUpdate: _drawMode ? (d) { final box = context.findRenderObject() as RenderBox; final p = box.globalToLocal(d.globalPosition); setState(() => _activeStroke?.add(p)); } : null,
              onPanEnd: _drawMode ? (_) => setState(() => _activeStroke = null) : null,
              child: ClipRect(child: Container(
                color: Colors.transparent,
                child: Stack(fit: StackFit.expand, children: [
                  Transform.rotate(angle: _rotation, child: Image.file(File(_imagePath), fit: BoxFit.contain, errorBuilder: (_, __, ___) => const Center(child: Icon(Icons.broken_image, size: 48)))),
                  CustomPaint(painter: _StickerDrawingPainter(_strokes, _drawColor)),
                  ..._layers.map((layer) => Positioned(
                    left: (layer.x * size.width).clamp(0.0, size.width),
                    top: (layer.y * size.height).clamp(0.0, size.height),
                    child: GestureDetector(
                      onScaleUpdate: (details) => setState(() {
                        layer.x = (layer.x + details.focalPointDelta.dx / size.width).clamp(.02, .98);
                        layer.y = (layer.y + details.focalPointDelta.dy / size.height).clamp(.02, .98);
                        layer.scale = (layer.scale * details.scale).clamp(.4, 4.0);
                        layer.rotation += details.rotation;
                      }),
                      onLongPress: () => setState(() => _layers.remove(layer)),
                      child: Transform.rotate(
                        angle: layer.rotation,
                        child: Transform.scale(
                          scale: layer.scale,
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                            decoration: layer.isEmoji
                                ? null
                                : BoxDecoration(
                              color: Colors.black.withValues(alpha: .38),
                              borderRadius: BorderRadius.circular(6),
                            ),
                            child: Text(
                              layer.text,
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: layer.color,
                                fontSize: layer.isEmoji ? 34 : 26,
                                fontWeight: FontWeight.w900,
                                shadows: const [
                                  Shadow(color: Colors.black87, blurRadius: 3, offset: Offset(1, 2)),
                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  )),
                  if (_busy) Container(color: Colors.black26, child: const Center(child: CircularProgressIndicator())),
                ]),
              )),
            );
          }))),
        ))),
        if (_drawMode) Padding(padding: const EdgeInsets.only(bottom: 8), child: Wrap(spacing: 10, children: [Colors.white, Colors.black, Colors.red, Colors.yellow, Colors.blue].map((c) => GestureDetector(onTap: () => setState(() => _drawColor = c), child: Container(width: 28, height: 28, decoration: BoxDecoration(color: c, shape: BoxShape.circle, border: Border.all(color: _drawColor == c ? AppColors.blue : Colors.grey, width: 2))))).toList())),
        SizedBox(height: 94, child: ListView(scrollDirection: Axis.horizontal, padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8), children: [
          _tool(Icons.auto_fix_high, 'Remove BG', _removeBackground),
          const SizedBox(width: 8),
          _tool(Icons.crop, 'Crop', _cropImage),
          const SizedBox(width: 8),
          _tool(Icons.rotate_right, 'Rotate', () => setState(() => _rotation += math.pi / 2)),
          const SizedBox(width: 8),
          _tool(Icons.title, 'Add text', _addText),
          const SizedBox(width: 8),
          _tool(Icons.emoji_emotions_outlined, 'Emoji', _addEmoji),
          const SizedBox(width: 8),
          _tool(Icons.draw, 'Draw', () => setState(() => _drawMode = !_drawMode), selected: _drawMode),
          const SizedBox(width: 8),
          _tool(Icons.undo, 'Undo', () => setState(() { if (_strokes.isNotEmpty) { _strokes.removeLast(); } else if (_layers.isNotEmpty) { _layers.removeLast(); } }),),
        ])),
        const Padding(padding: EdgeInsets.fromLTRB(12, 0, 12, 12), child: Text('Drag text or emoji to move • pinch to resize/rotate • long-press a layer to delete', textAlign: TextAlign.center, style: TextStyle(fontSize: 11, color: AppColors.muted))),
      ])),
    );
  }
}

class _StickerCheckerPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    const tile = 16.0;
    final paint = Paint();
    for (var y = 0; y < size.height; y += tile.toInt()) {
      for (var x = 0; x < size.width; x += tile.toInt()) {
        paint.color = ((x ~/ tile) + (y ~/ tile)).isEven ? const Color(0xFFE9E9E9) : Colors.white;
        canvas.drawRect(Rect.fromLTWH(x.toDouble(), y.toDouble(), tile, tile), paint);
      }
    }
  }
  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _StickerDrawingPainter extends CustomPainter {
  final List<List<Offset>> strokes;
  final Color color;
  _StickerDrawingPainter(this.strokes, this.color);
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color..strokeWidth = 4..strokeCap = StrokeCap.round..strokeJoin = StrokeJoin.round..style = PaintingStyle.stroke;
    for (final points in strokes) {
      if (points.isEmpty) continue;
      final path = Path()..moveTo(points.first.dx, points.first.dy);
      for (final point in points.skip(1)) { path.lineTo(point.dx, point.dy); }
      canvas.drawPath(path, paint);
    }
  }
  @override
  bool shouldRepaint(covariant _StickerDrawingPainter oldDelegate) => true;
}

class _CommentStickerMedia extends StatefulWidget {
  final String url;
  final String mediaType;

  const _CommentStickerMedia({
    required this.url,
    required this.mediaType,
  });

  @override
  State<_CommentStickerMedia> createState() => _CommentStickerMediaState();
}

class _CommentStickerMediaState extends State<_CommentStickerMedia> {
  VideoPlayerController? _controller;

  @override
  void initState() {
    super.initState();
    if (widget.mediaType == 'video') {
      final controller = VideoPlayerController.networkUrl(
        Uri.parse(widget.url),
      );
      _controller = controller;
      controller.setLooping(true);
      controller.setVolume(0);
      controller.initialize().then((_) {
        if (!mounted) return;
        setState(() {});
        controller.play();
      }).catchError((_) {
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (widget.mediaType != 'video') {
      return Image.network(
        widget.url,
        fit: BoxFit.contain,
        errorBuilder: (_, __, ___) =>
        const Icon(Icons.broken_image_outlined),
      );
    }

    final controller = _controller;
    if (controller == null || !controller.value.isInitialized) {
      return const SizedBox(
        width: 150,
        height: 150,
        child: Center(child: CircularProgressIndicator()),
      );
    }

    return AspectRatio(
      aspectRatio: controller.value.aspectRatio == 0
          ? 1
          : controller.value.aspectRatio,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(10),
        child: VideoPlayer(controller),
      ),
    );
  }
}

Future<_CustomSticker?> _showCustomCommentStickerPicker(
