                            child: Padding(
                              padding: const EdgeInsets.all(18),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Row(
                                    children: [
                                      Expanded(child: _ChatAttachButton(
                                        icon: Icons.photo_rounded,
                                        label: 'Create sticker',
                                        onTap: () => Navigator.of(choiceContext).pop(false),
                                      )),
                                      const SizedBox(width: 12),
                                      Expanded(child: _ChatAttachButton(
                                        icon: Icons.videocam_rounded,
                                        label: 'Video sticker',
                                        onTap: () => Navigator.of(choiceContext).pop(true),
                                      )),
                                    ],
                                  ),
                                  const SizedBox(height: 12),
                                  SizedBox(
                                    width: double.infinity,
                                    child: _ChatAttachButton(
                                      icon: Icons.collections_rounded,
                                      label: 'Import stickers from phone',
                                      onTap: () => Navigator.of(choiceContext).pop(null),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        );
                        if (!sheetContext.mounted) return;
                        if (choice == null) {
                          await _importCustomCommentStickers(sheetContext);
                          return;
                        }
                        final sticker = await _createCustomCommentSticker(
                          sheetContext,
                          video: choice,
                        );
                        if (!sheetContext.mounted || sticker == null) return;
                        Navigator.of(sheetContext).pop(sticker);
                      },
                    ),
                    const SizedBox(width: 6),
                    NeoIconButton(
                      icon: Icons.close_rounded,
                      onTap: () => Navigator.of(sheetContext).pop(),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1),
              Expanded(
                child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: _customStickersRef(uid)
                      .orderBy('createdAt', descending: true)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return const Center(
                        child: Text(
                          'Could not load your stickers.',
                          style: TextStyle(fontWeight: FontWeight.w700),
                        ),
                      );
                    }

                    if (snapshot.connectionState ==
                        ConnectionState.waiting) {
                      return const Center(child: CircularProgressIndicator());
                    }

                    final docs = snapshot.data?.docs ??
                        <QueryDocumentSnapshot<Map<String, dynamic>>>[];

                    if (docs.isEmpty) {
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(24),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Icon(
                                Icons.sticky_note_2_outlined,
                                size: 48,
                              ),
                              const SizedBox(height: 10),
                              const Text(
                                'No custom stickers yet.',
                                style: TextStyle(fontWeight: FontWeight.w900),
                              ),
                              const SizedBox(height: 6),
                              const Text(
                                'Tap + to create an image or video sticker.',
                                textAlign: TextAlign.center,
                                style: TextStyle(color: AppColors.muted),
                              ),
                            ],
                          ),
                        ),
                      );
                    }

                    return GridView.builder(
                      padding: const EdgeInsets.all(16),
                      itemCount: docs.length,
                      gridDelegate:
                      const SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: 4,
                        mainAxisSpacing: 12,
                        crossAxisSpacing: 12,
                      ),
                      itemBuilder: (_, index) {
                        final sticker = _CustomSticker.fromDoc(docs[index]);
                        return GestureDetector(
                          onTap: () => Navigator.of(sheetContext).pop(sticker),
                          child: Container(
                            padding: const EdgeInsets.all(8),
                            decoration: neoDeco(
                              color: Colors.white,
                              radius: 14,
                              shadow: false,
                            ),
                            child: sticker.mediaType == 'video'
                                ? const Center(
                              child: Icon(
                                Icons.play_circle_fill_rounded,
                                size: 42,
                                color: AppColors.ink,
                              ),
                            )
                                : Image.network(
                              sticker.url,
                              fit: BoxFit.contain,
                              errorBuilder: (_, __, ___) =>
                              const Icon(Icons.broken_image_outlined),
                            ),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      );
    },
  );
}

class _StudentPostCard extends StatelessWidget {
  final _StudentFeedPost post;

  const _StudentPostCard({required this.post});

  Future<void> _toggleLike() async {
    final uid = _currentUid();
    if (uid.isEmpty) return;

    final ref = FirebaseFirestore.instance
        .collection(post.collectionName)
        .doc(post.id)
        .collection('likes')
        .doc(uid);

    try {
      final existing = await ref.get();
      if (existing.exists) {
        await ref.delete();
      } else {
        await ref.set({
          'userId': uid,
          'createdAt': FieldValue.serverTimestamp(),
        });

        await _notifyStudentPostAuthor(
          authorUid: post.authorId,
          postId: post.id,
          type: 'student_post_like',
          title: '${userName.value.trim().isNotEmpty ? userName.value.trim() : 'Student'} liked your post',
          body: 'Your community post received a new like.',
        );
      }
    } catch (e) {
      // The UI will remain unchanged if the backend rejects the action.
    }
  }

  Future<void> _showLikes(BuildContext context) async {
    final likesRef = FirebaseFirestore.instance
        .collection(post.collectionName)
        .doc(post.id)
        .collection('likes');
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppColors.cream,
      builder: (sheetContext) => SafeArea(
        child: SizedBox(
          height: MediaQuery.of(sheetContext).size.height * .65,
          child: Column(
            children: [
              const Padding(
                padding: EdgeInsets.all(16),
                child: Text('People who liked this post', style: TextStyle(fontSize: 19, fontWeight: FontWeight.w900)),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: likesRef.orderBy('createdAt', descending: true).snapshots(),
                  builder: (context, snapshot) {
                    if (snapshot.hasError) return const Center(child: Text('Could not load likes.'));
                    if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());
                    final docs = snapshot.data!.docs;
                    if (docs.isEmpty) return const Center(child: Text('No likes yet.'));
                    return ListView.builder(
                      itemCount: docs.length,
                      itemBuilder: (context, index) {
                        final like = docs[index].data();
                        final uid = (like['userId'] ?? docs[index].id).toString();
                        return FutureBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                          future: FirebaseFirestore.instance.collection('users').doc(uid).get(),
                          builder: (context, userSnapshot) {
                            final user = userSnapshot.data?.data() ?? <String, dynamic>{};
                            final name = (user['name'] ?? user['displayName'] ?? user['username'] ?? 'Student').toString();
                            final image = (user['profileImage'] ?? user['photoURL'] ?? user['photoUrl'] ?? '').toString();
                            return ListTile(
                              leading: ProfileAvatar(imageUrl: image, name: name, radius: 22),
                              title: Text(name, style: const TextStyle(fontWeight: FontWeight.w800)),
                              onTap: () {
                                if (uid.isEmpty) return;
                                Navigator.of(sheetContext).pop();
                                pushPage(context, PublicStudentProfileScreen(profile: {...user, 'uid': uid, 'id': uid}));
                              },
                            );
                          },
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Future<void> _showComments(BuildContext context) async {
    final controller = TextEditingController();
    String? replyToCommentId;
    String? replyToCommentName;

    Future<void> sendComment({
      _CustomSticker? sticker,
    }) async {
      final uid = _currentUid();
      if (uid.isEmpty) return;

      final text = controller.text.trim();
      if (sticker == null && text.isEmpty) return;

      try {
        final isSticker = sticker != null;
        await FirebaseFirestore.instance
            .collection(post.collectionName)
            .doc(post.id)
            .collection('comments')
            .add({
          'userId': uid,
          'userName': userName.value.trim().isNotEmpty
              ? userName.value.trim()
              : 'Student',
          'userProfileImage': userProfileImage.value.trim(),
          'text': isSticker ? '' : text,
          'type': isSticker ? 'sticker' : 'text',
          'stickerId': sticker?.id ?? '',
          'stickerUrl': sticker?.url ?? '',
          'stickerType': sticker?.mediaType ?? '',
          'replyToCommentId': replyToCommentId ?? '',
          'replyToCommentName': replyToCommentName ?? '',
          'createdAt': FieldValue.serverTimestamp(),
        });
        replyToCommentId = null;
        replyToCommentName = null;

        // The comment is already saved. Notification delivery is best-effort:
        // a notification permission error must not report the comment itself
        // as failed or prevent the input from clearing.
        try {
          if (post.authorId.isNotEmpty && post.authorId != uid) {
            await _notifyStudentPostAuthor(
              authorUid: post.authorId,
              postId: post.id,
              type: 'student_post_comment',
              title:
              '${userName.value.trim().isNotEmpty ? userName.value.trim() : 'Student'} commented on your post',
              body: isSticker ? 'Sent a sticker.' : text,
            );
          }
        } catch (_) {
          // Keep the saved comment successful even if notification fails.
        }

        if (!isSticker) controller.clear();
      } catch (e) {
        if (context.mounted) {
          showSnack(
            context,
            'Could not add comment: $e',
            color: Colors.red,
            bottomMargin: 20,
          );
        }
      }
    }

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: AppColors.cream,
        builder: (sheetContext) {
          return SafeArea(
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                16,
                14,
                16,
                16 + MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.72,
                child: Column(
                  children: [
                    Container(
                      width: 44,
                      height: 5,
                      decoration: BoxDecoration(
                        color: AppColors.ink,
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    const SizedBox(height: 14),
                    const Text(
                      'Comments',
                      style: TextStyle(
                        fontSize: 21,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 12),
                    Expanded(
                      child: StreamBuilder<
                          QuerySnapshot<Map<String, dynamic>>>(
                        stream: FirebaseFirestore.instance
                            .collection(post.collectionName)
                            .doc(post.id)
                            .collection('comments')
                            .orderBy('createdAt')
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (snapshot.hasError) {
                            return Center(
                              child: Text(
                                'Could not load comments.\n${snapshot.error}',
                                textAlign: TextAlign.center,
                              ),
                            );
                          }

                          if (snapshot.connectionState ==
                              ConnectionState.waiting) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }

                          final docs = snapshot.data?.docs ??
                              <QueryDocumentSnapshot<
                                  Map<String, dynamic>>>[];

                          if (docs.isEmpty) {
                            return const Center(
                              child: Text(
                                'No comments yet.\nBe the first to comment.',
                                textAlign: TextAlign.center,
                                style: TextStyle(
                                  color: AppColors.muted,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            );
                          }

                          return ListView.separated(
                            itemCount: docs.length,
                            separatorBuilder: (_, __) =>
                            const SizedBox(height: 10),
                            itemBuilder: (context, index) {
                              final data = docs[index].data();
                              final name =
                                  data['userName']?.toString() ?? 'Student';
                              final image =
                                  data['userProfileImage']?.toString() ?? '';
                              final text =
                                  data['text']?.toString() ?? '';
                              final type =
                                  data['type']?.toString().toLowerCase() ??
                                      'text';
                              final stickerUrl =
                                  data['stickerUrl']?.toString().trim() ?? '';

                              final parentCommentId = (data['replyToCommentId'] ?? '').toString();
                              return Padding(
                                padding: EdgeInsets.only(left: parentCommentId.isNotEmpty ? 22 : 0),
                                child: Container(
                                  padding: const EdgeInsets.all(12),
                                  decoration: neoDeco(
                                    color: Colors.white,
                                    radius: 14,
                                    shadow: false,
                                  ),
                                  child: Row(
                                    crossAxisAlignment:
                                    CrossAxisAlignment.start,
                                    children: [
                                      ProfileAvatar(
                                        imageUrl: image,
                                        name: name,
                                        radius: 18,
                                      ),
                                      const SizedBox(width: 10),
                                      Expanded(
                                        child: Column(
                                          crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                          children: [
                                            Text(
                                              name,
                                              style: const TextStyle(
                                                fontWeight: FontWeight.w900,
                                              ),
                                            ),
                                            const SizedBox(height: 3),
                                            if ((data['replyToCommentName'] ?? '').toString().isNotEmpty)
                                              Container(
                                                margin: const EdgeInsets.only(bottom: 5),
                                                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
                                                decoration: BoxDecoration(color: AppColors.softBlue, borderRadius: BorderRadius.circular(7)),
                                                child: Text('Replying to @${data['replyToCommentName']}', style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800)),
                                              ),
                                            if (type == 'sticker' &&
                                                stickerUrl.isNotEmpty)
                                              Padding(
                                                padding:
                                                const EdgeInsets.only(top: 4),
                                                child: ConstrainedBox(
                                                  constraints:
                                                  const BoxConstraints(
                                                    maxWidth: 170,
                                                    maxHeight: 170,
                                                  ),
                                                  child: _CommentStickerMedia(
                                                    url: stickerUrl,
                                                    mediaType:
                                                    data['stickerType']
                                                        ?.toString()
                                                        .trim()
                                                        .toLowerCase() ==
                                                        'video'
                                                        ? 'video'
                                                        : 'image',
                                                  ),
                                                ),
                                              )
                                            else
                                              Text(
                                                text,
                                                style: const TextStyle(
                                                  fontWeight: FontWeight.w600,
                                                  height: 1.3,
                                                ),
                                              ),
                                            _FirestoreReactionBar(
                                              document: FirebaseFirestore.instance
                                                  .collection(post.collectionName)
                                                  .doc(post.id)
                                                  .collection('comments')
                                                  .doc(docs[index].id),
                                            ),
                                            Align(
                                              alignment: Alignment.centerLeft,
                                              child: TextButton.icon(
                                                style: TextButton.styleFrom(padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 0), minimumSize: const Size(0, 28), tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                                                onPressed: () {
                                                  replyToCommentId = docs[index].id;
                                                  replyToCommentName = name.trim().isEmpty ? 'Student' : name.trim();
                                                  controller.text = '@$replyToCommentName ';
                                                  controller.selection = TextSelection.collapsed(offset: controller.text.length);
                                                  FocusScope.of(sheetContext).requestFocus(FocusNode());
                                                },
                                                icon: const Icon(Icons.reply_rounded, size: 17),
                                                label: const Text('Reply', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w800)),
                                              ),
                                            ),
                                          ],
                                        ),
                                      ),
                                      if ((data['userId']?.toString() ?? '') == _currentUid() || (post.collectionName == 'studentPosts' && isPeerGridGlobalAdmin()))
                                        IconButton(
                                          tooltip: 'Delete comment',
                                          visualDensity: VisualDensity.compact,
                                          icon: const Icon(Icons.delete_outline_rounded, color: Colors.redAccent),
                                          onPressed: () async {
                                            final confirmed = await showDialog<bool>(
                                              context: sheetContext,
                                              builder: (dialogContext) => AlertDialog(
                                                title: const Text('Delete comment?'),
                                                content: const Text('This comment will be permanently deleted.'),
                                                actions: [
                                                  TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancel')),
                                                  TextButton(onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Delete')),
                                                ],
                                              ),
                                            );
                                            if (confirmed != true || !sheetContext.mounted) return;
                                            try {
                                              await FirebaseFirestore.instance
                                                  .collection(post.collectionName)
                                                  .doc(post.id)
                                                  .collection('comments')
                                                  .doc(docs[index].id)
                                                  .delete();
                                            } catch (e) {
                                              if (sheetContext.mounted) showSnack(sheetContext, 'Could not delete comment: $e', color: Colors.red);
                                            }
                                          },
                                        ),
                                    ],
                                  ),
                                ),
                              );
                            },
                          );
                        },
                      ),
                    ),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        NeoIconButton(
                          icon: Icons.sticky_note_2_rounded,
                          color: AppColors.cyan,
                          size: 46,
                          onTap: () async {
                            FocusScope.of(sheetContext).unfocus();
                            final sticker =
                            await _showCustomCommentStickerPicker(
                              sheetContext,
                            );
                            if (sticker == null || !sheetContext.mounted) {
                              return;
                            }
                            await sendComment(sticker: sticker);
                          },
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: TextField(
                            controller: controller,
                            minLines: 1,
                            maxLines: 3,
