  @override
  Widget build(BuildContext context) {
    final likesRef = FirebaseFirestore.instance
        .collection(post.collectionName)
        .doc(post.id)
        .collection('likes');

    final commentsRef = FirebaseFirestore.instance
        .collection(post.collectionName)
        .doc(post.id)
        .collection('comments');

    final uid = _currentUid();

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: neoDeco(
        color: Colors.white,
        radius: 26,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () async {
              if (post.authorId.isEmpty) return;
              try {
                final userDoc = await FirebaseFirestore.instance.collection('users').doc(post.authorId).get();
                if (!context.mounted) return;
                pushPage(context, PublicStudentProfileScreen(profile: {...?userDoc.data(), 'uid': post.authorId, 'id': post.authorId}));
              } catch (_) {}
            },
            child: Row(
              children: [
                ProfileAvatar(
                  imageUrl: post.profileImage,
                  name: post.author,
                  radius: 23,
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        post.author,
                        style: const TextStyle(
                          fontWeight: FontWeight.w900,
                          fontSize: 15,
                        ),
                      ),
                      Text(
                        '${post.college}  •  ${_studentPostTime(post.createdAt)}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: AppColors.muted,
                          fontSize: 12,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                if (post.collectionName == 'studentPosts' && isPeerGridGlobalAdmin())
                  IconButton(
                    tooltip: 'Admin: delete Community post',
                    icon: const Icon(Icons.delete_forever_rounded, color: Colors.redAccent),
                    onPressed: () async {
                      final confirmed = await showDialog<bool>(
                        context: context,
                        builder: (dialogContext) => AlertDialog(
                          title: const Text('Delete Community post?'),
                          content: const Text('This removes the post and its comments from the Community feed.'),
                          actions: [
                            TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancel')),
                            TextButton(onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Delete')),
                          ],
                        ),
                      );
                      if (confirmed != true || !context.mounted) return;
                      try {
                        final postRef = FirebaseFirestore.instance.collection(post.collectionName).doc(post.id);
                        final comments = await postRef.collection('comments').get();
                        final batch = FirebaseFirestore.instance.batch();
                        for (final comment in comments.docs) { batch.delete(comment.reference); }
                        batch.delete(postRef);
                        await batch.commit();
                        if (context.mounted) showSnack(context, 'Community post deleted.', color: AppColors.green, bottomMargin: 16);
                      } catch (e) {
                        if (context.mounted) showSnack(context, 'Could not delete post: $e', color: Colors.red, bottomMargin: 16);
                      }
                    },
                  ),
              ],
            ),
          ),
          if (post.text.trim().isNotEmpty) ...[
            const SizedBox(height: 12),
            Text(
              post.text,
              style: const TextStyle(
                fontSize: 15,
                height: 1.45,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
          if (post.mediaUrl.trim().isNotEmpty) ...[
            const SizedBox(height: 12),
            ClipRRect(
              borderRadius: BorderRadius.circular(18),
              child: post.mediaType == 'video'
                  ? _StudentFeedVideo(url: post.mediaUrl)
                  : Container(
                width: double.infinity,
                color: Colors.white,
                alignment: Alignment.center,
                child: AdaptiveImage(
                  image: NetworkImage(post.mediaUrl),
                  maxHeight: 420,
                  fit: BoxFit.contain,
                  error: const SizedBox(
                    height: 180,
                    child: Center(
                      child: Icon(
                        Icons.broken_image_rounded,
                        size: 44,
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ],
          const SizedBox(height: 14),
          Row(
            children: [
              StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: likesRef.doc(uid).snapshots(),
                builder: (context, likeSnapshot) {
                  final liked = likeSnapshot.data?.exists ?? false;

                  return StreamBuilder<
                      QuerySnapshot<Map<String, dynamic>>>(
                    stream: likesRef.snapshots(),
                    builder: (context, countSnapshot) {
                      final count = countSnapshot.data?.size ?? 0;

                      return Pressable(
                        onTap: _toggleLike,
                        child: Row(
                          children: [
                            Icon(
                              liked
                                  ? Icons.favorite_rounded
                                  : Icons.favorite_border_rounded,
                              color: liked ? Colors.red : AppColors.ink,
                              size: 23,
                            ),
                            const SizedBox(width: 6),
                            GestureDetector(
                              onTap: () => _showLikes(context),
                              child: Padding(
                                padding: const EdgeInsets.symmetric(vertical: 5),
                                child: Text(
                                  '$count',
                                  style: const TextStyle(fontWeight: FontWeight.w800),
                                ),
                              ),
                            ),
                          ],
                        ),
                      );
                    },
                  );
                },
              ),
              const SizedBox(width: 26),
              StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: commentsRef.snapshots(),
                builder: (context, snapshot) {
                  final count = snapshot.data?.size ?? 0;

                  return Pressable(
                    onTap: () => _showComments(context),
                    child: Row(
                      children: [
                        const Icon(
                          Icons.chat_bubble_outline_rounded,
                          size: 22,
                        ),
                        const SizedBox(width: 6),
                        Text(
                          '$count',
                          style: const TextStyle(
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ],
                    ),
                  );
                },
              ),
              const Spacer(),
              if (post.authorId == uid)
                const Text(
                  'YOUR POST',
                  style: TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    color: AppColors.muted,
                  ),
                ),
            ],
          ),
        ],
      ),
    );
  }
}

class StudentPostDetailScreen extends StatelessWidget {
  final String postId;
  final String collectionName;

  const StudentPostDetailScreen({
    super.key,
    required this.postId,
    this.collectionName = 'studentPosts',
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        title: const Text('Post', style: TextStyle(fontWeight: FontWeight.w900)),
      ),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection(collectionName)
            .doc(postId)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return const Center(child: Text('Could not load this post.'));
          }
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }
          if (!snapshot.data!.exists) {
            return const Center(child: Text('This post is no longer available.'));
          }
          final data = snapshot.data!.data() ?? <String, dynamic>{};
          final post = _StudentFeedPost(
            id: snapshot.data!.id,
            authorId: data['authorId']?.toString() ?? '',
            author: data['authorName']?.toString().trim().isNotEmpty == true
                ? data['authorName'].toString().trim()
                : 'Student',
            college: data['college']?.toString().trim() ?? '',
            profileImage: data['authorProfileImage']?.toString().trim() ?? '',
            text: data['text']?.toString() ?? '',
            mediaUrl: data['mediaUrl']?.toString().trim() ?? '',
            mediaType: data['mediaType']?.toString().trim() ?? '',
            mentionedUserIds: (data['mentionedUserIds'] as List?)
                ?.map((e) => e.toString())
                .toList() ??
                <String>[],
            mentionedUsernames: (data['mentionedUsernames'] as List?)
                ?.map((e) => e.toString())
                .toList() ??
                <String>[],
            createdAt: data['createdAt'] is Timestamp
                ? data['createdAt'] as Timestamp
                : null,
            collectionName: collectionName,
          );
          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 40),
            children: [_StudentPostCard(post: post)],
          );
        },
      ),
    );
  }
}

class StudentPostsProfileScreen extends StatefulWidget {
  final String uid;
  final String name;

  const StudentPostsProfileScreen({
    super.key,
    required this.uid,
    required this.name,
  });

  @override
  State<StudentPostsProfileScreen> createState() =>
      _StudentPostsProfileScreenState();
}

class _StudentPostsProfileScreenState extends State<StudentPostsProfileScreen> {
  final TextEditingController _personalPostController =
  TextEditingController();

  XFile? _personalPhoto;
  bool _postingPersonal = false;
  String _personalMentionQuery = '';
  List<Map<String, String>> _personalMentionSuggestions =
  <Map<String, String>>[];

  CollectionReference<Map<String, dynamic>> get _personalPosts =>
      FirebaseFirestore.instance.collection('personalPosts');

  @override
  void dispose() {
    _personalPostController.dispose();
    super.dispose();
  }

  Future<void> _updatePersonalMentionSuggestions(String text) async {
    final match = RegExp(r'@([A-Za-z0-9_.-]*)$').firstMatch(text);
    if (match == null) {
      if (mounted && _personalMentionSuggestions.isNotEmpty) {
        setState(() =>
        _personalMentionSuggestions = <Map<String, String>>[]);
      }
      _personalMentionQuery = '';
      return;
    }

    final query = (match.group(1) ?? '').toLowerCase();
    _personalMentionQuery = query;

    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .limit(100)
          .get();

      final results = <Map<String, String>>[];

      for (final doc in snap.docs) {
        if (doc.id == _currentUid()) continue;

        final data = doc.data();
        final username = data['username']?.toString().trim() ?? '';
        final name = data['name']?.toString().trim() ?? '';

        if (username.isEmpty && name.isEmpty) continue;

        if (query.isNotEmpty &&
            !username.toLowerCase().contains(query) &&
            !name.toLowerCase().contains(query)) {
          continue;
        }

        results.add({
          'uid': doc.id,
          'username': username.isNotEmpty ? username : name,
          'name': name.isNotEmpty ? name : username,
        });

        if (results.length >= 6) break;
      }

      if (!mounted || _personalMentionQuery != query) return;

      setState(() => _personalMentionSuggestions = results);
    } catch (_) {
      if (mounted) {
        setState(() =>
        _personalMentionSuggestions = <Map<String, String>>[]);
      }
    }
  }

  void _insertPersonalMention(Map<String, String> student) {
    final match = RegExp(r'@([A-Za-z0-9_.-]*)$')
        .firstMatch(_personalPostController.text);

    final username = student['username']?.trim() ?? '';

    if (match == null || username.isEmpty) return;

    final next = _personalPostController.text.replaceRange(
      match.start,
      _personalPostController.text.length,
      '@$username ',
    );

    _personalPostController.value = TextEditingValue(
      text: next,
      selection: TextSelection.collapsed(offset: next.length),
    );

    setState(() {
      _personalMentionQuery = '';
      _personalMentionSuggestions = <Map<String, String>>[];
    });
  }

  Future<Map<String, List<String>>> _resolvePersonalMentions(
      String text) async {
    final names = RegExp(r'@([A-Za-z0-9_.-]{2,30})')
        .allMatches(text)
        .map((m) => (m.group(1) ?? '').toLowerCase())
        .toSet();

    if (names.isEmpty) {
      return {
        'ids': <String>[],
        'usernames': <String>[],
      };
    }

    final snap = await FirebaseFirestore.instance
        .collection('users')
        .limit(200)
        .get();

    final ids = <String>[];
    final usernames = <String>[];

    for (final doc in snap.docs) {
      final username = doc.data()['username']?.toString().trim() ?? '';

      if (username.isNotEmpty &&
          names.contains(username.toLowerCase()) &&
          doc.id != _currentUid()) {
        ids.add(doc.id);
        usernames.add(username);
      }
    }

    return {
      'ids': ids,
      'usernames': usernames,
    };
  }

  Future<void> _pickPersonalPhoto() async {
    if (_postingPersonal) return;

    try {
      final picked = await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 88,
      );

      if (picked == null || !mounted) return;

      setState(() => _personalPhoto = picked);
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not select photo: $e',
          color: Colors.red,
        );
      }
    }
  }

  Future<void> _publishPersonalPost() async {
    if (_postingPersonal) return;

    final text = _personalPostController.text.trim();
    final photo = _personalPhoto;

    if (text.isEmpty && photo == null) {
      showSnack(
        context,
        'Write something or add a photo.',
        color: Colors.red,
      );
      return;
    }

    final uid = _currentUid();

    if (uid.isEmpty) {
      showSnack(
        context,
        'Please sign in again.',
        color: Colors.red,
      );
      return;
    }

    FocusScope.of(context).unfocus();
    setState(() => _postingPersonal = true);

    try {
      final postRef = _personalPosts.doc();

      final mentionData = await _resolvePersonalMentions(text);
      final mentionedUserIds =
          mentionData['ids'] ?? <String>[];
      final mentionedUsernames =
          mentionData['usernames'] ?? <String>[];

      String mediaUrl = '';

      if (photo != null) {
        final extension = photo.name.contains('.')
            ? photo.name.split('.').last.toLowerCase()
            : 'jpg';

        final contentType = extension == 'png'
            ? 'image/png'
            : extension == 'webp'
            ? 'image/webp'
            : 'image/jpeg';

        final storagePath =
            'personalPostMedia/$uid/${postRef.id}/${DateTime.now().millisecondsSinceEpoch}.$extension';

        final upload = await FirebaseStorage.instance
            .ref()
            .child(storagePath)
            .putFile(
          File(photo.path),
          SettableMetadata(contentType: contentType),
        );

        mediaUrl = await upload.ref.getDownloadURL();
      }

      await postRef.set({
        'authorId': uid,
        'authorName': userName.value.trim().isNotEmpty
            ? userName.value.trim()
            : 'Student',
        'authorProfileImage': userProfileImage.value.trim(),
        'college': userCollege.value.trim(),
        'text': text,
        'mediaUrl': mediaUrl,
        'mediaType': mediaUrl.isEmpty ? '' : 'image',
        'mentionedUserIds': mentionedUserIds,
        'mentionedUsernames': mentionedUsernames,
        'createdAt': FieldValue.serverTimestamp(),
      });

      for (final mentionedUid in mentionedUserIds) {
        await FirebaseFirestore.instance
            .collection('notifications')
            .add({
          'recipientId': mentionedUid,
          'senderId': uid,
          'senderName': userName.value.trim().isNotEmpty
              ? userName.value.trim()
              : 'Student',
          'senderProfileImage': userProfileImage.value.trim(),
          'type': 'personal_post_mention',
          'title': '${userName.value} mentioned you in a personal post',
          'body': text.isEmpty
              ? 'You were mentioned in a personal post.'
              : text,
          'relatedId': postRef.id,
          'isRead': false,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }

      if (!mounted) return;

      setState(() {
        _personalPostController.clear();
        _personalPhoto = null;
        _personalMentionQuery = '';
        _personalMentionSuggestions = <Map<String, String>>[];
      });

      showSnack(
        context,
        'Personal post published',
        color: AppColors.green,
      );
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not publish personal post: $e',
          color: Colors.red,
        );
      }
    } finally {
      if (mounted) {
        setState(() => _postingPersonal = false);
      }
    }
  }

  Widget _personalComposer() {
    final photo = _personalPhoto;

    return Container(
      margin: const EdgeInsets.fromLTRB(16, 16, 16, 18),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 16),
      decoration: neoDeco(
        color: const Color(0xFFF4EDFF),
        radius: 28,
      ),
      child: Column(
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              ProfileAvatar(
                imageUrl: userProfileImage.value,
                name: userName.value,
                radius: 24,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: TextField(
                  controller: _personalPostController,
                  onChanged: (value) {
                    setState(() {});
                    _updatePersonalMentionSuggestions(value);
                  },
                  minLines: 2,
                  maxLines: 5,
                  decoration: const InputDecoration(
                    border: InputBorder.none,
                    hintText: 'Share something on your profile...',
                    hintStyle: TextStyle(
                      color: AppColors.muted,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ),
            ],
          ),
          if (_personalMentionSuggestions.isNotEmpty)
            Container(
              width: double.infinity,
              margin: const EdgeInsets.only(top: 8),
              decoration: neoDeco(
                color: Colors.white,
                radius: 16,
                shadow: false,
              ),
              child: Column(
                children: [
                  for (final student in _personalMentionSuggestions)
                    ListTile(
                      dense: true,
                      leading: ProfileAvatar(
                        imageUrl: '',
                        name: student['name'] ?? 'Student',
                        radius: 18,
                      ),
                      title: Text(
                        student['name'] ?? 'Student',
                        style: const TextStyle(
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      subtitle: Text('@${student['username'] ?? ''}'),
                      onTap: () => _insertPersonalMention(student),
                    ),
                ],
              ),
            ),
          if (photo != null)
            Container(
              margin: const EdgeInsets.only(top: 10),
              height: 180,
              width: double.infinity,
              clipBehavior: Clip.antiAlias,
              decoration: neoDeco(
                color: Colors.white,
                radius: 16,
                shadow: false,
              ),
              child: Stack(
                children: [
                  Positioned.fill(
                    child: DarkSafe(
                      child: Image.file(
                        File(photo.path),
                        fit: BoxFit.cover,
                      ),
                    ),
                  ),
                  Positioned(
                    top: 8,
                    right: 8,
                    child: NeoIconButton(
                      icon: Icons.close_rounded,
                      color: Colors.white,
                      size: 38,
                      onTap: _postingPersonal
                          ? null
                          : () => setState(() => _personalPhoto = null),
                    ),
                  ),
                ],
              ),
            ),
          const SizedBox(height: 10),
          Row(
            children: [
              Pressable(
                onTap: _postingPersonal ? null : _pickPersonalPhoto,
                child: Container(
                  width: 48,
                  height: 44,
                  decoration: neoDeco(
                    color: Colors.white,
                    radius: 12,
                    shadow: false,
                  ),
                  child: const Icon(
                    Icons.add_photo_alternate_rounded,
                    color: AppColors.ink,
                  ),
                ),
              ),
              const SizedBox(width: 10),
              const Expanded(
                child: Text(
                  'Add a profile post photo',
                  style: TextStyle(
                    color: AppColors.muted,
                    fontWeight: FontWeight.w700,
                    fontSize: 12,
                  ),
                ),
              ),
              SizedBox(
                width: 132,
                child: PillButton(
                  label: 'Post',
                  height: 46,
                  loading: _postingPersonal,
                  onTap: _postingPersonal
                      ? null
                      : _publishPersonalPost,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        title: Text(
          '${widget.name} · Personal Posts',
          style: const TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: _personalPosts
            .where('authorId', isEqualTo: widget.uid)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return Center(
              child: Text(
                'Could not load personal posts.\n${snapshot.error}',
              ),
            );
          }

          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          final docs = [
            ...(snapshot.data?.docs ??
                <QueryDocumentSnapshot<Map<String, dynamic>>>[])
          ]..sort((a, b) {
            final at = a.data()['createdAt'];
            final bt = b.data()['createdAt'];
            final ad = at is Timestamp ? at.toDate() : DateTime(2000);
            final bd = bt is Timestamp ? bt.toDate() : DateTime(2000);
            return bd.compareTo(ad);
          });

          final isOwnProfile = widget.uid == _currentUid();

          return ListView(
            padding: const EdgeInsets.only(bottom: 40),
            children: [
              if (isOwnProfile) _personalComposer(),
              if (!isOwnProfile && docs.isEmpty)
                const EmptyState(
                  icon: Icons.article_outlined,
                  title: 'No personal posts yet',
                  subtitle: 'This student has not shared a personal post.',
                ),
              if (isOwnProfile && docs.isEmpty)
                const EmptyState(
                  icon: Icons.article_outlined,
                  title: 'No personal posts yet',
                  subtitle: 'Share your first post on your profile.',
                ),
              for (final doc in docs)
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
                  child: _StudentPostCard(
                    post: _StudentFeedPost.fromDoc(
                      doc,
                      collectionName: 'personalPosts',
                    ),
                  ),
                ),
            ],
          );
        },
      ),
    );
  }
}

class PersonalPostDetailScreen extends StatelessWidget {
  final String postId;

  const PersonalPostDetailScreen({
    super.key,
    required this.postId,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        title: const Text(
          'Personal Post',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('personalPosts')
            .doc(postId)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return const Center(
              child: Text('Could not load this personal post.'),
            );
          }

          if (!snapshot.hasData) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          if (!snapshot.data!.exists) {
            return const Center(
              child: Text('This personal post is no longer available.'),
            );
          }

          final data =
              snapshot.data!.data() ?? <String, dynamic>{};

          final post = _StudentFeedPost(
            id: snapshot.data!.id,
            authorId: data['authorId']?.toString() ?? '',
            author: data['authorName']?.toString().trim().isNotEmpty == true
                ? data['authorName'].toString().trim()
                : 'Student',
            college: data['college']?.toString().trim() ?? '',
            profileImage:
            data['authorProfileImage']?.toString().trim() ?? '',
            text: data['text']?.toString() ?? '',
            mediaUrl: data['mediaUrl']?.toString().trim() ?? '',
            mediaType: data['mediaType']?.toString().trim() ?? '',
            mentionedUserIds: (data['mentionedUserIds'] as List?)
                ?.map((e) => e.toString())
                .toList() ??
                <String>[],
            mentionedUsernames: (data['mentionedUsernames'] as List?)
                ?.map((e) => e.toString())
                .toList() ??
                <String>[],
            createdAt: data['createdAt'] is Timestamp
                ? data['createdAt'] as Timestamp
                : null,
            collectionName: 'personalPosts',
          );

          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 40),
            children: [
              _StudentPostCard(post: post),
            ],
          );
        },
      ),
    );
  }
}

class _StudentFeedVideo extends StatefulWidget {
  final String url;

  const _StudentFeedVideo({required this.url});

  @override
  State<_StudentFeedVideo> createState() => _StudentFeedVideoState();
}

class _StudentFeedVideoState extends State<_StudentFeedVideo> {
  VideoPlayerController? _controller;

  @override
  void initState() {
    super.initState();
    _controller = VideoPlayerController.networkUrl(Uri.parse(widget.url))
      ..initialize().then((_) {
        if (mounted) setState(() {});
      });
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;

    if (controller == null || !controller.value.isInitialized) {
      return Container(
        height: 240,
        color: Colors.black,
        alignment: Alignment.center,
        child: const CircularProgressIndicator(
          color: Colors.white,
        ),
      );
    }

    return AspectRatio(
      aspectRatio: controller.value.aspectRatio == 0
          ? 16 / 9
          : controller.value.aspectRatio,
      child: Stack(
        alignment: Alignment.center,
        children: [
          DarkSafe(child: VideoPlayer(controller)),
          if (!controller.value.isPlaying)
            NeoIconButton(
              icon: Icons.play_arrow_rounded,
              color: Colors.white,
              size: 52,
              onTap: () {
                setState(() {
                  controller.play();
                });
              },
            ),
        ],
      ),
    );
  }
}

