// =====================================================
// PRIVATE CHAT + GROUP CHAT
// =====================================================

String _currentUid() => FirebaseAuth.instance.currentUser?.uid ?? '';

String privateChatIdFor(String uid1, String uid2) {
  final ids = <String>[uid1, uid2]..sort();
  return '${ids[0]}_${ids[1]}';
}

String _chatDisplayTime(dynamic value) {
  if (value is! Timestamp) return '';
  final d = value.toDate();
  final now = DateTime.now();
  final sameDay = d.year == now.year && d.month == now.month && d.day == now.day;
  if (sameDay) {
    final h = d.hour % 12 == 0 ? 12 : d.hour % 12;
    final m = d.minute.toString().padLeft(2, '0');
    return '$h:$m ${d.hour >= 12 ? 'PM' : 'AM'}';
  }
  return '${d.day}/${d.month}/${d.year}';
}

Future<Map<String, dynamic>?> _loadUserProfile(String uid) async {
  final doc = await FirebaseFirestore.instance.collection('users').doc(uid).get();
  if (!doc.exists) return null;
  return doc.data();
}

Future<bool> _areFollowingEachOther(String uid1, String uid2) async {
  if (uid1.isEmpty || uid2.isEmpty || uid1 == uid2) return false;
  final both = await Future.wait([
    FirebaseFirestore.instance.collection('users').doc(uid1).collection('following').doc(uid2).get(),
    FirebaseFirestore.instance.collection('users').doc(uid2).collection('following').doc(uid1).get(),
  ]);
  return both[0].exists && both[1].exists;
}

Future<void> _ensurePrivateChat({
  required String otherUid,
  required String otherName,
}) async {
  final uid = _currentUid();
  if (uid.isEmpty || otherUid.isEmpty || uid == otherUid) return;

  final canMessage = await _areFollowingEachOther(uid, otherUid);
  if (!canMessage) {
    throw StateError('You can message this student only after they accept your follow request.');
  }

  final chatId = privateChatIdFor(uid, otherUid);
  final ref = FirebaseFirestore.instance.collection('privateChats').doc(chatId);
  final me = FirebaseAuth.instance.currentUser;

  // Do not read the chat document before creating it. A brand-new chat
  // has no participants yet, so a participant-only Firestore read rule
  // would correctly reject that initial lookup.
  //
  // set(..., merge: true) works for both cases:
  // - create: the authenticated user is one of the two participants
  // - update: the authenticated user is already a participant
  await ref.set({
    'participants': [uid, otherUid],
    'participantNames': {
      uid: me?.displayName?.trim().isNotEmpty == true
          ? me!.displayName!.trim()
          : userName.value,
      otherUid: otherName,
    },
    'lastMessage': '',
    'lastMessageAt': FieldValue.serverTimestamp(),
    'createdAt': FieldValue.serverTimestamp(),
    'unreadCounts': {uid: 0, otherUid: 0},
  }, SetOptions(merge: true));
}

Future<void> _markPrivateChatRead(String chatId) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;

  final ref = FirebaseFirestore.instance.collection('privateChats').doc(chatId);
  await ref.set({
    'unreadCounts': {uid: 0},
  }, SetOptions(merge: true));

  final messages = await ref
      .collection('messages')
      .orderBy('createdAt', descending: true)
      .limit(50)
      .get();

  final batch = FirebaseFirestore.instance.batch();
  for (final doc in messages.docs) {
    final data = doc.data();
    if (data['senderId'] == uid) continue;
    batch.update(doc.reference, {
      'readBy': FieldValue.arrayUnion([uid]),
    });
  }
  if (messages.docs.isNotEmpty) {
    await batch.commit();
  }
}

Future<void> _createMessageNotification({
  required String recipientUid,
  required String type,
  required String title,
  required String body,
  required String relatedId,
  required WriteBatch batch,
}) async {
  final uid = _currentUid();
  if (uid.isEmpty || recipientUid.isEmpty || recipientUid == uid) return;

  final ref = FirebaseFirestore.instance
      .collection('notifications')
      .doc();

  batch.set(ref, {
    'recipientId': recipientUid,
    'senderId': uid,
    'senderName': userName.value,
    'senderProfileImage': userProfileImage.value,
    'type': type,
    'title': title,
    'body': body,
    'relatedId': relatedId,
    'isRead': false,
    'createdAt': FieldValue.serverTimestamp(),
  });
}

Future<void> _notifyStudentPostFollowers({
  required String authorUid,
  required String postId,
  required String postText,
}) async {
  if (authorUid.isEmpty || postId.isEmpty) return;

  try {
    final followers = await FirebaseFirestore.instance
        .collection('users')
        .doc(authorUid)
        .collection('followers')
        .get();

    if (followers.docs.isEmpty) return;

    final title = '${userName.value.trim().isNotEmpty ? userName.value.trim() : 'Student'} shared a new post';
    final body = postText.trim().isNotEmpty
        ? postText.trim()
        : 'Check out the new post on the campus feed.';

    for (var start = 0; start < followers.docs.length; start += 400) {
      final batch = FirebaseFirestore.instance.batch();
      final chunk = followers.docs.skip(start).take(400);

      for (final followerDoc in chunk) {
        final recipientUid = followerDoc.id.trim().isNotEmpty
            ? followerDoc.id.trim()
            : (followerDoc.data()['uid']?.toString().trim() ?? '');
        if (recipientUid.isEmpty || recipientUid == authorUid) continue;

        final notificationRef = FirebaseFirestore.instance
            .collection('notifications')
            .doc();

        batch.set(notificationRef, {
          'recipientId': recipientUid,
          'senderId': authorUid,
          'senderName': userName.value.trim().isNotEmpty
              ? userName.value.trim()
              : 'Student',
          'senderProfileImage': userProfileImage.value.trim(),
          'type': 'student_post',
          'title': title,
          'body': body,
          'relatedId': postId,
          'isRead': false,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }

      await batch.commit();
    }
  } catch (_) {
    // A notification failure must never prevent the post itself from publishing.
  }
}

Future<void> _notifyStudentPostAuthor({
  required String authorUid,
  required String postId,
  required String type,
  required String title,
  required String body,
}) async {
  final uid = _currentUid();
  if (uid.isEmpty || authorUid.isEmpty || authorUid == uid || postId.isEmpty) return;

  try {
    await FirebaseFirestore.instance.collection('notifications').add({
      'recipientId': authorUid,
      'senderId': uid,
      'senderName': userName.value.trim().isNotEmpty
          ? userName.value.trim()
          : 'Student',
      'senderProfileImage': userProfileImage.value.trim(),
      'type': type,
      'title': title,
      'body': body,
      'relatedId': postId,
      'isRead': false,
      'createdAt': FieldValue.serverTimestamp(),
    });
  } catch (_) {
    // A notification failure must not block the like/comment action.
  }
}

Future<void> _sendPrivateMessage({
  required String chatId,
  required String recipientUid,
  required String text,
  String messageType = 'text',
  String mediaUrl = '',
  String thumbnailUrl = '',
  String sticker = '',
  String replyToId = '',
  String replyToText = '',
  String replyToSenderName = '',
  int voiceDurationSeconds = 0,
  String fileName = '',
  int fileSize = 0,
  String fileExtension = '',
  String storagePath = '',
}) async {
  final uid = _currentUid();
  final clean = text.trim();
  if (uid.isEmpty) return;
  if (messageType == 'text' && clean.isEmpty) return;

  final canMessage = await _areFollowingEachOther(uid, recipientUid);
  if (!canMessage) {
    throw StateError('Messaging is available only between accepted followers.');
  }

  final chatRef = FirebaseFirestore.instance.collection('privateChats').doc(chatId);
  final messageRef = chatRef.collection('messages').doc();
  final chatSnap = await chatRef.get();
  final data = chatSnap.data() ?? <String, dynamic>{};
  final unread = Map<String, dynamic>.from(
    (data['unreadCounts'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{},
  );
  final recipientUnread = (unread[recipientUid] is num)
      ? (unread[recipientUid] as num).toInt()
      : 0;
  unread[uid] = 0;
  unread[recipientUid] = recipientUnread + 1;

  final displayText = messageType == 'text'
      ? clean
      : messageType == 'image'
      ? '📷 Photo'
      : messageType == 'video'
      ? '🎥 Video'
      : messageType == 'sticker'
      ? '$sticker Sticker'
      : messageType == 'voice'
      ? '🎤 Voice message'
      : messageType == 'file'
      ? '📎 $fileName'
      : clean;

  final messageData = <String, dynamic>{
    'senderId': uid,
    'recipientId': recipientUid,
    'senderProfileImage': userProfileImage.value,
    'senderName': userName.value,
    'text': clean,
    'messageType': messageType,
    'mediaUrl': mediaUrl,
    'thumbnailUrl': thumbnailUrl,
    'voiceDurationSeconds': voiceDurationSeconds,
    'fileName': fileName,
    'fileSize': fileSize,
    'fileExtension': fileExtension,
    'storagePath': storagePath,
    'sticker': sticker,
    'replyToId': replyToId,
    'replyToText': replyToText,
    'replyToSenderName': replyToSenderName,
    'createdAt': FieldValue.serverTimestamp(),
    'readBy': [uid],
    'deliveredTo': [uid, recipientUid],
  };

  final batch = FirebaseFirestore.instance.batch();
  batch.set(messageRef, messageData);
  batch.set(chatRef, {
    'participants': FieldValue.arrayUnion([uid, recipientUid]),
    'lastMessage': displayText,
    'lastMessageAt': FieldValue.serverTimestamp(),
    'unreadCounts': unread,
  }, SetOptions(merge: true));

  await _createMessageNotification(
    recipientUid: recipientUid,
    type: 'private_message',
    title: 'New message from ${userName.value}',
    body: displayText,
    relatedId: chatId,
    batch: batch,
  );

  await batch.commit();
}



Future<void> _writeGroupJoinMarker({
  required String groupId,
  required String joinedUserId,
}) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;

  try {
    await FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId)
        .collection('messages')
        .add({
      'senderId': uid,
      'senderName': userName.value,
      'senderProfileImage': userProfileImage.value,
      'text': '',
      'type': 'member_joined',
      'joinedUserId': joinedUserId,
      'createdAt': FieldValue.serverTimestamp(),
    });
  } catch (_) {
    // Joining the group must still succeed if the history marker
    // cannot be written.
  }
}

Future<bool> joinPeerGroup(BuildContext context, Group group) async {
  final uid = _currentUid();
  if (uid.isEmpty) return false;

  try {
    final ref = FirebaseFirestore.instance.collection('groups').doc(group.id);
    final snap = await ref.get();
    bool newlyJoined = false;
    if (!snap.exists) {
      await ref.set({
        'id': group.id,
        'name': group.name,
        'subtitle': group.subtitle,
        'short': group.short,
        'memberCount': group.members + 1,
        'memberIds': [uid],
        'createdAt': FieldValue.serverTimestamp(),
      });
      newlyJoined = true;
    } else {
      final data = snap.data() ?? <String, dynamic>{};
      final ids = List<String>.from((data['memberIds'] as List?)?.whereType<String>() ?? const <String>[]);
      // Predefined communities (IEEE, TinkerHub, IEDC, etc.) are public
      // communities and remain open for any signed-in student to join.
      if (!ids.contains(uid)) {
        final count = (data['memberCount'] is num)
            ? (data['memberCount'] as num).toInt() + 1
            : group.members + 1;
        await ref.update({
          'memberIds': FieldValue.arrayUnion([uid]),
          'memberCount': count,
        });
        newlyJoined = true;
      }
    }

    if (newlyJoined) {
      await _writeGroupJoinMarker(
        groupId: group.id,
        joinedUserId: uid,
      );
    }

    toggleInSet(joinedCommunities, group.id);
    if (context.mounted) {
      showSnack(context, 'Welcome to ${group.name}!', color: AppColors.green);
    }
    return true;
  } catch (e) {
    if (context.mounted) {
      showSnack(context, 'Could not join group: $e', color: Colors.red);
    }
    return false;
  }
}

Future<void> leavePeerGroup(BuildContext context, Group group) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;
  try {
    final ref = FirebaseFirestore.instance.collection('groups').doc(group.id);
    final snap = await ref.get();
    if (snap.exists) {
      final data = snap.data() ?? <String, dynamic>{};
      final count = (data['memberCount'] is num)
          ? (data['memberCount'] as num).toInt()
          : group.members;
      await ref.update({
        'memberIds': FieldValue.arrayRemove([uid]),
        'memberCount': count > 0 ? count - 1 : 0,
      });
    }
    toggleInSet(joinedCommunities, group.id);
    if (context.mounted) {
      showSnack(context, 'You left ${group.name}');
    }
  } catch (e) {
    if (context.mounted) {
      showSnack(context, 'Could not leave group: $e', color: Colors.red);
    }
  }
}

