class NewPrivateChatScreen extends StatefulWidget {
  const NewPrivateChatScreen({super.key});

  @override
  State<NewPrivateChatScreen> createState() => _NewPrivateChatScreenState();
}

class _NewPrivateChatScreenState extends State<NewPrivateChatScreen> {
  final TextEditingController _search = TextEditingController();
  String _query = '';

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: Column(
          children: [
            PageHeader(title: 'New private chat'),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: SearchField(
                hint: 'Search students...',
                controller: _search,
                onChanged: (value) => setState(() => _query = value),
              ),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: FirebaseFirestore.instance
                    .collection('users')
                    .limit(100)
                    .snapshots(),
                builder: (context, snapshot) {
                  if (snapshot.hasError) {
                    return EmptyState(
                      icon: Icons.error_outline_rounded,
                      title: 'Could not load students',
                      subtitle: snapshot.error.toString(),
                    );
                  }
                  if (snapshot.connectionState == ConnectionState.waiting) {
                    return const Center(child: CircularProgressIndicator());
                  }

                  final students = snapshot.data!.docs.where((doc) {
                    if (doc.id == uid) return false;
                    final data = doc.data();
                    if (data['privateChatEnabled'] == false) return false;
                    final name = (data['name'] ?? '').toString();
                    final college = (data['college'] ?? '').toString();
                    final q = _query.toLowerCase().trim();
                    return q.isEmpty ||
                        name.toLowerCase().contains(q) ||
                        college.toLowerCase().contains(q);
                  }).toList();

                  if (students.isEmpty) {
                    return const EmptyState(
                      icon: Icons.people_outline_rounded,
                      title: 'No students found',
                      subtitle: 'Try another name or college.',
                    );
                  }

                  return ListView.builder(
                    padding: const EdgeInsets.only(bottom: 120),
                    itemCount: students.length,
                    itemBuilder: (context, index) {
                      final doc = students[index];
                      final data = doc.data();
                      final name = (data['name'] ?? 'Student').toString();
                      final college = (data['college'] ?? 'College').toString();
                      final bio = (data['bio'] ?? '').toString();
                      return _StudentChatTile(
                        name: name,
                        college: college,
                        bio: bio,
                        profileImage: (data['profileImage'] ?? '').toString(),
                        onTap: () async {
                          await _ensurePrivateChat(
                            otherUid: doc.id,
                            otherName: name,
                          );
                          if (!context.mounted) return;
                          Navigator.of(context).push(
                            SlideFadeRoute(
                              page: PrivateChatScreen(
                                otherUid: doc.id,
                                otherName: name,
                                otherCollege: college,
                                otherProfileImage: (data['profileImage'] ?? '').toString(),
                              ),
                            ),
                          );
                        },
                      );
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class PrivateChatList extends StatefulWidget {
  const PrivateChatList({super.key});

  @override
  State<PrivateChatList> createState() => _PrivateChatListState();
}

class _PrivateChatListState extends State<PrivateChatList> {
  Timer? _orderingRefresh;

  @override
  void initState() {
    super.initState();
    // Re-read last-message timestamps so private chats reorder after messages.
    _orderingRefresh = Timer.periodic(const Duration(seconds: 4), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _orderingRefresh?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    if (uid.isEmpty) {
      return const EmptyState(
        icon: Icons.lock_outline_rounded,
        title: 'Sign in required',
        subtitle: 'Please sign in to use chat.',
      );
    }

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('followers')
          .limit(100)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return EmptyState(
            icon: Icons.error_outline_rounded,
            title: 'Could not load followers',
            subtitle: snapshot.error.toString(),
          );
        }
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }

        final docs = snapshot.data?.docs ??
            <QueryDocumentSnapshot<Map<String, dynamic>>>[];
        if (docs.isEmpty) {
          return const EmptyState(
            icon: Icons.people_outline_rounded,
            title: 'No followers yet',
            subtitle: 'People who follow you will appear here so you can chat with them.',
          );
        }

        return FutureBuilder<List<_SortedPrivateChat>>(
          future: _loadPrivateChatsInLatestOrder(uid, docs),
          builder: (context, chatsSnapshot) {
            if (chatsSnapshot.connectionState == ConnectionState.waiting &&
                !chatsSnapshot.hasData) {
              return const Center(child: CircularProgressIndicator());
            }
            final chats = chatsSnapshot.data ?? <_SortedPrivateChat>[];
            return ListView.builder(
              padding: const EdgeInsets.fromLTRB(16, 4, 16, 120),
              itemCount: chats.length,
              itemBuilder: (context, index) {
                final chat = chats[index];
                return _ChatListTile(
                  title: chat.name.isEmpty ? 'Student' : chat.name,
                  subtitle: chat.subtitle,
                  time: chat.time,
                  unread: chat.unread,
                  icon: Icons.person_rounded,
                  profileImage: chat.profileImage,
                  onTap: () async {
                    try {
                      await _ensurePrivateChat(
                        otherUid: chat.uid,
                        otherName: chat.name.isEmpty ? 'Student' : chat.name,
                      );
                      if (!context.mounted) return;
                      Navigator.of(context).push(
                        SlideFadeRoute(
                          page: PrivateChatScreen(
                            otherUid: chat.uid,
                            otherName: chat.name.isEmpty ? 'Student' : chat.name,
                            otherCollege: chat.college,
                            otherProfileImage: chat.profileImage,
                          ),
                        ),
                      );
                    } catch (_) {
                      if (context.mounted) {
                        showSnack(
                          context,
                          'You can chat after the follow connection is mutual.',
                          color: Colors.red,
                          bottomMargin: 20,
                        );
                      }
                    }
                  },
                );
              },
            );
          },
        );
      },
    );
  }
}

class _SortedPrivateChat {
  final String uid;
  final String name;
  final String college;
  final String profileImage;
  final String subtitle;
  final String time;
  final int unread;
  final int lastMessageMillis;

  const _SortedPrivateChat({
    required this.uid,
    required this.name,
    required this.college,
    required this.profileImage,
    required this.subtitle,
    required this.time,
    required this.unread,
    required this.lastMessageMillis,
  });
}

Future<List<_SortedPrivateChat>> _loadPrivateChatsInLatestOrder(
    String uid,
    List<QueryDocumentSnapshot<Map<String, dynamic>>> followerDocs,
    ) async {
  final chats = await Future.wait(followerDocs.map((followerDoc) async {
    final otherUid = followerDoc.id;
    final results = await Future.wait([
      _loadUserProfile(otherUid),
      FirebaseFirestore.instance
          .collection('privateChats')
          .doc(privateChatIdFor(uid, otherUid))
          .get(),
    ]);
    final profile = results[0] as Map<String, dynamic>? ?? <String, dynamic>{};
    final chatSnapshot = results[1] as DocumentSnapshot<Map<String, dynamic>>;
    final chatData = chatSnapshot.data() ?? <String, dynamic>{};
    final name = (profile['name'] ?? 'Student').toString().trim();
    final college = (profile['college'] ?? '').toString().trim();
    final profileImage = (profile['profileImage'] ?? '').toString().trim();
    final lastMessage = (chatData['lastMessage'] ?? '').toString().trim();
    final lastValue = chatData['lastMessageAt'];
    final lastMillis =
    lastValue is Timestamp ? lastValue.millisecondsSinceEpoch : 0;
    final unreadMap = Map<String, dynamic>.from(
      (chatData['unreadCounts'] as Map?)?.cast<String, dynamic>() ??
          <String, dynamic>{},
    );
    final unreadValue = unreadMap[uid];
    return _SortedPrivateChat(
      uid: otherUid,
      name: name,
      college: college,
      profileImage: profileImage,
      subtitle: lastMessage.isNotEmpty
          ? lastMessage
          : (college.isNotEmpty ? college : 'Tap to start a conversation'),
      time: _chatDisplayTime(lastValue),
      unread: unreadValue is num ? unreadValue.toInt() : 0,
      lastMessageMillis: lastMillis,
    );
  }));
  chats.sort((a, b) => b.lastMessageMillis.compareTo(a.lastMessageMillis));
  return chats;
}


// =====================================================
// STUDY GROUPS
// =====================================================

String _studyGroupText(dynamic value) => value?.toString().trim() ?? '';

final Set<String> _studyGroupJoinRequestsInFlight = <String>{};

Future<void> _syncStudyGroupChat({
  required String groupId,
  required Map<String, dynamic> studyData,
}) async {
  final ref = FirebaseFirestore.instance.collection('groups').doc(groupId);
  await ref.set({
    'name': _studyGroupText(studyData['name']),
    'subtitle': _studyGroupText(studyData['subject']).isEmpty
        ? 'Study group'
        : _studyGroupText(studyData['subject']),
    'memberIds': List<String>.from(
      (studyData['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
    ),
    'creatorId': studyData['creatorId'] ?? '',
    'invitedUids': List<String>.from(
      (studyData['invitedUids'] as List?)?.whereType<String>() ?? const <String>[],
    ),
    'isPrivate': (studyData['isPrivate'] ?? true) == true,
    'memberCount': (studyData['memberCount'] is num)
        ? (studyData['memberCount'] as num).toInt()
        : 0,
    'lastMessage': studyData['lastMessage'] ?? '',
    'lastMessageAt': studyData['lastMessageAt'] ?? FieldValue.serverTimestamp(),
  }, SetOptions(merge: true));
}

Future<bool> _requestOrJoinStudyGroup(BuildContext context, String groupId) async {
  final uid = _currentUid();
  if (uid.isEmpty) return false;
  final actionKey = '$groupId:$uid';
  if (_studyGroupJoinRequestsInFlight.contains(actionKey)) return false;
  _studyGroupJoinRequestsInFlight.add(actionKey);
  try {
    return await _requestOrJoinStudyGroupImpl(context, groupId, uid);
  } finally {
    _studyGroupJoinRequestsInFlight.remove(actionKey);
  }
}

Future<bool> _requestOrJoinStudyGroupImpl(BuildContext context, String groupId, String uid) async {
  if (uid.isEmpty) return false;
  try {
    final db = FirebaseFirestore.instance;
    final ref = db.collection('studyGroups').doc(groupId);
    final snap = await ref.get();
    if (!snap.exists) return false;
    final data = snap.data() ?? <String, dynamic>{};
    final members = List<String>.from(
      (data['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
    );
    if (members.contains(uid)) return true;
    final maxMembers = (data['maxMembers'] is num)
        ? (data['maxMembers'] as num).toInt()
        : 2;
    if (members.length >= maxMembers) {
      if (context.mounted) showSnack(context, 'This study group is full.', color: Colors.red);
      return false;
    }

    if ((data['isPrivate'] ?? true) == true) {
      final requestRef = ref.collection('joinRequests').doc(uid);
      final existing = await requestRef.get();
      if (existing.exists && existing.data()?['status'] == 'pending') {
        if (context.mounted) showSnack(context, 'Your join request is waiting for admin approval.');
        return false;
      }
      await requestRef.set({
        'requesterId': uid,
        'requesterName': userName.value.trim().isEmpty ? 'PeerGrid student' : userName.value.trim(),
        'status': 'pending',
        'createdAt': FieldValue.serverTimestamp(),
      });
      final creatorId = _studyGroupText(data['creatorId']);
      if (creatorId.isNotEmpty && creatorId != uid) {
        await db.collection('notifications').add({
          'recipientId': creatorId,
          'senderId': uid,
          'senderName': userName.value.trim().isEmpty ? 'PeerGrid student' : userName.value.trim(),
          'senderProfileImage': userProfileImage.value,
          'type': 'study_group_join_request',
          'title': 'New study group join request',
          'body': '${userName.value.trim().isEmpty ? 'A student' : userName.value.trim()} requested to join ${_studyGroupText(data['name'])}.',
          'relatedId': groupId,
          'isRead': false,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }
      if (context.mounted) showSnack(context, 'Join request sent to the group admin.', color: AppColors.green);
      return false;
    }

    members.add(uid);
    await ref.update({'memberIds': members, 'memberCount': members.length});
    final latest = await ref.get();
    await _syncStudyGroupChat(groupId: groupId, studyData: latest.data() ?? data);
    await _writeGroupJoinMarker(groupId: groupId, joinedUserId: uid);
    if (context.mounted) showSnack(context, 'Joined study group.', color: AppColors.green);
    return true;
  } catch (e) {
    if (context.mounted) showSnack(context, 'Could not join/request access: $e', color: Colors.red);
    return false;
  }
}

Future<void> _reviewStudyGroupJoinRequest(
    BuildContext context, String groupId, String requesterId, bool approve,
    ) async {
  final uid = _currentUid();
  final db = FirebaseFirestore.instance;
  final groupRef = db.collection('studyGroups').doc(groupId);
  final requestRef = groupRef.collection('joinRequests').doc(requesterId);
  try {
    final groupSnap = await groupRef.get();
    final requestSnap = await requestRef.get();
    if (!groupSnap.exists || !requestSnap.exists) return;
    final group = groupSnap.data() ?? <String, dynamic>{};
    if (_studyGroupText(group['creatorId']) != uid) {
      if (context.mounted) showSnack(context, 'Only the group admin can review requests.', color: Colors.red);
      return;
    }
    final members = List<String>.from((group['memberIds'] as List?)?.whereType<String>() ?? const <String>[]);
    if (approve && !members.contains(requesterId)) {
      final maxMembers = (group['maxMembers'] is num) ? (group['maxMembers'] as num).toInt() : 2;
      if (members.length >= maxMembers) {
        if (context.mounted) showSnack(context, 'The group is full.', color: Colors.red);
        return;
      }
      members.add(requesterId);
      await groupRef.update({'memberIds': members, 'memberCount': members.length, 'updatedAt': FieldValue.serverTimestamp()});
      final updated = await groupRef.get();
      await _syncStudyGroupChat(groupId: groupId, studyData: updated.data() ?? group);
      await _writeGroupJoinMarker(groupId: groupId, joinedUserId: requesterId);
    }
    await requestRef.update({'status': approve ? 'approved' : 'rejected', 'reviewedBy': uid, 'reviewedAt': FieldValue.serverTimestamp()});
    await db.collection('notifications').add({
      'recipientId': requesterId,
      'senderId': uid,
      'senderName': userName.value.trim().isEmpty ? 'Group admin' : userName.value.trim(),
      'senderProfileImage': userProfileImage.value,
      'type': 'study_group_join_request_result',
      'title': approve ? 'Join request accepted' : 'Join request declined',
      'body': approve ? 'Your request to join ${_studyGroupText(group['name'])} was accepted.' : 'Your request to join ${_studyGroupText(group['name'])} was declined.',
      'relatedId': groupId,
      'isRead': false,
      'createdAt': FieldValue.serverTimestamp(),
    });
    if (context.mounted) showSnack(context, approve ? 'Request accepted.' : 'Request declined.', color: AppColors.green);
  } catch (e) {
    if (context.mounted) showSnack(context, 'Could not review request: $e', color: Colors.red);
  }
}

Future<void> _handleStudyGroupJoinRequestNotification(
    BuildContext context,
    DocumentSnapshot<Map<String, dynamic>> notification,
    String groupId,
    String requesterUid,
    bool approve,
    ) async {
  if (groupId.isEmpty || requesterUid.isEmpty) return;
  try {
    final requestRef = FirebaseFirestore.instance
        .collection('studyGroups').doc(groupId)
        .collection('joinRequests').doc(requesterUid);
    final requestSnap = await requestRef.get();
    if (!requestSnap.exists || requestSnap.data()?['status'] != 'pending') {
      try { await notification.reference.delete(); } catch (_) {}
      if (context.mounted) showSnack(context, 'This join request is no longer pending.');
      return;
    }
    await _reviewStudyGroupJoinRequest(context, groupId, requesterUid, approve);
    try { await notification.reference.delete(); } catch (_) {}
  } catch (e) {
    if (context.mounted) showSnack(context, 'Could not ${approve ? 'accept' : 'reject'} join request: $e', color: Colors.red);
  }
}

Future<void> _leaveStudyGroup(BuildContext context, String groupId) async {
  final uid = _currentUid();
  if (uid.isEmpty) return;
  try {
    final ref = FirebaseFirestore.instance.collection('studyGroups').doc(groupId);
    final snap = await ref.get();
    if (!snap.exists) return;
    final data = snap.data() ?? <String, dynamic>{};
    final creatorId = _studyGroupText(data['creatorId']);
    if (creatorId == uid) {
      if (context.mounted) {
        showSnack(context, 'The creator cannot leave this group. Delete it or transfer ownership later.');
      }
      return;
    }
    final members = List<String>.from(
      (data['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
    );
    members.remove(uid);
    await ref.update({'memberIds': members, 'memberCount': members.length});
    await FirebaseFirestore.instance.collection('groups').doc(groupId).update({
      'memberIds': members,
      'memberCount': members.length,
    });
    if (context.mounted) showSnack(context, 'You left the study group.');
  } catch (e) {
    if (context.mounted) showSnack(context, 'Could not leave study group: $e', color: Colors.red);
  }
}

class StudyGroupsScreen extends StatefulWidget {
  const StudyGroupsScreen({super.key});

