  State<StudyGroupsScreen> createState() => _StudyGroupsScreenState();
}

class _StudyGroupsScreenState extends State<StudyGroupsScreen> {
  final TextEditingController _search = TextEditingController();
  String _query = '';
  int _tab = 0;

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: Column(
          children: [
            PageHeader(
              title: 'Study Groups',
              trailing: IconButton(
                tooltip: 'Create study group',
                icon: const Icon(Icons.add_circle_outline_rounded),
                onPressed: () async {
                  await Navigator.of(context).push(
                    SlideFadeRoute(page: const CreateStudyGroupScreen()),
                  );
                  if (mounted) setState(() {});
                },
              ),
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20),
              child: SegmentedTabs(
                labels: const ['Browse', 'My Groups'],
                index: _tab,
                onChanged: (value) => setState(() => _tab = value),
              ),
            ),
            const SizedBox(height: 12),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: SearchField(
                hint: 'Search study groups...',
                controller: _search,
                onChanged: (value) => setState(() => _query = value),
              ),
            ),
            const SizedBox(height: 10),
            Expanded(
              child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: _tab == 0
                    ? FirebaseFirestore.instance
                    .collection('studyGroups')
                    .snapshots()
                    : FirebaseFirestore.instance
                    .collection('studyGroups')
                    .where('memberIds', arrayContains: uid)
                    .snapshots(),
                builder: (context, snapshot) {
                  if (snapshot.hasError) {
                    return EmptyState(
                      icon: Icons.error_outline_rounded,
                      title: 'Could not load study groups',
                      subtitle: snapshot.error.toString(),
                    );
                  }
                  if (snapshot.connectionState == ConnectionState.waiting) {
                    return const Center(child: CircularProgressIndicator());
                  }
                  final q = _query.trim().toLowerCase();
                  final docs = snapshot.data?.docs.where((doc) {
                    final d = doc.data();
                    if (q.isEmpty) return true;
                    return _studyGroupText(d['name']).toLowerCase().contains(q) ||
                        _studyGroupText(d['subject']).toLowerCase().contains(q) ||
                        _studyGroupText(d['course']).toLowerCase().contains(q) ||
                        _studyGroupText(d['description']).toLowerCase().contains(q);
                  }).toList() ?? <QueryDocumentSnapshot<Map<String, dynamic>>>[];

                  if (docs.isEmpty) {
                    return EmptyState(
                      icon: Icons.menu_book_rounded,
                      title: _tab == 0 ? 'No study groups found' : 'No groups joined yet',
                      subtitle: _tab == 0
                          ? 'Create a study group or try another search.'
                          : 'Join a study group from Browse to see it here.',
                    );
                  }

                  return ListView.builder(
                    padding: const EdgeInsets.fromLTRB(16, 4, 16, 120),
                    itemCount: docs.length,
                    itemBuilder: (context, index) {
                      return _StudyGroupCard(doc: docs[index]);
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

