class CreateStudyGroupScreen extends StatefulWidget {
  const CreateStudyGroupScreen({super.key});

  @override
  State<CreateStudyGroupScreen> createState() => _CreateStudyGroupScreenState();
}

class _CreateStudyGroupScreenState extends State<CreateStudyGroupScreen> {
  final _formKey = GlobalKey<FormState>();
  final _name = TextEditingController();
  final _subject = TextEditingController();
  final _course = TextEditingController();
  final _description = TextEditingController();
  final _maxMembers = TextEditingController(text: '5');
  bool _isPrivate = true;
  bool _saving = false;

  @override
  void dispose() {
    _name.dispose();
    _subject.dispose();
    _course.dispose();
    _description.dispose();
    _maxMembers.dispose();
    super.dispose();
  }

  Future<void> _create() async {
    if (!_formKey.currentState!.validate()) return;
    final uid = _currentUid();
    if (uid.isEmpty) return;
    final maxMembers = int.tryParse(_maxMembers.text.trim()) ?? 0;
    if (maxMembers < 2) {
      showSnack(context, 'Maximum members must be at least 2.', color: Colors.red);
      return;
    }
    setState(() => _saving = true);
    try {
      final ref = FirebaseFirestore.instance.collection('studyGroups').doc();
      final data = <String, dynamic>{
        'name': _name.text.trim(),
        'subject': _subject.text.trim(),
        'course': _course.text.trim(),
        'description': _description.text.trim(),
        'creatorId': uid,
        'memberIds': [uid],
        'invitedUids': <String>[],
        'isPrivate': _isPrivate,
        'memberCount': 1,
        'maxMembers': maxMembers,
        'createdAt': FieldValue.serverTimestamp(),
      };
      await ref.set(data);
      final snap = await ref.get();
      await _syncStudyGroupChat(groupId: ref.id, studyData: snap.data() ?? data);
      if (mounted) {
        showSnack(context, 'Study group created.', color: AppColors.green);
        Navigator.of(context).pop();
      }
    } catch (e) {
      if (mounted) showSnack(context, 'Could not create study group: $e', color: Colors.red);
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  InputDecoration _decoration(String hint) => InputDecoration(
    hintText: hint,
    filled: true,
    fillColor: const Color(0xFFF7F7F7),
    border: OutlineInputBorder(borderRadius: BorderRadius.circular(18), borderSide: const BorderSide(color: Colors.black26)),
    enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(18), borderSide: const BorderSide(color: Colors.black26)),
    focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(18), borderSide: const BorderSide(color: AppColors.blue, width: 2)),
  );

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: Form(
          key: _formKey,
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 30),
            children: [
              PageHeader(title: 'Create Study Group'),
              const SizedBox(height: 8),
              TextFormField(controller: _name, decoration: _decoration('Group name'), validator: (v) => v == null || v.trim().isEmpty ? 'Enter a group name' : null),
              const SizedBox(height: 12),
              TextFormField(controller: _subject, decoration: _decoration('Subject / topic'), validator: (v) => v == null || v.trim().isEmpty ? 'Enter a subject or topic' : null),
              const SizedBox(height: 12),
              TextFormField(controller: _course, decoration: _decoration('Course / branch (optional)')),
              const SizedBox(height: 12),
              TextFormField(controller: _maxMembers, keyboardType: TextInputType.number, decoration: _decoration('Maximum members'), validator: (v) => int.tryParse(v?.trim() ?? '') == null ? 'Enter a number' : null),
              const SizedBox(height: 12),
              TextFormField(controller: _description, minLines: 4, maxLines: 7, decoration: _decoration('What will this group study?'), validator: (v) => v == null || v.trim().isEmpty ? 'Add a short description' : null),
              const SizedBox(height: 8),
              SwitchListTile(
                contentPadding: EdgeInsets.zero,
                value: _isPrivate,
                onChanged: _saving ? null : (value) => setState(() => _isPrivate = value),
                title: const Text('Private group', style: TextStyle(fontWeight: FontWeight.w800)),
                subtitle: const Text('Only the creator and added members can open this group. It will not appear in Browse search.'),
                secondary: Icon(_isPrivate ? Icons.lock_rounded : Icons.public_rounded, color: AppColors.blue),
              ),
              const SizedBox(height: 20),
              FilledButton.icon(
                onPressed: _saving ? null : _create,
                icon: _saving ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white)) : const Icon(Icons.add_rounded),
                label: Text(_saving ? 'Creating...' : 'Create Study Group'),
                style: FilledButton.styleFrom(backgroundColor: AppColors.blue, minimumSize: const Size.fromHeight(54), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18))),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class StudyGroupDetailsScreen extends StatefulWidget {
  final String groupId;

  const StudyGroupDetailsScreen({super.key, required this.groupId});

  @override
  State<StudyGroupDetailsScreen> createState() => _StudyGroupDetailsScreenState();
}

class _StudyGroupDetailsScreenState extends State<StudyGroupDetailsScreen> {
  bool _busy = false;

  Future<void> _openChat() async {
    final uid = _currentUid();
    final snap = await FirebaseFirestore.instance
        .collection('studyGroups')
        .doc(widget.groupId)
        .get();
    if (!snap.exists) return;
    final data = snap.data() ?? <String, dynamic>{};
    final members = List<String>.from(
      (data['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
    );
    if (!members.contains(uid)) {
      final joined = await _requestOrJoinStudyGroup(context, widget.groupId);
      if (!joined) return;
    }
    final latest = await FirebaseFirestore.instance
        .collection('studyGroups')
        .doc(widget.groupId)
        .get();
    if (latest.exists) {
      await _syncStudyGroupChat(
        groupId: widget.groupId,
        studyData: latest.data() ?? data,
      );
    }
    if (mounted) {
      Navigator.of(context).push(
        SlideFadeRoute(page: GroupChatScreen(groupId: widget.groupId)),
      );
    }
  }

  Future<void> _uploadGroupPhoto() async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      final uid = _currentUid();
      final ref = FirebaseFirestore.instance
          .collection('studyGroups')
          .doc(widget.groupId);
      final snap = await ref.get();
      if (!snap.exists) return;
      final data = snap.data() ?? <String, dynamic>{};
      if (_studyGroupText(data['creatorId']) != uid) {
        if (mounted) {
          showSnack(context, 'Only the group creator can change the group picture.', color: Colors.red);
        }
        return;
      }

      final picker = ImagePicker();
      final picked = await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 82,
        maxWidth: 1000,
        maxHeight: 1000,
        profileCrop: true,
      );
      if (picked == null) return;

      final storageRef = FirebaseStorage.instance
          .ref()
          .child('studyGroups')
          .child(widget.groupId)
          .child('group.jpg');
      await storageRef.putFile(
        File(picked.path),
        SettableMetadata(contentType: 'image/jpeg'),
      );
      final url = await storageRef.getDownloadURL();
      await ref.update({
        'groupProfileImage': url,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      if (mounted) {
        showSnack(context, 'Group picture updated.', color: AppColors.green);
      }
    } catch (e) {
      if (mounted) {
        showSnack(context, 'Could not update group picture: $e', color: Colors.red);
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _removeMember(String memberId, String creatorId) async {
    if (_busy || memberId == creatorId) return;
    setState(() => _busy = true);
    try {
      final ref = FirebaseFirestore.instance
          .collection('studyGroups')
          .doc(widget.groupId);
      final snap = await ref.get();
      if (!snap.exists) return;
      final data = snap.data() ?? <String, dynamic>{};
      if (_studyGroupText(data['creatorId']) != _currentUid()) return;
      final members = List<String>.from(
        (data['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
      );
      if (!members.contains(memberId)) return;
      members.remove(memberId);
      await ref.update({
        'memberIds': members,
        'memberCount': members.length,
        'invitedUids': FieldValue.arrayRemove([memberId]),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await FirebaseFirestore.instance.collection('groups').doc(widget.groupId).set({
        'memberIds': members,
        'memberCount': members.length,
      }, SetOptions(merge: true));
      if (mounted) {
        showSnack(context, 'Member removed from the study group.');
      }
    } catch (e) {
      if (mounted) {
        showSnack(context, 'Could not remove member: $e', color: Colors.red);
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _showAddMemberSheet(
      List<String> currentMembers,
      int maxMembers,
      ) async {
    if (_busy) return;

    if (currentMembers.length >= maxMembers) {
      showSnack(context, 'This study group is full.', color: Colors.red);
      return;
    }

    final search = TextEditingController();
    String query = '';

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.white,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (context, setSheetState) {
              final currentUid = _currentUid();

              return Padding(
                padding: EdgeInsets.only(
                  bottom: MediaQuery.of(context).viewInsets.bottom,
                ),
                child: SizedBox(
                  height: MediaQuery.of(context).size.height * 0.78,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Padding(
                        padding: const EdgeInsets.fromLTRB(20, 18, 12, 0),
                        child: Row(
                          children: [
                            const Expanded(
                              child: Text(
                                'Add Member',
                                style: TextStyle(
                                  fontSize: 22,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                            IconButton(
                              onPressed: () => Navigator.pop(sheetContext),
                              icon: const Icon(Icons.close_rounded),
                            ),
                          ],
                        ),
                      ),
                      const Padding(
                        padding: EdgeInsets.symmetric(horizontal: 20),
                        child: Text(
                          'Search registered PeerGrid students and add them to this study group.',
                          style: TextStyle(color: AppColors.muted),
                        ),
                      ),
                      const SizedBox(height: 14),
                      Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 20),
                        child: TextField(
                          controller: search,
                          autofocus: true,
                          onChanged: (value) {
                            setSheetState(() {
                              query = value.trim().toLowerCase();
                            });
                          },
                          decoration: InputDecoration(
                            hintText: 'Search by name, username or college',
                            prefixIcon: const Icon(Icons.search_rounded),
                            filled: true,
                            fillColor: const Color(0xFFF7F7F7),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(18),
                              borderSide: const BorderSide(color: Colors.black12),
                            ),
                            enabledBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(18),
                              borderSide: const BorderSide(color: Colors.black12),
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(18),
                              borderSide: const BorderSide(color: AppColors.blue, width: 1.4),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(height: 14),
                      Expanded(
                        child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                          // IMPORTANT:
                          // Do not filter by discoverable here. A student can be
                          // discoverable=false and still be selected by the group
                          // creator. We also avoid filtering by profileSetupComplete
                          // so older student documents are not accidentally hidden.
                          stream: FirebaseFirestore.instance
                              .collection('users')
                              .limit(100)
                              .snapshots(),
                          builder: (context, snapshot) {
                            if (snapshot.connectionState == ConnectionState.waiting) {
                              return const Center(
                                child: CircularProgressIndicator(),
                              );
                            }

                            if (snapshot.hasError) {
                              return Padding(
                                padding: const EdgeInsets.all(20),
                                child: Center(
                                  child: Text(
                                    'Could not load students.\n${snapshot.error}',
                                    textAlign: TextAlign.center,
                                    style: const TextStyle(
                                      color: Colors.red,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ),
                              );
                            }

                            final allDocs = snapshot.data?.docs ??
                                <QueryDocumentSnapshot<Map<String, dynamic>>>[];

                            final docs = allDocs.where((doc) {
                              // Never show the creator/current user as a candidate.
                              if (doc.id == currentUid) return false;

                              // Do not show people already inside this study group.
                              if (currentMembers.contains(doc.id)) return false;

                              final data = doc.data();

                              // Keep only actual student profile documents.
                              // If an older profile does not have this field,
                              // it is still allowed to appear.
                              final profileComplete = data['profileSetupComplete'];
                              if (profileComplete != null &&
                                  profileComplete is bool &&
                                  !profileComplete) {
                                return false;
                              }

                              if (query.isEmpty) return true;

                              final name = _studyGroupText(data['name']).toLowerCase();
                              final username =
                              _studyGroupText(data['username']).toLowerCase();
                              final college =
                              _studyGroupText(data['college']).toLowerCase();
                              final course =
                              _studyGroupText(data['course']).toLowerCase();
                              final hobbies =
                              _studyGroupText(data['hobbies']).toLowerCase();

                              return name.contains(query) ||
                                  username.contains(query) ||
                                  college.contains(query) ||
                                  course.contains(query) ||
                                  hobbies.contains(query);
                            }).toList();

                            if (docs.isEmpty) {
                              return const Center(
                                child: Padding(
                                  padding: EdgeInsets.all(24),
                                  child: Text(
                                    'No students found.\n\nMake sure the other student has a profile in the users collection.',
                                    textAlign: TextAlign.center,
                                    style: TextStyle(
                                      fontWeight: FontWeight.w700,
                                      color: AppColors.muted,
                                    ),
                                  ),
                                ),
                              );
                            }

                            return ListView.separated(
                              padding: const EdgeInsets.fromLTRB(20, 0, 20, 24),
                              itemCount: docs.length,
                              separatorBuilder: (_, __) =>
                              const SizedBox(height: 8),
                              itemBuilder: (context, index) {
                                final doc = docs[index];
                                final data = doc.data();

                                final name = _studyGroupText(data['name']).isEmpty
                                    ? 'PeerGrid student'
                                    : _studyGroupText(data['name']);
                                final username =
                                _studyGroupText(data['username']);
                                final college = _studyGroupText(data['college']);
                                final course = _studyGroupText(data['course']);
                                final image =
                                _studyGroupText(data['profileImage']);

                                return Container(
                                  padding: const EdgeInsets.all(10),
                                  decoration: BoxDecoration(
                                    borderRadius: BorderRadius.circular(18),
                                    border: Border.all(color: Colors.black12),
                                    color: Colors.white,
                                  ),
                                  child: Row(
                                    children: [
                                      ProfileAvatar(
                                        imageUrl: image,
                                        name: name,
                                        radius: 23,
                                      ),
                                      const SizedBox(width: 10),
                                      Expanded(
                                        child: Column(
                                          crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                          children: [
                                            Text(
                                              name,
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                              style: const TextStyle(
                                                fontWeight: FontWeight.w900,
                                              ),
                                            ),
                                            if (username.isNotEmpty)
                                              Text(
                                                '@$username',
                                                maxLines: 1,
                                                overflow:
                                                TextOverflow.ellipsis,
                                                style: const TextStyle(
                                                  color: AppColors.muted,
                                                  fontSize: 12,
                                                ),
                                              ),
                                            if (college.isNotEmpty ||
                                                course.isNotEmpty)
                                              Text(
                                                [
                                                  if (course.isNotEmpty) course,
                                                  if (college.isNotEmpty) college,
                                                ].join(' • '),
                                                maxLines: 1,
                                                overflow:
                                                TextOverflow.ellipsis,
                                                style: const TextStyle(
                                                  color: AppColors.muted,
                                                  fontSize: 11,
                                                ),
                                              ),
                                          ],
                                        ),
                                      ),
                                      const SizedBox(width: 8),
                                      FilledButton(
                                        onPressed: () async {
                                          if (_busy) return;

                                          try {
                                            final uid = _currentUid();
                                            final ref = FirebaseFirestore.instance
                                                .collection('studyGroups')
                                                .doc(widget.groupId);

                                            final latest = await ref.get();
                                            if (!latest.exists) {
                                              if (sheetContext.mounted) {
                                                Navigator.pop(sheetContext);
                                              }
                                              showSnack(
                                                this.context,
                                                'Study group no longer exists.',
                                                color: Colors.red,
                                              );
                                              return;
                                            }

                                            final data = latest.data() ??
                                                <String, dynamic>{};

                                            // Creator-only protection in the UI.
                                            // Firestore rules should enforce this too.
                                            if (_studyGroupText(data['creatorId']) !=
                                                uid) {
                                              if (sheetContext.mounted) {
                                                Navigator.pop(sheetContext);
                                              }
                                              showSnack(
                                                this.context,
                                                'Only the group creator can add members.',
                                                color: Colors.red,
                                              );
                                              return;
                                            }

                                            final members = List<String>.from(
                                              (data['memberIds'] as List?)
                                                  ?.whereType<String>() ??
                                                  const <String>[],
                                            );
                                            final limit = data['maxMembers'] is num
                                                ? (data['maxMembers'] as num).toInt()
                                                : maxMembers;

                                            if (members.length >= limit) {
                                              if (sheetContext.mounted) {
                                                Navigator.pop(sheetContext);
                                              }
                                              showSnack(
                                                this.context,
                                                'The group is full.',
                                                color: Colors.red,
                                              );
                                              return;
                                            }

                                            if (members.contains(doc.id)) {
                                              if (sheetContext.mounted) {
                                                Navigator.pop(sheetContext);
                                              }
                                              return;
                                            }

                                            members.add(doc.id);

                                            await ref.update({
                                              'memberIds': members,
                                              'memberCount': members.length,
                                              'invitedUids': FieldValue.arrayUnion([doc.id]),
                                              'updatedAt':
                                              FieldValue.serverTimestamp(),
                                            });

                                            // Keep the existing group-chat
                                            // document in sync with the study group.
                                            await FirebaseFirestore.instance
                                                .collection('groups')
                                                .doc(widget.groupId)
                                                .set(
                                              {
                                                'memberIds': members,
                                                'memberCount': members.length,
                                                'invitedUids': FieldValue.arrayUnion([doc.id]),
                                              },
                                              SetOptions(merge: true),
                                            );

                                            await _writeGroupJoinMarker(
                                              groupId: widget.groupId,
                                              joinedUserId: doc.id,
                                            );

                                            if (sheetContext.mounted) {
                                              Navigator.pop(sheetContext);
                                            }

                                            if (this.context.mounted) {
                                              showSnack(
                                                this.context,
                                                '$name added to the study group.',
                                                color: AppColors.green,
                                              );
                                            }
                                          } catch (e) {
                                            if (this.context.mounted) {
                                              showSnack(
                                                this.context,
                                                'Could not add member: $e',
                                                color: Colors.red,
                                              );
                                            }
                                          }
                                        },
                                        child: const Text('Add'),
                                      ),
                                    ],
                                  ),
                                );
                              },
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );
    } finally {
      search.dispose();
    }
  }

  Future<void> _confirmRemoveMember(String memberId, String memberName, String creatorId) async {
    final remove = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Remove member?'),
        content: Text('Remove $memberName from this study group?'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Cancel')),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            child: const Text('Remove'),
          ),
        ],
      ),
    );
    if (remove == true) {
      await _removeMember(memberId, creatorId);
    }
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
          stream: FirebaseFirestore.instance
              .collection('studyGroups')
              .doc(widget.groupId)
              .snapshots(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(child: CircularProgressIndicator());
            }
            if (!snapshot.hasData || !snapshot.data!.exists) {
              return const Center(child: Text('Study group no longer exists.'));
            }
            final d = snapshot.data!.data() ?? <String, dynamic>{};
            final members = List<String>.from(
              (d['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
            );
            final creatorId = _studyGroupText(d['creatorId']);
            final joined = members.contains(uid);
            final creator = creatorId == uid;
            final maxMembers = (d['maxMembers'] is num) ? (d['maxMembers'] as num).toInt() : 0;
            final full = maxMembers > 0 && members.length >= maxMembers;
            final groupImage = _studyGroupText(d['groupProfileImage']);
            final groupName = _studyGroupText(d['name']).isEmpty ? 'Study Group' : _studyGroupText(d['name']);

            return Column(
              children: [
                PageHeader(title: groupName),
                Expanded(
                  child: ListView(
                    padding: const EdgeInsets.fromLTRB(20, 4, 20, 30),
                    children: [
                      Container(
                        padding: const EdgeInsets.all(20),
                        decoration: BoxDecoration(
                          color: const Color(0xFFEAF3FF),
                          borderRadius: BorderRadius.circular(28),
                          border: Border.all(color: Colors.black, width: 1.4),
                        ),
                        child: Column(
                          children: [
                            Stack(
                              alignment: Alignment.bottomRight,
                              children: [
                                ProfileAvatar(
                                  imageUrl: groupImage,
                                  name: groupName,
                                  radius: 48,
                                ),
                                if (creator)
                                  Material(
                                    color: AppColors.blue,
                                    shape: const CircleBorder(),
                                    child: InkWell(
                                      customBorder: const CircleBorder(),
                                      onTap: _busy ? null : _uploadGroupPhoto,
                                      child: const Padding(
                                        padding: EdgeInsets.all(9),
                                        child: Icon(Icons.camera_alt_rounded, color: Colors.white, size: 19),
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                            const SizedBox(height: 14),
                            Text(
                              groupName,
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900),
                            ),
                            const SizedBox(height: 6),
                            Text(
                              _studyGroupText(d['subject']).isEmpty ? 'Study group' : _studyGroupText(d['subject']),
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: AppColors.muted),
                            ),
                            if (_studyGroupText(d['course']).isNotEmpty) ...[
                              const SizedBox(height: 4),
                              Text(_studyGroupText(d['course']), style: const TextStyle(color: AppColors.muted)),
                            ],
                            const SizedBox(height: 14),
                            Text(
                              _studyGroupText(d['description']),
                              textAlign: TextAlign.center,
                              style: const TextStyle(fontSize: 15, height: 1.45),
                            ),
                            const SizedBox(height: 14),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                const Icon(Icons.people_outline_rounded),
                                const SizedBox(width: 6),
                                Text(
                                  maxMembers > 0 ? '${members.length}/$maxMembers members' : '${members.length} members',
                                  style: const TextStyle(fontWeight: FontWeight.w900),
                                ),
                              ],
                            ),
                            if (creator) ...[
                              const SizedBox(height: 12),
                              const Text(
                                'You are the creator. You can manage members and the group picture.',
                                textAlign: TextAlign.center,
                                style: TextStyle(color: AppColors.muted, fontSize: 12, fontWeight: FontWeight.w600),
                              ),
                            ],
                          ],
                        ),
                      ),
                      const SizedBox(height: 18),
                      Row(
                        children: [
                          Expanded(
                            child: joined
                                ? FilledButton.icon(
                              onPressed: _openChat,
                              icon: const Icon(Icons.forum_rounded),
                              label: const Text('Open Group Chat'),
                            )
                                : (d['isPrivate'] ?? true) == true
                                ? StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                              stream: FirebaseFirestore.instance.collection('studyGroups').doc(widget.groupId).collection('joinRequests').doc(_currentUid()).snapshots(),
                              builder: (context, requestSnapshot) {
                                final requested = requestSnapshot.data?.exists == true && requestSnapshot.data?.data()?['status'] == 'pending';
                                return FilledButton.icon(
                                  onPressed: full || requested || _studyGroupJoinRequestsInFlight.contains('${widget.groupId}:${_currentUid()}')
                                      ? null
                                      : () async { await _requestOrJoinStudyGroup(context, widget.groupId); },
                                  icon: Icon(requested ? Icons.schedule_rounded : Icons.group_add_rounded),
                                  label: Text(full ? 'Group Full' : requested ? 'Requested' : 'Request to Join'),
                                );
                              },
                            )
                                : FilledButton.icon(
                              onPressed: full ? null : () async { await _requestOrJoinStudyGroup(context, widget.groupId); },
                              icon: const Icon(Icons.group_add_rounded),
                              label: Text(full ? 'Group Full' : 'Join Group'),
                            ),
                          ),
                          if (joined && !creator) ...[
                            const SizedBox(width: 10),
                            OutlinedButton(
                              onPressed: () => _leaveStudyGroup(context, widget.groupId),
                              child: const Text('Leave'),
                            ),
                          ],
                        ],
                      ),
                      if (creator) ...[
                        const SizedBox(height: 22),
                        const Text('Join Requests', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900)),
                        const SizedBox(height: 10),
                        StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                          stream: FirebaseFirestore.instance.collection('studyGroups').doc(widget.groupId).collection('joinRequests').where('status', isEqualTo: 'pending').snapshots(),
                          builder: (context, requestSnapshot) {
                            if (requestSnapshot.hasError) return const Text('Could not load join requests.');
                            if (requestSnapshot.connectionState == ConnectionState.waiting) return const LinearProgressIndicator();
                            final requests = requestSnapshot.data?.docs ?? <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                            if (requests.isEmpty) return const Padding(padding: EdgeInsets.only(bottom: 8), child: Text('No pending requests.', style: TextStyle(color: AppColors.muted)));
                            return Column(children: requests.map((request) {
                              final rd = request.data();
                              final requesterName = _studyGroupText(rd['requesterName']).isEmpty ? 'PeerGrid student' : _studyGroupText(rd['requesterName']);
                              return Container(
                                margin: const EdgeInsets.only(bottom: 8), padding: const EdgeInsets.all(12),
                                decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: Colors.black12)),
                                child: Row(children: [
                                  Expanded(child: Text(requesterName, style: const TextStyle(fontWeight: FontWeight.w800))),
                                  IconButton(tooltip: 'Decline request', onPressed: () => _reviewStudyGroupJoinRequest(context, widget.groupId, request.id, false), icon: const Icon(Icons.close_rounded, color: Colors.red)),
                                  IconButton(tooltip: 'Accept request', onPressed: () => _reviewStudyGroupJoinRequest(context, widget.groupId, request.id, true), icon: const Icon(Icons.check_circle_rounded, color: AppColors.green)),
                                ]),
                              );
                            }).toList());
                          },
                        ),
                        const SizedBox(height: 22),
                        Row(
                          children: [
                            const Expanded(
                              child: Text('Manage Members', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900)),
                            ),
                            FilledButton.icon(
                              onPressed: _busy || (maxMembers > 0 && members.length >= maxMembers)
                                  ? null
                                  : () => _showAddMemberSheet(members, maxMembers),
                              icon: const Icon(Icons.person_add_alt_1_rounded),
                              label: const Text('Add'),
                            ),
                          ],
                        ),
                        const SizedBox(height: 10),
                      ] else ...[
                        const SizedBox(height: 24),
                        const Text('Members', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900)),
                        const SizedBox(height: 10),
                      ],
                      for (final memberId in members)
                        _StudyGroupMemberTile(
                          uid: memberId,
                          isCreator: memberId == creatorId,
                          canRemove: creator && memberId != creatorId,
                          onRemove: () async {
                            final memberDoc = await FirebaseFirestore.instance.collection('users').doc(memberId).get();
                            final memberData = memberDoc.data() ?? <String, dynamic>{};
                            final memberName = _studyGroupText(memberData['name']).isEmpty
                                ? 'this member'
                                : _studyGroupText(memberData['name']);
                            if (mounted) {
                              await _confirmRemoveMember(memberId, memberName, creatorId);
                            }
                          },
                        ),
                    ],
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

