class GroupChatList extends StatelessWidget {
  const GroupChatList({super.key});

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('groups')
          .where('memberIds', arrayContains: uid)
          .limit(100)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return EmptyState(
            icon: Icons.error_outline_rounded,
            title: 'Could not load group chats',
            subtitle: snapshot.error.toString(),
          );
        }
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }
        final docs = snapshot.data!.docs.toList()
          ..sort((a, b) {
            final aValue = a.data()['lastMessageAt'];
            final bValue = b.data()['lastMessageAt'];
            final aTime = aValue is Timestamp ? aValue.millisecondsSinceEpoch : 0;
            final bTime = bValue is Timestamp ? bValue.millisecondsSinceEpoch : 0;
            return bTime.compareTo(aTime);
          });
        if (docs.isEmpty) {
          return const EmptyState(
            icon: Icons.groups_outlined,
            title: 'No group chats yet',
            subtitle: 'Join a community from the Groups tab to start chatting.',
          );
        }

        return ListView.builder(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 120),
          itemCount: docs.length,
          itemBuilder: (context, index) {
            final data = docs[index].data();
            final id = docs[index].id;
            final name = (data['name'] ?? id).toString();
            final subtitle = (data['subtitle'] ?? 'Community group').toString();
            final lastMessage = (data['lastMessage'] ?? '').toString().trim();
            final memberCount = data['memberCount'] is num ? (data['memberCount'] as num).toInt() : 0;
            return _ChatListTile(
              title: name,
              subtitle: lastMessage.isNotEmpty
                  ? lastMessage
                  : '$memberCount members • $subtitle',
              time: _chatDisplayTime(data['lastMessageAt']),
              unread: 0,
              icon: Icons.groups_rounded,
              onTap: () => Navigator.of(context).push(
                SlideFadeRoute(page: GroupChatScreen(groupId: id)),
              ),
            );
          },
        );
      },
    );
  }
}

