class _FirestoreReactionBar extends StatelessWidget {
  final DocumentReference<Map<String, dynamic>> document;
  const _FirestoreReactionBar({required this.document});

  // Broad emoji selection, grouped together in a WhatsApp-like floating picker.
  static const _choices = <String>[
    '😀','😃','😄','😁','😆','😅','😂','🤣','🥹','😊','😇','🙂','🙃','😉','😍','🥰','😘','😗','😙','😚','😋','😛','😜','🤪','😎','🥳','😭','😢','🥺','😡','🤬','😱','😮','😴','🤔','🤗','🫡','🤭','🫢','🤫','🫠','🤥','😶','😐','😑','🙄','😬','🤐','😷','🤒','🤕','🤧','🥵','🥶','🥴','😵','🤯','🤠','🥸','😈','👿','💀','☠️','💩','🤡','👻','👽','🤖','🎃',
    '❤️','🧡','💛','💚','💙','💜','🖤','🤍','🤎','💔','❤️‍🔥','💕','💞','💓','💗','💖','💘','💝','💟','❣️','💋','💯','💢','💥','💫','💦','💨','🕳️','💤','🔥','✨','⭐','🌟','🌈','☀️','🌙','⚡','☁️','🌧️','❄️','☃️',
    '👍','👎','👌','🤌','🤏','✌️','🤞','🫰','🤟','🤘','🤙','👈','👉','👆','👇','☝️','✋','🤚','🖐️','🖖','👋','🤝','🙏','👏','🙌','🫶','🤲','💪','🦾','🫵','🫂','👀','👁️','🧠','👑','🎉','🎊','🎈','🎁','🏆','🥇','💐','🌹','🌻','🌷','🍀','🍕','🍔','🍟','🍿','☕','🧋','🍰','🎂','⚽','🏀','🏏','🎮','🎵','🎶','📚','🎓','🚀','🐱','🐶','🦋','🐼','🦄','🐸','🐥','🌍','💎','🧸'
  ];

  Future<void> _react(BuildContext context, String emoji) async {
    final uid = _currentUid();
    if (uid.isEmpty) return;
    try {
      final snap = await document.get();
      final data = snap.data() ?? <String, dynamic>{};
      final reactions = Map<String, dynamic>.from(data['reactions'] as Map? ?? {});
      if (reactions[uid] == emoji) {
        reactions.remove(uid);
      } else {
        reactions[uid] = emoji;
      }
      await document.set({'reactions': reactions}, SetOptions(merge: true));
    } catch (_) {
      if (context.mounted) showSnack(context, 'Could not update reaction.', color: Colors.red, bottomMargin: 20);
    }
  }

  static Future<void> showPickerFor(BuildContext context, DocumentReference<Map<String, dynamic>> document) =>
      _FirestoreReactionBar(document: document)._showPicker(context);

  Future<void> _showPicker(BuildContext context) async {
    final emoji = await showDialog<String>(
      context: context,
      barrierColor: Colors.black26,
      builder: (dialogContext) => Dialog(
        insetPadding: const EdgeInsets.symmetric(horizontal: 18),
        backgroundColor: Colors.transparent,
        elevation: 0,
        child: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(28),
            boxShadow: const [BoxShadow(color: Colors.black26, blurRadius: 24, offset: Offset(0, 8))],
          ),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Row(children: [
              const Expanded(child: Text('React with emoji', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 14))),
              IconButton(onPressed: () => Navigator.pop(dialogContext), icon: const Icon(Icons.close_rounded, size: 19)),
            ]),
            SizedBox(
              height: MediaQuery.of(dialogContext).size.height * .42,
              child: GridView.builder(
                itemCount: _choices.length,
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 7, mainAxisSpacing: 4, crossAxisSpacing: 4),
                itemBuilder: (_, index) => InkWell(
                  borderRadius: BorderRadius.circular(12),
                  onTap: () => Navigator.pop(dialogContext, _choices[index]),
                  child: Center(child: Text(_choices[index], style: const TextStyle(fontSize: 25))),
                ),
              ),
            ),
          ]),
        ),
      ),
    );
    if (emoji != null && context.mounted) await _react(context, emoji);
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onLongPress: () => _showPicker(context),
      child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: document.snapshots(),
        builder: (context, snapshot) {
          final reactions = Map<String, dynamic>.from(snapshot.data?.data()?['reactions'] as Map? ?? {});
          final counts = <String, int>{};
          for (final value in reactions.values) {
            final emoji = value.toString();
            counts[emoji] = (counts[emoji] ?? 0) + 1;
          }
          final mine = reactions[_currentUid()]?.toString();
          return Padding(
            padding: const EdgeInsets.only(top: 4),
            child: Wrap(spacing: 5, runSpacing: 3, crossAxisAlignment: WrapCrossAlignment.center, children: [
              for (final emoji in counts.keys)
                InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: () => _react(context, emoji),
                  onLongPress: () => _showPicker(context),
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                    decoration: BoxDecoration(color: mine == emoji ? AppColors.cyan : Colors.white, borderRadius: BorderRadius.circular(14), border: Border.all(color: AppColors.ink, width: .8)),
                    child: Text('$emoji ${counts[emoji]}', style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800)),
                  ),
                ),
              GestureDetector(
                onLongPress: () => _showPicker(context),
                child: InkWell(
                  borderRadius: BorderRadius.circular(18),
                  onTap: () => _showPicker(context),
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(18), boxShadow: const [BoxShadow(color: Colors.black12, blurRadius: 8, offset: Offset(0, 3))]),
                    child: const Icon(Icons.add_reaction_outlined, size: 18),
                  ),
                ),
              ),
            ]),
          );
        },
      ),
    );
  }
}

class PrivateChatScreen extends StatefulWidget {
  final String otherUid;
  final String otherName;
  final String otherCollege;
  final String otherProfileImage;

  const PrivateChatScreen({
    super.key,
    required this.otherUid,
    required this.otherName,
    this.otherCollege = '',
    this.otherProfileImage = '',
  });

  @override
  State<PrivateChatScreen> createState() => _PrivateChatScreenState();
}

class _PrivateChatScreenState extends State<PrivateChatScreen> {
  final TextEditingController _controller = TextEditingController();
  final ScrollController _scroll = ScrollController();
  final ImagePicker _picker = ImagePicker();

  bool _sending = false;
  bool _typing = false;
  Timer? _typingTimer;
  Map<String, dynamic>? _replyingTo;
  double _replySwipeDistance = 0;
  bool _replySwipeTriggered = false;
  final AudioRecorder _voiceRecorder = AudioRecorder();
  Timer? _voiceTimer;
  bool _recordingVoice = false;
  bool _uploadingVoice = false;
  int _voiceSeconds = 0;

  String get _chatId => privateChatIdFor(_currentUid(), widget.otherUid);

  DocumentReference<Map<String, dynamic>> get _chatRef =>
      FirebaseFirestore.instance.collection('privateChats').doc(_chatId);

  CollectionReference<Map<String, dynamic>> get _messagesRef =>
      _chatRef.collection('messages');

  DocumentReference<Map<String, dynamic>> get _typingRef =>
      _chatRef.collection('typing').doc(_currentUid());

  @override
  void initState() {
    super.initState();
    _markPrivateChatRead(_chatId).catchError((_) {});
    _controller.addListener(_onTypingChanged);
  }

  @override
  void dispose() {
    _typingTimer?.cancel();
    _stopTyping();
    _controller.removeListener(_onTypingChanged);
    _controller.dispose();
    _scroll.dispose();
    _voiceTimer?.cancel();
    _voiceRecorder.dispose();
    super.dispose();
  }

  Future<void> _toggleVoiceNote() async {
    if (_uploadingVoice) return;
    if (!_recordingVoice) {
      try {
        if (!await _voiceRecorder.hasPermission()) {
          if (mounted) showSnack(context, 'Microphone permission is required to record voice notes.');
          return;
        }
        final dir = await getTemporaryDirectory();
        final path = '${dir.path}/peergrid_voice_${DateTime.now().millisecondsSinceEpoch}.m4a';
        await _voiceRecorder.start(const RecordConfig(encoder: AudioEncoder.aacLc), path: path);
        if (!mounted) return;
        setState(() { _recordingVoice = true; _voiceSeconds = 0; });
        _voiceTimer?.cancel();
        _voiceTimer = Timer.periodic(const Duration(seconds: 1), (_) {
          if (mounted) setState(() => _voiceSeconds++);
        });
      } catch (e) {
        if (mounted) showSnack(context, 'Could not start recording: $e', color: Colors.red);
      }
      return;
    }
    _voiceTimer?.cancel();
    try {
      final path = await _voiceRecorder.stop();
      if (mounted) setState(() { _recordingVoice = false; _uploadingVoice = true; });
      if (path == null || !await File(path).exists() || await File(path).length() == 0) {
        if (mounted) setState(() => _uploadingVoice = false);
        return;
      }
      final duration = _voiceSeconds;
      final uid = _currentUid();
      final storageRef = FirebaseStorage.instance.ref().child('private_voice_notes/$_chatId/${DateTime.now().millisecondsSinceEpoch}_$uid.m4a');
      await storageRef.putFile(File(path), SettableMetadata(contentType: 'audio/mp4'));
      final url = await storageRef.getDownloadURL();
      await _sendPrivateMessage(chatId: _chatId, recipientUid: widget.otherUid, text: '', messageType: 'voice', mediaUrl: url, thumbnailUrl: '', voiceDurationSeconds: duration);
      if (mounted) showSnack(context, 'Voice note sent');
    } catch (e) {
      if (mounted) showSnack(context, 'Could not send voice note: $e', color: Colors.red);
    } finally {
      if (mounted) setState(() { _recordingVoice = false; _uploadingVoice = false; _voiceSeconds = 0; });
    }
  }

  void _onTypingChanged() {
    if (_sending) return;
    final hasText = _controller.text.trim().isNotEmpty;
    if (hasText && !_typing) {
      _setTyping(true);
    } else if (!hasText && _typing) {
      _setTyping(false);
    }
    _typingTimer?.cancel();
    if (hasText) {
      _typingTimer = Timer(const Duration(seconds: 2), () {
        _setTyping(false);
      });
    }
  }

  Future<void> _setTyping(bool value) async {
    if (_currentUid().isEmpty) return;
    if (_typing == value && value) {
      try {
        await _typingRef.set({
          'uid': _currentUid(),
          'name': userName.value,
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      } catch (_) {}
      return;
    }
    if (mounted) setState(() => _typing = value);
    try {
      if (value) {
        await _typingRef.set({
          'uid': _currentUid(),
          'name': userName.value,
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      } else {
        await _typingRef.delete();
      }
    } catch (_) {}
  }

  Future<void> _stopTyping() async {
    if (_currentUid().isEmpty) return;
    try {
      await _typingRef.delete();
    } catch (_) {}
  }

  void _setReply(Map<String, dynamic> data) {
    setState(() {
      _replyingTo = <String, dynamic>{
        'id': data['id']?.toString() ?? '',
        'text': data['text']?.toString() ?? '',
        'senderName': data['senderName']?.toString() ?? 'Student',
        'messageType': data['messageType']?.toString() ?? 'text',
        'sticker': data['sticker']?.toString() ?? '',
      };
    });
    FocusScope.of(context).requestFocus(FocusNode());
  }

  void _clearReply() {
    if (mounted) setState(() => _replyingTo = null);
  }

  Future<void> _send() async {
    final text = _controller.text.trim();
    if (text.isEmpty || _sending) return;

    final reply = _replyingTo;
    setState(() => _sending = true);
    _controller.clear();
    _clearReply();
    await _setTyping(false);

    try {
      await _sendPrivateMessage(
        chatId: _chatId,
        recipientUid: widget.otherUid,
        text: text,
        replyToId: reply?['id']?.toString() ?? '',
        replyToText: reply?['text']?.toString() ?? '',
        replyToSenderName: reply?['senderName']?.toString() ?? '',
      );
    } catch (e) {
      if (mounted) {
        _controller.text = text;
        showSnack(context, 'Could not send message: $e', color: Colors.red, bottomMargin: 20);
      }
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _sendMedia({required bool video}) async {
    if (_sending) return;

    try {
      final XFile? picked = video
          ? await _picker.pickVideo(source: ImageSource.gallery)
          : await _pickAndCropImage(
        source: ImageSource.gallery,
        imageQuality: 88,
      );

      if (picked == null) return;

      setState(() => _sending = true);

      // IMPORTANT:
      // The Storage Rules authorize private-chat media only when the
      // corresponding Firestore privateChats/{chatId} document exists
      // and contains the signed-in user as a participant.
      await _ensurePrivateChat(
        otherUid: widget.otherUid,
        otherName: widget.otherName,
      );

      // Verify that the chat document really exists before starting the
      // Storage upload. This prevents a Storage request from being made
      // against a chat that has not been created successfully.
      final chatSnapshot = await _chatRef.get();
      if (!chatSnapshot.exists) {
        throw StateError(
          'Private chat could not be created. Please open the chat again and retry.',
        );
      }

      final chatData = chatSnapshot.data();
      final participants = (chatData?['participants'] as List?)
          ?.map((value) => value.toString())
          .toList() ??
          <String>[];

      if (!participants.contains(_currentUid()) ||
          !participants.contains(widget.otherUid)) {
        throw StateError(
          'Private chat participants could not be verified.',
        );
      }

      final extension = picked.name.contains('.')
          ? picked.name.split('.').last.toLowerCase()
          : (video ? 'mp4' : 'jpg');

      final type = video ? 'video' : 'image';

      final storagePath =
          'privateChats/$_chatId/media/${DateTime.now().millisecondsSinceEpoch}_${_currentUid()}.$extension';

      final ref = FirebaseStorage.instance.ref().child(storagePath);

      final contentType = video
          ? (extension == 'mov'
          ? 'video/quicktime'
          : extension == 'm4v'
          ? 'video/x-m4v'
          : 'video/mp4')
          : (extension == 'png'
          ? 'image/png'
          : extension == 'webp'
          ? 'image/webp'
          : extension == 'gif'
          ? 'image/gif'
          : 'image/jpeg');

      final metadata = SettableMetadata(
        contentType: contentType,
      );

      final upload = await ref.putFile(
        File(picked.path),
        metadata,
      );

      final url = await upload.ref.getDownloadURL();

      final reply = _replyingTo;
      _clearReply();

      await _sendPrivateMessage(
        chatId: _chatId,
        recipientUid: widget.otherUid,
        text: '',
        messageType: type,
        mediaUrl: url,
        replyToId: reply?['id']?.toString() ?? '',
        replyToText: reply?['text']?.toString() ?? '',
        replyToSenderName: reply?['senderName']?.toString() ?? '',
      );
    } catch (e) {
      if (mounted) {
        showSnack(
          context,
          'Could not send ${video ? 'video' : 'image'}: $e',
          color: Colors.red,
          bottomMargin: 20,
        );
      }
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }


  Future<void> _pickAndSendFile() async {
    if (_sending) return;
    try {
      final result = await FilePicker.platform.pickFiles(
        type: FileType.any,
        allowMultiple: false,
        withData: false,
      );
      if (result == null || result.files.isEmpty) return;
      final picked = result.files.single;
      final path = picked.path;
      if (path == null || path.isEmpty) {
        throw StateError('This file could not be accessed. Please choose it again.');
      }
      final file = File(path);
      if (!await file.exists()) throw StateError('The selected file is no longer available.');
      final size = await file.length();
      if (size <= 0) throw StateError('The selected file is empty.');
      if (size > 25 * 1024 * 1024) {
        throw StateError('Please choose a file smaller than 25 MB.');
      }

      setState(() => _sending = true);
      await _ensurePrivateChat(otherUid: widget.otherUid, otherName: widget.otherName);
      final chatSnapshot = await _chatRef.get();
      final participants = (chatSnapshot.data()?['participants'] as List?)
          ?.map((value) => value.toString()).toList() ?? <String>[];
      if (!chatSnapshot.exists ||
          !participants.contains(_currentUid()) ||
          !participants.contains(widget.otherUid)) {
        throw StateError('Private chat participants could not be verified.');
      }

      final safeName = picked.name.replaceAll(RegExp(r'[/\\]'), '_');
      final extension = safeName.contains('.')
          ? safeName.split('.').last.toLowerCase()
          : '';
      final storagePath =
          'privateChats/$_chatId/files/${DateTime.now().millisecondsSinceEpoch}_${_currentUid()}_$safeName';
      final ref = FirebaseStorage.instance.ref().child(storagePath);
      await ref.putFile(
        file,
        SettableMetadata(contentType: 'application/octet-stream'),
      );
      final url = await ref.getDownloadURL();
      final reply = _replyingTo;
      _clearReply();
      await _sendPrivateMessage(
        chatId: _chatId,
        recipientUid: widget.otherUid,
        text: '',
        messageType: 'file',
        mediaUrl: url,
        fileName: safeName,
        fileSize: size,
        fileExtension: extension,
        storagePath: storagePath,
        replyToId: reply?['id']?.toString() ?? '',
        replyToText: reply?['text']?.toString() ?? '',
        replyToSenderName: reply?['senderName']?.toString() ?? '',
      );
    } catch (e) {
      if (mounted) showSnack(context, 'Could not send file: $e',
          color: Colors.red, bottomMargin: 20);
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _openSharedFile(String url) async {
    final uri = Uri.tryParse(url);
    if (uri == null || !await launchUrl(uri, mode: LaunchMode.externalApplication)) {
      if (mounted) showSnack(context, 'Could not open this file.',
          color: Colors.red, bottomMargin: 20);
    }
  }

  Future<void> _sendSticker(String sticker) async {
    if (_sending) return;
    final reply = _replyingTo;
    _clearReply();
    try {
      setState(() => _sending = true);
      await _sendPrivateMessage(
        chatId: _chatId,
        recipientUid: widget.otherUid,
        text: '',
        messageType: 'sticker',
        sticker: sticker,
        replyToId: reply?['id']?.toString() ?? '',
        replyToText: reply?['text']?.toString() ?? '',
        replyToSenderName: reply?['senderName']?.toString() ?? '',
      );
    } catch (e) {
      if (mounted) {
        showSnack(context, 'Could not send sticker: $e', color: Colors.red, bottomMargin: 20);
      }
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  void _showStickerPicker() {
    const stickers = [
      '😀', '😂', '🥹', '😍', '🤩', '😎', '🥳', '🤗',
      '❤️', '💛', '💚', '💙', '💜', '🔥', '✨', '⭐',
      '👍', '👏', '🙌', '💯', '🎉', '🚀', '💻', '🤝',
      '😭', '😅', '🤔', '😴', '😱', '🤯', '🥰', '😇',
    ];

    showModalBottomSheet(
      context: context,
      backgroundColor: AppColors.cream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
        side: BorderSide(color: AppColors.ink, width: 2),
      ),
      builder: (sheetContext) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 14, 18, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    const Expanded(child: Text('Stickers', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900))),
                    TextButton.icon(
                      onPressed: () async {
                        Navigator.of(sheetContext).pop();
                        final custom = await _showCustomCommentStickerPicker(context);
                        if (custom != null && mounted) await _sendSticker(custom.url);
                      },
                      icon: const Icon(Icons.collections_rounded),
                      label: const Text('My Stickers'),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                GridView.builder(
                  shrinkWrap: true,
                  itemCount: stickers.length,
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 8,
                    mainAxisSpacing: 8,
                    crossAxisSpacing: 8,
                  ),
                  itemBuilder: (_, i) => GestureDetector(
                    onTap: () {
                      Navigator.pop(sheetContext);
                      _sendSticker(stickers[i]);
                    },
                    child: Container(
                      alignment: Alignment.center,
                      decoration: neoDeco(color: Colors.white, radius: 12, shadow: false),
                      child: Text(stickers[i], style: const TextStyle(fontSize: 25)),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _showMessageActions(Map<String, dynamic> data) {
    final type = data['messageType']?.toString() ?? 'text';
    showModalBottomSheet(
      context: context,
      backgroundColor: AppColors.cream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
        side: BorderSide(color: AppColors.ink, width: 2),
      ),
      builder: (sheetContext) {
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ListTile(
                leading: const Icon(Icons.reply_rounded),
                title: const Text('Reply', style: TextStyle(fontWeight: FontWeight.w800)),
                onTap: () {
                  Navigator.pop(sheetContext);
                  _setReply(data);
                },
              ),
              if (type == 'text' && (data['text'] ?? '').toString().isNotEmpty)
                ListTile(
                  leading: const Icon(Icons.copy_rounded),
                  title: const Text('Copy', style: TextStyle(fontWeight: FontWeight.w800)),
                  onTap: () async {
                    await Clipboard.setData(
                      ClipboardData(text: (data['text'] ?? '').toString()),
                    );
                    if (mounted) {
                      Navigator.pop(sheetContext);
                      showSnack(context, 'Message copied');
                    }
                  },
                ),
              ListTile(
                leading: const Icon(Icons.close_rounded),
                title: const Text('Cancel', style: TextStyle(fontWeight: FontWeight.w800)),
                onTap: () => Navigator.pop(sheetContext),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _replyPreview(Map<String, dynamic> data, {bool composer = false}) {
    final sender = (data['replyToSenderName'] ?? '').toString();
    final text = (data['replyToText'] ?? '').toString();
    final sticker = (data['sticker'] ?? '').toString();
    final display = text.isNotEmpty ? text : (sticker.isNotEmpty ? '$sticker Sticker' : 'Media');
    return Container(
      width: double.infinity,
      margin: EdgeInsets.only(bottom: composer ? 8 : 6),
      padding: const EdgeInsets.fromLTRB(10, 7, 10, 7),
      decoration: BoxDecoration(
        color: composer ? AppColors.softBlue : Colors.black.withOpacity(.07),
        borderRadius: BorderRadius.circular(12),
        border: const Border(left: BorderSide(color: AppColors.blue, width: 4)),
      ),
      child: Text(
        sender.isEmpty ? display : '$sender · $display',
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
        style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800),
      ),
    );
  }

  Widget _messageContent(Map<String, dynamic> data, bool mine) {
    final type = data['messageType']?.toString() ?? 'text';
    final text = (data['text'] ?? '').toString();
    final mediaUrl = (data['mediaUrl'] ?? '').toString();
    final sticker = (data['sticker'] ?? '').toString();

    final children = <Widget>[];

    if ((data['replyToText'] ?? '').toString().isNotEmpty ||
        (data['replyToSenderName'] ?? '').toString().isNotEmpty) {
      children.add(_replyPreview(data));
    }

    if (type == 'image' && mediaUrl.isNotEmpty) {
      children.add(
        ClipRRect(
          borderRadius: BorderRadius.circular(13),
          child: GestureDetector(
            onTap: () => _openImage(mediaUrl),
            child: AdaptiveImage(
              image: NetworkImage(mediaUrl),
              width: 220,
              maxHeight: 320,
              fit: BoxFit.contain,
              error: const SizedBox(
                width: 220,
                height: 120,
                child: Icon(Icons.broken_image_rounded),
              ),
            ),
          ),
        ),
      );
    } else if (type == 'video' && mediaUrl.isNotEmpty) {
      children.add(_ChatVideoBubble(url: mediaUrl));
    } else if (type == 'voice' && mediaUrl.isNotEmpty) {
      children.add(_VoiceNoteBubble(url: mediaUrl, durationSeconds: int.tryParse((data['voiceDurationSeconds'] ?? 0).toString()) ?? 0, mine: mine));
    } else if (type == 'file' && mediaUrl.isNotEmpty) {
      children.add(_SharedFileMessage(
        fileName: (data['fileName'] ?? 'Shared file').toString(),
        fileSize: int.tryParse((data['fileSize'] ?? 0).toString()) ?? 0,
        url: mediaUrl,
        mine: mine,
      ));
    } else if (type == 'sticker') {
      final isImageSticker = sticker.startsWith('https://') || sticker.startsWith('http://');
      children.add(isImageSticker
          ? GestureDetector(
        onTap: () => _openImage(sticker),
        child: Image.network(sticker, width: 150, height: 150, fit: BoxFit.contain,
            errorBuilder: (_, __, ___) => const Icon(Icons.broken_image_outlined, size: 48)),
      )
          : Text(sticker, style: const TextStyle(fontSize: 64)));
    } else if (text.isNotEmpty) {
      children.add(
        Text(
          text,
          style: TextStyle(
            color: mine ? Colors.white : AppColors.ink,
            fontSize: 15,
            height: 1.3,
          ),
        ),
      );
    }

    return Column(
      crossAxisAlignment: mine ? CrossAxisAlignment.end : CrossAxisAlignment.start,
      children: children,
    );
  }

  void _openImage(String url) {
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => Scaffold(
          backgroundColor: Colors.black,
          appBar: AppBar(backgroundColor: Colors.black),
          body: Center(
            child: InteractiveViewer(
              child: DarkSafe(
                child: DarkSafe(
                  child: Image.network(url, fit: BoxFit.contain),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _typingIndicator() {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: _chatRef.collection('typing').doc(widget.otherUid).snapshots(),
      builder: (context, snapshot) {
        final data = snapshot.data?.data();
        if (data == null) return const SizedBox.shrink();
        final updated = data['updatedAt'];
        if (updated is Timestamp &&
            DateTime.now().difference(updated.toDate()).inSeconds > 5) {
          return const SizedBox.shrink();
        }
        return Align(
          alignment: Alignment.centerLeft,
          child: Container(
            margin: const EdgeInsets.fromLTRB(16, 0, 16, 6),
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
            decoration: neoDeco(color: Colors.white, radius: 14, shadow: false),
            child: Text(
              '${widget.otherName} is typing…',
              style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800),
            ),
          ),
        );
      },
    );
  }

  Widget _ticks(Map<String, dynamic> data) {
    final readBy = List<String>.from(
      (data['readBy'] as List?)?.whereType<String>() ?? const <String>[],
    );
    final deliveredTo = List<String>.from(
      (data['deliveredTo'] as List?)?.whereType<String>() ?? const <String>[],
    );
    final isRead = readBy.contains(widget.otherUid);
    final isDelivered = deliveredTo.contains(widget.otherUid);
    return Icon(
      isRead ? Icons.done_all_rounded : Icons.done_all_rounded,
      size: 14,
      color: isRead
          ? const Color(0xFF39A9FF)
          : (isDelivered ? Colors.white70 : Colors.white70),
    );
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();

    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(
        backgroundColor: AppColors.cyan,
        foregroundColor: AppColors.ink,
        elevation: 0,
        titleSpacing: 0,
        title: Row(
          children: [
            ProfileAvatar(
              imageUrl: widget.otherProfileImage,
              name: widget.otherName,
              radius: 20,
            ),
            const SizedBox(width: 10),
            Expanded(
              child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: _chatRef.collection('typing').doc(widget.otherUid).snapshots(),
                builder: (context, snapshot) {
                  final data = snapshot.data?.data();
                  final typing = data != null &&
                      data['updatedAt'] is Timestamp &&
                      DateTime.now().difference((data['updatedAt'] as Timestamp).toDate()).inSeconds <= 5;
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(widget.otherName,
                          style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900)),
                      Text(
                        typing
                            ? 'typing…'
                            : (widget.otherCollege.trim().isEmpty ? 'PeerGrid student' : widget.otherCollege),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w700,
                          color: typing ? AppColors.blue : AppColors.ink,
                        ),
                      ),
                    ],
                  );
                },
              ),
            ),
            NeoIconButton(
              icon: Icons.palette_rounded,
              color: AppColors.softBlue,
              size: 38,
              onTap: () => showSnack(context, 'PeerGrid theme enabled'),
            ),
          ],
        ),
      ),
      body: Stack(
        children: [
          Positioned.fill(
            child: CustomPaint(
              painter: _ChatPatternPainter(),
            ),
          ),
          Column(
            children: [
              Expanded(
                child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: _messagesRef.orderBy('createdAt', descending: false).limitToLast(150).snapshots(),
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return EmptyState(
                        icon: Icons.error_outline_rounded,
                        title: 'Could not load messages',
                        subtitle: snapshot.error.toString(),
                      );
                    }
                    if (snapshot.connectionState == ConnectionState.waiting) {
                      return const Center(child: CircularProgressIndicator());
                    }

                    final docs = snapshot.data!.docs;
                    if (docs.isEmpty) {
                      return const EmptyState(
                        icon: Icons.chat_bubble_outline_rounded,
                        title: 'Start the conversation',
                        subtitle: 'Send a message to say hello.',
                      );
                    }

                    WidgetsBinding.instance.addPostFrameCallback((_) {
                      if (_scroll.hasClients) {
                        _scroll.jumpTo(_scroll.position.maxScrollExtent);
                      }
                      _markPrivateChatRead(_chatId).catchError((_) {});
                    });

                    return ListView.builder(
                      controller: _scroll,
                      padding: const EdgeInsets.fromLTRB(12, 18, 12, 10),
                      itemCount: docs.length,
                      itemBuilder: (context, index) {
                        final raw = docs[index].data();
                        final data = <String, dynamic>{...raw, 'id': docs[index].id};
                        final mine = data['senderId'] == uid;
                        final timestamp = data['createdAt'];

                        final bubble = Container(
                          constraints: BoxConstraints(
                            maxWidth: MediaQuery.of(context).size.width * .78,
                          ),
                          margin: const EdgeInsets.only(bottom: 8),
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: mine ? AppColors.blue : Colors.white,
                            borderRadius: BorderRadius.only(
                              topLeft: const Radius.circular(18),
                              topRight: const Radius.circular(18),
                              bottomLeft: Radius.circular(mine ? 18 : 4),
                              bottomRight: Radius.circular(mine ? 4 : 18),
                            ),
                            border: Border.all(color: AppColors.ink, width: 1.5),
                            boxShadow: mine ? neoShadow : null,
                          ),
                          child: Column(
                            crossAxisAlignment:
                            mine ? CrossAxisAlignment.end : CrossAxisAlignment.start,
                            children: [
                              if (!mine)
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 3),
                                  child: Text(
                                    (data['senderName'] ?? widget.otherName).toString(),
                                    style: const TextStyle(
                                      color: AppColors.blue,
                                      fontSize: 11,
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                ),
                              _messageContent(data, mine),
                              const SizedBox(height: 4),
                              Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    _chatDisplayTime(timestamp),
                                    style: TextStyle(
                                      color: mine ? Colors.white70 : AppColors.muted,
                                      fontSize: 9,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  if (mine) ...[
                                    const SizedBox(width: 4),
                                    _ticks(data),
                                  ],
                                ],
                              ),
                              _FirestoreReactionBar(document: _messagesRef.doc(data['id'].toString())),
                            ],
                          ),
                        );

                        return Align(
                          alignment: mine ? Alignment.centerRight : Alignment.centerLeft,
                          child: GestureDetector(
                            onLongPress: () => _FirestoreReactionBar.showPickerFor(context, _messagesRef.doc(data['id'].toString())),
                            onHorizontalDragStart: (_) {
                              _replySwipeDistance = 0;
                              _replySwipeTriggered = false;
                            },
                            onHorizontalDragUpdate: (details) {
                              if (_replySwipeTriggered) return;
                              if (details.delta.dx > 0) {
                                _replySwipeDistance += details.delta.dx;
                                if (_replySwipeDistance >= 55) {
                                  _replySwipeTriggered = true;
                                  _setReply(data);
                                }
                              } else {
                                _replySwipeDistance = 0;
                              }
                            },
                            onHorizontalDragEnd: (_) {
                              _replySwipeDistance = 0;
                              _replySwipeTriggered = false;
                            },
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              crossAxisAlignment: CrossAxisAlignment.end,
                              children: mine
                                  ? [
                                Flexible(child: bubble),
                                const SizedBox(width: 5),
                                ProfileAvatar(
                                  imageUrl: (data['senderProfileImage'] ?? userProfileImage.value).toString(),
                                  name: (data['senderName'] ?? userName.value).toString(),
                                  radius: 15,
                                ),
                              ]
                                  : [
                                ProfileAvatar(
                                  imageUrl: widget.otherProfileImage,
                                  name: widget.otherName,
                                  radius: 15,
                                ),
                                const SizedBox(width: 5),
                                Flexible(child: bubble),
                              ],
                            ),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
              _typingIndicator(),
              if (_recordingVoice || _uploadingVoice)
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 4, 16, 4),
                  child: Row(children: [Icon(_uploadingVoice ? Icons.cloud_upload_rounded : Icons.fiber_manual_record, color: Colors.red, size: 16), const SizedBox(width: 8), Text(_uploadingVoice ? 'Sending voice note…' : 'Recording voice note · ${_voiceSeconds}s', style: const TextStyle(fontWeight: FontWeight.w800))]),
                ),
              if (_replyingTo != null)
                Padding(
                  padding: const EdgeInsets.fromLTRB(12, 0, 12, 4),
                  child: Row(
                    children: [
                      Expanded(child: _replyPreview(_replyingTo!, composer: true)),
                      IconButton(
                        onPressed: _clearReply,
                        icon: const Icon(Icons.close_rounded),
                      ),
                    ],
                  ),
                ),
              SafeArea(
                top: false,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(10, 7, 10, 10),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      NeoIconButton(
                        icon: Icons.add_rounded,
                        color: AppColors.cyan,
                        size: 44,
                        onTap: () => showModalBottomSheet(
                          context: context,
                          backgroundColor: AppColors.cream,
                          shape: const RoundedRectangleBorder(
                            borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
                            side: BorderSide(color: AppColors.ink, width: 2),
                          ),
                          builder: (_) => SafeArea(
                            child: Padding(
                              padding: const EdgeInsets.all(18),
                              child: Row(
                                mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                                children: [
                                  _ChatAttachButton(
                                    icon: Icons.photo_rounded,
                                    label: 'Photo',
                                    onTap: () {
                                      Navigator.pop(context);
                                      _sendMedia(video: false);
                                    },
                                  ),
                                  _ChatAttachButton(
                                    icon: Icons.videocam_rounded,
                                    label: 'Video',
                                    onTap: () {
                                      Navigator.pop(context);
                                      _sendMedia(video: true);
                                    },
                                  ),
                                  _ChatAttachButton(
                                    icon: Icons.insert_drive_file_rounded,
                                    label: 'File',
                                    onTap: () {
                                      Navigator.pop(context);
                                      _pickAndSendFile();
                                    },
                                  ),
                                  _ChatAttachButton(
                                    icon: Icons.sticky_note_2_rounded,
                                    label: 'Sticker',
                                    onTap: () {
                                      Navigator.pop(context);
                                      _showStickerPicker();
                                    },
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 7),
                      Expanded(
                        child: TextField(
                          controller: _controller,
                          textInputAction: TextInputAction.send,
                          onSubmitted: (_) => _send(),
                          minLines: 1,
                          maxLines: 5,
                          decoration: InputDecoration(
                            hintText: 'Message ${widget.otherName}...',
                            filled: true,
                            fillColor: Colors.white,
                            contentPadding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 12,
                            ),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(28),
                              borderSide: const BorderSide(color: AppColors.ink, width: 2),
                            ),
                            enabledBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(28),
                              borderSide: const BorderSide(color: AppColors.ink, width: 2),
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(28),
                              borderSide: const BorderSide(color: AppColors.blue, width: 2.5),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 7),
                      NeoIconButton(
                        icon: _uploadingVoice ? Icons.hourglass_top_rounded : (_recordingVoice ? Icons.stop_rounded : Icons.mic_rounded),
                        color: _recordingVoice ? Colors.redAccent : AppColors.cyan,
                        size: 44,
                        onTap: _sending || _uploadingVoice ? null : _toggleVoiceNote,
                      ),
                      const SizedBox(width: 5),
                      NeoIconButton(
                        icon: Icons.send_rounded,
                        color: AppColors.blue,
                        size: 48,
                        onTap: _sending ? null : _send,
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}


class _SharedFileMessage extends StatelessWidget {
  final String fileName;
  final int fileSize;
  final String url;
  final bool mine;

  const _SharedFileMessage({
    required this.fileName,
    required this.fileSize,
    required this.url,
    required this.mine,
  });

  String get _formattedSize {
    if (fileSize <= 0) return 'File';
    if (fileSize < 1024 * 1024) return '${(fileSize / 1024).toStringAsFixed(1)} KB';
    return '${(fileSize / (1024 * 1024)).toStringAsFixed(1)} MB';
  }

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: () async {
        final uri = Uri.tryParse(url);
        if (uri == null || !await launchUrl(uri, mode: LaunchMode.externalApplication)) {
          if (context.mounted) {
            showSnack(context, 'Could not open this file.',
                color: Colors.red, bottomMargin: 20);
          }
        }
      },
      borderRadius: BorderRadius.circular(12),
      child: Container(
        constraints: const BoxConstraints(minWidth: 190, maxWidth: 260),
        padding: const EdgeInsets.all(11),
        decoration: BoxDecoration(
          color: mine ? Colors.white.withOpacity(.14) : AppColors.softBlue,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: mine ? Colors.white30 : Colors.black12),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.insert_drive_file_rounded,
                size: 32, color: mine ? Colors.white : AppColors.blue),
            const SizedBox(width: 9),
            Flexible(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(fileName,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: mine ? Colors.white : AppColors.ink,
                        fontWeight: FontWeight.w800,
                        fontSize: 13,
                      )),
                  const SizedBox(height: 3),
                  Text('$_formattedSize · Tap to open',
                      style: TextStyle(
                        color: mine ? Colors.white70 : AppColors.muted,
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                      )),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

