class _VoiceNoteBubble extends StatefulWidget {
  final String url;
  final int durationSeconds;
  final bool mine;
  const _VoiceNoteBubble({required this.url, required this.durationSeconds, required this.mine});

  @override
  State<_VoiceNoteBubble> createState() => _VoiceNoteBubbleState();
}

class _VoiceNoteBubbleState extends State<_VoiceNoteBubble> {
  late final AudioPlayer _player = AudioPlayer();
  bool _playing = false;
  Duration _position = Duration.zero;
  Duration _duration = Duration.zero;
  StreamSubscription<PlayerState>? _stateSub;
  StreamSubscription<Duration>? _positionSub;
  StreamSubscription<Duration?>? _durationSub;

  @override
  void initState() {
    super.initState();
    _stateSub = _player.onPlayerStateChanged.listen((state) {
      if (mounted) setState(() => _playing = state == PlayerState.playing);
    });
    _positionSub = _player.onPositionChanged.listen((value) { if (mounted) setState(() => _position = value); });
    _durationSub = _player.onDurationChanged.listen((value) { if (mounted) setState(() => _duration = value); });
  }

  @override
  void didUpdateWidget(covariant _VoiceNoteBubble oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.url != widget.url) { _player.stop(); _position = Duration.zero; }
  }

  @override
  void dispose() {
    _stateSub?.cancel(); _positionSub?.cancel(); _durationSub?.cancel(); _player.dispose();
    super.dispose();
  }

  String _time(Duration value) => '${value.inMinutes}:${(value.inSeconds % 60).toString().padLeft(2, '0')}';

  @override
  Widget build(BuildContext context) {
    final total = _duration.inSeconds > 0 ? _duration : Duration(seconds: widget.durationSeconds);
    final color = widget.mine ? Colors.white : AppColors.ink;
    final maxMs = total.inMilliseconds;
    return SizedBox(width: 220, child: Row(children: [
      IconButton(visualDensity: VisualDensity.compact, onPressed: () async {
        try { if (_playing) { await _player.pause(); } else { if (_position >= total && total > Duration.zero) await _player.seek(Duration.zero); await _player.play(UrlSource(widget.url)); } }
        catch (_) { if (mounted) showSnack(context, 'Could not play this voice note.'); }
      }, icon: Icon(_playing ? Icons.pause_circle_filled_rounded : Icons.play_circle_fill_rounded, size: 36, color: color)),
      Expanded(child: Column(mainAxisSize: MainAxisSize.min, children: [
        SliderTheme(data: SliderTheme.of(context).copyWith(trackHeight: 3, thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 5), overlayShape: SliderComponentShape.noOverlay, activeTrackColor: color, inactiveTrackColor: color.withOpacity(.25), thumbColor: color),
            child: Slider(value: maxMs <= 0 ? 0 : _position.inMilliseconds.clamp(0, maxMs).toDouble(), max: maxMs <= 0 ? 1 : maxMs.toDouble(), onChanged: maxMs <= 0 ? null : (v) => _player.seek(Duration(milliseconds: v.round())))),
        Align(alignment: Alignment.centerLeft, child: Text(_time(_position == Duration.zero ? total : _position), style: TextStyle(fontSize: 10, color: color, fontWeight: FontWeight.w700))),
      ])),
    ]));
  }
}

class _ChatVideoBubble extends StatefulWidget {
  final String url;

  const _ChatVideoBubble({required this.url});

  @override
  State<_ChatVideoBubble> createState() => _ChatVideoBubbleState();
}

class _ChatVideoBubbleState extends State<_ChatVideoBubble> {
  VideoPlayerController? _controller;

  @override
  void initState() {
    super.initState();
    final controller = VideoPlayerController.networkUrl(Uri.parse(widget.url));
    _controller = controller;
    controller.initialize().then((_) {
      if (mounted) setState(() {});
    }).catchError((_) {});
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    if (controller == null || !controller.value.isInitialized) {
      return Container(
        width: 220,
        height: 150,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: Colors.black12,
          borderRadius: BorderRadius.circular(13),
        ),
        child: const CircularProgressIndicator(),
      );
    }

    return ClipRRect(
      borderRadius: BorderRadius.circular(13),
      child: GestureDetector(
        onTap: () {
          setState(() {
            controller.value.isPlaying ? controller.pause() : controller.play();
          });
        },
        child: Stack(
          alignment: Alignment.center,
          children: [
            SizedBox(
              width: 220,
              height: 150,
              child: FittedBox(
                fit: BoxFit.cover,
                child: SizedBox(
                  width: controller.value.size.width,
                  height: controller.value.size.height,
                  child: VideoPlayer(controller),
                ),
              ),
            ),
            if (!controller.value.isPlaying)
              Container(
                width: 52,
                height: 52,
                decoration: const BoxDecoration(
                  color: AppColors.cyan,
                  shape: BoxShape.circle,
                  border: Border.fromBorderSide(
                    BorderSide(color: AppColors.ink, width: 2),
                  ),
                ),
                child: const Icon(Icons.play_arrow_rounded, color: AppColors.ink, size: 30),
              ),
          ],
        ),
      ),
    );
  }
}

class _ChatPatternPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = AppColors.ink.withOpacity(.055)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5;

    for (double y = 30; y < size.height; y += 90) {
      for (double x = 20; x < size.width; x += 90) {
        final r = Rect.fromCircle(center: Offset(x + (y % 180), y), radius: 8);
        canvas.drawRect(r, paint);
      }
    }

    final dotPaint = Paint()..color = AppColors.lavender.withOpacity(.16);
    for (double y = 65; y < size.height; y += 140) {
      for (double x = 50; x < size.width; x += 140) {
        canvas.drawCircle(Offset(x, y), 4, dotPaint);
      }
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

