class GroupChatScreen extends StatefulWidget {
  final String groupId;

  const GroupChatScreen({super.key, required this.groupId});

  @override
  State<GroupChatScreen> createState() => _GroupChatScreenState();
}

class _GroupChatScreenState extends State<GroupChatScreen> {
  final TextEditingController _controller = TextEditingController();
  final ScrollController _scroll = ScrollController();
  bool _sending = false;
  bool _joinCutoffLoading = true;
  DateTime? _joinCutoff;
  Map<String, dynamic>? _replyingTo;
  double _replySwipeDistance = 0;
  bool _replySwipeTriggered = false;
  final AudioRecorder _voiceRecorder = AudioRecorder();
  Timer? _voiceTimer;
  bool _recordingVoice = false;
  bool _uploadingVoice = false;
  int _voiceSeconds = 0;

  @override
  void initState() {
    super.initState();
    _loadGroupJoinCutoff();
  }

  Future<void> _loadGroupJoinCutoff() async {
    final uid = _currentUid();
    if (uid.isEmpty) {
      if (mounted) {
        setState(() => _joinCutoffLoading = false);
      }
      return;
    }

    try {
      final snapshot = await FirebaseFirestore.instance
          .collection('groups')
          .doc(widget.groupId)
          .collection('messages')
          .where('joinedUserId', isEqualTo: uid)
          .get();

      DateTime? latestJoin;
      for (final doc in snapshot.docs) {
        final data = doc.data();
        if (data['type'] != 'member_joined') continue;
        final createdAt = data['createdAt'];
        if (createdAt is Timestamp) {
          final value = createdAt.toDate();
          if (latestJoin == null || value.isAfter(latestJoin)) {
            latestJoin = value;
          }
        }
      }

      if (mounted) {
        setState(() {
          _joinCutoff = latestJoin;
          _joinCutoffLoading = false;
        });
      }
    } catch (_) {
      // If no join marker can be read, preserve the existing behaviour
      // rather than breaking the group chat.
      if (mounted) {
        setState(() {
          _joinCutoff = null;
          _joinCutoffLoading = false;
        });
      }
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    _scroll.dispose();
    _voiceTimer?.cancel();
    _voiceRecorder.dispose();
    super.dispose();
  }

  Future<void> _toggleGroupVoiceNote() async {
    if (_uploadingVoice) return;
    if (!_recordingVoice) {
      try {
        if (!await _voiceRecorder.hasPermission()) {
          if (mounted) showSnack(context, 'Microphone permission is required to record voice notes.');
          return;
        }
        final dir = await getTemporaryDirectory();
        final path = '${dir.path}/peergrid_group_voice_${DateTime.now().millisecondsSinceEpoch}.m4a';
        await _voiceRecorder.start(const RecordConfig(encoder: AudioEncoder.aacLc), path: path);
        if (!mounted) return;
        setState(() { _recordingVoice = true; _voiceSeconds = 0; });
        _voiceTimer?.cancel();
        _voiceTimer = Timer.periodic(const Duration(seconds: 1), (_) { if (mounted) setState(() => _voiceSeconds++); });
      } catch (e) { if (mounted) showSnack(context, 'Could not start recording: $e', color: Colors.red); }
      return;
    }
    _voiceTimer?.cancel();
    try {
      final path = await _voiceRecorder.stop();
      if (mounted) setState(() { _recordingVoice = false; _uploadingVoice = true; });
      if (path == null || !await File(path).exists() || await File(path).length() == 0) return;
      final duration = _voiceSeconds;
      final uid = _currentUid();
      final groupRef = FirebaseFirestore.instance.collection('groups').doc(widget.groupId);
      final groupSnap = await groupRef.get();
      if (!groupSnap.exists) throw StateError('Group could not be found.');
      final groupData = groupSnap.data() ?? <String, dynamic>{};
      final groupName = (groupData['name'] ?? 'Group chat').toString();
      final memberIds = List<String>.from((groupData['memberIds'] as List?)?.whereType<String>() ?? const <String>[]);
      if (!memberIds.contains(uid)) throw StateError('You are not a member of this group.');
      final storageRef = FirebaseStorage.instance.ref().child('group_voice_notes/${widget.groupId}/${DateTime.now().millisecondsSinceEpoch}_$uid.m4a');
      await storageRef.putFile(File(path), SettableMetadata(contentType: 'audio/mp4'));
      final url = await storageRef.getDownloadURL();
      final messageRef = groupRef.collection('messages').doc();
      final batch = FirebaseFirestore.instance.batch();
      batch.set(messageRef, {'senderId': uid, 'senderName': userName.value, 'senderProfileImage': userProfileImage.value, 'text': '', 'messageType': 'voice', 'mediaUrl': url, 'thumbnailUrl': '', 'voiceDurationSeconds': duration, 'createdAt': FieldValue.serverTimestamp()});
      batch.set(groupRef, {'lastMessage': '🎤 Voice message', 'lastMessageAt': FieldValue.serverTimestamp()}, SetOptions(merge: true));
      for (final memberId in memberIds) {
        if (memberId == uid) continue;
        await _createMessageNotification(recipientUid: memberId, type: 'group_message', title: '$groupName · ${userName.value}', body: 'Sent a voice message', relatedId: widget.groupId, batch: batch);
      }
      await batch.commit();
    } catch (e) { if (mounted) showSnack(context, 'Could not send voice note: $e', color: Colors.red, bottomMargin: 20); }
    finally { if (mounted) setState(() { _recordingVoice = false; _uploadingVoice = false; _voiceSeconds = 0; }); }
  }


  Future<void> _pickAndSendGroupFile() async {
    if (_sending) return;
    try {
      final result = await FilePicker.platform.pickFiles(
        type: FileType.any,
        allowMultiple: false,
        withData: false,
      );
      if (result == null || result.files.isEmpty) return;
      final picked = result.files.single;
      final path = picked.path;
      if (path == null || path.isEmpty) {
        throw StateError('This file could not be accessed. Please choose it again.');
      }
      final file = File(path);
      if (!await file.exists()) throw StateError('The selected file is no longer available.');
      final size = await file.length();
      if (size <= 0) throw StateError('The selected file is empty.');
      if (size > 25 * 1024 * 1024) {
        throw StateError('Please choose a file smaller than 25 MB.');
      }

      setState(() => _sending = true);
      final uid = _currentUid();
      final groupRef = FirebaseFirestore.instance.collection('groups').doc(widget.groupId);
      final groupSnap = await groupRef.get();
      if (!groupSnap.exists) throw StateError('Group could not be found.');
      final groupData = groupSnap.data() ?? <String, dynamic>{};
      final groupName = (groupData['name'] ?? 'Group chat').toString();
      final memberIds = List<String>.from(
        (groupData['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
      );
      if (!memberIds.contains(uid)) throw StateError('You are not a member of this group.');

      final safeName = picked.name.replaceAll(RegExp(r'[/\\]'), '_');
      final extension = safeName.contains('.')
          ? safeName.split('.').last.toLowerCase()
          : '';
      final storagePath =
          'groups/${widget.groupId}/files/${DateTime.now().millisecondsSinceEpoch}_${uid}_$safeName';
      final ref = FirebaseStorage.instance.ref().child(storagePath);
      await ref.putFile(file, SettableMetadata(contentType: 'application/octet-stream'));
      final url = await ref.getDownloadURL();

      final messageRef = groupRef.collection('messages').doc();
      final batch = FirebaseFirestore.instance.batch();
      batch.set(messageRef, {
        'senderId': uid,
        'senderName': userName.value,
        'senderProfileImage': userProfileImage.value,
        'text': '',
        'messageType': 'file',
        'mediaUrl': url,
        'fileName': safeName,
        'fileSize': size,
        'fileExtension': extension,
        'storagePath': storagePath,
        'createdAt': FieldValue.serverTimestamp(),
      });
      batch.set(groupRef, {
        'lastMessage': '📎 $safeName',
        'lastMessageAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      for (final memberId in memberIds) {
        if (memberId == uid) continue;
        await _createMessageNotification(
          recipientUid: memberId,
          type: 'group_message',
          title: '$groupName · ${userName.value}',
          body: 'Shared a file: $safeName',
          relatedId: widget.groupId,
          batch: batch,
        );
      }
      await batch.commit();
    } catch (e) {
      if (mounted) showSnack(context, 'Could not send file: $e',
          color: Colors.red, bottomMargin: 20);
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _sendGroupSticker(String stickerUrl) async {
    final uid = _currentUid();
    if (uid.isEmpty || _sending) return;
    setState(() => _sending = true);
    try {
      final groupRef = FirebaseFirestore.instance.collection('groups').doc(widget.groupId);
      final groupSnap = await groupRef.get();
      if (!groupSnap.exists) throw StateError('Group could not be found.');
      final groupData = groupSnap.data() ?? <String, dynamic>{};
      final groupName = (groupData['name'] ?? 'Group chat').toString();
      final memberIds = List<String>.from(
        (groupData['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
      );
      if (!memberIds.contains(uid)) throw StateError('You are not a member of this group.');
      final messageRef = groupRef.collection('messages').doc();
      final batch = FirebaseFirestore.instance.batch();
      batch.set(messageRef, {
        'senderId': uid,
        'senderName': userName.value,
        'senderProfileImage': userProfileImage.value,
        'text': '',
        'messageType': 'sticker',
        'sticker': stickerUrl,
        'createdAt': FieldValue.serverTimestamp(),
      });
      batch.set(groupRef, {
        'lastMessage': 'Sticker',
        'lastMessageAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      for (final memberId in memberIds) {
        if (memberId == uid) continue;
        await _createMessageNotification(
          recipientUid: memberId,
          type: 'group_message',
          title: '$groupName · ${userName.value}',
          body: 'Sent a sticker',
          relatedId: widget.groupId,
          batch: batch,
        );
      }
      await batch.commit();
    } catch (e) {
      if (mounted) showSnack(context, 'Could not send sticker: $e', color: Colors.red, bottomMargin: 20);
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _pickGroupSticker() async {
    final sticker = await _showCustomCommentStickerPicker(context);
    if (sticker != null && mounted) await _sendGroupSticker(sticker.url);
  }

  void _setGroupReply(Map<String, dynamic> data, String id) {
    setState(() {
      _replyingTo = <String, dynamic>{
        'id': id,
        'text': data['text']?.toString() ?? '',
        'senderName': data['senderName']?.toString() ?? 'Student',
        'messageType': data['messageType']?.toString() ?? 'text',
        'sticker': data['sticker']?.toString() ?? '',
      };
    });
    FocusScope.of(context).requestFocus(FocusNode());
  }

  void _clearGroupReply() {
    if (mounted) setState(() => _replyingTo = null);
  }

  Widget _groupReplyPreview(Map<String, dynamic> data, {bool composer = false}) {
    final sender = (data['replyToSenderName'] ?? data['senderName'] ?? '').toString();
    final text = (data['replyToText'] ?? data['text'] ?? '').toString();
    final sticker = (data['sticker'] ?? '').toString();
    final display = text.isNotEmpty ? text : (sticker.isNotEmpty ? '$sticker Sticker' : 'Media');
    return Container(
      width: double.infinity,
      margin: EdgeInsets.only(bottom: composer ? 8 : 6),
      padding: const EdgeInsets.fromLTRB(10, 7, 10, 7),
      decoration: BoxDecoration(
        color: composer ? AppColors.softBlue : Colors.black.withOpacity(.07),
        borderRadius: BorderRadius.circular(12),
        border: const Border(left: BorderSide(color: AppColors.blue, width: 4)),
      ),
      child: Text(
        sender.isEmpty ? display : '$sender · $display',
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
        style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800),
      ),
    );
  }

  Future<void> _send() async {
    final uid = _currentUid();
    final text = _controller.text.trim();
    if (uid.isEmpty || text.isEmpty || _sending) return;
    final reply = _replyingTo;
    setState(() => _sending = true);
    _controller.clear();
    _clearGroupReply();
    try {
      final groupRef = FirebaseFirestore.instance.collection('groups').doc(widget.groupId);
      final groupSnap = await groupRef.get();
      final groupData = groupSnap.data() ?? <String, dynamic>{};
      final groupName = (groupData['name'] ?? 'Group chat').toString();
      final memberIds = List<String>.from(
        (groupData['memberIds'] as List?)?.whereType<String>() ?? const <String>[],
      );

      final messageRef = groupRef.collection('messages').doc();
      final batch = FirebaseFirestore.instance.batch();

      batch.set(messageRef, {
        'senderId': uid,
        'senderName': userName.value,
        'senderProfileImage': userProfileImage.value,
        'text': text,
        'replyToId': reply?['id']?.toString() ?? '',
        'replyToText': reply?['text']?.toString() ?? '',
        'replyToSenderName': reply?['senderName']?.toString() ?? '',
        'createdAt': FieldValue.serverTimestamp(),
      });

      batch.set(groupRef, {
        'lastMessage': text,
        'lastMessageAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      for (final memberId in memberIds) {
        await _createMessageNotification(
          recipientUid: memberId,
          type: 'group_message',
          title: '$groupName · ${userName.value}',
          body: text,
          relatedId: widget.groupId,
          batch: batch,
        );
      }

      await batch.commit();
    } catch (e) {
      if (mounted) {
        _controller.text = text;
        showSnack(context, 'Could not send message: $e', color: Colors.red, bottomMargin: 20);
      }
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    final groupRef = FirebaseFirestore.instance.collection('groups').doc(widget.groupId);
    final messagesRef = groupRef.collection('messages');

    final Stream<QuerySnapshot<Map<String, dynamic>>> messagesStream =
    _joinCutoffLoading
        ? const Stream<QuerySnapshot<Map<String, dynamic>>>.empty()
        : (_joinCutoff == null
        ? messagesRef
        .orderBy('createdAt', descending: false)
        .limitToLast(150)
        .snapshots()
        : messagesRef
        .where(
      'createdAt',
      isGreaterThanOrEqualTo:
      Timestamp.fromDate(_joinCutoff!),
    )
        .orderBy('createdAt', descending: false)
        .limitToLast(150)
        .snapshots());

    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFD),
      appBar: AppBar(
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
        elevation: 0,
        title: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
          stream: groupRef.snapshots(),
          builder: (context, snapshot) {
            final data = snapshot.data?.data() ?? <String, dynamic>{};
            final memberIds = (data['memberIds'] as List?)?.whereType<String>().toList() ?? <String>[];
            return Row(
              children: [
                CircleAvatar(
                  radius: 19,
                  backgroundColor: Colors.white24,
                  backgroundImage: (data['photoUrl'] ?? data['imageUrl'] ?? '').toString().trim().isNotEmpty
                      ? NetworkImage((data['photoUrl'] ?? data['imageUrl']).toString())
                      : null,
                  child: ((data['photoUrl'] ?? data['imageUrl'] ?? '').toString().trim().isEmpty)
                      ? const Icon(Icons.groups_rounded, color: Colors.white, size: 21)
                      : null,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text((data['name'] ?? 'Group chat').toString(), maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w900)),
                      Text('${memberIds.isNotEmpty ? memberIds.length : (data['memberCount'] ?? 0)} members', style: const TextStyle(fontSize: 11)),
                    ],
                  ),
                ),
              ],
            );
          },
        ),
        actions: [
          IconButton(
            tooltip: 'Group details',
            icon: const Icon(Icons.info_outline_rounded),
            onPressed: () => pushPage(context, GroupChatDetailsScreen(groupId: widget.groupId)),
          ),
        ],
      ),
      body: Column(
        children: [
          Expanded(
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: messagesStream,
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return EmptyState(icon: Icons.error_outline_rounded, title: 'Could not load group messages', subtitle: snapshot.error.toString());
                }
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                final docs = snapshot.data!.docs
                    .where((doc) => doc.data()['type'] != 'member_joined')
                    .toList();

                if (_joinCutoffLoading) {
                  return const Center(child: CircularProgressIndicator());
                }

                if (docs.isEmpty) {
                  return const EmptyState(
                    icon: Icons.groups_rounded,
                    title: 'Group chat is ready',
                    subtitle: 'Be the first to send a message.',
                  );
                }
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (_scroll.hasClients) _scroll.jumpTo(_scroll.position.maxScrollExtent);
                });
                return ListView.builder(
                  controller: _scroll,
                  padding: const EdgeInsets.fromLTRB(14, 16, 14, 16),
                  itemCount: docs.length,
                  itemBuilder: (context, index) {
                    final data = docs[index].data();
                    final mine = data['senderId'] == uid;
                    final senderName = (data['senderName'] ?? 'Student').toString();
                    final senderImage = (data['senderProfileImage'] ?? '').toString();
                    return GestureDetector(
                      onLongPress: () => _FirestoreReactionBar.showPickerFor(context, messagesRef.doc(docs[index].id)),
                      onHorizontalDragStart: (_) {
                        _replySwipeDistance = 0;
                        _replySwipeTriggered = false;
                      },
                      onHorizontalDragUpdate: (details) {
                        if (_replySwipeTriggered) return;
                        if (details.delta.dx > 0) {
                          _replySwipeDistance += details.delta.dx;
                          if (_replySwipeDistance >= 55) {
                            _replySwipeTriggered = true;
                            _setGroupReply(data, docs[index].id);
                          }
                        } else {
                          _replySwipeDistance = 0;
                        }
                      },
                      onHorizontalDragEnd: (_) {
                        _replySwipeDistance = 0;
                        _replySwipeTriggered = false;
                      },
                      child: Align(
                        alignment: mine ? Alignment.centerRight : Alignment.centerLeft,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.end,
                          children: mine
                              ? [
                            Flexible(
                              child: Container(
                                constraints: BoxConstraints(maxWidth: MediaQuery.of(context).size.width * .72),
                                margin: const EdgeInsets.only(bottom: 8),
                                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                                decoration: BoxDecoration(
                                  color: mine ? AppColors.blue : Colors.white,
                                  borderRadius: BorderRadius.circular(18),
                                  border: Border.all(color: mine ? AppColors.blue : Colors.black12),
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.end,
                                  children: [
                                    if ((data['replyToText'] ?? '').toString().isNotEmpty || (data['replyToSenderName'] ?? '').toString().isNotEmpty)
                                      _groupReplyPreview(data),
                                    if ((data['messageType'] ?? '').toString() == 'sticker' && ((data['sticker'] ?? '').toString().startsWith('http')))
                                      Image.network((data['sticker']).toString(), width: 150, height: 150, fit: BoxFit.contain,
                                          errorBuilder: (_, __, ___) => const Icon(Icons.broken_image_outlined, color: Colors.white))
                                    else if ((data['messageType'] ?? '').toString() == 'voice' && (data['mediaUrl'] ?? '').toString().isNotEmpty)
                                      _VoiceNoteBubble(url: (data['mediaUrl']).toString(), durationSeconds: int.tryParse((data['voiceDurationSeconds'] ?? 0).toString()) ?? 0, mine: true)
                                    else if ((data['messageType'] ?? '').toString() == 'file' && (data['mediaUrl'] ?? '').toString().isNotEmpty)
                                        _SharedFileMessage(fileName: (data['fileName'] ?? 'Shared file').toString(), fileSize: int.tryParse((data['fileSize'] ?? 0).toString()) ?? 0, url: (data['mediaUrl']).toString(), mine: true)
                                      else
                                        Text((data['text'] ?? '').toString(), style: const TextStyle(color: Colors.white, fontSize: 15, height: 1.3)),
                                    const SizedBox(height: 4),
                                    Text(_chatDisplayTime(data['createdAt']), style: const TextStyle(color: Colors.white70, fontSize: 9)),
                                    _FirestoreReactionBar(document: messagesRef.doc(docs[index].id)),
                                  ],
                                ),
                              ),
                            ),
                            ProfileAvatar(
                              imageUrl: userProfileImage.value,
                              name: userName.value,
                              radius: 15,
                            ),
                          ]
                              : [
                            ProfileAvatar(
                              imageUrl: senderImage,
                              name: senderName,
                              radius: 15,
                            ),
                            const SizedBox(width: 6),
                            Flexible(
                              child: Container(
                                constraints: BoxConstraints(maxWidth: MediaQuery.of(context).size.width * .72),
                                margin: const EdgeInsets.only(bottom: 8),
                                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(18),
                                  border: Border.all(color: Colors.black12),
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    if ((data['replyToText'] ?? '').toString().isNotEmpty || (data['replyToSenderName'] ?? '').toString().isNotEmpty)
                                      _groupReplyPreview(data),
                                    Text(senderName, style: const TextStyle(color: AppColors.blue, fontSize: 11, fontWeight: FontWeight.w900)),
                                    const SizedBox(height: 2),
                                    if ((data['messageType'] ?? '').toString() == 'sticker' && ((data['sticker'] ?? '').toString().startsWith('http')))
                                      Image.network((data['sticker']).toString(), width: 150, height: 150, fit: BoxFit.contain,
                                          errorBuilder: (_, __, ___) => const Icon(Icons.broken_image_outlined))
                                    else if ((data['messageType'] ?? '').toString() == 'voice' && (data['mediaUrl'] ?? '').toString().isNotEmpty)
                                      _VoiceNoteBubble(url: (data['mediaUrl']).toString(), durationSeconds: int.tryParse((data['voiceDurationSeconds'] ?? 0).toString()) ?? 0, mine: false)
                                    else if ((data['messageType'] ?? '').toString() == 'file' && (data['mediaUrl'] ?? '').toString().isNotEmpty)
                                        _SharedFileMessage(fileName: (data['fileName'] ?? 'Shared file').toString(), fileSize: int.tryParse((data['fileSize'] ?? 0).toString()) ?? 0, url: (data['mediaUrl']).toString(), mine: false)
                                      else
                                        Text((data['text'] ?? '').toString(), style: const TextStyle(color: Colors.black, fontSize: 15, height: 1.3)),
                                    const SizedBox(height: 4),
                                    Text(_chatDisplayTime(data['createdAt']), style: const TextStyle(color: AppColors.muted, fontSize: 9)),
                                    _FirestoreReactionBar(document: messagesRef.doc(docs[index].id)),
                                  ],
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
          if (_replyingTo != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 0, 12, 4),
              child: Row(
                children: [
                  Expanded(child: _groupReplyPreview(_replyingTo!, composer: true)),
                  IconButton(onPressed: _clearGroupReply, icon: const Icon(Icons.close_rounded)),
                ],
              ),
            ),
          if (_recordingVoice || _uploadingVoice)
            Padding(padding: const EdgeInsets.fromLTRB(16, 4, 16, 4), child: Row(children: [Icon(_uploadingVoice ? Icons.cloud_upload_rounded : Icons.fiber_manual_record, color: Colors.red, size: 16), const SizedBox(width: 8), Text(_uploadingVoice ? 'Sending voice note…' : 'Recording voice note · ${_voiceSeconds}s', style: const TextStyle(fontWeight: FontWeight.w800))])),
          SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(10, 8, 10, 10),
              child: Row(
                children: [
                  IconButton(
                    tooltip: 'Send a file',
                    onPressed: _sending ? null : _pickAndSendGroupFile,
                    icon: const Icon(Icons.attach_file_rounded, color: AppColors.blue),
                  ),
                  IconButton(
                    tooltip: 'My stickers',
                    onPressed: _sending ? null : _pickGroupSticker,
                    icon: const Icon(Icons.sticky_note_2_rounded, color: AppColors.blue),
                  ),
                  Expanded(
                    child: TextField(
                      controller: _controller,
                      textInputAction: TextInputAction.send,
                      onSubmitted: (_) async {
                        final snap = await groupRef.get();
                        final name = (snap.data()?['name'] ?? 'Group chat').toString();
                        await _send();
                      },
                      minLines: 1,
                      maxLines: 5,
                      decoration: InputDecoration(
                        hintText: 'Message the group...',
                        filled: true,
                        fillColor: Colors.white,
                        contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                        border: OutlineInputBorder(borderRadius: BorderRadius.circular(28), borderSide: BorderSide.none),
                        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(28), borderSide: const BorderSide(color: Colors.black12)),
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  IconButton(
                    tooltip: _recordingVoice ? 'Stop and send voice note' : 'Record voice note',
                    onPressed: _sending || _uploadingVoice ? null : _toggleGroupVoiceNote,
                    icon: Icon(_uploadingVoice ? Icons.hourglass_top_rounded : (_recordingVoice ? Icons.stop_circle_rounded : Icons.mic_rounded), color: _recordingVoice ? Colors.red : AppColors.blue, size: 28),
                  ),
                  CircleAvatar(
                    radius: 25,
                    backgroundColor: AppColors.blue,
                    child: IconButton(
                      onPressed: _sending
                          ? null
                          : () async {
                        final snap = await groupRef.get();
                        final name = (snap.data()?['name'] ?? 'Group chat').toString();
                        await _send();
                      },
                      icon: _sending ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white)) : const Icon(Icons.send_rounded, color: Colors.white),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

