  late final List<Review> _reviews = [
    Review(
      name: 'Arjun S',
      daysAgo: '3 days ago',
      text:
      'Good campus environment and active student community. Lots of opportunities for growth.',
      stars: 5,
      likes: 8,
      comments: 9,
    ),
    Review(
      name: 'Meera M',
      daysAgo: '5 days ago',
      text:
      'Great infrastructure and campus life. Placement opportunities are good.',
      stars: 4,
      likes: 28,
      comments: 31,
    ),
  ];

  void _writeReview() {
    final controller = TextEditingController();
    int stars = 5;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(32)),
      ),
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (context, setSheetState) {
            return Padding(
              padding: EdgeInsets.fromLTRB(
                20,
                20,
                20,
                20 + MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SafeArea(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Text(
                      'Write a review',
                      style:
                      TextStyle(fontSize: 22, fontWeight: FontWeight.w900),
                    ),
                    const SizedBox(height: 14),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        for (int i = 1; i <= 5; i++)
                          GestureDetector(
                            onTap: () => setSheetState(() => stars = i),
                            child: AnimatedScale(
                              scale: i <= stars ? 1.1 : 1,
                              duration: const Duration(milliseconds: 150),
                              child: Icon(
                                i <= stars
                                    ? Icons.star_rounded
                                    : Icons.star_outline_rounded,
                                color: AppColors.amber,
                                size: 42,
                              ),
                            ),
                          ),
                      ],
                    ),
                    const SizedBox(height: 14),
                    TextField(
                      controller: controller,
                      minLines: 3,
                      maxLines: 5,
                      decoration: InputDecoration(
                        hintText: 'Share your experience with this college...',
                        filled: true,
                        fillColor: AppColors.softBlue,
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(24),
                          borderSide: BorderSide.none,
                        ),
                      ),
                    ),
                    const SizedBox(height: 16),
                    PillButton(
                      label: 'Submit review',
                      icon: Icons.send_rounded,
                      onTap: () {
                        final text = controller.text.trim();
                        if (text.isEmpty) return;
                        setState(() {
                          _reviews.insert(
                            0,
                            Review(
                              name: userName.value,
                              daysAgo: 'Just now',
                              text: text,
                              stars: stars,
                              likes: 0,
                              comments: 0,
                            ),
                          );
                        });
                        Navigator.pop(sheetContext);
                      },
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

