              StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: FirebaseFirestore.instance
                    .collection('colleges')
                    .doc(firestoreCollegeIdForStudentCollege(c.id))
                    .collection('posts')
                    .snapshots(),
                builder: (context, snapshot) {
                  final docs = [...(snapshot.data?.docs ?? <QueryDocumentSnapshot<Map<String, dynamic>>>[])];
                  docs.sort((a, b) {
                    final aValue = a.data()['createdAt'];
                    final bValue = b.data()['createdAt'];
                    final aDate = aValue is Timestamp ? aValue.toDate() : DateTime(2000);
                    final bDate = bValue is Timestamp ? bValue.toDate() : DateTime(2000);
                    return bDate.compareTo(aDate);
                  });

                  final latest = docs.take(2).toList();

                  return Container(
