class GamesHubScreen extends StatelessWidget {
  const GamesHubScreen({super.key});

  Future<void> _createRoom(BuildContext context, String game) async {
    final uid = _currentUid();
    if (uid.isEmpty) {
      showSnack(context, 'Sign in to play with friends.');
      return;
    }
    try {
      final ref = FirebaseFirestore.instance.collection('gameRooms').doc();
      await ref.set({
        'game': game,
        'hostUid': uid,
        'players': [uid],
        'invitedUids': <String>[],
        'status': 'waiting',
        'board': List<String>.filled(9, ''),
        'turnUid': uid,
        'choices': <String, dynamic>{},
        'scores': {uid: 0},
        'round': 1,
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      if (!context.mounted) return;
      pushPage(context, GameRoomScreen(roomId: ref.id));
    } catch (e) {
      if (context.mounted) showSnack(context, 'Could not create game room. Check Firestore rules.');
    }
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(title: const Text('Games', style: TextStyle(fontWeight: FontWeight.w900))),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 32),
        children: [
          Container(
            padding: const EdgeInsets.all(16),
            decoration: neoDeco(color: AppColors.softBlue, radius: 16),
            child: const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('A little friendly competition', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900)),
              SizedBox(height: 5),
              Text('Create a room, invite a student, and play live together.', style: TextStyle(fontWeight: FontWeight.w600, height: 1.35)),
            ]),
          ),
          const SizedBox(height: 20),
          _gameChoice(context, game: 'tictactoe', title: 'Tic-Tac-Toe', subtitle: 'Classic X vs O · Two players', icon: Icons.grid_3x3_rounded, color: AppColors.cyan, onTap: () => _createRoom(context, 'tictactoe')),
          const SizedBox(height: 12),
          _gameChoice(context, game: 'rps', title: 'Rock Paper Scissors', subtitle: 'Choose secretly, reveal together', icon: Icons.front_hand_rounded, color: const Color(0xFFFFD6C7), onTap: () => _createRoom(context, 'rps')),
          const SizedBox(height: 24),
          const Text('GAME INVITATIONS', style: TextStyle(fontSize: 13, letterSpacing: 1.1, fontWeight: FontWeight.w900)),
          const SizedBox(height: 10),
          if (uid.isEmpty)
            const Text('Sign in to receive game invitations.')
          else
            StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance.collection('gameInvites').where('recipientId', isEqualTo: uid).where('status', isEqualTo: 'pending').snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) return const Text('Could not load invitations. Check your Firestore rules.');
                if (snapshot.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator());
                final docs = snapshot.data?.docs ?? [];
                if (docs.isEmpty) return Container(padding: const EdgeInsets.all(16), decoration: neoDeco(color: Colors.white, radius: 12, shadow: false), child: const Text('No pending invitations yet.', style: TextStyle(color: AppColors.muted, fontWeight: FontWeight.w700)));
                return Column(children: docs.map((doc) {
                  final data = doc.data();
                  final game = (data['game'] ?? '').toString();
                  final hostName = (data['senderName'] ?? 'A student').toString();
                  final roomId = (data['roomId'] ?? '').toString();
                  return Container(
                    margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(12),
                    decoration: neoDeco(color: Colors.white, radius: 12, shadow: false),
                    child: Row(children: [
                      const Icon(Icons.mail_rounded, size: 28), const SizedBox(width: 10),
                      Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('$hostName invited you', style: const TextStyle(fontWeight: FontWeight.w900)), Text(game == 'tictactoe' ? 'Tic-Tac-Toe' : 'Rock Paper Scissors', style: const TextStyle(color: AppColors.muted, fontSize: 12))])),
                      FilledButton(onPressed: roomId.isEmpty ? null : () async {
                        try {
                          final roomRef = FirebaseFirestore.instance.collection('gameRooms').doc(roomId);
                          await FirebaseFirestore.instance.runTransaction((tx) async {
                            final room = await tx.get(roomRef);
                            if (!room.exists) throw StateError('This room no longer exists.');
                            final roomData = room.data() ?? <String, dynamic>{};
                            final players = List<String>.from((roomData['players'] as List?)?.whereType<String>() ?? const <String>[]);
                            if (!players.contains(uid)) {
                              if (players.length >= 2) throw StateError('This room is already full.');
                              players.add(uid);
                            }
                            tx.update(roomRef, {'players': players, 'status': 'playing', 'updatedAt': FieldValue.serverTimestamp()});
                            tx.update(doc.reference, {'status': 'accepted', 'respondedAt': FieldValue.serverTimestamp()});
                          });
                          if (!context.mounted) return;
                          pushPage(context, GameRoomScreen(roomId: roomId));
                        } catch (e) {
                          if (context.mounted) showSnack(context, 'Could not join room. It may be full or expired.');
                        }
                      }, child: const Text('Join')),
                    ]),
                  );
                }).toList());
              },
            ),
        ],
      ),
    );
  }

  Widget _gameChoice(BuildContext context, {required String game, required String title, required String subtitle, required IconData icon, required Color color, required VoidCallback onTap}) {
    return Pressable(shadow: true, radius: 14, onTap: onTap, child: Container(
      padding: const EdgeInsets.all(15), decoration: neoDeco(color: Colors.white, radius: 14, shadow: false),
      child: Row(children: [Container(width: 54, height: 54, decoration: neoDeco(color: color, radius: 12, shadow: false), child: Icon(icon, size: 29)), const SizedBox(width: 13), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900)), const SizedBox(height: 4), Text(subtitle, style: const TextStyle(color: AppColors.muted, fontSize: 12, fontWeight: FontWeight.w600))])), const Icon(Icons.add_circle_outline_rounded, size: 27)]),
    ));
  }
}

class GameRoomScreen extends StatefulWidget {
  final String roomId;
  const GameRoomScreen({super.key, required this.roomId});
  @override
  State<GameRoomScreen> createState() => _GameRoomScreenState();
}

class _GameRoomScreenState extends State<GameRoomScreen> {
  bool _busy = false;

  Future<void> _inviteStudent(Map<String, dynamic> roomData) async {
    final uid = _currentUid();
    if (uid.isEmpty) return;
    final players = List<String>.from((roomData['players'] as List?)?.whereType<String>() ?? const <String>[]);
    final invited = List<String>.from((roomData['invitedUids'] as List?)?.whereType<String>() ?? const <String>[]);
    if (players.length >= 2) { showSnack(context, 'This room already has two players.'); return; }
    final search = TextEditingController();
    String query = '';
    String? sendingUid;
    await showModalBottomSheet<void>(
      context: context, isScrollControlled: true, builder: (sheetContext) => StatefulBuilder(builder: (sheetContext, setSheetState) => Padding(
      padding: EdgeInsets.fromLTRB(18, 18, 18, MediaQuery.of(sheetContext).viewInsets.bottom + 20),
      child: SizedBox(height: MediaQuery.of(sheetContext).size.height * .68, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Text('Invite a student', style: TextStyle(fontSize: 21, fontWeight: FontWeight.w900)), const SizedBox(height: 12),
        TextField(controller: search, onChanged: (v) => setSheetState(() => query = v.trim().toLowerCase()), decoration: const InputDecoration(prefixIcon: Icon(Icons.search_rounded), hintText: 'Search students by name or college', border: OutlineInputBorder())),
        const SizedBox(height: 12),
        Expanded(child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(stream: FirebaseFirestore.instance.collection('users').limit(150).snapshots(), builder: (context, snapshot) {
          if (snapshot.hasError) return const Center(child: Text('Could not load students.'));
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());
          final docs = snapshot.data!.docs.where((doc) {
            if (doc.id == uid || players.contains(doc.id) || invited.contains(doc.id)) return false;
            final data = doc.data();
            final name = (data['name'] ?? data['username'] ?? 'Student').toString().toLowerCase();
            final college = (data['college'] ?? '').toString().toLowerCase();
            return query.isEmpty || name.contains(query) || college.contains(query);
          }).toList();
          if (docs.isEmpty) return const Center(child: Text('No students found.'));
          return ListView.builder(itemCount: docs.length, itemBuilder: (_, i) {
            final doc = docs[i]; final data = doc.data();
            final name = (data['name'] ?? data['username'] ?? 'Student').toString();
            return ListTile(leading: ProfileAvatar(imageUrl: (data['profileImage'] ?? '').toString(), name: name, radius: 22), title: Text(name, style: const TextStyle(fontWeight: FontWeight.w800)), subtitle: Text((data['college'] ?? '').toString()), trailing: sendingUid == doc.id ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.send_rounded), onTap: sendingUid != null ? null : () async {
              setSheetState(() => sendingUid = doc.id);
              try {
                final roomRef = FirebaseFirestore.instance.collection('gameRooms').doc(widget.roomId);
                final inviteRef = FirebaseFirestore.instance.collection('gameInvites').doc();
                await inviteRef.set({'roomId': widget.roomId, 'game': roomData['game'], 'senderId': uid, 'senderName': userName.value, 'recipientId': doc.id, 'status': 'pending', 'createdAt': FieldValue.serverTimestamp()});
                await roomRef.update({'invitedUids': FieldValue.arrayUnion([doc.id]), 'updatedAt': FieldValue.serverTimestamp()});
                if (sheetContext.mounted) Navigator.pop(sheetContext);
                if (mounted) showSnack(context, 'Invitation sent to $name.');
              } catch (_) { setSheetState(() => sendingUid = null); if (mounted) showSnack(context, 'Could not send invitation. Check Firestore rules.'); }
            });
          });
        })),
      ])),
    )),
    );
    search.dispose();
  }

  Future<void> _playTicTacToe(String roomId, Map<String, dynamic> data, int cell) async {
    final uid = _currentUid();
    if (_busy || uid.isEmpty) return;
    final players = List<String>.from((data['players'] as List?)?.whereType<String>() ?? const <String>[]);
    final board = List<String>.from((data['board'] as List?)?.map((e) => e.toString()) ?? List<String>.filled(9, ''));
    if (players.length != 2 || board[cell].isNotEmpty || data['turnUid'] != uid || data['status'] == 'finished') return;
    setState(() => _busy = true);
    try {
      final roomRef = FirebaseFirestore.instance.collection('gameRooms').doc(roomId);
      await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(roomRef); if (!snap.exists) throw StateError('Room missing');
        final d = snap.data() ?? <String, dynamic>{};
        final b = List<String>.from((d['board'] as List?)?.map((e) => e.toString()) ?? List<String>.filled(9, ''));
        final ps = List<String>.from((d['players'] as List?)?.whereType<String>() ?? const <String>[]);
        if (ps.length != 2 || d['turnUid'] != uid || b[cell].isNotEmpty || d['status'] == 'finished') return;
        b[cell] = ps[0] == uid ? 'X' : 'O';
        const wins = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
        String winner = '';
        for (final line in wins) { if (b[line[0]].isNotEmpty && b[line[0]] == b[line[1]] && b[line[1]] == b[line[2]]) { winner = b[line[0]]; break; } }
        final draw = winner.isEmpty && b.every((v) => v.isNotEmpty);
        final updates = <String, dynamic>{'board': b, 'turnUid': ps.firstWhere((p) => p != uid), 'updatedAt': FieldValue.serverTimestamp()};
        if (winner.isNotEmpty || draw) { updates['status'] = 'finished'; updates['winnerUid'] = winner.isEmpty ? '' : (winner == 'X' ? ps[0] : ps[1]); updates['result'] = draw ? 'draw' : 'win'; }
        tx.update(roomRef, updates);
      });
    } catch (_) { if (mounted) showSnack(context, 'Could not submit move.'); }
    finally { if (mounted) setState(() => _busy = false); }
  }

  Future<void> _chooseRps(String roomId, Map<String, dynamic> data, String choice) async {
    final uid = _currentUid(); if (_busy || uid.isEmpty) return;
    final players = List<String>.from((data['players'] as List?)?.whereType<String>() ?? const <String>[]);
    if (players.length != 2 || data['status'] == 'finished') return;
    setState(() => _busy = true);
    try {
      final ref = FirebaseFirestore.instance.collection('gameRooms').doc(roomId);
      await FirebaseFirestore.instance.runTransaction((tx) async {
        final snap = await tx.get(ref); if (!snap.exists) throw StateError('Room missing');
        final d = snap.data() ?? <String, dynamic>{};
        final ps = List<String>.from((d['players'] as List?)?.whereType<String>() ?? const <String>[]);
        if (!ps.contains(uid) || ps.length != 2 || d['status'] == 'finished') return;
        final choices = Map<String, dynamic>.from((d['choices'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{});
        choices[uid] = choice;
        final updates = <String, dynamic>{'choices': choices, 'updatedAt': FieldValue.serverTimestamp()};
        if (ps.every((p) => choices.containsKey(p))) {
          final a = choices[ps[0]].toString(); final b = choices[ps[1]].toString();
          final winner = a == b ? '' : ((a == 'rock' && b == 'scissors') || (a == 'paper' && b == 'rock') || (a == 'scissors' && b == 'paper') ? ps[0] : ps[1]);
          updates['winnerUid'] = winner; updates['result'] = winner.isEmpty ? 'draw' : 'win'; updates['status'] = 'finished';
        }
        tx.update(ref, updates);
      });
    } catch (_) { if (mounted) showSnack(context, 'Could not submit choice.'); }
    finally { if (mounted) setState(() => _busy = false); }
  }

  Future<void> _playAgain(String roomId, Map<String, dynamic> data) async {
    final uid = _currentUid(); final game = (data['game'] ?? '').toString();
    try {
      await FirebaseFirestore.instance.collection('gameRooms').doc(roomId).update({
        'status': 'playing', 'board': List<String>.filled(9, ''), 'turnUid': (data['players'] as List).first,
        'choices': <String, dynamic>{}, 'winnerUid': FieldValue.delete(), 'result': FieldValue.delete(), 'round': FieldValue.increment(1), 'updatedAt': FieldValue.serverTimestamp(),
      });
    } catch (_) { if (mounted) showSnack(context, 'Could not restart the game.'); }
  }

  @override
  Widget build(BuildContext context) {
    final uid = _currentUid();
    return Scaffold(
      backgroundColor: AppColors.cream,
      appBar: AppBar(title: const Text('Game room', style: TextStyle(fontWeight: FontWeight.w900))),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance.collection('gameRooms').doc(widget.roomId).snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) return const Center(child: Text('Could not load room. Check Firestore rules.'));
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());
          if (!snapshot.data!.exists) return const Center(child: Text('This game room no longer exists.'));
          final data = snapshot.data!.data() ?? <String, dynamic>{};
          final game = (data['game'] ?? 'tictactoe').toString();
          final players = List<String>.from((data['players'] as List?)?.whereType<String>() ?? const <String>[]);
          final waiting = players.length < 2;
          final board = List<String>.from((data['board'] as List?)?.map((e) => e.toString()) ?? List<String>.filled(9, ''));
          final choices = Map<String, dynamic>.from((data['choices'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{});
          final finished = data['status'] == 'finished';
          final winnerUid = (data['winnerUid'] ?? '').toString();
          final resultText = winnerUid.isEmpty ? (finished ? 'It’s a draw!' : '') : (winnerUid == uid ? 'You won!' : 'Your friend won!');
          return ListView(padding: const EdgeInsets.all(16), children: [
            Container(
              padding: const EdgeInsets.all(14),
              decoration: neoDeco(color: AppColors.softBlue, radius: 14),
              child: Row(
                children: [
                  const Icon(Icons.meeting_room_rounded, size: 28),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          game == 'tictactoe' ? 'Tic-Tac-Toe' : 'Rock Paper Scissors',
                          style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
                        ),
                        Text(
                          'Room code: ${widget.roomId.substring(0, widget.roomId.length > 6 ? 6 : widget.roomId.length).toUpperCase()}',
                          style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700),
                        ),
                      ],
                    ),
                  ),
                  if (waiting && data['hostUid'] == uid)
                    IconButton(
                      onPressed: () => _inviteStudent(data),
                      icon: const Icon(Icons.person_add_alt_1_rounded),
                      tooltip: 'Invite a student',
                    ),
                ],
              ),
            ),
            const SizedBox(height: 12),
            if (waiting) Container(padding: const EdgeInsets.all(16), decoration: neoDeco(color: Colors.white, radius: 12, shadow: false), child: Column(children: [const Icon(Icons.hourglass_top_rounded, size: 35), const SizedBox(height: 8), const Text('Waiting for your friend', style: TextStyle(fontWeight: FontWeight.w900, fontSize: 16)), const SizedBox(height: 5), const Text('Tap the invite button above to choose a student.', textAlign: TextAlign.center, style: TextStyle(color: AppColors.muted))])),
            if (!waiting && game == 'tictactoe') ...[
              Text(data['turnUid'] == uid && !finished ? 'Your turn' : (finished ? resultText : 'Friend’s turn'), textAlign: TextAlign.center, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900)),
              const SizedBox(height: 12),
              GridView.builder(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(), itemCount: 9, gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 3, crossAxisSpacing: 8, mainAxisSpacing: 8), itemBuilder: (_, i) => Pressable(shadow: true, radius: 12, onTap: _busy || finished || data['turnUid'] != uid || board[i].isNotEmpty ? null : () => _playTicTacToe(widget.roomId, data, i), child: Container(decoration: neoDeco(color: board[i].isEmpty ? Colors.white : (board[i] == 'X' ? const Color(0xFFFFD6C7) : AppColors.softBlue), radius: 12, shadow: false), child: Center(child: Text(board[i], style: TextStyle(fontSize: 48, fontWeight: FontWeight.w900, color: board[i] == 'X' ? AppColors.blue : AppColors.ink))))),),
              if (finished) Padding(padding: const EdgeInsets.only(top: 18), child: FilledButton.icon(onPressed: () => _playAgain(widget.roomId, data), icon: const Icon(Icons.replay_rounded), label: const Text('Play again'))),
            ],
            if (!waiting && game == 'rps') ...[
              Text(finished ? resultText : (choices.containsKey(uid) ? 'Waiting for your friend to choose…' : 'Make your choice'), textAlign: TextAlign.center, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w900)),
              const SizedBox(height: 16),
              if (!finished) Wrap(alignment: WrapAlignment.center, spacing: 10, runSpacing: 10, children: [
                _rpsButton('Rock', 'rock', Icons.sports_mma_rounded, choices.containsKey(uid), data),
                _rpsButton('Paper', 'paper', Icons.back_hand_rounded, choices.containsKey(uid), data),
                _rpsButton('Scissors', 'scissors', Icons.content_cut_rounded, choices.containsKey(uid), data),
              ]),
              if (finished) ...[
                const SizedBox(height: 8),
                Text('You chose ${choices[uid] ?? '—'} · Friend chose ${choices[players.firstWhere((p) => p != uid, orElse: () => '')] ?? '—'}', textAlign: TextAlign.center, style: const TextStyle(fontWeight: FontWeight.w700)),
                const SizedBox(height: 18), FilledButton.icon(onPressed: () => _playAgain(widget.roomId, data), icon: const Icon(Icons.replay_rounded), label: const Text('Play again')),
              ],
            ],
            if (players.length == 2) Padding(padding: const EdgeInsets.only(top: 22), child: Text('Players connected: 2/2', textAlign: TextAlign.center, style: const TextStyle(color: AppColors.muted, fontWeight: FontWeight.w700))),
          ]);
        },
      ),
    );
  }

  Widget _rpsButton(String label, String value, IconData icon, bool alreadyChosen, Map<String, dynamic> data) => Pressable(shadow: true, radius: 12, onTap: alreadyChosen || _busy ? null : () => _chooseRps(widget.roomId, data, value), child: Container(width: 94, padding: const EdgeInsets.symmetric(vertical: 16, horizontal: 10), decoration: neoDeco(color: Colors.white, radius: 12, shadow: false), child: Column(children: [Icon(icon, size: 30), const SizedBox(height: 7), Text(label, style: const TextStyle(fontWeight: FontWeight.w900))])));
}

// =====================================================
// LEADERBOARD (opened from the home-page Vault tile)
// =====================================================

class _LeaderboardEntry {
  final String uid;
  final String name;
  final String username;
  final String college;
  final String image;
  final int followers;
  final int communityPosts;
  final int personalPosts;

  const _LeaderboardEntry({
    required this.uid,
    required this.name,
    required this.username,
    required this.college,
    required this.image,
    required this.followers,
    required this.communityPosts,
    required this.personalPosts,
  });

  int get activityScore => followers + communityPosts * 10 + personalPosts * 5;

  factory _LeaderboardEntry.fromData(
      String uid,
      Map<String, dynamic> data, {
        required int followers,
        required int communityPosts,
        required int personalPosts,
      }) => _LeaderboardEntry(
    uid: uid,
    name: (data['name'] ?? data['displayName'] ?? data['username'] ?? 'Student').toString(),
    username: (data['username'] ?? '').toString(),
    college: (data['college'] ?? '').toString(),
    image: (data['profileImage'] ?? data['photoURL'] ?? data['photoUrl'] ?? '').toString(),
    followers: followers,
    communityPosts: communityPosts,
    personalPosts: personalPosts,
  );
}

String _followerMilestoneBadge(int count) {
  if (count >= 1000) return '🏆 Legend';
  if (count >= 500) return '💎 Campus Icon';
  if (count >= 100) return '🔥 Influencer';
  if (count >= 50) return '⭐ Popular';
  if (count >= 25) return '🤝 Connector';
  if (count >= 10) return '🌱 Rising Star';
  return '';
}

class LeaderboardScreen extends StatefulWidget {
  const LeaderboardScreen({super.key});

  @override
  State<LeaderboardScreen> createState() => _LeaderboardScreenState();
}

class _LeaderboardScreenState extends State<LeaderboardScreen> {
  int _selectedTab = 0;
  late Future<List<_LeaderboardEntry>> _entriesFuture;

  @override
  void initState() {
    super.initState();
    _entriesFuture = _loadEntries();
  }

  Future<int> _countPosts(String collection, String uid) async {
    try {
      final snap = await FirebaseFirestore.instance
          .collection(collection).where('authorId', isEqualTo: uid).count().get();
      return snap.count ?? 0;
    } catch (_) {
      try {
        final snap = await FirebaseFirestore.instance
            .collection(collection).where('authorId', isEqualTo: uid).get();
        return snap.size;
      } catch (_) {
        return 0;
      }
    }
  }

  Future<List<_LeaderboardEntry>> _loadEntries() async {
    final users = await FirebaseFirestore.instance.collection('users').limit(150).get();
    return Future.wait(users.docs.map((doc) async {
      final results = await Future.wait<dynamic>([
        FirebaseFirestore.instance.collection('users').doc(doc.id).collection('followers').count().get(),
        _countPosts('studentPosts', doc.id),
        _countPosts('personalPosts', doc.id),
      ]);
      return _LeaderboardEntry.fromData(
        doc.id, doc.data(),
        followers: (results[0] as AggregateQuerySnapshot).count ?? 0,
        communityPosts: results[1] as int,
        personalPosts: results[2] as int,
      );
    }));
  }

  List<_LeaderboardEntry> _sorted(List<_LeaderboardEntry> entries) {
    final result = List<_LeaderboardEntry>.from(entries);
    result.sort((a, b) {
      int score(_LeaderboardEntry e) => _selectedTab == 0
          ? e.followers : _selectedTab == 1 ? e.communityPosts : e.activityScore;
      return score(b).compareTo(score(a));
    });
    return result;
  }

  int _metric(_LeaderboardEntry e) => _selectedTab == 0
      ? e.followers : _selectedTab == 1 ? e.communityPosts : e.activityScore;
  String get _metricLabel => _selectedTab == 0
      ? 'followers' : _selectedTab == 1 ? 'posts' : 'points';
  String get _banner => _selectedTab == 0
      ? 'STUDENTS WITH THE MOST FOLLOWERS'
      : _selectedTab == 1 ? 'STUDENTS SHARING WITH THE COMMUNITY'
      : 'SCORE FROM FOLLOWERS & POSTS';

  @override
  Widget build(BuildContext context) {
    const tabs = ['Top followers', 'Posts', 'App activity'];
    return Scaffold(
      backgroundColor: const Color(0xFFFEF9F1),
      appBar: AppBar(
        backgroundColor: const Color(0xFFFEF9F1),
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        automaticallyImplyLeading: false,
        title: Row(mainAxisSize: MainAxisSize.min, children: [
          Container(width: 12, height: 12, decoration: BoxDecoration(
            color: const Color(0xFFFF5A36), shape: BoxShape.circle,
            border: Border.all(color: AppColors.ink, width: 1),
          )),
          const SizedBox(width: 8),
          const Flexible(child: Text('Leaderboard', maxLines: 1,
              style: TextStyle(color: AppColors.ink, fontSize: 23, fontWeight: FontWeight.w900, letterSpacing: -0.7))),
        ]),
        centerTitle: true,
      ),
      body: FutureBuilder<List<_LeaderboardEntry>>(
        future: _entriesFuture,
        builder: (context, snapshot) {
          if (snapshot.hasError) return const Center(child: Text('Could not load leaderboard. Please try again.'));
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator(color: AppColors.blue));
          final entries = _sorted(snapshot.data!);
          if (entries.isEmpty) return const Center(child: Text('No students to rank yet.'));
          final top = entries.take(3).toList();
          final currentUid = FirebaseAuth.instance.currentUser?.uid;
          final currentIndex = entries.indexWhere((e) => e.uid == currentUid);
          final me = currentIndex >= 0 ? entries[currentIndex] : entries.first;
          return Stack(children: [
            Column(children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 10, 20, 14),
                child: Container(
                  padding: const EdgeInsets.all(5),
                  decoration: BoxDecoration(color: Colors.white, border: Border.all(color: AppColors.ink, width: 2),
                      borderRadius: BorderRadius.circular(22),
                      boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(3, 3))]),
                  child: Row(children: List.generate(tabs.length, (index) => Expanded(
                    child: GestureDetector(
                      onTap: () => setState(() => _selectedTab = index),
                      child: AnimatedContainer(
                        duration: const Duration(milliseconds: 180),
                        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 2),
                        decoration: BoxDecoration(
                          color: _selectedTab == index ? const Color(0xFFFFD23F) : Colors.transparent,
                          border: _selectedTab == index ? Border.all(color: AppColors.ink, width: 2) : null,
                          borderRadius: BorderRadius.circular(15),
                          boxShadow: _selectedTab == index ? const [BoxShadow(color: AppColors.ink, offset: Offset(2, 2))] : null,
                        ),
                        child: Text(tabs[index], textAlign: TextAlign.center,
                            style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                                color: _selectedTab == index ? AppColors.ink : const Color(0xFF77736B))),
                      ),
                    ),
                  ))),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(24, 0, 22, 0),
                child: Row(children: [
                  Expanded(child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
                    decoration: BoxDecoration(color: const Color(0xFFFFEED0), border: Border.all(color: AppColors.ink, width: 2),
                        borderRadius: BorderRadius.circular(28)),
                    child: Row(children: [
                      const Icon(Icons.verified_rounded, color: Color(0xFFFF5A36), size: 17),
                      const SizedBox(width: 8),
                      Expanded(child: Text(_banner, style: const TextStyle(fontSize: 11, height: 1.25, fontWeight: FontWeight.w900, letterSpacing: .2))),
                    ]),
                  )),
                  const SizedBox(width: 8),
                  const Text('Updated now', style: TextStyle(fontSize: 11, color: AppColors.muted, fontWeight: FontWeight.w800)),
                ]),
              ),
              Expanded(child: ListView(
                padding: const EdgeInsets.fromLTRB(20, 18, 20, 112),
                children: [
                  if (top.length >= 3) _buildPodium(top),
                  if (entries.length > 3) ...[
                    const SizedBox(height: 22),
                    Row(children: [
                      const Text('RANKINGS 4 – 10', style: TextStyle(color: Color(0xFF77736B), fontSize: 11, fontWeight: FontWeight.w900, letterSpacing: .7)),
                      const SizedBox(width: 10),
                      const Expanded(child: Divider(color: Color(0xFFEBDDC9), thickness: 2, height: 2)),
                    ]),
                    const SizedBox(height: 12),
                    ...entries.skip(3).toList().asMap().entries.map((item) =>
                        _buildRankRow(item.value, item.key + 4)),
                  ],
                ],
              )),
            ]),
            Positioned(left: 20, right: 20, bottom: 10,
                child: _buildStickyStanding(me, currentIndex >= 0 ? currentIndex + 1 : 1)),
          ]);
        },
      ),
    );
  }

  Widget _buildPodium(List<_LeaderboardEntry> top) {
    final second = top[1], first = top[0], third = top[2];
    return SizedBox(height: 405, child: Row(
      crossAxisAlignment: CrossAxisAlignment.end,
      children: [
        Expanded(child: _podiumPerson(second, 2, const Color(0xFF009B72), const Color(0xFFEAE4D7), 70)),
        const SizedBox(width: 8),
        Expanded(child: _podiumPerson(first, 1, const Color(0xFF5146E5), const Color(0xFFFFD23F), 108)),
        const SizedBox(width: 8),
        Expanded(child: _podiumPerson(third, 3, const Color(0xFFE07800), const Color(0xFFEAE4D7), 56)),
      ],
    ));
  }

  Widget _podiumPerson(_LeaderboardEntry entry, int rank, Color avatarColor, Color stepColor, double stepHeight) {
    final isFirst = rank == 1;
    return Column(mainAxisAlignment: MainAxisAlignment.end, children: [
      if (isFirst) const Padding(padding: EdgeInsets.only(bottom: 2), child: Text('👑', style: TextStyle(fontSize: 25))),
      ProfileAvatar(imageUrl: entry.image, name: entry.name, radius: isFirst ? 44 : 32,
          backgroundColor: avatarColor),
      const SizedBox(height: 7),
      Container(width: 32, height: 32, alignment: Alignment.center,
          decoration: BoxDecoration(color: rank == 1 ? const Color(0xFFFFD23F) : rank == 2 ? const Color(0xFFE6E8EC) : const Color(0xFFF3D5A5),
              shape: BoxShape.circle, border: Border.all(color: AppColors.ink, width: 2),
              boxShadow: rank == 1 ? const [BoxShadow(color: AppColors.ink, offset: Offset(2, 2))] : null),
          child: Text('$rank', style: const TextStyle(fontWeight: FontWeight.w900))),
      const SizedBox(height: 9),
      Text(entry.name, maxLines: 1, overflow: TextOverflow.ellipsis, textAlign: TextAlign.center,
          style: TextStyle(fontSize: isFirst ? 15 : 13, fontWeight: FontWeight.w900)),
      Text(entry.username.isEmpty ? '' : '@${entry.username}', maxLines: 1, overflow: TextOverflow.ellipsis,
          textAlign: TextAlign.center, style: const TextStyle(fontSize: 10, color: AppColors.muted)),
      if (isFirst && _selectedTab == 0 && _followerMilestoneBadge(entry.followers).isNotEmpty)
        Padding(padding: const EdgeInsets.only(top: 5), child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
            decoration: BoxDecoration(color: const Color(0xFFFFF3C4), border: Border.all(color: AppColors.ink), borderRadius: BorderRadius.circular(16)),
            child: Text(_followerMilestoneBadge(entry.followers), style: const TextStyle(fontSize: 9, fontWeight: FontWeight.w900)))),
      Padding(padding: const EdgeInsets.only(top: 5, bottom: 8), child: Text('${_metric(entry)} ${_metricLabel.toUpperCase()}',
          maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 10, fontWeight: FontWeight.w900, color: isFirst ? const Color(0xFFFF5A36) : AppColors.muted))),
      Container(height: stepHeight, width: double.infinity,
        decoration: BoxDecoration(color: stepColor, border: Border.all(color: AppColors.ink, width: 2),
            borderRadius: const BorderRadius.vertical(top: Radius.circular(16)),
            boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(3, 3))]),
        child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
          if (isFirst) const Icon(Icons.emoji_events_rounded, size: 25),
          Text('#$rank', style: TextStyle(fontSize: isFirst ? 23 : 20, fontWeight: FontWeight.w900,
              color: isFirst ? AppColors.ink : const Color(0xFF858178))),
        ]),
      ),
    ]);
  }

  Widget _buildRankRow(_LeaderboardEntry entry, int rank) {
    return InkWell(
      onTap: () => pushPage(context, PublicStudentProfileScreen(profile: {
        'uid': entry.uid, 'name': entry.name, 'username': entry.username,
        'college': entry.college, 'profileImage': entry.image,
      })),
      borderRadius: BorderRadius.circular(16),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 3, vertical: 10),
        decoration: const BoxDecoration(border: Border(bottom: BorderSide(color: Color(0xFFEBDDC9), width: 1))),
        child: Row(children: [
          SizedBox(width: 32, child: Text('$rank', textAlign: TextAlign.center,
              style: const TextStyle(color: Color(0xFF77736B), fontWeight: FontWeight.w900, fontSize: 15))),
          const SizedBox(width: 12),
          ProfileAvatar(imageUrl: entry.image, name: entry.name, radius: 23),
          const SizedBox(width: 13),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(entry.name, maxLines: 1, overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900)),
            if (entry.username.isNotEmpty) Text('@${entry.username}', maxLines: 1, overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 12, color: AppColors.muted, fontWeight: FontWeight.w600)),
          ])),
          const SizedBox(width: 8),
          Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Text('${_metric(entry)}', style: const TextStyle(fontSize: 19, fontWeight: FontWeight.w900, height: 1)),
            Text(_metricLabel.toUpperCase(), style: const TextStyle(fontSize: 9, color: AppColors.muted, fontWeight: FontWeight.w900)),
          ]),
        ]),
      ),
    );
  }

  Widget _buildStickyStanding(_LeaderboardEntry entry, int rank) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
      decoration: BoxDecoration(color: AppColors.ink, border: Border.all(color: AppColors.ink, width: 2),
          borderRadius: BorderRadius.circular(20),
          boxShadow: const [BoxShadow(color: AppColors.ink, offset: Offset(3, 3))]),
      child: Row(children: [
        Stack(clipBehavior: Clip.none, children: [
          Container(padding: const EdgeInsets.all(2), decoration: BoxDecoration(shape: BoxShape.circle, border: Border.all(color: const Color(0xFFFFD23F), width: 2)),
              child: ProfileAvatar(imageUrl: entry.image, name: entry.name, radius: 21, backgroundColor: const Color(0xFF555555))),
          Positioned(right: -4, bottom: -4, child: Container(padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
              decoration: BoxDecoration(color: const Color(0xFFFFD23F), borderRadius: BorderRadius.circular(6), border: Border.all(color: AppColors.ink)),
              child: Text('#$rank', style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w900)))),
        ]),
        const SizedBox(width: 10),
        Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Flexible(child: Text(entry.name, maxLines: 1, overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: Colors.white, fontSize: 14, fontWeight: FontWeight.w900))),
            const SizedBox(width: 6),
            Container(padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(color: const Color(0xFFFF5A36), borderRadius: BorderRadius.circular(5)),
                child: const Text('YOU', style: TextStyle(color: Colors.white, fontSize: 9, fontWeight: FontWeight.w900))),
          ]),
          Text('Rank #$rank • ${_metric(entry)} ${_metricLabel.toUpperCase()}',
              maxLines: 1, overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: Color(0xFFD6D3D1), fontSize: 11, fontWeight: FontWeight.w600)),
        ])),
        const SizedBox(width: 8),
        Material(color: const Color(0xFFFFD23F), borderRadius: BorderRadius.circular(12),
          child: InkWell(
            onTap: () {
              final text = 'I am ranked #$rank on PeerGrid Leaderboard!';
              ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
            },
            borderRadius: BorderRadius.circular(12),
            child: Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(border: Border.all(color: Colors.white, width: 1.5), borderRadius: BorderRadius.circular(12)),
              child: const Row(children: [Icon(Icons.share_rounded, size: 14), SizedBox(width: 5), Text('Share', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900))]),
            ),
          ),
        ),
      ]),
    );
  }
}

