class SavedScreen extends StatelessWidget {
  const SavedScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: ValueListenableBuilder<Set<String>>(
          valueListenable: savedColleges,
          builder: (context, saved, _) {
            final list = allColleges.where((c) => saved.contains(c.id)).toList();

            return ListView(
              padding: const EdgeInsets.only(bottom: 30),
              children: [
                const PageHeader(title: 'Saved colleges'),
                if (list.isEmpty)
                  const EmptyState(
                    icon: Icons.bookmark_border_rounded,
                    title: 'Nothing saved yet',
                    subtitle:
                    'Tap the bookmark on any college to keep it here for later.',
                  ),
                for (int i = 0; i < list.length; i++)
                  Padding(
                    key: ValueKey('saved-${list[i].id}'),
                    padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
                    child: Entrance(
                      delayMs: i * 70,
                      child: CollegeCard(
                        college: list[i],
                        heroPrefix: 'saved',
                      ),
                    ),
                  ),
              ],
            );
          },
        ),
      ),
    );
  }
}

// =====================================================
// PREDICT COLLEGE SCREEN  (same ML/API logic, new UI)
// =====================================================

class PredictCollegeScreen extends StatefulWidget {
  const PredictCollegeScreen({super.key});

  @override
  State<PredictCollegeScreen> createState() => _PredictCollegeScreenState();
}

class _PredictCollegeScreenState extends State<PredictCollegeScreen> {
  // USER INPUTS
  String selectedExam = 'KEAM';
  String selectedCategory = 'General';
  String selectedCourse = 'B.Tech, CSE';

  final TextEditingController scoreController = TextEditingController();

  // ML RESULT STATE
  bool isLoading = false;
  bool showResults = false;
  String? predictionError;
  int _run = 0;
  final GlobalKey _resultsKey = GlobalKey();

  List<Map<String, dynamic>> recommendations = [];

  // Android Emulator -> Windows computer
  // 10.0.2.2 points to the host computer's localhost.
  static const String predictionApiUrl = 'http://10.0.2.2:8000/predict';

  @override
  void dispose() {
    scoreController.dispose();
    super.dispose();
  }

  // MAP FLUTTER UI VALUES TO DATASET VALUES
  String getApiCategory() {
    switch (selectedCategory) {
      case 'General':
        return 'SM';

    // The current UI uses OBC as a simplified label.
    // The current dataset contains KEAM category EZ rather
    // than a generic "OBC" category.
      case 'OBC':
        return 'EZ';

      case 'SC':
        return 'SC';

      case 'ST':
        return 'ST';

      default:
        return 'SM';
    }
  }

  String getApiCourse() {
    switch (selectedCourse) {
      case 'B.Tech, CSE':
        return 'Computer Science & Engineering';

      case 'B.Tech, ECE':
        return 'Electronics & Communication Engineering';

      case 'B.Tech, EEE':
        return 'Electrical & Electronics Engineering';

      case 'B.Tech, ME':
        return 'Mechanical Engineering';

      default:
        return selectedCourse;
    }
  }

  // CALL FASTAPI + ML MODEL
  Future<void> predictCollege() async {
    FocusScope.of(context).unfocus();

    final rankText = scoreController.text.trim();
    final rank = int.tryParse(rankText);

    if (rank == null || rank <= 0) {
      setState(() {
        predictionError = 'Please enter a valid KEAM rank.';
        showResults = false;
        recommendations = [];
      });
      return;
    }

    if (selectedExam != 'KEAM') {
      setState(() {
        predictionError = 'The current recommendation model supports KEAM only.';
        showResults = false;
        recommendations = [];
      });
      return;
    }

    setState(() {
      isLoading = true;
      predictionError = null;
      showResults = false;
      recommendations = [];
    });

    try {
      final client = HttpClient();

      try {
        final request = await client.postUrl(
          Uri.parse(predictionApiUrl),
        );

        request.headers.contentType = ContentType.json;

        request.write(
          jsonEncode({
            'rank': rank,
            'category': getApiCategory(),
            'course': getApiCourse(),
            'top_n': 10,
          }),
        );

        final response = await request.close();

        final responseBody = await response.transform(utf8.decoder).join();

        if (!mounted) return;

        dynamic decoded;

        try {
          decoded = jsonDecode(responseBody);
        } catch (_) {
          decoded = null;
        }

        if (response.statusCode == 200) {
          final List<dynamic> rawRecommendations = decoded is Map<String, dynamic>
              ? (decoded['recommendations'] as List<dynamic>? ?? [])
              : [];

          final results =
          rawRecommendations.whereType<Map<String, dynamic>>().toList();

          setState(() {
            recommendations = results;
            showResults = results.isNotEmpty;
            isLoading = false;
            _run++;

            if (results.isEmpty) {
              predictionError = decoded is Map<String, dynamic>
                  ? (decoded['message']?.toString() ??
                  'No recommendations were found for these selections.')
                  : 'No recommendations were found.';
            }
          });

          if (results.isNotEmpty) {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              final ctx = _resultsKey.currentContext;
              if (ctx != null) {
                Scrollable.ensureVisible(
                  ctx,
                  duration: const Duration(milliseconds: 650),
                  curve: Curves.easeInOutCubic,
                  alignment: 0.02,
                );
              }
            });
          }
        } else {
          String message =
              'Prediction failed. Server returned ${response.statusCode}.';

          if (decoded is Map<String, dynamic> && decoded['detail'] != null) {
            message = decoded['detail'].toString();
          }

          setState(() {
            predictionError = message;
            showResults = false;
            recommendations = [];
            isLoading = false;
          });
        }
      } finally {
        client.close(force: true);
      }
    } on FormatException {
      if (!mounted) return;

      setState(() {
        predictionError =
        'The recommendation server returned an invalid response.';
        showResults = false;
        recommendations = [];
        isLoading = false;
      });
    } on Exception {
      if (!mounted) return;

      setState(() {
        predictionError = 'Could not connect to the recommendation server.\n'
            'Make sure FastAPI is running on port 8000.';
        showResults = false;
        recommendations = [];
        isLoading = false;
      });
    }
  }

  // RESULT HELPERS
  Color getMatchColor(String match) {
    switch (match) {
      case 'Strong Match':
        return AppColors.green;
      case 'Good Match':
        return const Color(0xFF2587C1);
      case 'Possible Match':
        return const Color(0xFFE59B00);
      case 'Borderline':
        return const Color(0xFFE07A00);
      case 'Low Match':
        return const Color(0xFFD64545);
      default:
        return const Color(0xFF2867B7);
    }
  }

  String getCollegeName(Map<String, dynamic> item) {
    final name = item['college']?.toString() ?? 'Unknown College';
    return name.replaceAll(RegExp(r'\s+'), ' ').trim();
  }

  String getClosingRank(Map<String, dynamic> item) {
    final value = item['predicted_closing_rank'];
    if (value == null) return 'Not available';
    return value.toString();
  }

  String _matchNote(String match) {
    switch (match) {
      case 'Strong Match':
        return 'Your rank looks comfortably within the predicted closing rank, so this option looks very achievable.';
      case 'Good Match':
        return 'Your rank is close to the safe range for this college and course.';
      case 'Possible Match':
        return 'This is within reach, but cutoffs can vary from year to year.';
      case 'Borderline':
        return 'Your rank is very close to the predicted cutoff. Keep this as a reach or backup option.';
      case 'Low Match':
        return 'Your rank is beyond the predicted closing rank, so treat this as a long shot.';
      default:
        return 'Based on historical KEAM cutoff trends.';
    }
  }

  void _showDetail(Map<String, dynamic> item) {
    final match = item['match']?.toString() ?? 'Possible Match';
    final color = getMatchColor(match);

    showModalBottomSheet(
      context: context,
