                      ),
                      const SizedBox(height: 22),
                      ...recommendations.asMap().entries.map((entry) {
                        final index = entry.key;
                        final item = entry.value;

                        final match =
                            item['match']?.toString() ?? 'Possible Match';
                        final color = getMatchColor(match);
                        final predictedClosing = getClosingRank(item);

                        return Padding(
                          key: ValueKey('$_run-$index'),
                          padding: EdgeInsets.only(
                            bottom:
                            index == recommendations.length - 1 ? 0 : 16,
