              onPressed: () async {
                Navigator.pop(dialogContext);
                try {
                  await FirebaseAuth.instance.signOut();
                  userName.value = '';
                  userCollege.value = '';
                  userHobbies.value = '';
                  savedColleges.value = <String>{};
                  registeredEvents.value = <String>{};
