class _ProfilePersonalPostsSection extends StatelessWidget {
  final String uid;

  const _ProfilePersonalPostsSection({required this.uid});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('personalPosts')
          .where('authorId', isEqualTo: uid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return const Padding(
            padding: EdgeInsets.symmetric(horizontal: 20),
            child: Text(
              'Could not load personal posts.',
              style: TextStyle(fontWeight: FontWeight.w700),
            ),
          );
        }

        final docs = [
          ...(snapshot.data?.docs ??
              <QueryDocumentSnapshot<Map<String, dynamic>>>[])
        ]..sort((a, b) {
          final at = a.data()['createdAt'];
          final bt = b.data()['createdAt'];
          final ad = at is Timestamp ? at.toDate() : DateTime(2000);
          final bd = bt is Timestamp ? bt.toDate() : DateTime(2000);
          return bd.compareTo(ad);
        });

        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  const Text(
                    'MY POSTS',
                    style: TextStyle(
                      fontSize: 21,
                      fontWeight: FontWeight.w900,
                      letterSpacing: -0.5,
                    ),
                  ),
                  const SizedBox(width: 7),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 3,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFD23F),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: AppColors.ink, width: 1.5),
                    ),
                    child: Text(
                      '${docs.length}',
                      style: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  const Spacer(),
                  Pressable(
                    shadow: true,
                    radius: 12,
                    onTap: () => pushPage(
                      context,
                      StudentPostsProfileScreen(
                        uid: uid,
                        name: userName.value,
                      ),
                    ),
                    child: Container(
                      width: 112,
                      height: 48,
                      decoration: BoxDecoration(
                        color: const Color(0xFFF2EDE5),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: AppColors.ink, width: 2),
                      ),
                      child: const Row(
                        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                        children: [
                          Icon(Icons.grid_view_rounded, size: 21),
                          Icon(Icons.view_agenda_outlined, size: 21),
                          Icon(Icons.bookmark_border_rounded, size: 21),
                        ],
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              if (docs.isEmpty)
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.symmetric(vertical: 30),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: AppColors.ink, width: 2),
                    boxShadow: const [
                      BoxShadow(
                        color: AppColors.ink,
                        offset: Offset(3, 4),
                        blurRadius: 0,
                      ),
                    ],
                  ),
                  child: const Column(
                    children: [
                      Icon(Icons.photo_library_outlined, size: 38),
                      SizedBox(height: 8),
                      Text(
                        'No personal posts yet',
                        style: TextStyle(fontWeight: FontWeight.w900),
                      ),
                    ],
                  ),
                )
              else
                GridView.builder(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  itemCount: docs.length,
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 2,
                    crossAxisSpacing: 8,
                    mainAxisSpacing: 8,
                    childAspectRatio: 0.76,
                  ),
                  itemBuilder: (context, index) {
                    final post = _StudentFeedPost.fromDoc(
                      docs[index],
                      collectionName: 'personalPosts',
                    );
                    return _ProfilePostTile(post: post);
                  },
                ),
              const SizedBox(height: 20),
              Center(
                child: Pressable(
                  shadow: true,
                  radius: 12,
                  onTap: () => pushPage(
                    context,
                    StudentPostsProfileScreen(
                      uid: uid,
                      name: userName.value,
                    ),
                  ),
                  child: Container(
                    height: 48,
                    padding: const EdgeInsets.symmetric(horizontal: 22),
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFD23F),
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: AppColors.ink, width: 2),
                    ),
                    child: const Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(Icons.add_circle_outline_rounded, size: 21),
                        SizedBox(width: 8),
                        Text(
                          'CREATE NEW POST',
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

