// COLLEGE ADMIN DASHBOARD
// =====================================================

class CollegeAdminDashboard extends StatefulWidget {
  final String collegeId;

  const CollegeAdminDashboard({
    super.key,
    required this.collegeId,
  });

  @override
  State<CollegeAdminDashboard> createState() =>
      _CollegeAdminDashboardState();
}

class _CollegeAdminDashboardState
    extends State<CollegeAdminDashboard> {
  bool loading = true;
  String collegeName = 'College Admin';
  String collegeShortName = '';
  String collegeLocation = '';
  String collegeDescription = '';
  String collegeLogoUrl = '';
  String collegeCoverUrl = '';

  @override
  void initState() {
    super.initState();
    _loadCollege();
  }

  Future<void> _loadCollege() async {
    try {
      final doc = await FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .get();

      if (doc.exists) {
        final data = doc.data() ?? {};

        if (mounted) {
          setState(() {
            collegeName =
            data['name']?.toString().trim().isNotEmpty == true
                ? data['name'].toString().trim()
                : 'College Admin';

            collegeShortName =
                data['shortName']?.toString().trim() ?? '';

            collegeLocation =
                data['location']?.toString().trim() ?? '';

            collegeDescription =
                data['description']?.toString().trim() ?? '';

            collegeLogoUrl =
                data['logoUrl']?.toString().trim() ?? '';

            collegeCoverUrl =
                data['coverUrl']?.toString().trim() ?? '';

            loading = false;
          });
        }
      } else {
        if (mounted) {
          setState(() {
            loading = false;
          });
        }
      }
    } catch (_) {
      if (mounted) {
        setState(() {
          loading = false;
        });
      }
    }
  }

  Future<void> _openProfileEditor() async {
    await Navigator.of(context).push(
      FadePageRoute(
        page: CollegeProfileEditor(
          collegeId: widget.collegeId,
        ),
      ),
    );

    if (mounted) {
      await _loadCollege();
    }
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();

    if (!mounted) return;

    userName.value = '';
    userCollege.value = '';
    userHobbies.value = '';
    savedColleges.value = <String>{};
    registeredEvents.value = <String>{};
    joinedCommunities.value = <String>{};

    Navigator.of(context).pushAndRemoveUntil(
      FadePageRoute(
        page: const WelcomeScreen(),
      ),
          (route) => false,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
        elevation: 0,
        title: const Text(
          'College Admin',
          style: TextStyle(
            fontWeight: FontWeight.w900,
          ),
        ),
        actions: [
          IconButton(
            tooltip: 'Logout',
            onPressed: _logout,
            icon: const Icon(Icons.logout_rounded),
          ),
        ],
      ),
      body: loading
          ? const Center(
        child: CircularProgressIndicator(
          color: AppColors.blue,
        ),
      )
          : SafeArea(
        child: RefreshIndicator(
          color: AppColors.blue,
          onRefresh: _loadCollege,
          child: SingleChildScrollView(
            physics:
            const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(
              20,
              20,
              20,
              32,
            ),
            child: Column(
              crossAxisAlignment:
              CrossAxisAlignment.start,
              children: [
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(22),
                  decoration: BoxDecoration(
                    color: AppColors.softBlue,
                    borderRadius:
                    BorderRadius.circular(26),
                    border: Border.all(
                      color: AppColors.blue,
                      width: 1.5,
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment:
                    CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 54,
                            height: 54,
                            decoration:
                            BoxDecoration(
                              color: Colors.white,
                              borderRadius:
                              BorderRadius.circular(
                                  16),
                            ),
                            child: collegeLogoUrl
                                .isNotEmpty
                                ? ClipRRect(
                              borderRadius:
                              BorderRadius
                                  .circular(
                                  16),
                              child: DarkSafe(
                                child: Image.network(
                                  collegeLogoUrl,
                                  fit: BoxFit.cover,
                                  errorBuilder:
                                      (_, __, ___) =>
                                  const Icon(
                                    Icons.school_rounded,
                                    color:
                                    AppColors.blue,
                                    size: 30,
                                  ),
                                ),
                              ),
                            )
                                : const Icon(
                              Icons.school_rounded,
                              color:
                              AppColors.blue,
                              size: 30,
                            ),
                          ),
                          const SizedBox(width: 14),
                          const Expanded(
                            child: Row(
                              children: [
                                Icon(
                                  Icons.verified_rounded,
                                  color:
                                  AppColors.blue,
                                  size: 22,
                                ),
                                SizedBox(width: 6),
                                Flexible(
                                  child: Text(
                                    'Official College Account',
