// =====================================================
// COLLEGE PROFILE EDITOR
// =====================================================


class CollegePhotoManager extends StatefulWidget {
  final String collegeId;

  const CollegePhotoManager({
    super.key,
    required this.collegeId,
  });

  @override
  State<CollegePhotoManager> createState() =>
      _CollegePhotoManagerState();
}

class _CollegePhotoManagerState extends State<CollegePhotoManager> {
  final ImagePicker _picker = ImagePicker();
  bool uploading = false;
  String? uploadingType;

  CollectionReference<Map<String, dynamic>> get _photos =>
      FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('photos');

  Future<void> _uploadSingle(String type) async {
    if (uploading) return;

    final picked = await _pickAndCropImage(
      source: ImageSource.gallery,
      imageQuality: 85,
      maxWidth: 1800,
    );

    if (picked == null) return;

    setState(() {
      uploading = true;
      uploadingType = type;
    });

    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw Exception('You are not signed in.');

      final extension = picked.name.contains('.')
          ? picked.name.split('.').last.toLowerCase()
          : 'jpg';
      final fileName = '${type}_${DateTime.now().millisecondsSinceEpoch}.$extension';
      final storagePath =
          'colleges/${widget.collegeId}/$type/$fileName';

      final ref = FirebaseStorage.instance.ref(storagePath);
      await ref.putFile(File(picked.path));
      final downloadUrl = await ref.getDownloadURL();

      final photoDoc = _photos.doc();
      await photoDoc.set({
        'type': type,
        'imageUrl': downloadUrl,
        'storagePath': storagePath,
        'caption': type == 'logo' ? 'Official college logo' : 'Official college cover photo',
        'uploadedBy': user.uid,
        'createdAt': FieldValue.serverTimestamp(),
      });

      await FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .set({
        type == 'logo' ? 'logoUrl' : 'coverUrl': downloadUrl,
        'updatedAt': FieldValue.serverTimestamp(),
        'updatedBy': user.uid,
      }, SetOptions(merge: true));

      if (!mounted) return;
      showSnack(
        context,
        type == 'logo'
            ? 'College logo uploaded successfully.'
            : 'College cover photo uploaded successfully.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Upload failed: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    } finally {
      if (mounted) {
        setState(() {
          uploading = false;
          uploadingType = null;
        });
      }
    }
  }

  Future<void> _uploadGallery() async {
    if (uploading) return;

    final picked = await _pickAndCropImages(
      imageQuality: 85,
      maxWidth: 1800,
    );

    if (picked.isEmpty) return;

    setState(() {
      uploading = true;
      uploadingType = 'gallery';
    });

    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw Exception('You are not signed in.');

      int uploadedCount = 0;

      for (final image in picked) {
        final extension = image.name.contains('.')
            ? image.name.split('.').last.toLowerCase()
            : 'jpg';
        final fileName =
            'gallery_${DateTime.now().millisecondsSinceEpoch}_$uploadedCount.$extension';
        final storagePath =
            'colleges/${widget.collegeId}/gallery/$fileName';

        final ref = FirebaseStorage.instance.ref(storagePath);
        await ref.putFile(File(image.path));
        final downloadUrl = await ref.getDownloadURL();

        await _photos.doc().set({
          'type': 'gallery',
          'imageUrl': downloadUrl,
          'storagePath': storagePath,
          'caption': '',
          'uploadedBy': user.uid,
          'createdAt': FieldValue.serverTimestamp(),
        });

        uploadedCount++;
      }

      if (!mounted) return;
      showSnack(
        context,
        '$uploadedCount gallery photo${uploadedCount == 1 ? '' : 's'} uploaded successfully.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Gallery upload failed: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    } finally {
      if (mounted) {
        setState(() {
          uploading = false;
          uploadingType = null;
        });
      }
    }
  }

  Future<void> _deletePhoto(
      DocumentSnapshot<Map<String, dynamic>> doc,
      ) async {
    final data = doc.data() ?? {};
    final type = data['type']?.toString() ?? 'gallery';
    final storagePath = data['storagePath']?.toString() ?? '';

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text('Delete photo?'),
          content: const Text(
            'This will remove the photo from your college page.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              style: FilledButton.styleFrom(
                backgroundColor: Colors.red,
              ),
              child: const Text('Delete'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) return;

    try {
      if (storagePath.isNotEmpty) {
        try {
          await FirebaseStorage.instance.ref(storagePath).delete();
        } catch (_) {
          // Continue deleting the Firestore metadata even if the storage
          // object has already been removed.
        }
      }

      await doc.reference.delete();

      if (type == 'logo' || type == 'cover') {
        await FirebaseFirestore.instance
            .collection('colleges')
            .doc(widget.collegeId)
            .set({
          type == 'logo' ? 'logoUrl' : 'coverUrl': '',
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }

      if (!mounted) return;
      showSnack(
        context,
        'Photo deleted.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Could not delete photo: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    }
  }

  Widget _uploadCard({
    required IconData icon,
    required String title,
    required String subtitle,
    required VoidCallback onTap,
    required bool busy,
  }) {
    return InkWell(
      onTap: uploading ? null : onTap,
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.all(18),
        decoration: BoxDecoration(
          color: AppColors.softBlue,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: AppColors.blue.withValues(alpha: 0.25),
          ),
        ),
        child: Row(
          children: [
            Container(
              width: 50,
              height: 50,
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(15),
              ),
              child: busy
                  ? const Padding(
                padding: EdgeInsets.all(14),
                child: CircularProgressIndicator(strokeWidth: 2.5),
              )
                  : Icon(icon, color: AppColors.blue),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: const TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    subtitle,
                    style: const TextStyle(
                      fontSize: 12,
                      color: AppColors.muted,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const Icon(Icons.chevron_right_rounded),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        title: const Text(
          'College Photos',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
      ),
      body: SafeArea(
        child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: _photos.orderBy('createdAt', descending: true).snapshots(),
          builder: (context, snapshot) {
            if (snapshot.hasError) {
              return Center(
                child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Text(
                    'Could not load photos.\n\n${snapshot.error}',
                    textAlign: TextAlign.center,
                  ),
                ),
              );
            }

            final docs = snapshot.data?.docs ?? [];

            return ListView(
              padding: const EdgeInsets.fromLTRB(20, 20, 20, 32),
              children: [
                Container(
                  padding: const EdgeInsets.all(18),
                  decoration: BoxDecoration(
                    color: AppColors.softBlue,
                    borderRadius: BorderRadius.circular(22),
                  ),
                  child: const Text(
                    'Upload official college images. Logo and cover photos are also connected to the college profile automatically.',
                    style: TextStyle(
                      fontWeight: FontWeight.w700,
                      color: AppColors.ink,
                      height: 1.45,
                    ),
                  ),
                ),
                const SizedBox(height: 18),
                _uploadCard(
                  icon: Icons.account_balance_rounded,
                  title: 'Upload College Logo',
                  subtitle: 'Use the official college logo.',
                  onTap: () => _uploadSingle('logo'),
                  busy: uploadingType == 'logo',
                ),
                const SizedBox(height: 12),
                _uploadCard(
                  icon: Icons.panorama_outlined,
                  title: 'Upload Cover Photo',
                  subtitle: 'Choose the main banner image.',
                  onTap: () => _uploadSingle('cover'),
                  busy: uploadingType == 'cover',
                ),
                const SizedBox(height: 12),
                _uploadCard(
                  icon: Icons.add_photo_alternate_outlined,
                  title: 'Add Gallery Photos',
                  subtitle: 'Select one or multiple college photos.',
                  onTap: _uploadGallery,
                  busy: uploadingType == 'gallery',
                ),
                const SizedBox(height: 28),
                Text(
                  'Uploaded Photos (${docs.length})',
                  style: const TextStyle(
                    fontSize: 22,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 14),
                if (docs.isEmpty)
                  Container(
                    padding: const EdgeInsets.all(28),
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: AppColors.grey),
                    ),
                    child: const Column(
                      children: [
                        Icon(
                          Icons.photo_library_outlined,
                          size: 42,
                          color: AppColors.muted,
                        ),
                        SizedBox(height: 10),
                        Text(
                          'No college photos yet.',
                          style: TextStyle(fontWeight: FontWeight.w800),
                        ),
                      ],
                    ),
                  )
                else
                  ...docs.map((doc) {
                    final data = doc.data();
                    final imageUrl = data['imageUrl']?.toString() ?? '';
                    final type = data['type']?.toString() ?? 'gallery';
                    final caption = data['caption']?.toString() ?? '';

                    return Container(
                      margin: const EdgeInsets.only(bottom: 14),
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(20),
                        border: Border.all(color: AppColors.grey),
                      ),
                      clipBehavior: Clip.antiAlias,
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (imageUrl.isNotEmpty)
                            Container(
                              width: double.infinity,
                              color: Colors.white,
                              alignment: Alignment.center,
                              child: AdaptiveImage(
                                image: NetworkImage(imageUrl),
                                maxHeight: 320,
                                fit: BoxFit.contain,
                                error: const Center(
                                  child: Icon(Icons.broken_image_outlined),
                                ),
                              ),
                            ),
                          Padding(
                            padding: const EdgeInsets.fromLTRB(14, 12, 8, 12),
                            child: Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                    CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        type == 'logo'
                                            ? 'College Logo'
                                            : type == 'cover'
                                            ? 'Cover Photo'
                                            : 'Gallery Photo',
                                        style: const TextStyle(
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      if (caption.isNotEmpty) ...[
                                        const SizedBox(height: 3),
                                        Text(
                                          caption,
                                          style: const TextStyle(
                                            color: AppColors.muted,
                                            fontSize: 12,
                                          ),
                                        ),
                                      ],
                                    ],
                                  ),
                                ),
                                IconButton(
                                  tooltip: 'Delete photo',
                                  onPressed: uploading
                                      ? null
                                      : () => _deletePhoto(doc),
                                  icon: const Icon(
                                    Icons.delete_outline_rounded,
                                    color: Colors.red,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    );
                  }),
              ],
            );
          },
        ),
      ),
    );
  }
}



// =====================================================
// COLLEGE EVENTS MANAGER
// =====================================================

class CollegeEventsManager extends StatefulWidget {
  final String collegeId;

  const CollegeEventsManager({
    super.key,
    required this.collegeId,
  });

  @override
  State<CollegeEventsManager> createState() => _CollegeEventsManagerState();
}

class _CollegeEventsManagerState extends State<CollegeEventsManager> {
  CollectionReference<Map<String, dynamic>> get _events =>
      FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('events');

  Future<void> _openEditor({
    DocumentSnapshot<Map<String, dynamic>>? event,
  }) async {
    await Navigator.of(context).push(
      FadePageRoute(
        page: CollegeEventEditor(
          collegeId: widget.collegeId,
          event: event,
        ),
      ),
    );
  }

  Future<void> _deleteEvent(
      DocumentSnapshot<Map<String, dynamic>> event,
      ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Delete event?'),
        content: const Text(
          'This removes the event from the student Events section.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: FilledButton.styleFrom(backgroundColor: Colors.red),
            child: const Text('Delete'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    try {
      final data = event.data() ?? {};
      final path = data['storagePath']?.toString() ?? '';
      if (path.isNotEmpty) {
        try {
          await FirebaseStorage.instance.ref(path).delete();
        } catch (_) {}
      }

      await event.reference.delete();

      if (!mounted) return;
      showSnack(
        context,
        'Event deleted.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Could not delete event: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    }
  }

  String _formatDate(dynamic value) {
    if (value is Timestamp) {
      final d = value.toDate();
      const months = <String>[
        'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
      ];
      return '${d.day} ${months[d.month - 1]} ${d.year}';
    }
    return 'Date TBA';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        title: const Text(
          'College Events',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
      ),
      floatingActionButton: FloatingActionButton.extended(
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
        onPressed: () => _openEditor(),
        icon: const Icon(Icons.add_rounded),
        label: const Text(
          'Create Event',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: _events.snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Text(
                  'Could not load events.\n\n${snapshot.error}',
                  textAlign: TextAlign.center,
                ),
              ),
            );
          }

          final docs = [...(snapshot.data?.docs ?? <QueryDocumentSnapshot<Map<String, dynamic>>>[])]
            ..sort((a, b) {
              final aValue = a.data()['eventDate'];
              final bValue = b.data()['eventDate'];
              final aDate = aValue is Timestamp ? aValue.toDate() : DateTime(2100);
              final bDate = bValue is Timestamp ? bValue.toDate() : DateTime(2100);
              return aDate.compareTo(bDate);
            });

          return ListView(
            padding: const EdgeInsets.fromLTRB(20, 20, 20, 110),
            children: [
              Container(
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  color: AppColors.softBlue,
                  borderRadius: BorderRadius.circular(22),
                ),
                child: const Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(Icons.verified_rounded, color: AppColors.blue),
                    SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        'Events published here automatically appear in the student Events section and on the home page.',
                        style: TextStyle(
                          fontWeight: FontWeight.w700,
                          height: 1.45,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 24),
              Text(
                'Official Events (${docs.length})',
                style: const TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 14),
              if (docs.isEmpty)
                const EmptyState(
                  icon: Icons.event_outlined,
                  title: 'No college events yet',
                  subtitle: 'Tap Create Event to publish your first event.',
                )
              else
                ...docs.map((doc) {
                  final data = doc.data();
                  final imageUrl = data['imageUrl']?.toString().trim() ?? '';
                  return Container(
                    margin: const EdgeInsets.only(bottom: 16),
                    clipBehavior: Clip.antiAlias,
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(22),
                      border: Border.all(color: AppColors.grey),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (imageUrl.isNotEmpty)
                          Container(
                            width: double.infinity,
                            color: Colors.white,
