// =====================================================
// CREATE / EDIT COLLEGE EVENT
// =====================================================

class CollegeEventEditor extends StatefulWidget {
  final String collegeId;
  final DocumentSnapshot<Map<String, dynamic>>? event;

  const CollegeEventEditor({
    super.key,
    required this.collegeId,
    this.event,
  });

  @override
  State<CollegeEventEditor> createState() => _CollegeEventEditorState();
}

class _CollegeEventEditorState extends State<CollegeEventEditor> {
  final ImagePicker _picker = ImagePicker();
  final TextEditingController _titleController = TextEditingController();
  final TextEditingController _locationController = TextEditingController();
  final TextEditingController _descriptionController = TextEditingController();

  DateTime _eventDate = DateTime.now().add(const Duration(days: 7));
  TimeOfDay _eventTime = const TimeOfDay(hour: 10, minute: 0);
  String _category = 'College';
  XFile? _newImage;
  String _existingImageUrl = '';
  String _existingStoragePath = '';
  bool saving = false;

  bool get isEditing => widget.event != null;

  @override
  void initState() {
    super.initState();
    final data = widget.event?.data() ?? {};
    _titleController.text = data['title']?.toString() ?? '';
    _locationController.text = data['location']?.toString() ?? '';
    _descriptionController.text = data['description']?.toString() ?? '';
    _category = data['category']?.toString().trim().isNotEmpty == true
        ? data['category'].toString().trim()
        : 'College';

    final timestamp = data['eventDate'];
    if (timestamp is Timestamp) {
      _eventDate = timestamp.toDate();
    }

    final timeText = data['time']?.toString() ?? '';
    final match = RegExp(r'^(\d{1,2}):(\d{2})\s*(AM|PM)$', caseSensitive: false)
        .firstMatch(timeText);
    if (match != null) {
      var hour = int.tryParse(match.group(1)!) ?? 10;
      final minute = int.tryParse(match.group(2)!) ?? 0;
      final ampm = match.group(3)!.toUpperCase();
      if (ampm == 'PM' && hour < 12) hour += 12;
      if (ampm == 'AM' && hour == 12) hour = 0;
      _eventTime = TimeOfDay(hour: hour, minute: minute);
    }

    _existingImageUrl = data['imageUrl']?.toString() ?? '';
    _existingStoragePath = data['storagePath']?.toString() ?? '';
  }

  @override
  void dispose() {
    _titleController.dispose();
    _locationController.dispose();
    _descriptionController.dispose();
    super.dispose();
  }

  String _formatDate(DateTime d) {
    const months = <String>[
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${d.day} ${months[d.month - 1]} ${d.year}';
  }

  String _formatTime(TimeOfDay time) {
    final hour = time.hourOfPeriod == 0 ? 12 : time.hourOfPeriod;
    final minute = time.minute.toString().padLeft(2, '0');
    final period = time.period == DayPeriod.am ? 'AM' : 'PM';
    return '$hour:$minute $period';
  }

  Future<void> _pickImage() async {
    if (saving) return;
    final picked = await _pickAndCropImage(
      source: ImageSource.gallery,
      imageQuality: 82,
      maxWidth: 1800,
    );
    if (picked == null || !mounted) return;
    setState(() => _newImage = picked);
  }

  Future<void> _save() async {
    final title = _titleController.text.trim();
    final location = _locationController.text.trim();
    if (title.isEmpty || location.isEmpty) {
      showSnack(
        context,
        'Add an event title and location.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    setState(() => saving = true);

    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw Exception('You are not signed in.');

      final collegeRef = FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId);

      final collegeSnap = await collegeRef.get();
      final collegeData = collegeSnap.data() ?? {};
      final collegeName =
      collegeData['name']?.toString().trim().isNotEmpty == true
          ? collegeData['name'].toString().trim()
          : 'Official College';

      final events = collegeRef.collection('events');
      final eventRef = widget.event?.reference ?? events.doc();
      final eventId = eventRef.id;

      var imageUrl = _existingImageUrl;
      var storagePath = _existingStoragePath;

      if (_newImage != null) {
        if (storagePath.isNotEmpty) {
          try {
            await FirebaseStorage.instance.ref(storagePath).delete();
          } catch (_) {}
        }

        final extension = _newImage!.name.contains('.')
            ? _newImage!.name.split('.').last.toLowerCase()
            : 'jpg';
        storagePath =
        'colleges/${widget.collegeId}/events/$eventId/event.$extension';
        final ref = FirebaseStorage.instance.ref(storagePath);
        await ref.putFile(File(_newImage!.path));
        imageUrl = await ref.getDownloadURL();
      }

      final eventDateTime = DateTime(
        _eventDate.year,
        _eventDate.month,
        _eventDate.day,
        _eventTime.hour,
        _eventTime.minute,
      );

      await eventRef.set({
        'title': title,
        'description': _descriptionController.text.trim(),
        'date': _formatDate(_eventDate),
        'time': _formatTime(_eventTime),
        'eventDate': Timestamp.fromDate(eventDateTime),
        'location': location,
        'category': _category,
        'imageUrl': imageUrl,
        'storagePath': storagePath,
        'collegeName': collegeName,
        'createdBy': user.uid,
        'createdAt': widget.event == null
            ? FieldValue.serverTimestamp()
            : (widget.event?.data()?['createdAt'] ??
            FieldValue.serverTimestamp()),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      if (!mounted) return;
      Navigator.pop(context);
      showSnack(
        context,
        isEditing ? 'Event updated.' : 'Event published.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Could not save event: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        title: Text(
          isEditing ? 'Edit College Event' : 'Create College Event',
          style: const TextStyle(fontWeight: FontWeight.w900),
        ),
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(20, 20, 20, 40),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            TextField(
              controller: _titleController,
              textInputAction: TextInputAction.next,
              decoration: const InputDecoration(
                labelText: 'Event title',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 14),
            DropdownButtonFormField<String>(
              value: _category,
              decoration: const InputDecoration(
                labelText: 'Category',
                border: OutlineInputBorder(),
              ),
              items: const [
                DropdownMenuItem(value: 'College', child: Text('College')),
                DropdownMenuItem(value: 'Tech', child: Text('Tech')),
                DropdownMenuItem(value: 'Cultural', child: Text('Cultural')),
                DropdownMenuItem(value: 'Workshop', child: Text('Workshop')),
                DropdownMenuItem(value: 'Sports', child: Text('Sports')),
              ],
              onChanged: saving
                  ? null
                  : (value) => setState(() => _category = value ?? 'College'),
            ),
            const SizedBox(height: 14),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text(
                'Date',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
              subtitle: Text(_formatDate(_eventDate)),
              trailing: const Icon(Icons.calendar_month_rounded),
              onTap: saving
                  ? null
                  : () async {
                final picked = await showDatePicker(
                  context: context,
                  initialDate: _eventDate,
                  firstDate: DateTime.now(),
                  lastDate: DateTime.now().add(const Duration(days: 730)),
                );
                if (picked != null && mounted) {
                  setState(() => _eventDate = picked);
                }
              },
            ),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text(
                'Time',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
              subtitle: Text(_formatTime(_eventTime)),
              trailing: const Icon(Icons.access_time_rounded),
              onTap: saving
                  ? null
                  : () async {
                final picked = await showTimePicker(
                  context: context,
                  initialTime: _eventTime,
                );
                if (picked != null && mounted) {
                  setState(() => _eventTime = picked);
                }
              },
            ),
            const SizedBox(height: 8),
            TextField(
              controller: _locationController,
              decoration: const InputDecoration(
                labelText: 'Location',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 14),
            TextField(
              controller: _descriptionController,
              minLines: 3,
              maxLines: 6,
              decoration: const InputDecoration(
                labelText: 'Description (optional)',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 16),
            if (_existingImageUrl.isNotEmpty || _newImage != null)
              Container(
                height: 180,
                width: double.infinity,
                clipBehavior: Clip.antiAlias,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: AppColors.grey),
                ),
                child: _newImage != null
                    ? AdaptiveImage(
                  image: FileImage(File(_newImage!.path)),
                  maxHeight: 320,
                  fit: BoxFit.contain,
                  error: const Center(
                    child: Icon(Icons.broken_image_outlined),
                  ),
                )
                    : AdaptiveImage(
                  image: NetworkImage(_existingImageUrl),
                  maxHeight: 320,
                  fit: BoxFit.contain,
                  error: const Center(
                    child: Icon(Icons.broken_image_outlined),
                  ),
                ),
              ),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              onPressed: saving ? null : _pickImage,
              icon: const Icon(Icons.photo_library_outlined),
              label: Text(
                _existingImageUrl.isNotEmpty || _newImage != null
                    ? 'Change event image'
                    : 'Add event image',
              ),
            ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: saving ? null : _save,
                icon: saving
                    ? const SizedBox(
                  width: 18,
                  height: 18,
                  child: CircularProgressIndicator(
                    strokeWidth: 2,
                    color: Colors.white,
                  ),
                )
                    : const Icon(Icons.publish_rounded),
                label: Text(
                  saving
                      ? 'Saving...'
                      : isEditing
                      ? 'Update Event'
                      : 'Publish Event',
                  style: const TextStyle(fontWeight: FontWeight.w900),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}


// =====================================================
// COLLEGE POSTS MANAGER
// =====================================================

class CollegePostsManager extends StatefulWidget {
  final String collegeId;

  const CollegePostsManager({
    super.key,
    required this.collegeId,
  });

  @override
  State<CollegePostsManager> createState() =>
      _CollegePostsManagerState();
}

class _CollegePostsManagerState extends State<CollegePostsManager> {
  CollectionReference<Map<String, dynamic>> get _posts =>
      FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('posts');

  Future<void> _openEditor({
    DocumentSnapshot<Map<String, dynamic>>? post,
  }) async {
    await Navigator.of(context).push(
      FadePageRoute(
        page: CollegePostEditor(
          collegeId: widget.collegeId,
          post: post,
        ),
      ),
    );
  }

  Future<void> _deletePost(
      DocumentSnapshot<Map<String, dynamic>> post,
      ) async {
    final data = post.data() ?? {};
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text('Delete post?'),
          content: const Text(
            'This will remove the official update and its uploaded images.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              style: FilledButton.styleFrom(backgroundColor: Colors.red),
              child: const Text('Delete'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) return;

    try {
      final storagePaths = (data['storagePaths'] as List?)
          ?.map((e) => e.toString())
          .where((e) => e.isNotEmpty)
          .toList() ??
          <String>[];

      for (final path in storagePaths) {
        try {
          await FirebaseStorage.instance.ref(path).delete();
        } catch (_) {
          // Continue deleting the Firestore post even if an old file is gone.
        }
      }

      await post.reference.delete();

      if (!mounted) return;
      showSnack(
        context,
        'Post deleted successfully.',
        color: AppColors.green,
        bottomMargin: 16,
      );
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Could not delete post: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    }
  }

  String _formatDate(dynamic value) {
    DateTime? date;
    if (value is Timestamp) date = value.toDate();
    if (value is DateTime) date = value;
    if (date == null) return 'Recently';

    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        title: const Text(
          'College Posts',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
      ),
      floatingActionButton: FloatingActionButton.extended(
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
        onPressed: () => _openEditor(),
        icon: const Icon(Icons.add_rounded),
        label: const Text(
          'Create Post',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: _posts.snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Text(
                  'Could not load posts.\n\n${snapshot.error}',
                  textAlign: TextAlign.center,
                ),
              ),
            );
          }

          final docs = [...(snapshot.data?.docs ?? <QueryDocumentSnapshot<Map<String, dynamic>>>[])]
            ..sort((a, b) {
              final aTime = a.data()['createdAt'];
              final bTime = b.data()['createdAt'];
              final aDate = aTime is Timestamp ? aTime.toDate() : DateTime(2000);
              final bDate = bTime is Timestamp ? bTime.toDate() : DateTime(2000);
              return bDate.compareTo(aDate);
            });

          return ListView(
            padding: const EdgeInsets.fromLTRB(20, 20, 20, 110),
            children: [
              Container(
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  color: AppColors.softBlue,
                  borderRadius: BorderRadius.circular(22),
                ),
                child: const Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(Icons.verified_rounded, color: AppColors.blue),
                    SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        'Posts published here appear on the official college page with a verified college identity.',
                        style: TextStyle(
                          fontWeight: FontWeight.w700,
                          height: 1.45,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 24),
              Text(
                'Official Updates (${docs.length})',
                style: const TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w900,
                  color: AppColors.ink,
                ),
              ),
              const SizedBox(height: 14),
              if (docs.isEmpty)
                Container(
                  padding: const EdgeInsets.all(28),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(color: AppColors.grey),
                  ),
                  child: const Column(
                    children: [
                      Icon(
                        Icons.article_outlined,
                        size: 42,
                        color: AppColors.muted,
                      ),
                      SizedBox(height: 10),
                      Text(
                        'No official posts yet.',
                        style: TextStyle(fontWeight: FontWeight.w800),
                      ),
                      SizedBox(height: 5),
                      Text(
                        'Tap Create Post to publish your first update.',
                        textAlign: TextAlign.center,
                        style: TextStyle(color: AppColors.muted),
                      ),
                    ],
                  ),
                )
              else
                ...docs.map((doc) {
                  final data = doc.data();
                  final text = data['text']?.toString() ?? '';
                  final imageUrls = (data['imageUrls'] as List?)
                      ?.map((e) => e.toString())
                      .where((e) => e.isNotEmpty)
                      .toList() ??
                      <String>[];

                  return Container(
                    margin: const EdgeInsets.only(bottom: 16),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(22),
                      border: Border.all(color: AppColors.grey),
                      boxShadow: const [
                        BoxShadow(
                          color: Color(0x0A000000),
                          blurRadius: 12,
                          offset: Offset(0, 4),
                        ),
                      ],
                    ),
                    clipBehavior: Clip.antiAlias,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (imageUrls.isNotEmpty)
                          SizedBox(
                            height: 180,
                            child: PageView.builder(
                              itemCount: imageUrls.length,
                              itemBuilder: (context, index) {
                                return Container(
                                  color: Colors.white,
                                  alignment: Alignment.center,
                                  child: AdaptiveImage(
                                    image: NetworkImage(imageUrls[index]),
                                    maxHeight: 180,
                                    fit: BoxFit.contain,
                                    error: const Center(
                                      child: Icon(Icons.broken_image_outlined),
                                    ),
                                  ),
                                );
                              },
                            ),
                          ),
                        Padding(
                          padding: const EdgeInsets.fromLTRB(16, 14, 10, 14),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  const Icon(
                                    Icons.verified_rounded,
                                    size: 18,
                                    color: AppColors.blue,
                                  ),
                                  const SizedBox(width: 6),
                                  const Expanded(
                                    child: Text(
                                      'Official College Update',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w900,
                                        color: AppColors.blue,
                                      ),
                                    ),
                                  ),
                                  PopupMenuButton<String>(
                                    onSelected: (value) {
                                      if (value == 'edit') {
                                        _openEditor(post: doc);
                                      } else if (value == 'delete') {
                                        _deletePost(doc);
                                      }
                                    },
                                    itemBuilder: (_) => const [
                                      PopupMenuItem(
                                        value: 'edit',
                                        child: Text('Edit'),
                                      ),
                                      PopupMenuItem(
                                        value: 'delete',
                                        child: Text('Delete'),
                                      ),
                                    ],
                                  ),
                                ],
                              ),
                              if (text.trim().isNotEmpty) ...[
                                const SizedBox(height: 10),
                                Text(
                                  text,
                                  style: const TextStyle(
                                    fontSize: 15,
                                    height: 1.45,
                                    color: AppColors.ink,
                                  ),
                                ),
                              ],
                              const SizedBox(height: 10),
                              Text(
                                _formatDate(data['createdAt']),
                                style: const TextStyle(
                                  fontSize: 12,
                                  color: AppColors.muted,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  );
                }),
            ],
          );
        },
      ),
    );
  }
}

// =====================================================
// CREATE / EDIT COLLEGE POST
// =====================================================

class CollegePostEditor extends StatefulWidget {
  final String collegeId;
  final DocumentSnapshot<Map<String, dynamic>>? post;

  const CollegePostEditor({
    super.key,
    required this.collegeId,
    this.post,
  });

  @override
  State<CollegePostEditor> createState() => _CollegePostEditorState();
}

class _CollegePostEditorState extends State<CollegePostEditor> {
  final ImagePicker _picker = ImagePicker();
  final TextEditingController _textController = TextEditingController();
  List<XFile> _newImages = <XFile>[];
  List<String> _existingImageUrls = <String>[];
  List<String> _existingStoragePaths = <String>[];
  bool saving = false;

  bool get isEditing => widget.post != null;

  @override
  void initState() {
    super.initState();
    final data = widget.post?.data() ?? {};
    _textController.text = data['text']?.toString() ?? '';
    _existingImageUrls = (data['imageUrls'] as List?)
        ?.map((e) => e.toString())
        .where((e) => e.isNotEmpty)
        .toList() ??
        <String>[];
    _existingStoragePaths = (data['storagePaths'] as List?)
        ?.map((e) => e.toString())
        .where((e) => e.isNotEmpty)
        .toList() ??
        <String>[];
  }

  @override
  void dispose() {
    _textController.dispose();
    super.dispose();
  }

  Future<void> _pickImages() async {
    if (saving) return;
    final picked = await _pickAndCropImages(
      imageQuality: 82,
      maxWidth: 1800,
      maxImages: 6,
    );
    if (picked.isEmpty) return;

    if (!mounted) return;
    setState(() {
      _newImages = picked;
    });

  }

  Future<void> _removeExistingImage(int index) async {
    if (saving) return;
    if (index < 0 || index >= _existingImageUrls.length) return;

    final url = _existingImageUrls[index];
    final path = index < _existingStoragePaths.length
        ? _existingStoragePaths[index]
        : '';

    setState(() {
      _existingImageUrls.removeAt(index);
      if (index < _existingStoragePaths.length) {
        _existingStoragePaths.removeAt(index);
      }
    });

    if (path.isNotEmpty) {
      try {
        await FirebaseStorage.instance.ref(path).delete();
      } catch (_) {
        // The file may already be gone.
      }
    } else if (url.isNotEmpty) {
      // No storage path recorded; nothing can safely be deleted from Storage.
    }
  }

  Future<List<String>> _uploadNewImages(String postId) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) throw Exception('You are not signed in.');

    final urls = <String>[];
    final paths = <String>[];

    for (int i = 0; i < _newImages.length; i++) {
      final image = _newImages[i];
      final extension = image.name.contains('.')
          ? image.name.split('.').last.toLowerCase()
          : 'jpg';
      final fileName =
          'post_${DateTime.now().millisecondsSinceEpoch}_$i.$extension';
      final storagePath =
          'colleges/${widget.collegeId}/posts/$postId/$fileName';

      final ref = FirebaseStorage.instance.ref(storagePath);
      await ref.putFile(File(image.path));
      final url = await ref.getDownloadURL();
      urls.add(url);
      paths.add(storagePath);
    }

    return <String>[...urls, ...paths];
  }

  Future<void> _save() async {
    final text = _textController.text.trim();
    if (text.isEmpty && _existingImageUrls.isEmpty && _newImages.isEmpty) {
      showSnack(
        context,
        'Add some text or at least one image to create a post.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    setState(() => saving = true);

    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw Exception('You are not signed in.');

      final posts = FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .collection('posts');

      final postRef = widget.post?.reference ?? posts.doc();
      final postId = postRef.id;

      final uploaded = await _uploadNewImages(postId);
      final newUrls = uploaded.take(_newImages.length).toList();
      final newPaths = uploaded.skip(_newImages.length).toList();

      final imageUrls = <String>[..._existingImageUrls, ...newUrls];
      final storagePaths = <String>[..._existingStoragePaths, ...newPaths];

      await postRef.set({
        'text': text,
        'imageUrls': imageUrls,
        'storagePaths': storagePaths,
        'createdBy': user.uid,
        'createdAt': widget.post == null
            ? FieldValue.serverTimestamp()
            : (widget.post?.data()?['createdAt'] ?? FieldValue.serverTimestamp()),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      await FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .set({
        'updatedAt': FieldValue.serverTimestamp(),
        'updatedBy': user.uid,
      }, SetOptions(merge: true));

      if (!mounted) return;
      showSnack(
        context,
        isEditing ? 'Post updated successfully.' : 'Post published successfully.',
        color: AppColors.green,
        bottomMargin: 16,
      );
      Navigator.of(context).pop();
    } catch (e) {
      if (!mounted) return;
      showSnack(
        context,
        'Could not save post: $e',
        color: Colors.red,
        bottomMargin: 16,
      );
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

