  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.cream,
      body: FutureBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        future: FirebaseFirestore.instance
            .collection('colleges')
            .doc(collegeId)
            .get(),
        builder: (context, collegeSnapshot) {
          if (collegeSnapshot.connectionState == ConnectionState.waiting) {
            return const Scaffold(
              backgroundColor: Color(0xFFFEF9F1),
              body: Center(
                child: CircularProgressIndicator(color: AppColors.blue),
              ),
            );
          }

          if (collegeSnapshot.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Text(
                  'Could not load college page.\n\n${collegeSnapshot.error}',
                  textAlign: TextAlign.center,
                ),
              ),
            );
          }

          if (!collegeSnapshot.data!.exists) {
            return const Center(
              child: Text(
                'College profile is not available yet.',
                style: TextStyle(fontWeight: FontWeight.w800),
              ),
            );
          }

          final data = collegeSnapshot.data!.data() ?? {};
          final name = data['name']?.toString().trim().isNotEmpty == true
              ? data['name'].toString().trim()
              : 'College';
          final shortName = data['shortName']?.toString().trim() ?? '';
          final location = data['location']?.toString().trim() ?? '';
          final description = data['description']?.toString().trim() ?? '';
          final logoUrl = data['logoUrl']?.toString().trim() ?? '';
          final coverUrl = data['coverUrl']?.toString().trim() ?? '';
          final phone = data['phone']?.toString().trim() ?? '';
          final email = data['email']?.toString().trim() ?? '';
          final website = data['website']?.toString().trim() ?? '';
          final principal = data['principal']?.toString().trim() ?? '';
          final admissionInfo =
              data['admissionInfo']?.toString().trim() ?? '';
          final courses = _stringList(data['courses']);
          final facilities = _stringList(data['facilities']);

          final photosStream = FirebaseFirestore.instance
              .collection('colleges')
              .doc(collegeId)
              .collection('photos')
              .snapshots();
          final postsStream = FirebaseFirestore.instance
              .collection('colleges')
              .doc(collegeId)
              .collection('posts')
              .snapshots();

          return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: photosStream,
            builder: (context, photoSnapshot) {
              final photoDocs = [
                ...(photoSnapshot.data?.docs ??
                    <QueryDocumentSnapshot<Map<String, dynamic>>>[])
              ];
              photoDocs.sort((a, b) {
                final aTime = a.data()['createdAt'];
                final bTime = b.data()['createdAt'];
                final aDate =
                aTime is Timestamp ? aTime.toDate() : DateTime(2000);
                final bDate =
                bTime is Timestamp ? bTime.toDate() : DateTime(2000);
                return bDate.compareTo(aDate);
              });

              final galleryUrls = photoDocs
                  .where((doc) =>
              (doc.data()['type']?.toString() ?? 'gallery') ==
                  'gallery')
                  .map((doc) => doc.data()['imageUrl']?.toString() ?? '')
                  .where((url) => url.isNotEmpty)
                  .toList();

              return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: postsStream,
                builder: (context, postSnapshot) {
                  final postDocs = [
                    ...(postSnapshot.data?.docs ??
                        <QueryDocumentSnapshot<Map<String, dynamic>>>[])
                  ];
                  postDocs.sort((a, b) {
                    final aTime = a.data()['createdAt'];
                    final bTime = b.data()['createdAt'];
                    final aDate =
                    aTime is Timestamp ? aTime.toDate() : DateTime(2000);
