class CollegeProfileEditor extends StatefulWidget {
  final String collegeId;

  const CollegeProfileEditor({
    super.key,
    required this.collegeId,
  });

  @override
  State<CollegeProfileEditor> createState() =>
      _CollegeProfileEditorState();
}

class _CollegeProfileEditorState
    extends State<CollegeProfileEditor> {
  final nameCtrl = TextEditingController();
  final shortNameCtrl = TextEditingController();
  final locationCtrl = TextEditingController();
  final descriptionCtrl = TextEditingController();
  final phoneCtrl = TextEditingController();
  final emailCtrl = TextEditingController();
  final websiteCtrl = TextEditingController();
  final coursesCtrl = TextEditingController();
  final facilitiesCtrl = TextEditingController();
  final principalCtrl = TextEditingController();
  final admissionCtrl = TextEditingController();
  final logoUrlCtrl = TextEditingController();
  final coverUrlCtrl = TextEditingController();

  bool loading = true;
  bool saving = false;

  @override
  void initState() {
    super.initState();
    _loadProfile();
  }

  @override
  void dispose() {
    nameCtrl.dispose();
    shortNameCtrl.dispose();
    locationCtrl.dispose();
    descriptionCtrl.dispose();
    phoneCtrl.dispose();
    emailCtrl.dispose();
    websiteCtrl.dispose();
    coursesCtrl.dispose();
    facilitiesCtrl.dispose();
    principalCtrl.dispose();
    admissionCtrl.dispose();
    logoUrlCtrl.dispose();
    coverUrlCtrl.dispose();
    super.dispose();
  }

  Future<void> _loadProfile() async {
    try {
      final doc = await FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .get();

      final data = doc.data() ?? {};

      nameCtrl.text = data['name']?.toString() ?? '';
      shortNameCtrl.text =
          data['shortName']?.toString() ?? '';
      locationCtrl.text =
          data['location']?.toString() ?? '';
      descriptionCtrl.text =
          data['description']?.toString() ?? '';
      phoneCtrl.text = data['phone']?.toString() ?? '';
      emailCtrl.text = data['email']?.toString() ?? '';
      websiteCtrl.text =
          data['website']?.toString() ?? '';
      principalCtrl.text =
          data['principal']?.toString() ?? '';
      admissionCtrl.text =
          data['admissionInfo']?.toString() ?? '';
      logoUrlCtrl.text =
          data['logoUrl']?.toString() ?? '';
      coverUrlCtrl.text =
          data['coverUrl']?.toString() ?? '';

      final courses = data['courses'];
      if (courses is List) {
        coursesCtrl.text =
            courses.map((e) => e.toString()).join(', ');
      } else {
        coursesCtrl.text =
            data['courses']?.toString() ?? '';
      }

      final facilities = data['facilities'];
      if (facilities is List) {
        facilitiesCtrl.text =
            facilities.map((e) => e.toString()).join(', ');
      } else {
        facilitiesCtrl.text =
            data['facilities']?.toString() ?? '';
      }
    } catch (_) {
      if (mounted) {
        showSnack(
          context,
          'Could not load college profile.',
          color: Colors.red,
          bottomMargin: 16,
        );
      }
    } finally {
      if (mounted) {
        setState(() {
          loading = false;
        });
      }
    }
  }

  List<String> _commaList(String value) {
    return value
        .split(',')
        .map((item) => item.trim())
        .where((item) => item.isNotEmpty)
        .toList();
  }

  Future<void> _saveProfile() async {
    if (nameCtrl.text.trim().isEmpty) {
      showSnack(
        context,
        'College name is required.',
        color: Colors.red,
        bottomMargin: 16,
      );
      return;
    }

    FocusScope.of(context).unfocus();

    setState(() {
      saving = true;
    });

    try {
      final user = FirebaseAuth.instance.currentUser;

      await FirebaseFirestore.instance
          .collection('colleges')
          .doc(widget.collegeId)
          .set(
        {
          'name': nameCtrl.text.trim(),
          'shortName': shortNameCtrl.text.trim(),
          'location': locationCtrl.text.trim(),
          'description': descriptionCtrl.text.trim(),
          'phone': phoneCtrl.text.trim(),
          'email': emailCtrl.text.trim(),
          'website': websiteCtrl.text.trim(),
          'courses': _commaList(coursesCtrl.text),
          'facilities': _commaList(facilitiesCtrl.text),
          'principal': principalCtrl.text.trim(),
          'admissionInfo': admissionCtrl.text.trim(),
          'logoUrl': logoUrlCtrl.text.trim(),
          'coverUrl': coverUrlCtrl.text.trim(),
          'updatedAt': FieldValue.serverTimestamp(),
          'updatedBy': user?.uid ?? '',
        },
        SetOptions(merge: true),
      );

      if (!mounted) return;

      showSnack(
        context,
        'College profile updated successfully.',
        bottomMargin: 16,
      );

      Navigator.of(context).pop();
    } on FirebaseException catch (e) {
      if (!mounted) return;

      showSnack(
        context,
        e.message ?? 'Could not save the college profile.',
        color: Colors.red,
        bottomMargin: 16,
      );
    } catch (_) {
      if (!mounted) return;

      showSnack(
        context,
        'Could not save the college profile.',
        color: Colors.red,
        bottomMargin: 16,
      );
    } finally {
      if (mounted) {
        setState(() {
          saving = false;
        });
      }
    }
  }

  InputDecoration _decoration(
      String label,
      IconData icon,
      ) {
    return InputDecoration(
      labelText: label,
      prefixIcon: Icon(icon),
      filled: true,
      fillColor: AppColors.softBlue,
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(18),
        borderSide: BorderSide.none,
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(18),
        borderSide: const BorderSide(
          color: AppColors.blue,
          width: 1.5,
        ),
      ),
    );
  }

  Widget _field(
      TextEditingController controller,
      String label,
      IconData icon, {
        int maxLines = 1,
        TextInputType? keyboardType,
      }) {
    return TextField(
      controller: controller,
      maxLines: maxLines,
      keyboardType: keyboardType,
      decoration: _decoration(label, icon),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: AppColors.blue,
        foregroundColor: Colors.white,
