              ),

              const SizedBox(height: 24),

              const Text(
                'Academic Information',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 8),

              const Text(
                'For courses and facilities, separate items with commas.',
                style: TextStyle(
                  color: AppColors.muted,
                  fontWeight: FontWeight.w600,
                ),
              ),

              const SizedBox(height: 14),

              _field(
                coursesCtrl,
                'Courses',
                Icons.menu_book_outlined,
                maxLines: 3,
              ),

              const SizedBox(height: 12),

              _field(
                facilitiesCtrl,
                'Facilities',
                Icons.apartment_outlined,
                maxLines: 3,
              ),

              const SizedBox(height: 24),

              const Text(
                'Official Information',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 14),

              _field(
                principalCtrl,
                'Principal / official',
                Icons.person_outline_rounded,
              ),

              const SizedBox(height: 12),

              _field(
                admissionCtrl,
                'Admission information',
                Icons.how_to_reg_outlined,
                maxLines: 4,
              ),

              const SizedBox(height: 24),

              const Text(
                'Images',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
